        , "wsSpot" .= ("wss://stream.binance.com:9443/ws" :: String)
        , "wsSpotTestnet" .= ("wss://testnet.binance.vision/ws" :: String)
        , "wsFutures" .= ("wss://fstream.binance.com/ws" :: String)
        , "wsFuturesTestnet" .= ("wss://stream.binancefuture.com/ws" :: String)
        ]

