platformSeedMap :: HM.HashMap Text PlatformSeed
platformSeedMap =
    HM.fromList [(normalizePlatformText (psCode seed), seed) | seed <- platformSeeds]

platformLabelFromCode :: Text -> Text
platformLabelFromCode code =
    case parsePlatform (T.unpack code) of
        Right p -> T.pack (platformLabel p)
        Left _ -> code

platformSeedForCode :: Text -> PlatformSeed
platformSeedForCode raw =
    let code = normalizePlatformText raw
     in fromMaybe
            PlatformSeed
                { psCode = code
                , psLabel = platformLabelFromCode code
                , psRestUrl = Nothing
                , psWsUrl = Nothing
                , psDocsUrl = Nothing
                , psConnectionJson = Nothing
                }
            (HM.lookup code platformSeedMap)

uuidFromText :: Text -> Maybe UUID.UUID
uuidFromText txt =
    UUID.fromText =<< normalizeMaybeText (Just txt)

uuidToText :: UUID.UUID -> Text
uuidToText = UUID.toText

encodeJsonTextMaybe :: Maybe Aeson.Value -> Maybe Text
encodeJsonTextMaybe = fmap (TE.decodeUtf8 . BL.toStrict . Aeson.encode)

decodeJsonTextMaybe :: Maybe Text -> Maybe Aeson.Value
decodeJsonTextMaybe mText =
    case mText of
        Nothing -> Nothing
        Just txt -> Aeson.decode (BL.fromStrict (TE.encodeUtf8 txt))

data PersistedOperationRow = PersistedOperationRow
    { porId :: !Int64
    , porAtMs :: !Int64
    , porKind :: !Text
    , porSymbol :: !(Maybe Text)
    , porComboUuid :: !(Maybe UUID.UUID)
    , porOrderId :: !(Maybe Text)
    , porParams :: !(Maybe Text)
    , porArgs :: !(Maybe Text)
    , porResult :: !(Maybe Text)
    , porEquity :: !(Maybe Double)
    }
    deriving (Eq, Show)

instance FromRow PersistedOperationRow where
    fromRow =
        PersistedOperationRow
            <$> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field

persistedOperationFromRow :: PersistedOperationRow -> PersistedOperation
persistedOperationFromRow row =
    PersistedOperation
        { poId = porId row
        , poAtMs = porAtMs row
        , poKind = porKind row
        , poSymbol = porSymbol row
        , poComboUuid = uuidToText <$> porComboUuid row
        , poOrderId = porOrderId row
        , poParams = decodeJsonTextMaybe (porParams row)
        , poArgs = decodeJsonTextMaybe (porArgs row)
        , poResult = decodeJsonTextMaybe (porResult row)
        , poEquity = porEquity row
        }

data PersistedComboRow = PersistedComboRow
    { pcrUuid :: !UUID.UUID
    , pcrFinalEquity :: !(Maybe Double)
    , pcrAnnualizedReturn :: !(Maybe Double)
    , pcrObjective :: !(Maybe Text)
    , pcrSource :: !(Maybe Text)
    , pcrScore :: !(Maybe Double)
    , pcrOpenThreshold :: !(Maybe Double)
    , pcrCloseThreshold :: !(Maybe Double)
    , pcrParams :: !(Maybe Text)
    , pcrMetrics :: !(Maybe Text)
    , pcrCreatedAtMs :: !(Maybe Int64)
    , pcrUpdatedAtMs :: !(Maybe Int64)
    }
    deriving (Eq, Show)

instance FromRow PersistedComboRow where
    fromRow =
        PersistedComboRow
            <$> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field

persistedComboToValue :: PersistedComboRow -> Maybe Aeson.Value
persistedComboToValue row = do
    paramsVal <- decodeJsonTextMaybe (pcrParams row)
    paramsObj <-
        case paramsVal of
            Aeson.Object obj -> Just obj
            _ -> Nothing
    let metricsBase =
            case decodeJsonTextMaybe (pcrMetrics row) of
                Just (Aeson.Object obj) -> obj
                _ -> KM.empty
        metricsWithAnnualized =
            case (pcrAnnualizedReturn row, KM.lookup (AK.fromString "annualizedReturn") metricsBase >>= coerceDoubleValue) of
                (Just ann, Nothing) | not (isNaN ann || isInfinite ann) -> KM.insert (AK.fromString "annualizedReturn") (toJSON ann) metricsBase
                _ -> metricsBase
        metricsWithFinalEq =
            case (pcrFinalEquity row, KM.lookup (AK.fromString "finalEquity") metricsWithAnnualized >>= coerceDoubleValue) of
                (Just eq, Nothing) | not (isNaN eq || isInfinite eq) -> KM.insert (AK.fromString "finalEquity") (toJSON eq) metricsWithAnnualized
                _ -> metricsWithAnnualized
        metricsVal =
            if KM.null metricsWithFinalEq
                then Aeson.Null
                else Aeson.Object metricsWithFinalEq
        createdAtMs = pcrCreatedAtMs row <|> pcrUpdatedAtMs row
        comboFields =
            [ "uuid" .= uuidToText (pcrUuid row)
            , "createdAtMs" .= createdAtMs
            , "finalEquity" .= pcrFinalEquity row
            , "annualizedReturn" .= pcrAnnualizedReturn row
            , "objective" .= pcrObjective row
            , "score" .= pcrScore row
            , "openThreshold" .= pcrOpenThreshold row
            , "closeThreshold" .= pcrCloseThreshold row
            , "metrics" .= metricsVal
            , "params" .= Aeson.Object paramsObj
            ]
    pure
        ( object
            ( maybe [] (\source -> ["source" .= source]) (persistedComboSource row)
                ++ comboFields
            )
        )

persistedComboSource :: PersistedComboRow -> Maybe Text
persistedComboSource row =
    case trim . T.unpack <$> pcrSource row of
        Just source | not (null source) -> Just (T.pack source)
        _ -> Nothing

persistedComboLegacyIdentityKey :: PersistedComboRow -> Maybe BS.ByteString
persistedComboLegacyIdentityKey row = do
    paramsVal <- decodeJsonTextMaybe (pcrParams row)
    paramsObj <-
        case paramsVal of
            Aeson.Object obj -> Just obj
            _ -> Nothing
    pure $
        BL.toStrict $
            encodePretty $
                object
                    [ "params" .= paramsObj
                    , "openThreshold" .= pcrOpenThreshold row
                    , "closeThreshold" .= pcrCloseThreshold row
                    , "objective" .= pcrObjective row
                    ]

filterPersistedComboRows :: [PersistedComboRow] -> [PersistedComboRow]
filterPersistedComboRows rows =
    let sourceAwareKeys =
            [ key
            | row <- rows
            , isJust (persistedComboSource row)
            , Just key <- [persistedComboLegacyIdentityKey row]
            ]
     in [ row
        | row <- rows
        , isJust (persistedComboSource row)
            || maybe True (`notElem` sourceAwareKeys) (persistedComboLegacyIdentityKey row)
        ]

coerceDoubleValue :: Aeson.Value -> Maybe Double
coerceDoubleValue value =
    case AT.parseMaybe Aeson.parseJSON value of
        Just v
            | isNaN v || isInfinite v -> Nothing
            | otherwise -> Just v
        Nothing ->
            case value of
                Aeson.String s ->
                    let trimmed = trimString (T.unpack s)
                     in case readMaybe trimmed of
                            Just v | not (isNaN v || isInfinite v) -> Just v
                            _ -> Nothing
                Aeson.Bool v -> Just (if v then 1 else 0)
                _ -> Nothing

valueStringMaybe :: Aeson.Value -> Maybe String
valueStringMaybe = AT.parseMaybe Aeson.parseJSON

lookupJsonText :: Text -> Aeson.Value -> Maybe Text
lookupJsonText key val =
    case val of
        Aeson.Object obj ->
            case KM.lookup (AK.fromString (T.unpack key)) obj of
                Nothing -> Nothing
                Just v -> T.pack <$> valueStringMaybe v
        _ -> Nothing

lookupJsonTextKeys :: [Text] -> Aeson.Value -> Maybe Text
lookupJsonTextKeys keys val =
    firstJust [lookupJsonText key val | key <- keys]

lookupJsonTextMaybe :: [Text] -> Maybe Aeson.Value -> Maybe Text
lookupJsonTextMaybe keys mVal = mVal >>= lookupJsonTextKeys keys

lookupJsonInt64 :: Text -> Aeson.Value -> Maybe Int64
lookupJsonInt64 key val =
    case val of
        Aeson.Object obj ->
            case KM.lookup (AK.fromString (T.unpack key)) obj of
                Nothing -> Nothing
                Just v -> AT.parseMaybe Aeson.parseJSON v
        _ -> Nothing

inferPlatformFromJson :: Maybe Aeson.Value -> Maybe Text
inferPlatformFromJson = lookupJsonTextMaybe ["platform"]

inferSymbolFromJson :: Maybe Aeson.Value -> Maybe Text
inferSymbolFromJson = lookupJsonTextMaybe ["binanceSymbol", "symbol"]

inferMarketFromJson :: Maybe Aeson.Value -> Maybe Text
inferMarketFromJson = lookupJsonTextMaybe ["market"]

inferPlatformFromKind :: Text -> Maybe Text
inferPlatformFromKind kind =
    let k = T.toLower kind
     in if "binance." `T.isPrefixOf` k
            then Just "binance"
            else
                if "coinbase." `T.isPrefixOf` k
                    then Just "coinbase"
                    else
                        if "kraken." `T.isPrefixOf` k
                            then Just "kraken"
                            else
                                if "poloniex." `T.isPrefixOf` k
                                    then Just "poloniex"
                                    else Nothing

data TradeRequestRow = TradeRequestRow
    { trrRequestHash :: !Text
    , trrStatus :: !Text
    , trrResponseJson :: !(Maybe Text)
    , trrErrorText :: !(Maybe Text)
    }
    deriving (Eq, Show)

instance FromRow TradeRequestRow where
    fromRow = TradeRequestRow <$> field <*> field <*> field <*> field

data TradeIdempotencyCheck
    = TradeIdemAcquire
    | TradeIdemCached !Aeson.Value
    | TradeIdemBusy !String
    | TradeIdemConflict !String
    deriving (Eq, Show)

normalizeTenantScope :: Maybe TenantKey -> Text
normalizeTenantScope mTenantKey =
    fromMaybe "" (normalizeMaybeText mTenantKey)

requestHashFromApiParams :: ApiParams -> Text
requestHashFromApiParams params =
    T.pack (hashBytesHex (Aeson.encode (sanitizeApiParams params)))

resolveTradeIdempotency ::
    OpsStore ->
    Maybe TenantKey ->
    Text ->
    Text ->
    IO TradeIdempotencyCheck
resolveTradeIdempotency store mTenantKey idempotencyKey requestHash = do
    now <- getTimestampMs
    let tenantScope = normalizeTenantScope mTenantKey
        tenantKey' = normalizeMaybeText mTenantKey
    withMVar (osLock store) $ \_ ->
        withTransaction (osConn store) $ do
            inserted <-
                execute
                    (osConn store)
                    ( "INSERT INTO trade_requests (tenant_scope, tenant_key, idempotency_key, request_hash, status, created_at_ms, updated_at_ms) "
                        <> "VALUES (?, ?, ?, ?, 'running', ?, ?) "
                        <> "ON CONFLICT (tenant_scope, idempotency_key) DO NOTHING"
                    )
                    (tenantScope, tenantKey', idempotencyKey, requestHash, now, now)
            if inserted > 0
                then pure TradeIdemAcquire
                else do
                    rows <-
                        query
                            (osConn store)
                            "SELECT request_hash, status, response_json::text, error_text FROM trade_requests WHERE tenant_scope = ? AND idempotency_key = ? LIMIT 1"
                            (tenantScope, idempotencyKey)
                    case rows of
                        (row : _) ->
                            if trrRequestHash row /= requestHash
                                then
                                    pure
                                        ( TradeIdemConflict
                                            "idempotencyKey already exists for a different trade payload."
                                        )
                                else case T.toLower (trrStatus row) of
                                    "done" ->
                                        case decodeJsonTextMaybe (trrResponseJson row) of
                                            Just v -> pure (TradeIdemCached v)
                                            Nothing ->
                                                pure
                                                    ( TradeIdemBusy
                                                        "idempotencyKey is done but cached response is unavailable."
                                                    )
                                    "error" ->
                                        pure
                                            ( TradeIdemBusy
                                                ( maybe
                                                    "A prior trade request with this idempotencyKey failed."
                                                    T.unpack
                                                    (normalizeMaybeText (trrErrorText row))
                                                )
                                            )
                                    _ ->
                                        pure
                                            ( TradeIdemBusy
                                                "A trade request with this idempotencyKey is already running."
                                            )
                        _ -> pure TradeIdemAcquire

completeTradeIdempotencySuccess ::
    OpsStore ->
    Maybe TenantKey ->
    Text ->
    Text ->
    Aeson.Value ->
    IO ()
completeTradeIdempotencySuccess store mTenantKey idempotencyKey requestHash responseJson = do
    now <- getTimestampMs
    let tenantScope = normalizeTenantScope mTenantKey
        tenantKey' = normalizeMaybeText mTenantKey
        responseText = TE.decodeUtf8 (BL.toStrict (Aeson.encode responseJson))
    withMVar (osLock store) $ \_ ->
        void $
            execute
                (osConn store)
                ( "UPDATE trade_requests "
                    <> "SET tenant_key = ?, request_hash = ?, status = 'done', response_json = ?::jsonb, error_text = NULL, updated_at_ms = ?, completed_at_ms = ? "
                    <> "WHERE tenant_scope = ? AND idempotency_key = ?"
                )
                (tenantKey', requestHash, responseText, now, now, tenantScope, idempotencyKey)

completeTradeIdempotencyError ::
    OpsStore ->
    Maybe TenantKey ->
    Text ->
    Text ->
    String ->
    IO ()
completeTradeIdempotencyError store mTenantKey idempotencyKey requestHash errMsg = do
    now <- getTimestampMs
    let tenantScope = normalizeTenantScope mTenantKey
        tenantKey' = normalizeMaybeText mTenantKey
        msg = T.pack (take 4000 errMsg)
    withMVar (osLock store) $ \_ ->
        void $
            execute
                (osConn store)
                ( "UPDATE trade_requests "
                    <> "SET tenant_key = ?, request_hash = ?, status = 'error', response_json = NULL, error_text = ?, updated_at_ms = ?, completed_at_ms = ? "
                    <> "WHERE tenant_scope = ? AND idempotency_key = ?"
                )
                (tenantKey', requestHash, msg, now, now, tenantScope, idempotencyKey)

writeAsyncJobDb :: OpsStore -> Text -> Text -> Aeson.Value -> IO ()
writeAsyncJobDb store jobType jobId payload = do
    now <- getTimestampMs
    let status = fromMaybe "running" (lookupJsonText "status" payload)
        createdAtMs = lookupJsonInt64 "createdAtMs" payload
        completedAtMs = lookupJsonInt64 "completedAtMs" payload
        payloadText = TE.decodeUtf8 (BL.toStrict (Aeson.encode payload))
    withMVar (osLock store) $ \_ ->
        void $
            execute
                (osConn store)
                ( "INSERT INTO async_jobs (job_id, job_type, status, payload_json, created_at_ms, completed_at_ms, updated_at_ms) "
                    <> "VALUES (?, ?, ?, ?::jsonb, ?, ?, ?) "
                    <> "ON CONFLICT (job_id) DO UPDATE SET "
                    <> "job_type = EXCLUDED.job_type, "
                    <> "status = EXCLUDED.status, "
                    <> "payload_json = EXCLUDED.payload_json, "
                    <> "created_at_ms = COALESCE(EXCLUDED.created_at_ms, async_jobs.created_at_ms), "
                    <> "completed_at_ms = EXCLUDED.completed_at_ms, "
                    <> "updated_at_ms = EXCLUDED.updated_at_ms"
                )
                (jobId, jobType, status, payloadText, createdAtMs, completedAtMs, now)

readAsyncJobDb :: OpsStore -> Text -> IO (Maybe Aeson.Value)
readAsyncJobDb store jobId = do
    rows <-
        withMVar (osLock store) $ \_ ->
            query
                (osConn store)
                "SELECT payload_json::text FROM async_jobs WHERE job_id = ? LIMIT 1"
                (Only jobId) ::
                IO [Only Text]
    pure $
        case rows of
            (Only payloadText : _) -> decodeJsonTextMaybe (Just payloadText)
            _ -> Nothing

sanitizeSymbolForPlatformText :: Maybe Text -> Text -> Maybe Text
sanitizeSymbolForPlatformText mPlatform sym =
    T.pack <$> sanitizeSymbolForPlatform (T.unpack <$> mPlatform) (T.unpack sym)

splitDelimitedSymbol :: Char -> Text -> Maybe (Text, Text)
splitDelimitedSymbol delim sym =
    let delimText = T.singleton delim
        (base, rest) = T.breakOn delimText sym
        quote = T.drop (T.length delimText) rest
     in if T.null base || T.null quote
            then Nothing
            else Just (base, quote)

splitSymbolForPlatform :: Maybe Text -> Text -> (Maybe Text, Maybe Text)
splitSymbolForPlatform mPlatform sym =
    case normalizePlatformText <$> mPlatform of
        Just "coinbase" ->
            case splitDelimitedSymbol '-' sym of
                Just (base, quote) -> (Just base, Just quote)
                Nothing -> (Nothing, Nothing)
        Just "poloniex" ->
            case splitDelimitedSymbol '_' sym of
                Just (base, quote) -> (Just base, Just quote)
                Nothing -> (Nothing, Nothing)
        _ ->
            let (base, quote) = splitSymbol (T.unpack sym)
             in (Just (T.pack base), Just (T.pack quote))

symbolCacheKey :: Text -> Text -> Maybe Text -> (Text, Text, Text)
symbolCacheKey platform symbol mMarket =
    let market = fromMaybe "" mMarket
     in (platform, symbol, market)

resolvePlatformId :: OpsStore -> Connection -> Text -> IO (Maybe Int)
resolvePlatformId store conn rawCode = do
    let code = normalizePlatformText rawCode
    cached <- readIORef (osPlatformCache store)
    case HM.lookup code cached of
        Just pid -> pure (Just pid)
        Nothing -> do
            let seed = platformSeedForCode code
            now <- getTimestampMs
            let connJson = encodeJsonTextMaybe (psConnectionJson seed)
            rows <-
                query
                    conn
                    ( "INSERT INTO platforms (code, label, rest_url, ws_url, api_docs_url, connection_json, created_at_ms, updated_at_ms) "
                        <> "VALUES (?, ?, ?, ?, ?, ?::jsonb, ?, ?) "
                        <> "ON CONFLICT (code) DO UPDATE "
                        <> "SET label = EXCLUDED.label, "
                        <> "rest_url = COALESCE(EXCLUDED.rest_url, platforms.rest_url), "
                        <> "ws_url = COALESCE(EXCLUDED.ws_url, platforms.ws_url), "
                        <> "api_docs_url = COALESCE(EXCLUDED.api_docs_url, platforms.api_docs_url), "
                        <> "connection_json = COALESCE(EXCLUDED.connection_json, platforms.connection_json), "
                        <> "updated_at_ms = EXCLUDED.updated_at_ms "
                        <> "RETURNING id"
                    )
                    ( psCode seed
                    , psLabel seed
                    , psRestUrl seed
                    , psWsUrl seed
                    , psDocsUrl seed
                    , connJson
                    , now
                    , now
                    )
            let pid =
                    case rows of
                        (Only v : _) -> v
                        _ -> 0
            if pid > 0
                then do
                    atomicModifyIORef' (osPlatformCache store) (\m -> (HM.insert code pid m, ()))
                    pure (Just pid)
                else pure Nothing

resolvePlatformSymbolId :: OpsStore -> Connection -> Text -> Int -> Text -> Maybe Text -> IO (Maybe Int64)
resolvePlatformSymbolId store conn platformCode platformId symbol mMarket = do
    let key = symbolCacheKey platformCode symbol mMarket
    cached <- readIORef (osSymbolCache store)
    case HM.lookup key cached of
        Just sid -> pure (Just sid)
        Nothing -> do
            let (mBase, mQuote) = splitSymbolForPlatform (Just platformCode) symbol
            now <- getTimestampMs
            rows <-
                query
                    conn
                    ( "INSERT INTO platform_symbols (platform_id, symbol, market, base_asset, quote_asset, status, metadata_json, created_at_ms, updated_at_ms) "
                        <> "VALUES (?, ?, ?, ?, ?, NULL, NULL, ?, ?) "
                        <> "ON CONFLICT (platform_id, symbol, market) DO UPDATE "
                        <> "SET base_asset = COALESCE(EXCLUDED.base_asset, platform_symbols.base_asset), "
                        <> "quote_asset = COALESCE(EXCLUDED.quote_asset, platform_symbols.quote_asset), "
                        <> "updated_at_ms = EXCLUDED.updated_at_ms "
                        <> "RETURNING id"
                    )
                    (platformId, symbol, mMarket, mBase, mQuote, now, now)
            let sid =
                    case rows of
                        (Only v : _) -> v
                        _ -> 0
            if sid > 0
                then do
                    atomicModifyIORef' (osSymbolCache store) (\m -> (HM.insert key sid m, ()))
                    pure (Just sid)
                else pure Nothing

data GitCommitLog = GitCommitLog
    { gclHash :: !Text
    , gclCommittedAtMs :: !Int64
    }
    deriving (Eq, Show)

resolveGitRepoRoot :: IO (Either String FilePath)
resolveGitRepoRoot = do
    (code, out, err) <- readCreateProcessWithExitCode (proc "git" ["rev-parse", "--show-toplevel"]) ""
    case code of
        ExitSuccess ->
            case trim out of
                "" -> pure (Left "git rev-parse returned an empty repo root.")
                root -> pure (Right root)
        ExitFailure _ ->
            pure (Left ("Failed to resolve git repo root: " ++ trim (if null err then out else err)))

parseGitCommitLogLine :: String -> Either String GitCommitLog
parseGitCommitLogLine raw =
    case break (== '|') (trim raw) of
        (hashRaw, '|' : tsRaw) -> do
            let hash = trim hashRaw
                tsTrimmed = trim tsRaw
            if null hash
                then Left ("Invalid git log line (empty hash): " ++ raw)
                else case readMaybe tsTrimmed :: Maybe Integer of
                    Nothing -> Left ("Invalid git commit timestamp: " ++ tsTrimmed)
                    Just ts ->
                        let tsMs = fromIntegral ts * 1000
                         in Right (GitCommitLog (T.pack hash) tsMs)
        _ -> Left ("Invalid git log line: " ++ raw)

parseGitCommitLog :: String -> Either String [GitCommitLog]
parseGitCommitLog raw = do
    let rows = filter (not . null) (map trim (lines raw))
    forM rows parseGitCommitLogLine

readGitCommitLog :: IO (Either String [GitCommitLog])
readGitCommitLog = do
    rootResult <- resolveGitRepoRoot
    case rootResult of
        Left err -> pure (Left err)
        Right root -> do
            let cmd = proc "git" ["-C", root, "log", "--all", "--format=%H|%ct"]
            (code, out, err) <- readCreateProcessWithExitCode cmd ""
            case code of
                ExitSuccess -> pure (parseGitCommitLog out)
                ExitFailure _ ->
                    pure (Left ("Failed to read git commit history: " ++ trim (if null err then out else err)))

resolveGitCommitId :: Connection -> Text -> Maybe Text -> Maybe Int64 -> IO (Maybe Int64)
resolveGitCommitId conn commitHash mVersion mCommittedAtMs = do
    now <- getTimestampMs
    rows <-
        query
            conn
            ( "INSERT INTO git_commits (commit_hash, version, committed_at_ms, created_at_ms) "
                <> "VALUES (?, ?, ?, ?) "
                <> "ON CONFLICT (commit_hash) DO UPDATE "
                <> "SET version = COALESCE(EXCLUDED.version, git_commits.version), "
                <> "committed_at_ms = COALESCE(EXCLUDED.committed_at_ms, git_commits.committed_at_ms) "
                <> "RETURNING id"
            )
            (commitHash, mVersion, mCommittedAtMs, now)
    case rows of
        (Only v : _) -> pure (Just v)
        _ -> pure Nothing

resolveDbUrl :: IO (Either String BS.ByteString)
resolveDbUrl = do
    mPrimary <- lookupEnv "TRADER_DB_URL"
    mFallback <- lookupEnv "DATABASE_URL"
    let pick =
            listToMaybe
                [ url
                | Just raw <- [mPrimary, mFallback]
                , let url = trim raw
                , not (null url)
                ]
    case pick of
        Nothing -> pure (Left "TRADER_DB_URL or DATABASE_URL not set.")
        Just url -> pure (Right (BS.pack url))

