newOpsStoreFromEnv :: IO (Maybe OpsStore)
newOpsStoreFromEnv = do
    dbUrlOrErr <- resolveDbUrl
    case dbUrlOrErr of
        Left err -> do
            hPutStrLn stderr ("WARN: ops persistence disabled (" ++ err ++ ")")
            pure Nothing
        Right url -> do
            connResult <- try (connectPostgreSQL url) :: IO (Either SomeException Connection)
            case connResult of
                Left e -> do
                    hPutStrLn stderr ("WARN: ops persistence disabled (" ++ show e ++ ")")
                    pure Nothing
                Right conn -> do
                    schemaResult <- try (ensureOpsDbSchema conn >> seedStrategies conn >> seedPlatforms conn) :: IO (Either SomeException ())
                    case schemaResult of
                        Left e -> do
                            hPutStrLn stderr ("WARN: ops persistence disabled (" ++ show e ++ ")")
                            pure Nothing
                        Right _ -> do
                            mCommitRaw <- getBuildCommit
                            let mCommitText = normalizeMaybeText (T.pack <$> mCommitRaw)
                                mVersionText = normalizeMaybeText (Just (T.pack traderVersion))
                            mCommitId <-
                                case mCommitText of
                                    Nothing -> pure Nothing
                                    Just commitHash -> do
                                        commitResult <- try (resolveGitCommitId conn commitHash mVersionText Nothing) :: IO (Either SomeException (Maybe Int64))
                                        case commitResult of
                                            Left e -> do
                                                hPutStrLn stderr ("WARN: unable to persist git commit metadata (" ++ show e ++ ")")
                                                pure Nothing
                                            Right v -> pure v
                            maxRows <- query_ conn "SELECT COALESCE(MAX(id), 0) FROM ops" :: IO [Only Int64]
                            let maxId =
                                    case maxRows of
                                        (Only v : _) -> v
                                        _ -> 0
                            lock <- newMVar ()
                            latestRef <- newIORef maxId
                            platformCache <- newIORef HM.empty
                            symbolCache <- newIORef HM.empty
                            pure (Just (OpsStore lock conn latestRef platformCache symbolCache mCommitId))

backfillGitCommitsAndOps :: Connection -> IO (Either String (Int, Int64, Int64))
backfillGitCommitsAndOps conn = do
    logResult <- readGitCommitLog
    case logResult of
        Left err -> pure (Left err)
        Right commits -> do
            now <- getTimestampMs
            let rows = [(gclHash c, gclCommittedAtMs c, now) | c <- commits]
                upsertSql =
                    "INSERT INTO git_commits (commit_hash, committed_at_ms, created_at_ms) "
                        <> "VALUES (?, ?, ?) "
                        <> "ON CONFLICT (commit_hash) DO UPDATE "
                        <> "SET committed_at_ms = COALESCE(EXCLUDED.committed_at_ms, git_commits.committed_at_ms), "
                        <> "version = COALESCE(git_commits.version, EXCLUDED.version)"
                updateOpsSql =
                    "WITH ordered_commits AS ("
                        <> "SELECT id, committed_at_ms, "
                        <> "LEAD(committed_at_ms) OVER (ORDER BY committed_at_ms, id) AS next_at "
                        <> "FROM git_commits WHERE committed_at_ms IS NOT NULL"
                        <> "), bounds AS ("
                        <> "SELECT id, committed_at_ms, COALESCE(next_at, 9223372036854775807) AS next_at "
                        <> "FROM ordered_commits"
                        <> ") "
                        <> "UPDATE ops "
                        <> "SET git_commit_id = bounds.id "
                        <> "FROM bounds "
                        <> "WHERE ops.git_commit_id IS NULL "
                        <> "AND ops.at_ms >= bounds.committed_at_ms "
                        <> "AND ops.at_ms < bounds.next_at"
            upserted <-
                if null rows
                    then pure 0
                    else executeMany conn upsertSql rows
            updated <- execute_ conn updateOpsSql
            pure (Right (length commits, upserted, updated))

runOpsBackfillCommits :: IO ()
runOpsBackfillCommits = do
    dbUrlOrErr <- resolveDbUrl
    case dbUrlOrErr of
        Left err -> die ("Ops backfill requires TRADER_DB_URL or DATABASE_URL (" ++ err ++ ")")
        Right url -> do
            connResult <- try (connectPostgreSQL url) :: IO (Either SomeException Connection)
            case connResult of
                Left e -> die ("Ops backfill failed to connect to Postgres (" ++ show e ++ ")")
                Right conn -> do
                    schemaResult <- try (ensureOpsDbSchema conn) :: IO (Either SomeException ())
                    case schemaResult of
                        Left e -> die ("Ops backfill failed to ensure schema (" ++ show e ++ ")")
                        Right _ -> do
                            backfillResult <- backfillGitCommitsAndOps conn
                            case backfillResult of
                                Left err -> die ("Ops backfill failed (" ++ err ++ ")")
                                Right (totalCommits, commitsUpserted, opsUpdated) -> do
                                    putStrLn ("Git commits discovered: " ++ show totalCommits)
                                    putStrLn ("Git commits upserted: " ++ show commitsUpserted)
                                    putStrLn ("Ops rows updated: " ++ show opsUpdated)

comboCompletedOperationKind :: Text
comboCompletedOperationKind = "bot.order"

finiteMaybe :: Maybe Double -> Maybe Double
finiteMaybe mX = do
    x <- mX
    if not (isNaN x || isInfinite x) then Just x else Nothing

updateComboPerformanceFromCompletedOperation ::
    Connection ->
    Int64 ->
    UUID.UUID ->
    Double ->
    IO ()
updateComboPerformanceFromCompletedOperation conn now comboUuid currentEq = do
    eqRows <-
        query
            conn
            "SELECT equity FROM ops WHERE combo_uuid = ? AND kind = ? AND equity IS NOT NULL ORDER BY id DESC LIMIT 2"
            (comboUuid, comboCompletedOperationKind) ::
            IO [Only Double]
    comboRows <-
        query
            conn
            "SELECT final_equity, annualized_return, interval, metrics_json::text FROM combos WHERE combo_uuid = ? LIMIT 1"
            (Only comboUuid) ::
            IO [(Maybe Double, Maybe Double, Maybe Text, Maybe Text)]
    case comboRows of
        [] -> pure ()
        ((mFinalEq, mAnnualized, mInterval, mMetricsText) : _) -> do
            let metricsObj =
                    case decodeJsonTextMaybe mMetricsText of
                        Just (Aeson.Object o) -> o
                        _ -> KM.empty
                (nextFinalEq, nextAnnualized, metricsObj') =
                    recalculateComboPerformanceFromOperation
                        (T.unpack <$> mInterval)
                        mFinalEq
                        mAnnualized
                        metricsObj
                        (case eqRows of (_ : Only v : _) -> Just v; _ -> Nothing)
                        currentEq
                metricsJson = encodeJsonTextMaybe (Just (Aeson.Object metricsObj'))
            void $
                execute
                    conn
                    ( "UPDATE combos "
                        <> "SET final_equity = ?, annualized_return = ?, metrics_json = ?::jsonb, updated_at_ms = ? "
                        <> "WHERE combo_uuid = ?"
                    )
                    (nextFinalEq, nextAnnualized, metricsJson, now, comboUuid)

opsAppend ::
    OpsStore ->
    Maybe TenantKey ->
    Text ->
    Maybe Aeson.Value ->
    Maybe Aeson.Value ->
    Maybe Aeson.Value ->
    Maybe Double ->
    Maybe Text ->
    Maybe Text ->
    Maybe Text ->
    IO PersistedOperation
opsAppend store mTenantKey kind mParams mArgs mResult mEquity mComboUuid mSymbol mOrderId = do
    now <- getTimestampMs
    let mTenantKey' = normalizeMaybeText mTenantKey
        mPlatformRaw =
            firstJust
                [ inferPlatformFromJson mArgs
                , inferPlatformFromJson mParams
                , inferPlatformFromJson mResult
                , inferPlatformFromKind kind
                ]
        mPlatform = normalizeMaybeText (normalizePlatformText <$> mPlatformRaw)
        mMarketRaw =
            firstJust
                [ inferMarketFromJson mArgs
                , inferMarketFromJson mParams
                , inferMarketFromJson mResult
                ]
        mMarket = normalizeMaybeText (normalizeMarketText <$> mMarketRaw)
        mSymbolRaw = firstJust [mSymbol, inferSymbolFromJson mArgs, inferSymbolFromJson mParams, inferSymbolFromJson mResult]
        mSymbolTrim = normalizeMaybeText mSymbolRaw
        mSymbolSanitized = mSymbolTrim >>= sanitizeSymbolForPlatformText mPlatform
        mSymbol' = mSymbolSanitized <|> mSymbolTrim
        mOrderId' = normalizeMaybeText mOrderId
        mComboUuid' = mComboUuid >>= uuidFromText
        paramsJson = encodeJsonTextMaybe mParams
        argsJson = encodeJsonTextMaybe mArgs
        resultJson = encodeJsonTextMaybe mResult
        mCommitId = osCommitId store
    opId <- withMVar (osLock store) $ \_ ->
        withTransaction (osConn store) $ do
            let conn = osConn store
            mPlatformId <- case mPlatform of
                Nothing -> pure Nothing
                Just platformCode -> resolvePlatformId store conn platformCode
            mSymbolId <- case (mPlatform, mPlatformId, mSymbolSanitized) of
                (Just platformCode, Just platformId, Just sym) -> resolvePlatformSymbolId store conn platformCode platformId sym mMarket
                _ -> pure Nothing
            rows <-
                query
                    conn
                    "INSERT INTO ops (tenant_key, at_ms, kind, platform_id, symbol_id, symbol, combo_uuid, order_id, params_json, args_json, result_json, equity, git_commit_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?::jsonb, ?::jsonb, ?::jsonb, ?, ?) RETURNING id"
                    (mTenantKey', now, kind, mPlatformId, mSymbolId, mSymbol', mComboUuid', mOrderId', paramsJson, argsJson, resultJson, mEquity, mCommitId)
            let newId =
                    case rows of
                        (Only v : _) -> v
                        _ -> 0
            case mComboUuid' of
                Nothing -> pure ()
                Just comboUuid ->
                    do
                        void $
                            execute
                                conn
                                ( "INSERT INTO combos (combo_uuid, operation_count, created_at_ms, updated_at_ms) "
                                    <> "VALUES (?, 1, ?, ?) "
                                    <> "ON CONFLICT (combo_uuid) DO UPDATE "
                                    <> "SET operation_count = combos.operation_count + 1, "
                                    <> "created_at_ms = COALESCE(combos.created_at_ms, EXCLUDED.created_at_ms), "
                                    <> "updated_at_ms = EXCLUDED.updated_at_ms"
                                )
                                (comboUuid, now, now)
                        when (kind == comboCompletedOperationKind) $
                            for_
                                (finiteMaybe mEquity)
                                (updateComboPerformanceFromCompletedOperation conn now comboUuid)
            pure newId
    let op =
            PersistedOperation
                { poId = opId
                , poAtMs = now
                , poKind = kind
                , poSymbol = mSymbol'
                , poComboUuid = uuidToText <$> mComboUuid'
                , poOrderId = mOrderId'
                , poParams = mParams
                , poArgs = mArgs
                , poResult = mResult
                , poEquity = mEquity
                }
    writeIORef (osLatestId store) opId
    pure op

opsAppendMaybe ::
    Maybe OpsStore ->
    Maybe TenantKey ->
    Text ->
    Maybe Aeson.Value ->
    Maybe Aeson.Value ->
    Maybe Aeson.Value ->
    Maybe Double ->
    Maybe Text ->
    Maybe Text ->
    Maybe Text ->
    IO ()
opsAppendMaybe mStore mTenantKey kind mParams mArgs mResult mEquity mComboUuid mSymbol mOrderId =
    case mStore of
        Nothing -> pure ()
        Just store -> do
            _ <- try (opsAppend store mTenantKey kind mParams mArgs mResult mEquity mComboUuid mSymbol mOrderId) :: IO (Either SomeException PersistedOperation)
            pure ()

outboxEnqueue ::
    OpsStore ->
    Maybe TenantKey ->
    Text ->
    Maybe Text ->
    Aeson.Value ->
    IO ()
outboxEnqueue store mTenantKey topic mEventKey payload = do
    now <- getTimestampMs
    let tenantKey' = normalizeMaybeText mTenantKey
        eventKey' = normalizeMaybeText mEventKey
        payloadJson = TE.decodeUtf8 (BL.toStrict (Aeson.encode payload))
    withMVar (osLock store) $ \_ ->
        void $
            execute
                (osConn store)
                ( "INSERT INTO outbox_events (tenant_key, topic, event_key, payload_json, status, attempts, next_attempt_at_ms, created_at_ms, updated_at_ms) "
                    <> "VALUES (?, ?, ?, ?::jsonb, 'pending', 0, NULL, ?, ?)"
                )
                (tenantKey', topic, eventKey', payloadJson, now, now)

outboxEnqueueMaybe ::
    Maybe OpsStore ->
    Maybe TenantKey ->
    Text ->
    Maybe Text ->
    Aeson.Value ->
    IO ()
outboxEnqueueMaybe mStore mTenantKey topic mEventKey payload =
    case mStore of
        Nothing -> pure ()
        Just store -> do
            _ <- try (outboxEnqueue store mTenantKey topic mEventKey payload) :: IO (Either SomeException ())
            pure ()

ownerKeyFromArgs :: Maybe TenantKey -> Args -> Text
ownerKeyFromArgs mTenantKey args =
    let tenant = fromMaybe "public" (normalizeMaybeText mTenantKey)
        symbol = fromMaybe "-" (normalizeMaybeText (T.pack <$> argBinanceSymbol args))
     in T.intercalate ":" [tenant, T.pack (platformCode (argPlatform args)), symbol, T.pack (marketCode (argBinanceMarket args)), T.pack (argInterval args)]

data OpsCondition = OpsCondition
    { ocSql :: !String
    , ocParams :: ![Action]
    }

opsList ::
    OpsStore ->
    Maybe TenantKey ->
    Maybe Int64 ->
    Int ->
    Maybe Text ->
    Maybe Text ->
    Maybe Text ->
    Maybe Text ->
    Maybe Int64 ->
    Maybe Int64 ->
    Maybe Bool ->
    IO [PersistedOperation]
opsList store mTenantKey sinceId limit mKind mSymbol mComboUuid mOrderId mFromMs mToMs mBotOnly = do
    let limitSafe = max 0 (min 5000 limit)
        mTenantKey' = normalizeMaybeText mTenantKey
        mKind' = normalizeMaybeText mKind
        mSymbol' = normalizeMaybeText mSymbol
        mOrderId' = normalizeMaybeText mOrderId
        mComboUuid' = mComboUuid >>= uuidFromText
        baseConditions =
            catMaybes
                [ fmap (\tkey -> OpsCondition "tenant_key = ?" [toField tkey]) mTenantKey'
                , fmap (\sid -> OpsCondition "id > ?" [toField sid]) sinceId
                , fmap (\k -> OpsCondition "kind = ?" [toField k]) mKind'
                , fmap (\sym -> OpsCondition "symbol = ?" [toField sym]) mSymbol'
                , fmap (\uuid -> OpsCondition "combo_uuid = ?" [toField uuid]) mComboUuid'
                , fmap (\oid -> OpsCondition "order_id = ?" [toField oid]) mOrderId'
                , fmap (\fromMs -> OpsCondition "at_ms >= ?" [toField fromMs]) mFromMs
                , fmap (\toMs -> OpsCondition "at_ms <= ?" [toField toMs]) mToMs
                ]
        botCondition =
            case mBotOnly of
                Just True -> [OpsCondition "kind LIKE 'bot.%'" []]
                _ -> []
        conditions = botCondition ++ baseConditions
        whereSql =
            if null conditions
                then ""
                else " WHERE " ++ intercalate " AND " (map ocSql conditions)
        orderSql =
            if isJust sinceId
                then " ORDER BY id ASC"
                else " ORDER BY id DESC"
        sql =
            "SELECT id, at_ms, kind, symbol, combo_uuid, order_id, params_json::text, args_json::text, result_json::text, equity "
                <> "FROM ops"
                <> whereSql
                <> orderSql
                <> " LIMIT ?"
        params = concatMap ocParams conditions ++ [toField limitSafe]
    case (mComboUuid, mComboUuid') of
        (Just _, Nothing) -> pure []
        _ -> do
            rows <- withMVar (osLock store) $ \_ -> query (osConn store) (fromString sql) params
            let ops = map persistedOperationFromRow rows
            pure (if isJust sinceId then ops else reverse ops)

data OpsPerformanceReady = OpsPerformanceReady
    { oprCommitsReadyFlag :: !Bool
    , oprCombosReadyFlag :: !Bool
    }
    deriving (Eq, Show)

opsPerformanceReady :: OpsStore -> IO OpsPerformanceReady
opsPerformanceReady store =
    withMVar (osLock store) $ \_ -> do
        rows <-
            query
                (osConn store)
                "SELECT to_regclass('public.performance_commit_deltas') IS NOT NULL, to_regclass('public.performance_combo_deltas') IS NOT NULL"
                () ::
                IO [(Bool, Bool)]
        case rows of
            ((commitsReady, combosReady) : _) -> pure (OpsPerformanceReady commitsReady combosReady)
            _ -> pure (OpsPerformanceReady False False)

opsPerformanceCommits :: OpsStore -> Maybe TenantKey -> Int -> IO [PerformanceCommitDelta]
opsPerformanceCommits store mTenantKey limit = do
    let limitSafe = max 0 (min 200 limit)
        tenantKey' = normalizeMaybeText mTenantKey
        (whereSql, params) =
            case tenantKey' of
                Nothing -> ("", [])
                Just t -> (" WHERE tenant_key = ?", [toField t])
        sql =
            "SELECT git_commit_id, commit_hash, committed_at_ms, start_at_ms, end_at_ms, symbols, combos, rollups, "
                <> "avg_return, median_return, min_return, max_return, avg_drawdown, median_drawdown, worst_drawdown, "
                <> "status_points, order_count, sample_points, updated_at_ms, prev_commit_hash, prev_median_return, "
                <> "delta_median_return, prev_median_drawdown, delta_median_drawdown, prev_worst_drawdown, delta_worst_drawdown "
                <> "FROM performance_commit_deltas "
                <> whereSql
                <> " ORDER BY committed_at_ms DESC NULLS LAST, git_commit_id DESC "
                <> "LIMIT ?"
        finalParams = params ++ [toField limitSafe]
    if limitSafe <= 0
        then pure []
        else withMVar (osLock store) $ \_ ->
            query
                (osConn store)
                (fromString sql)
                finalParams

opsPerformanceCombos :: OpsStore -> Maybe TenantKey -> Int -> Text -> Text -> IO [PerformanceComboDelta]
opsPerformanceCombos store mTenantKey limit scope order = do
    let limitSafe = max 0 (min 200 limit)
        scopeNorm = T.toLower (T.strip scope)
        orderNorm = T.toLower (T.strip order)
        tenantKey' = normalizeMaybeText mTenantKey
        (tenantWhere, tenantParams) =
            case tenantKey' of
                Nothing -> ("", [])
                Just t -> ("tenant_key = ?", [toField t])
        scopeClause =
            if scopeNorm == "all"
                then ""
                else
                    let subWhere =
                            case tenantWhere of
                                "" -> "WHERE committed_at_ms IS NOT NULL "
                                _ -> "WHERE " <> tenantWhere <> " AND committed_at_ms IS NOT NULL "
                     in "committed_at_ms = ("
                            <> "SELECT committed_at_ms FROM performance_combo_deltas "
                            <> subWhere
                            <> "ORDER BY committed_at_ms DESC NULLS LAST LIMIT 1"
                            <> ")"
        conditions = filter (not . null) [tenantWhere, scopeClause]
        whereSql =
            if null conditions
                then ""
                else " WHERE " <> intercalate " AND " conditions
        orderSql =
            case orderNorm of
                "recent" -> "ORDER BY committed_at_ms DESC NULLS LAST, git_commit_id DESC"
                "return" -> "ORDER BY return DESC NULLS LAST"
                _ -> "ORDER BY delta_return ASC NULLS LAST"
        sql =
            "SELECT git_commit_id, commit_hash, committed_at_ms, symbol, market, interval, combo_uuid::text, "
                <> "start_at_ms, end_at_ms, first_equity, last_equity, return, max_drawdown, status_points, order_count, "
                <> "sample_points, updated_at_ms, prev_commit_hash, prev_return, delta_return, prev_max_drawdown, delta_drawdown "
                <> "FROM performance_combo_deltas "
                <> whereSql
                <> " "
                <> orderSql
                <> " LIMIT ?"
        extraTenantParams =
            case (tenantKey', scopeNorm == "all") of
                (Just _, False) -> tenantParams
                _ -> []
        finalParams = tenantParams ++ extraTenantParams ++ [toField limitSafe]
    if limitSafe <= 0
        then pure []
        else withMVar (osLock store) $ \_ ->
            query
                (osConn store)
                (fromString sql)
                finalParams

outboxStatusValue :: OpsStore -> Maybe TenantKey -> Maybe Text -> IO Aeson.Value
outboxStatusValue store mTenantKey mStatus = do
    now <- getTimestampMs
    (rows, mOldestPending) <-
        withMVar (osLock store) $ \_ -> do
            let tenantKey' = normalizeMaybeText mTenantKey
                status' = normalizeMaybeText mStatus
                whereParts =
                    catMaybes
                        [ fmap (const "tenant_key = ?") tenantKey'
                        , fmap (const "status = ?") status'
                        ]
                whereSql =
                    if null whereParts
                        then ""
                        else " WHERE " <> intercalate " AND " whereParts
                whereSqlOldest =
                    if null whereParts
                        then " WHERE status = 'pending'"
                        else " WHERE status = 'pending' AND " <> intercalate " AND " whereParts
                params = catMaybes [toField <$> tenantKey', toField <$> status']
            grouped <-
                query
                    (osConn store)
                    (fromString ("SELECT status, COUNT(*)::bigint FROM outbox_events" <> whereSql <> " GROUP BY status"))
                    params ::
                    IO [(Text, Int64)]
            oldestRows <-
                query
                    (osConn store)
                    (fromString ("SELECT MIN(created_at_ms) FROM outbox_events" <> whereSqlOldest))
                    params ::
                    IO [Only (Maybe Int64)]
            let oldest =
                    case oldestRows of
                        (Only v : _) -> v
                        _ -> Nothing
            pure (grouped, oldest)
    let counts = HM.fromList rows
        countFor key = fromMaybe 0 (HM.lookup key counts)
        pending = countFor "pending"
        publishing = countFor "publishing"
        published = countFor "published"
        failed = countFor "failed"
        total = pending + publishing + published + failed
        oldestPendingAgeMs =
            case mOldestPending of
                Nothing -> Nothing
                Just createdAt -> Just (max 0 (now - createdAt))
    pure
        ( object
            [ "enabled" .= True
            , "atMs" .= now
            , "tenantKey" .= normalizeMaybeText mTenantKey
            , "statusFilter" .= normalizeMaybeText mStatus
            , "counts"
                .= object
                    [ "total" .= total
                    , "pending" .= pending
                    , "publishing" .= publishing
                    , "published" .= published
                    , "failed" .= failed
                    ]
            , "oldestPendingAgeMs" .= oldestPendingAgeMs
            ]
        )

binanceOpsLogger :: OpsStore -> Maybe TenantKey -> BinanceLog -> IO ()
binanceOpsLogger store mTenantKey entry = do
    let params =
            object
                [ "label" .= blLabel entry
                , "method" .= blMethod entry
                , "path" .= blPath entry
                , "market" .= marketCode (blMarket entry)
                , "params" .= [object ["key" .= k, "value" .= v] | (k, v) <- blParams entry]
                ]
        result =
            object
                [ "ok" .= blOk entry
                , "status" .= blStatus entry
                , "latencyMs" .= blLatencyMs entry
                , "error" .= blError entry
                ]
        mSymbol = lookup "symbol" (blParams entry)
        mOrderId = lookup "orderId" (blParams entry)
    opsAppendMaybe (Just store) mTenantKey "binance.request" (Just params) Nothing (Just result) Nothing Nothing mSymbol mOrderId

data OpsOrderOriginRow = OpsOrderOriginRow
    { oorId :: !Int64
    , oorTenantKey :: !(Maybe Text)
    , oorKind :: !Text
    , oorOrderId :: !(Maybe Text)
    , oorParams :: !(Maybe Aeson.Value)
    , oorResult :: !(Maybe Aeson.Value)
    }
    deriving (Eq, Show)

instance FromRow OpsOrderOriginRow where
    fromRow = OpsOrderOriginRow <$> field <*> field <*> field <*> field <*> field <*> field

trimmedTextOrNothing :: Text -> Maybe Text
trimmedTextOrNothing raw =
    let trimmed = T.strip raw
     in if T.null trimmed then Nothing else Just trimmed

jsonValueToText :: Aeson.Value -> Maybe Text
jsonValueToText v =
    case v of
        Aeson.String t -> trimmedTextOrNothing t
        Aeson.Number n ->
            case (toBoundedInteger n :: Maybe Int64) of
                Just i -> Just (T.pack (show i))
                Nothing -> trimmedTextOrNothing (T.pack (formatScientific Fixed Nothing n))
        _ -> Nothing

jsonLookupPathText :: [AK.Key] -> Aeson.Value -> Maybe Text
jsonLookupPathText path v =
    case path of
        [] -> Nothing
        [k] ->
            case v of
                Aeson.Object o -> KM.lookup k o >>= jsonValueToText
                _ -> Nothing
        (k : ks) ->
            case v of
                Aeson.Object o ->
                    case KM.lookup k o of
                        Just next -> jsonLookupPathText ks next
                        Nothing -> Nothing
                _ -> Nothing

extractOriginIpFromOp :: Maybe Aeson.Value -> Maybe Text
extractOriginIpFromOp mVal =
    case mVal of
        Nothing -> Nothing
        Just v ->
            listToMaybe . catMaybes $
                [ jsonLookupPathText [AK.fromString "originIp"] v
                , jsonLookupPathText [AK.fromString "origin_ip"] v
                , jsonLookupPathText [AK.fromString "event", AK.fromString "originIp"] v
                , jsonLookupPathText [AK.fromString "order", AK.fromString "originIp"] v
                , jsonLookupPathText [AK.fromString "event", AK.fromString "order", AK.fromString "originIp"] v
                ]

extractOrderIdFromOp :: OpsOrderOriginRow -> Maybe Text
extractOrderIdFromOp row =
    let fromJson mVal =
            case mVal of
                Nothing -> Nothing
                Just v ->
                    listToMaybe . catMaybes $
                        [ jsonLookupPathText [AK.fromString "orderId"] v
                        , jsonLookupPathText [AK.fromString "order", AK.fromString "orderId"] v
                        , jsonLookupPathText [AK.fromString "event", AK.fromString "order", AK.fromString "orderId"] v
                        ]
     in normalizeMaybeText (oorOrderId row) <|> fromJson (oorResult row) <|> fromJson (oorParams row)

originIpFromRow :: OpsOrderOriginRow -> Maybe Text
originIpFromRow row = extractOriginIpFromOp (oorResult row) <|> extractOriginIpFromOp (oorParams row)

rowScore :: TenantKey -> OpsOrderOriginRow -> Maybe Text -> (Int, Int, Int, Int64)
rowScore tenantKey row mIp =
    let tenantRank =
            case normalizeMaybeText (oorTenantKey row) of
                Just t | t == tenantKey -> 1
                _ -> 0
        ipRank = if isJust mIp then 1 else 0
        kindRank =
            if oorKind row == "trade.order"
                then 1
                else 0
     in (ipRank, tenantRank, kindRank, oorId row)

attachBinanceTradeOriginIps :: OpsStore -> TenantKey -> [BinanceTrade] -> IO [BinanceTrade]
attachBinanceTradeOriginIps store tenantKey trades = do
    let orderIds =
            dedupeStable
                [ T.pack (show oid)
                | Just oid <- map btOrderId trades
                ]
    if null orderIds
        then pure trades
        else do
            rows <-
                withMVar (osLock store) $ \_ ->
                    query
                        (osConn store)
                        ( "SELECT id, tenant_key, kind, order_id, params_json, result_json "
                            <> "FROM ops "
                            <> "WHERE kind IN ('trade.order', 'bot.order') "
                            <> "AND (tenant_key = ? OR tenant_key IS NULL OR tenant_key = '') "
                            <> "AND ("
                            <> "order_id = ANY (?) "
                            <> "OR result_json ->> 'orderId' = ANY (?) "
                            <> "OR result_json #>> '{order,orderId}' = ANY (?) "
                            <> "OR result_json #>> '{event,order,orderId}' = ANY (?) "
                            <> "OR params_json ->> 'orderId' = ANY (?) "
                            <> "OR params_json #>> '{order,orderId}' = ANY (?) "
                            <> "OR params_json #>> '{event,order,orderId}' = ANY (?)"
                            <> ") "
                            <> "ORDER BY id DESC"
                        )
                        ( tenantKey
                        , PGArray orderIds
                        , PGArray orderIds
                        , PGArray orderIds
                        , PGArray orderIds
                        , PGArray orderIds
                        , PGArray orderIds
                        , PGArray orderIds
                        )
            let orderLookup = HM.fromList [(oid, ()) | oid <- orderIds]
                ipMapScored =
                    foldl'
                        ( \acc row ->
                            case extractOrderIdFromOp row of
                                Nothing -> acc
                                Just oid ->
                                    if not (HM.member oid orderLookup)
                                        then acc
                                        else
                                            let mIp = originIpFromRow row
                                                score = rowScore tenantKey row mIp
                                             in case HM.lookup oid acc of
                                                    Nothing -> HM.insert oid (score, mIp) acc
                                                    Just (prevScore, _prevIp) ->
                                                        if score > prevScore
                                                            then HM.insert oid (score, mIp) acc
                                                            else acc
                        )
                        HM.empty
                        rows
            let ipMap =
                    HM.fromList
                        [ (oid, ip)
                        | (oid, (_score, Just ip)) <- HM.toList ipMapScored
                        ]
                attachIp trade =
                    case btOriginIp trade of
                        Just _ -> trade
                        Nothing ->
                            case btOrderId trade of
                                Nothing -> trade
                                Just oid ->
                                    case HM.lookup (T.pack (show oid)) ipMap of
                                        Just ip -> trade{btOriginIp = Just ip}
                                        Nothing -> trade
            pure (map attachIp trades)

attachBinanceLogger :: Maybe OpsStore -> Maybe TenantKey -> BinanceEnv -> BinanceEnv
attachBinanceLogger mOps mTenantKey env =
    case mOps of
        Nothing -> env
        Just store -> env{beLogger = Just (binanceOpsLogger store mTenantKey)}

newBinanceEnvWithOps :: Maybe OpsStore -> BinanceMarket -> String -> Maybe BS.ByteString -> Maybe BS.ByteString -> IO BinanceEnv
newBinanceEnvWithOps mOps market baseUrl apiKey apiSecret =
    let mTenantKey = tenantKeyFromBinanceKeys (BS.unpack <$> apiKey) (BS.unpack <$> apiSecret)
     in attachBinanceLogger mOps mTenantKey <$> newBinanceEnv market baseUrl apiKey apiSecret

botStatusLogIntervalMs :: Int64
botStatusLogIntervalMs = 60000

botStatusLogMaybe :: Maybe OpsStore -> Bool -> BotState -> IO ()
botStatusLogMaybe mOps running st = do
    let args = botArgs st
        settings = botSettings st
        eq = vectorLastMaybe (botEquityCurve st)
        result =
            object
                [ "symbol" .= botSymbol st
                , "market" .= marketCode (argBinanceMarket args)
                , "interval" .= argInterval args
                , "running" .= running
                , "live" .= argBinanceLive args
                , "tradeEnabled" .= bsTradeEnabled settings
                , "protectionOrders" .= bsProtectionOrders settings
                , "halted" .= isJust (botHaltReason st)
                , "haltReason" .= botHaltReason st
                , "error" .= botError st
                , "updatedAtMs" .= botUpdatedAtMs st
                , "polledAtMs" .= botPolledAtMs st
                ]
    opsAppendMaybe
        mOps
        (Just (botTenantKey st))
        "bot.status"
        Nothing
        (Just (argsPublicJson args))
        (Just result)
        eq
        (activeBotComboUuid st)
        (Just (T.pack (botSymbol st)))
        Nothing
    persistBotSnapshotMaybe mOps running st result

persistBotSnapshotMaybe :: Maybe OpsStore -> Bool -> BotState -> Aeson.Value -> IO ()
persistBotSnapshotMaybe mOps running st statusJson =
    case mOps of
        Nothing -> pure ()
        Just store -> do
            _ <- try (persistBotSnapshot store running st statusJson) :: IO (Either SomeException ())
            pure ()

persistBotSnapshot :: OpsStore -> Bool -> BotState -> Aeson.Value -> IO ()
persistBotSnapshot store running st statusJson =
    withMVar (osLock store) $ \_ -> do
        let args = botArgs st
            tenantKey = botTenantKey st
            platformCodeText = normalizePlatformText (T.pack (platformCode (argPlatform args)))
            symbolRaw = T.pack (botSymbol st)
            mSymbolSanitized = sanitizeSymbolForPlatformText (Just platformCodeText) symbolRaw
            symbolText = fromMaybe symbolRaw mSymbolSanitized
            marketText = normalizeMarketText (T.pack (marketCode (argBinanceMarket args)))
            intervalText = T.pack (argInterval args)
            live = argBinanceLive args
            tradeEnabled = bsTradeEnabled (botSettings st)
            mComboUuid = botComboUuid st >>= uuidFromText
            argsJson = encodeJsonTextMaybe (Just (argsPublicJson args))
            statusJsonText = encodeJsonTextMaybe (Just statusJson)
            startedAt = botStartedAtMs st
            updatedAt = botUpdatedAtMs st
            conn = osConn store
        mPlatformId <- resolvePlatformId store conn platformCodeText
        case mPlatformId of
            Nothing -> pure ()
            Just platformId -> do
                mSymbolId <- case mSymbolSanitized of
                    Nothing -> pure Nothing
                    Just sym -> resolvePlatformSymbolId store conn platformCodeText platformId sym (Just marketText)
                rows <-
                    query
                        conn
                        ( "INSERT INTO bots (tenant_key, platform_id, symbol_id, symbol, market, interval, live, trade_enabled, running, combo_uuid, args_json, status_json, started_at_ms, updated_at_ms) "
                            <> "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?::jsonb, ?::jsonb, ?, ?) "
                            <> "ON CONFLICT (tenant_key, platform_id, symbol, market, interval) DO UPDATE "
                            <> "SET symbol_id = EXCLUDED.symbol_id, "
                            <> "live = EXCLUDED.live, "
                            <> "trade_enabled = EXCLUDED.trade_enabled, "
                            <> "running = EXCLUDED.running, "
                            <> "combo_uuid = COALESCE(EXCLUDED.combo_uuid, bots.combo_uuid), "
                            <> "args_json = EXCLUDED.args_json, "
                            <> "status_json = EXCLUDED.status_json, "
                            <> "updated_at_ms = EXCLUDED.updated_at_ms "
                            <> "RETURNING id"
                        )
                        ( tenantKey
                        , platformId
                        , mSymbolId
                        , symbolText
                        , marketText
                        , intervalText
                        , live
                        , tradeEnabled
                        , running
                        , mComboUuid
                        , argsJson
                        , statusJsonText
                        , startedAt
                        , updatedAt
                        )
                case rows of
                    (Only botId : _) -> persistBotPosition conn botId platformId mSymbolId symbolText marketText st
                    _ -> pure ()

persistBotPosition :: Connection -> Int64 -> Int -> Maybe Int64 -> Text -> Text -> BotState -> IO ()
persistBotPosition conn botId platformId mSymbolId symbolText marketText st = do
    let pos = vectorLastOr 0 (botPositions st)
        mSide
            | pos > 0 = Just ("long" :: Text)
            | pos < 0 = Just ("short" :: Text)
            | otherwise = Nothing
        mOpenTrade = botOpenTrade st
        mEntryPrice = botOpenEntryPrice <$> mOpenTrade
        markPrice = lsCurrentPrice (botLatestSignal st)
        openTime =
            case mOpenTrade of
                Nothing -> Nothing
                Just trade ->
                    let idx = botOpenEntryIndex trade
                        times = botOpenTimes st
                     in if idx >= 0 && idx < V.length times
                            then Just (times V.! idx)
                            else Nothing
        positionJson =
            object
                [ "position" .= pos
                , "openTrade" .= fmap botOpenTradeJson mOpenTrade
                , "currentPrice" .= markPrice
                , "updatedAtMs" .= botUpdatedAtMs st
                ]
        positionJsonText = encodeJsonTextMaybe (Just positionJson)
    case mSide of
        Nothing -> do
            _ <- execute conn "DELETE FROM positions WHERE bot_id = ?" (Only botId)
            pure ()
        Just side -> do
            _ <-
                execute
                    conn
                    ( "INSERT INTO positions (platform_id, symbol_id, bot_id, symbol, market, side, quantity, entry_price, mark_price, position_json, opened_at_ms, updated_at_ms) "
                        <> "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?::jsonb, ?, ?) "
                        <> "ON CONFLICT (bot_id) DO UPDATE "
                        <> "SET symbol_id = EXCLUDED.symbol_id, "
                        <> "symbol = EXCLUDED.symbol, "
                        <> "market = EXCLUDED.market, "
                        <> "side = EXCLUDED.side, "
                        <> "quantity = EXCLUDED.quantity, "
                        <> "entry_price = EXCLUDED.entry_price, "
                        <> "mark_price = EXCLUDED.mark_price, "
                        <> "position_json = EXCLUDED.position_json, "
                        <> "opened_at_ms = EXCLUDED.opened_at_ms, "
                        <> "updated_at_ms = EXCLUDED.updated_at_ms"
                    )
                    ( platformId
                    , mSymbolId
                    , botId
                    , symbolText
                    , marketText
                    , side
                    , fromIntegral pos :: Double
                    , mEntryPrice
                    , markPrice
                    , positionJsonText
                    , openTime
                    , botUpdatedAtMs st
                    )
            pure ()

botOpenTradeJson :: BotOpenTrade -> Aeson.Value
botOpenTradeJson trade =
    object
        [ "entryIndex" .= botOpenEntryIndex trade
        , "entryEquity" .= botOpenEntryEquity trade
        , "entryIp" .= botOpenEntryIp trade
        , "comboUuid" .= botOpenComboUuid trade
        , "entryHighVolProb" .= botOpenEntryHighVolProb trade
        , "holdingPeriods" .= botOpenHoldingPeriods trade
        , "entryPrice" .= botOpenEntryPrice trade
        , "trail" .= botOpenTrail trade
        , "size" .= botOpenSize trade
        , "partialTaken" .= botOpenPartialTaken trade
        , "side" .= positionSideLabel (botOpenSide trade)
        ]

botOpenTradeComboUuidMaybe :: Maybe BotOpenTrade -> Maybe Text
botOpenTradeComboUuidMaybe mTrade =
    mTrade >>= botOpenComboUuid

activeBotComboUuid :: BotState -> Maybe Text
activeBotComboUuid st =
    activeComboUuid (botOpenTradeComboUuidMaybe (botOpenTrade st)) (botComboUuid st)

positionSideLabel :: PositionSide -> Text
positionSideLabel side =
    case side of
        SideLong -> "long"
        SideShort -> "short"

persistBinancePositionsMaybe :: Maybe OpsStore -> BinanceMarket -> [FuturesPositionRisk] -> IO ()
persistBinancePositionsMaybe mOps market positions =
    case mOps of
        Nothing -> pure ()
        Just store -> do
            _ <- try (persistBinancePositions store market positions) :: IO (Either SomeException ())
            pure ()

persistBinancePositions :: OpsStore -> BinanceMarket -> [FuturesPositionRisk] -> IO ()
persistBinancePositions store market positions =
    withMVar (osLock store) $ \_ -> do
        let platformCodeText = "binance"
            marketText = normalizeMarketText (T.pack (marketCode market))
            conn = osConn store
        now <- getTimestampMs
        mPlatformId <- resolvePlatformId store conn platformCodeText
        case mPlatformId of
            Nothing -> pure ()
            Just platformId -> do
                _ <- execute conn "DELETE FROM positions WHERE bot_id IS NULL AND platform_id = ? AND market = ?" (platformId, marketText)
                forM_ positions $ \pos -> do
                    let symbolRaw = T.pack (fprSymbol pos)
                        mSymbolSanitized = sanitizeSymbolForPlatformText (Just platformCodeText) symbolRaw
                        symbolText = fromMaybe symbolRaw mSymbolSanitized
                        sideText :: Text
                        sideText =
                            case fmap normalizeKey (fprPositionSide pos) of
                                Just "short" -> "short"
                                Just "long" -> "long"
                                _ ->
                                    if fprPositionAmt pos < 0
                                        then "short"
                                        else "long"
                        positionJson =
                            object
                                [ "symbol" .= fprSymbol pos
                                , "positionAmt" .= fprPositionAmt pos
                                , "entryPrice" .= fprEntryPrice pos
                                , "markPrice" .= fprMarkPrice pos
                                , "unrealizedPnl" .= fprUnrealizedProfit pos
                                , "liquidationPrice" .= fprLiquidationPrice pos
                                , "breakEvenPrice" .= fprBreakEvenPrice pos
                                , "leverage" .= fprLeverage pos
                                , "marginType" .= fprMarginType pos
                                , "positionSide" .= fprPositionSide pos
                                ]
                        positionJsonText = encodeJsonTextMaybe (Just positionJson)
                    mSymbolId <- case mSymbolSanitized of
                        Nothing -> pure Nothing
                        Just sym -> resolvePlatformSymbolId store conn platformCodeText platformId sym (Just marketText)
                    _ <-
                        execute
                            conn
                            ( "INSERT INTO positions (platform_id, symbol_id, bot_id, symbol, market, side, quantity, entry_price, mark_price, leverage, pnl_unrealized, position_json, opened_at_ms, updated_at_ms) "
                                <> "VALUES (?, ?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?::jsonb, NULL, ?) "
                            )
                            ( platformId
                            , mSymbolId
                            , symbolText
                            , marketText
                            , sideText
                            , fprPositionAmt pos
                            , fprEntryPrice pos
                            , fprMarkPrice pos
                            , fprLeverage pos
                            , fprUnrealizedProfit pos
                            , positionJsonText
                            , now
                            )
                    pure ()

data ComboParamsRow = ComboParamsRow
    { cprFinalEquity :: !(Maybe Double)
    , cprObjective :: !(Maybe Text)
    , cprSource :: !(Maybe Text)
    , cprScore :: !(Maybe Double)
    , cprOpenThreshold :: !(Maybe Double)
    , cprCloseThreshold :: !(Maybe Double)
    , cprParams :: !(Maybe Text)
    , cprMetrics :: !(Maybe Text)
    }
    deriving (Eq, Show)

instance FromRow ComboParamsRow where
    fromRow =
        ComboParamsRow
            <$> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field
            <*> field

comboParamsRowToTopCombo :: UUID.UUID -> ComboParamsRow -> Maybe TopCombo
comboParamsRowToTopCombo uuid row = do
    paramsVal <- decodeJsonTextMaybe (cprParams row)
    paramsObj <- case paramsVal of
        Aeson.Object o -> Just o
        _ -> Nothing
    let metricsObj =
            case decodeJsonTextMaybe (cprMetrics row) of
                Just (Aeson.Object o) -> Just o
                _ -> Nothing
    pure
        TopCombo
            { tcRank = Nothing
            , tcFinalEquity = cprFinalEquity row
            , tcObjectiveLabel = T.unpack <$> cprObjective row
            , tcScore = cprScore row
            , tcOpenThreshold = cprOpenThreshold row
            , tcCloseThreshold = cprCloseThreshold row
            , tcUuid = Just (uuidToText uuid)
            , tcSource = normalizedTopComboSource (T.unpack <$> cprSource row)
            , tcParams = paramsObj
            , tcMetrics = metricsObj
            }

readTopComboByUuidFromDb :: OpsStore -> UUID.UUID -> IO (Maybe TopCombo)
readTopComboByUuidFromDb store comboUuid =
    withMVar (osLock store) $ \_ -> do
        rows <-
            query
                (osConn store)
                "SELECT final_equity, objective, source, score, open_threshold, close_threshold, params_json::text, metrics_json::text FROM combos WHERE combo_uuid = ?"
                (Only comboUuid) ::
                IO [ComboParamsRow]
        pure (listToMaybe (mapMaybe (comboParamsRowToTopCombo comboUuid) rows))

data PositionOrigin = PositionOrigin
    { poriSide :: !Text
    , poriComboUuid :: !(Maybe UUID.UUID)
    , poriOpenedAtMs :: !(Maybe Int64)
    , poriOrderId :: !(Maybe Text)
    }
    deriving (Eq, Show)

instance FromRow PositionOrigin where
    fromRow =
        PositionOrigin
            <$> field
            <*> field
            <*> field
            <*> field

positionOriginSideFromSign :: Int -> Maybe Text
positionOriginSideFromSign pos
    | pos > 0 = Just "long"
    | pos < 0 = Just "short"
    | otherwise = Nothing

readPositionOrigin :: OpsStore -> TenantKey -> Args -> String -> IO (Maybe PositionOrigin)
readPositionOrigin store tenantKey args sym = do
    let platformCodeText = normalizePlatformText (T.pack (platformCode (argPlatform args)))
        marketText = normalizeMarketText (T.pack (marketCode (argBinanceMarket args)))
        symbolRaw = T.pack sym
        symbolText = fromMaybe symbolRaw (sanitizeSymbolForPlatformText (Just platformCodeText) symbolRaw)
    withMVar (osLock store) $ \_ -> do
        let conn = osConn store
        mPlatformId <- resolvePlatformId store conn platformCodeText
        case mPlatformId of
            Nothing -> pure Nothing
            Just platformId -> do
                rows <-
                    query
                        conn
                        "SELECT side, combo_uuid, opened_at_ms, order_id FROM position_origins WHERE tenant_key = ? AND platform_id = ? AND symbol = ? AND market = ?"
                        (tenantKey, platformId, symbolText, marketText) ::
                        IO [PositionOrigin]
                pure (listToMaybe rows)

deletePositionOrigin :: OpsStore -> TenantKey -> Args -> String -> IO ()
deletePositionOrigin store tenantKey args sym = do
    let platformCodeText = normalizePlatformText (T.pack (platformCode (argPlatform args)))
        marketText = normalizeMarketText (T.pack (marketCode (argBinanceMarket args)))
        symbolRaw = T.pack sym
        symbolText = fromMaybe symbolRaw (sanitizeSymbolForPlatformText (Just platformCodeText) symbolRaw)
    withMVar (osLock store) $ \_ -> do
        let conn = osConn store
        mPlatformId <- resolvePlatformId store conn platformCodeText
        case mPlatformId of
            Nothing -> pure ()
            Just platformId -> do
                void $
                    execute
                        conn
                        "DELETE FROM position_origins WHERE tenant_key = ? AND platform_id = ? AND symbol = ? AND market = ?"
                        (tenantKey, platformId, symbolText, marketText)

persistPositionOriginMaybe ::
    Maybe OpsStore ->
    TenantKey ->
    Args ->
    String ->
    Int ->
    Maybe Text ->
    Maybe Text ->
    Int64 ->
    IO ()
persistPositionOriginMaybe mOps tenantKey args sym posSign mComboUuid mOrderId atMs =
    case mOps of
        Nothing -> pure ()
        Just store -> do
            let platformCodeText = normalizePlatformText (T.pack (platformCode (argPlatform args)))
                marketText = normalizeMarketText (T.pack (marketCode (argBinanceMarket args)))
                symbolRaw = T.pack sym
                symbolText = fromMaybe symbolRaw (sanitizeSymbolForPlatformText (Just platformCodeText) symbolRaw)
                mSide = positionOriginSideFromSign posSign
                mComboUuid' = mComboUuid >>= uuidFromText
                mOrderId' = normalizeMaybeText mOrderId
            withMVar (osLock store) $ \_ -> do
                let conn = osConn store
                mPlatformId <- resolvePlatformId store conn platformCodeText
                case mPlatformId of
                    Nothing -> pure ()
                    Just platformId ->
                        case mSide of
                            Nothing -> do
                                void $
                                    execute
                                        conn
                                        "DELETE FROM position_origins WHERE tenant_key = ? AND platform_id = ? AND symbol = ? AND market = ?"
                                        (tenantKey, platformId, symbolText, marketText)
                            Just side -> do
                                void $
                                    execute
                                        conn
                                        ( "INSERT INTO position_origins (tenant_key, platform_id, symbol, market, side, combo_uuid, opened_at_ms, order_id, updated_at_ms) "
                                            <> "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) "
                                            <> "ON CONFLICT (tenant_key, platform_id, symbol, market) DO UPDATE "
                                            <> "SET side = EXCLUDED.side, "
                                            <> "combo_uuid = EXCLUDED.combo_uuid, "
                                            <> "opened_at_ms = EXCLUDED.opened_at_ms, "
                                            <> "order_id = EXCLUDED.order_id, "
                                            <> "updated_at_ms = EXCLUDED.updated_at_ms"
                                        )
                                        (tenantKey, platformId, symbolText, marketText, side, mComboUuid', atMs, mOrderId', atMs)

