    mkFeatureInputs
        (botPrices st)
        (Just (botOpens st))
        (Just (botHighs st))
        (Just (botLows st))
        (Just (botVolumes st))

newBotController :: IO BotController
newBotController = BotController <$> newMVar HM.empty

emptyBotAdjustments :: BotAdjustments
emptyBotAdjustments = BotAdjustments 0 0 0 0

emptyBotPerfStats :: Int -> BotPerfStats
emptyBotPerfStats lookback =
    BotPerfStats
        { bpsLookback = max 0 lookback
        , bpsTrades = 0
        , bpsWins = 0
        , bpsLosses = 0
        , bpsWinRate = 0
        , bpsProfitFactor = Nothing
        , bpsExpectancy = 0
        }

computeBotPerfStats :: Int -> [Trade] -> BotPerfStats
computeBotPerfStats lookback trades =
    let lb = max 0 lookback
        recent = if lb <= 0 then [] else take lb (reverse trades)
        bad x = isNaN x || isInfinite x
        returns = [trReturn t | t <- recent, not (bad (trReturn t))]
        wins = length [r | r <- returns, r > 0]
        losses = length [r | r <- returns, r < 0]
        winRate =
            if wins + losses == 0
                then 0
                else fromIntegral wins / fromIntegral (wins + losses)
        grossWin = sum [r | r <- returns, r > 0]
        grossLoss = abs (sum [r | r <- returns, r < 0])
        profitFactor
            | grossLoss > 0 = Just (grossWin / grossLoss)
            | grossWin > 0 = Nothing
            | otherwise = Just 0
        expectancy =
            if null returns
                then 0
                else sum returns / fromIntegral (length returns)
     in BotPerfStats
            { bpsLookback = lb
            , bpsTrades = length recent
            , bpsWins = wins
            , bpsLosses = losses
            , bpsWinRate = winRate
            , bpsProfitFactor = profitFactor
            , bpsExpectancy = expectancy
            }

highVolCutoff :: Double
highVolCutoff = 0.6

botCurrentHighVolFlag :: LatestSignal -> Maybe Bool
botCurrentHighVolFlag sig =
    case lsRegimes sig of
        Nothing -> Nothing
        Just r -> Just (rpHighVol r >= highVolCutoff)

tradeEntryHighVolFlag :: Trade -> Maybe Bool
tradeEntryHighVolFlag tr =
    case trEntryHighVolProb tr of
        Nothing -> Nothing
        Just hv -> Just (hv >= highVolCutoff)

computeBotPerfStatsFiltered :: Int -> (Trade -> Bool) -> [Trade] -> BotPerfStats
computeBotPerfStatsFiltered lookback keep trades =
    let lb = max 0 lookback
        recent = if lb <= 0 then [] else take lb (reverse (filter keep trades))
        bad x = isNaN x || isInfinite x
        returns = [trReturn t | t <- recent, not (bad (trReturn t))]
        wins = length [r | r <- returns, r > 0]
        losses = length [r | r <- returns, r < 0]
        winRate =
            if wins + losses == 0
                then 0
                else fromIntegral wins / fromIntegral (wins + losses)
        grossWin = sum [r | r <- returns, r > 0]
        grossLoss = abs (sum [r | r <- returns, r < 0])
        profitFactor
            | grossLoss > 0 = Just (grossWin / grossLoss)
            | grossWin > 0 = Nothing
            | otherwise = Just 0
        expectancy =
            if null returns
                then 0
                else sum returns / fromIntegral (length returns)
     in BotPerfStats
            { bpsLookback = lb
            , bpsTrades = length recent
            , bpsWins = wins
            , bpsLosses = losses
            , bpsWinRate = winRate
            , bpsProfitFactor = profitFactor
            , bpsExpectancy = expectancy
            }

data PerfGateMode
    = PerfGateGlobal
    | PerfGateRegimeHighVol
    | PerfGateRegimeLowVol
    deriving (Eq, Show)

perfGateModeLabel :: PerfGateMode -> String
perfGateModeLabel mode =
    case mode of
        PerfGateGlobal -> "GLOBAL"
        PerfGateRegimeHighVol -> "REGIME_HIGH_VOL"
        PerfGateRegimeLowVol -> "REGIME_LOW_VOL"

selectPerfStatsForPerfGate :: Args -> LatestSignal -> BotPerfStats -> [Trade] -> (BotPerfStats, PerfGateMode)
selectPerfStatsForPerfGate args sig statsAll trades =
    let lb = max 0 (argPerfLookback args)
        mHighVolNow = botCurrentHighVolFlag sig
     in case mHighVolNow of
            Nothing -> (statsAll, PerfGateGlobal)
            Just wantHigh ->
                let statsRegime = computeBotPerfStatsFiltered lb (\tr -> tradeEntryHighVolFlag tr == Just wantHigh) trades
                    ready = lb > 0 && bpsTrades statsRegime >= lb
                    mode =
                        if wantHigh
                            then PerfGateRegimeHighVol
                            else PerfGateRegimeLowVol
                 in if ready then (statsRegime, mode) else (statsAll, PerfGateGlobal)

perfGateReason :: Args -> BotPerfStats -> Maybe String
perfGateReason args stats =
    let lookback = max 0 (argPerfLookback args)
        ready = lookback > 0 && bpsTrades stats >= lookback
        minWin = argPerfMinWinRate args
        minPf = argPerfMinProfitFactor args
        winOk =
            case minWin of
                Just v | v > 0 -> bpsWinRate stats >= v
                _ -> True
        pfOk =
            case minPf of
                Just v | v > 0 ->
                    case bpsProfitFactor stats of
                        Nothing -> True
                        Just pf -> pf >= v
                _ -> True
     in if not ready
            then Nothing
            else
                if not winOk
                    then Just "PERF_WIN_RATE"
                    else
                        if not pfOk
                            then Just "PERF_PROFIT_FACTOR"
                            else Nothing

clamp01 :: Double -> Double
clamp01 x = max 0 (min 1 x)

isFiniteDouble :: Double -> Bool
isFiniteDouble x = not (isNaN x || isInfinite x)

neutralPredFromPrev :: Double -> Double
neutralPredFromPrev prev =
    if isFiniteDouble prev
        then prev
        else 0

finiteBlendOrNeutral :: Double -> Double -> Double -> Double -> Double
finiteBlendOrNeutral weight prev kalPred lstmPred =
    let w = clamp01 weight
        blended = w * kalPred + (1 - w) * lstmPred
     in if isFiniteDouble blended
            then blended
            else neutralPredFromPrev prev

blendPredFromPreds :: Double -> Double -> Double -> Double -> Double
blendPredFromPreds fallbackWeight prev kalPred lstmPred =
    let bad x = isNaN x || isInfinite x
        w = clamp01 fallbackWeight
     in case (bad kalPred, bad lstmPred) of
            (False, False) -> finiteBlendOrNeutral w prev kalPred lstmPred
            (False, True) -> kalPred
            (True, False) -> lstmPred
            (True, True) -> neutralPredFromPrev prev

blendPredictionsV :: Double -> V.Vector Double -> V.Vector Double -> V.Vector Double -> V.Vector Double
blendPredictionsV fallbackWeight pricesV kalPredV lstmPredV =
    let stepCount = minimum [V.length pricesV - 1, V.length kalPredV, V.length lstmPredV]
        pick t =
            let prev = pricesV V.! t
                kalPred = kalPredV V.! t
                lstmPred = lstmPredV V.! t
             in blendPredFromPreds fallbackWeight prev kalPred lstmPred
     in V.generate (max 0 stepCount) pick

computeAdaptiveAdjustments :: Args -> BotPerfStats -> BotAdjustments
computeAdaptiveAdjustments args stats =
    let lookback = max 0 (argPerfLookback args)
        ready = lookback > 0 && bpsTrades stats >= lookback
        -- When adaptive filters are enabled, tighten gradually *before* the hard perf gate fails.
        -- Win-rate tightening starts at (minWinRate + 0.05) and reaches full strictness at minWinRate.
        -- Profit-factor tightening starts at (minPF * 1.10) and reaches full strictness at minPF.
        winScore =
            case argPerfMinWinRate args of
                Just v
                    | v > 0 ->
                        let slack = 0.05
                            start = min 1 (v + slack)
                            denom = max 1e-12 (start - v)
                            raw = (start - bpsWinRate stats) / denom
                         in clamp01 raw
                _ -> 0
        pfScore =
            case argPerfMinProfitFactor args of
                Just v
                    | v > 0 ->
                        let start = v * 1.10
                            denom = max 1e-12 (start - v)
                            pfVal = fromMaybe start (bpsProfitFactor stats)
                            raw = (start - pfVal) / denom
                         in clamp01 raw
                _ -> 0
        strictness =
            if argAdaptiveFilters args && ready
                then max winScore pfScore
                else 0
        edgeAdd = strictness * max 0 (argAdaptiveEdgeBufferMax args)
        snrAdd = strictness * max 0 (argAdaptiveMinSignalToNoiseMax args)
        zAdd = strictness * max 0 (argAdaptiveKalmanZMinMax args)
        trendAdd = round (strictness * fromIntegral (max 0 (argAdaptiveTrendLookbackMax args)))
     in BotAdjustments
            { baEdgeBufferAdd = edgeAdd
            , baMinSignalToNoiseAdd = snrAdd
            , baKalmanZMinAdd = zAdd
            , baTrendLookbackAdd = trendAdd
            }

applyBotAdjustments :: BotAdjustments -> Args -> Args
applyBotAdjustments adj args =
    args
        { argEdgeBuffer = argEdgeBuffer args + baEdgeBufferAdd adj
        , argMinSignalToNoise = argMinSignalToNoise args + baMinSignalToNoiseAdd adj
        , argKalmanZMin = argKalmanZMin args + baKalmanZMinAdd adj
        , argTrendLookback = argTrendLookback args + baTrendLookbackAdd adj
        }

clampInt :: Int -> Int -> Int -> Int
clampInt lo hi n = max lo (min hi n)

defaultBotPollSeconds :: Args -> Int
defaultBotPollSeconds args =
    case parseIntervalSeconds (argInterval args) of
        Nothing -> 10
        Just sec ->
            let half = max 1 (sec `div` 2)
             in clampInt 5 60 half

defaultBotSettings :: Args -> BotSettings
defaultBotSettings args =
    BotSettings
        { bsPollSeconds = defaultBotPollSeconds args
        , bsOnlineEpochs = 1
        , bsTrainBars = 800
        , bsMaxPoints = 2000
        , bsTradeEnabled = True
        , bsProtectionOrders = False
        , bsAdoptExistingPosition = True
        }

botSettingsFromApi :: Args -> ApiParams -> Either String BotSettings
botSettingsFromApi args p = do
    let poll = fromMaybe (defaultBotPollSeconds args) (apBotPollSeconds p)
        onlineEpochs = fromMaybe 1 (apBotOnlineEpochs p)
        trainBars = fromMaybe 800 (apBotTrainBars p)
        maxPoints = fromMaybe 2000 (apBotMaxPoints p)
        tradeEnabled = fromMaybe True (apBotTrade p)
        protectionOrders = fromMaybe False (apBotProtectionOrders p)
        adoptExistingPosition = True

    ensure "botPollSeconds must be between 1 and 3600" (poll >= 1 && poll <= 3600)
    ensure "botOnlineEpochs must be between 0 and 50" (onlineEpochs >= 0 && onlineEpochs <= 50)
    ensure "botTrainBars must be >= 10" (trainBars >= 10)
    ensure "botMaxPoints must be between 100 and 100000" (maxPoints >= 100 && maxPoints <= 100000)

    pure
        BotSettings
            { bsPollSeconds = poll
            , bsOnlineEpochs = onlineEpochs
            , bsTrainBars = trainBars
            , bsMaxPoints = maxPoints
            , bsTradeEnabled = tradeEnabled
            , bsProtectionOrders = protectionOrders
            , bsAdoptExistingPosition = adoptExistingPosition
            }
  where
    ensure :: String -> Bool -> Either String ()
    ensure msg cond = if cond then Right () else Left msg

botStatusJson :: BotState -> Aeson.Value
botStatusJson st =
    let finiteMaybe x =
            if isNaN x || isInfinite x
                then Nothing
                else Just x

        argsBase = botArgs st
        argsAdjusted = applyBotAdjustments (botAdjustments st) argsBase
        perfAll = botPerfStats st
        (perfGate, perfMode) =
            selectPerfStatsForPerfGate argsBase (botLatestSignal st) perfAll (botTrades st)
        perfJson =
            object
                [ "mode" .= perfGateModeLabel perfMode
                , "lookback" .= bpsLookback perfGate
                , "trades" .= bpsTrades perfGate
                , "wins" .= bpsWins perfGate
                , "losses" .= bpsLosses perfGate
                , "winRate" .= bpsWinRate perfGate
                , "profitFactor" .= bpsProfitFactor perfGate
                , "expectancy" .= bpsExpectancy perfGate
                , "lossStreak" .= botLossStreak st
                , "gateReason" .= perfGateReason argsBase perfGate
                , "all"
                    .= object
                        [ "lookback" .= bpsLookback perfAll
                        , "trades" .= bpsTrades perfAll
                        , "wins" .= bpsWins perfAll
                        , "losses" .= bpsLosses perfAll
                        , "winRate" .= bpsWinRate perfAll
                        , "profitFactor" .= bpsProfitFactor perfAll
                        , "expectancy" .= bpsExpectancy perfAll
                        , "gateReason" .= perfGateReason argsBase perfAll
                        ]
                ]
        adj = botAdjustments st
        adaptiveJson =
            object
                [ "enabled" .= argAdaptiveFilters argsBase
                , "edgeBuffer" .= argEdgeBuffer argsAdjusted
                , "minSignalToNoise" .= argMinSignalToNoise argsAdjusted
                , "kalmanZMin" .= argKalmanZMin argsAdjusted
                , "trendLookback" .= argTrendLookback argsAdjusted
                , "adjustments"
                    .= object
                        [ "edgeBufferAdd" .= baEdgeBufferAdd adj
                        , "minSignalToNoiseAdd" .= baMinSignalToNoiseAdd adj
                        , "kalmanZMinAdd" .= baKalmanZMinAdd adj
                        , "trendLookbackAdd" .= baTrendLookbackAdd adj
                        ]
                ]

        klineJson k =
            object
                [ "openTime" .= kOpenTime k
                , "open" .= kOpen k
                , "high" .= kHigh k
                , "low" .= kLow k
                , "close" .= kClose k
                , "volume" .= kVolume k
                ]
     in object $
            [ "running" .= True
            , "symbol" .= botSymbol st
            , "tenantKey" .= botTenantKey st
            , "interval" .= argInterval (botArgs st)
            , "market" .= marketCode (argBinanceMarket (botArgs st))
            , "method" .= methodCode (argMethod (botArgs st))
            , "threshold" .= argOpenThreshold (botArgs st)
            , "openThreshold" .= argOpenThreshold (botArgs st)
            , "closeThreshold" .= argCloseThreshold (botArgs st)
            , "settings"
                .= object
                    [ "pollSeconds" .= bsPollSeconds (botSettings st)
                    , "onlineEpochs" .= bsOnlineEpochs (botSettings st)
                    , "trainBars" .= bsTrainBars (botSettings st)
                    , "maxPoints" .= bsMaxPoints (botSettings st)
                    , "tradeEnabled" .= bsTradeEnabled (botSettings st)
                    , "protectionOrders" .= bsProtectionOrders (botSettings st)
                    , "adoptExistingPosition" .= bsAdoptExistingPosition (botSettings st)
                    ]
            , "startIndex" .= botStartIndex st
            , "startedAtMs" .= botStartedAtMs st
            , "updatedAtMs" .= botUpdatedAtMs st
            , "polledAtMs" .= botPolledAtMs st
            , "pollLatencyMs" .= botPollLatencyMs st
            , "fetchedKlines" .= botFetchedKlines st
            , "lastBatchAtMs" .= botLastBatchAtMs st
            , "lastBatchSize" .= botLastBatchSize st
            , "lastBatchMs" .= botLastBatchMs st
            , "halted" .= isJust (botHaltReason st)
            , "peakEquity" .= botPeakEquity st
            , "dayStartEquity" .= botDayStartEquity st
            , "weekStartEquity" .= botWeekStartEquity st
            , "dayTrades" .= botDayTrades st
            , "consecutiveOrderErrors" .= botConsecutiveOrderErrors st
            , "cooldownLeft" .= botCooldownLeft st
            , "prices" .= V.toList (botPrices st)
            , "openTimes" .= V.toList (botOpenTimes st)
            , "kalmanPredNext" .= map finiteMaybe (V.toList (botKalmanPredNext st))
            , "lstmPredNext" .= map finiteMaybe (V.toList (botLstmPredNext st))
            , "equityCurve" .= V.toList (botEquityCurve st)
            , "positions" .= V.toList (botPositions st)
            , "operations" .= botOps st
            , "orders" .= botOrders st
            , "trades" .= map tradeToJson (botTrades st)
            , "openTrade" .= fmap botOpenTradeJson (botOpenTrade st)
            , "performance" .= perfJson
            , "adaptive" .= adaptiveJson
            , "latestSignal" .= botLatestSignal st
            ]
                ++ maybe [] (\o -> ["lastOrder" .= o]) (botLastOrder st)
                ++ maybe [] (\k -> ["fetchedLastKline" .= klineJson k]) (botFetchedLastKline st)
                ++ maybe [] (\r -> ["haltReason" .= r]) (botHaltReason st)
                ++ maybe [] (\t -> ["haltedAtMs" .= t]) (botHaltedAtMs st)
                ++ maybe [] (\e -> ["error" .= e]) (botError st)

botStateTail :: Int -> BotState -> BotState
botStateTail tailN st =
    let n = V.length (botPrices st)
        t = max 0 tailN
        dropCount = max 0 (n - t)
     in if dropCount <= 0
            then st
            else
                let shiftTrade tr =
                        tr{trEntryIndex = trEntryIndex tr - dropCount, trExitIndex = trExitIndex tr - dropCount}
                    tradesShifted =
                        [ shiftTrade tr
                        | tr <- botTrades st
                        , trEntryIndex tr >= dropCount
                        , trExitIndex tr >= dropCount
                        ]
                    opsShifted =
                        [ op{boIndex = boIndex op - dropCount}
                        | op <- botOps st
                        , boIndex op >= dropCount
                        ]
                    ordersShifted =
                        [ e{boeIndex = boeIndex e - dropCount}
                        | e <- botOrders st
                        , boeIndex e >= dropCount
                        ]
                    openTradeShifted =
                        case botOpenTrade st of
                            Nothing -> Nothing
                            Just ot -> Just (shiftOpenTradeIndex dropCount ot)
                 in st
                        { botPrices = V.drop dropCount (botPrices st)
                        , botOpens = V.drop dropCount (botOpens st)
                        , botHighs = V.drop dropCount (botHighs st)
                        , botLows = V.drop dropCount (botLows st)
                        , botVolumes = V.drop dropCount (botVolumes st)
                        , botOpenTimes = V.drop dropCount (botOpenTimes st)
                        , botKalmanPredNext = V.drop dropCount (botKalmanPredNext st)
                        , botLstmPredNext = V.drop dropCount (botLstmPredNext st)
                        , botEquityCurve = V.drop dropCount (botEquityCurve st)
                        , botPositions = V.drop dropCount (botPositions st)
                        , botOps = opsShifted
                        , botOrders = ordersShifted
                        , botTrades = tradesShifted
                        , botOpenTrade = openTradeShifted
                        , botStartIndex = botStartIndex st + dropCount
                        }

shiftOpenTradeIndex :: Int -> BotOpenTrade -> BotOpenTrade
shiftOpenTradeIndex dropCount ot =
    ot{botOpenEntryIndex = max 0 (botOpenEntryIndex ot - dropCount)}

positionChangeCount :: [Int] -> Int
positionChangeCount positions =
    case positions of
        [] -> 0
        (p0 : rest) ->
            snd (foldl' (\(prev, acc) cur -> (cur, if cur == prev then acc else acc + 1)) (p0, 0) rest)

lastMaybe :: [a] -> Maybe a
lastMaybe = foldl' (\_ x -> Just x) Nothing

vectorLastMaybe :: V.Vector a -> Maybe a
vectorLastMaybe v =
    if V.null v
        then Nothing
        else Just (V.last v)

vectorLastOr :: a -> V.Vector a -> a
vectorLastOr fallback = fromMaybe fallback . vectorLastMaybe

botBacktestResultFromState :: BotState -> BacktestResult
botBacktestResultFromState st =
    let eq = V.toList (botEquityCurve st)
        posAll = botPositions st
        posForMetrics = V.toList (V.take (max 0 (V.length posAll - 1)) posAll)
        posChanges = positionChangeCount (V.toList posAll)
     in BacktestResult
            { brEquityCurve = eq
            , brPositions = map fromIntegral posForMetrics
            , brAgreementOk = []
            , brAgreementValid = []
            , brPositionChanges = posChanges
            , brTrades = botTrades st
            }

botMetricsFromState :: BotState -> BacktestMetrics
botMetricsFromState st =
    computeMetrics (periodsPerYear (botArgs st)) (botBacktestResultFromState st)

botStartingJson :: BotStartRuntime -> Aeson.Value
botStartingJson rt =
    object
        [ "running" .= False
        , "starting" .= True
        , "startingReason" .= bsrStartReason rt
        , "symbol" .= bsrSymbol rt
        , "tenantKey" .= bsrTenantKey rt
        , "interval" .= argInterval (bsrArgs rt)
        , "market" .= marketCode (argBinanceMarket (bsrArgs rt))
        , "method" .= methodCode (argMethod (bsrArgs rt))
        , "threshold" .= argOpenThreshold (bsrArgs rt)
        , "openThreshold" .= argOpenThreshold (bsrArgs rt)
        , "closeThreshold" .= argCloseThreshold (bsrArgs rt)
        , "startedAtMs" .= bsrRequestedAtMs rt
        ]

botStartReasonFromAdopt :: AdoptRequirement -> String
botStartReasonFromAdopt req =
    if arActive req
        then "Adopting existing positions or orders."
        else "Initializing model."

botStoppedJson :: Aeson.Value
botStoppedJson =
    object
        [ "running" .= False
        ]

botStatusJsonMulti :: [Aeson.Value] -> Aeson.Value
botStatusJsonMulti bots =
    let running = any isRunning bots
        starting = any isStarting bots
     in object
            [ "running" .= running
            , "starting" .= starting
            , "multi" .= True
            , "bots" .= bots
            ]
  where
    isRunning v =
        case v of
            Aeson.Object o -> KM.lookup "running" o == Just (Aeson.Bool True)
            _ -> False
    isStarting v =
        case v of
            Aeson.Object o -> KM.lookup "starting" o == Just (Aeson.Bool True)
            _ -> False

data BotStatusSnapshot = BotStatusSnapshot
    { bssSavedAtMs :: !Int64
    , bssStatus :: !Aeson.Value
    }
    deriving (Eq, Show, Generic)

instance ToJSON BotStatusSnapshot where
    toJSON = Aeson.genericToJSON (jsonOptions 3)

instance FromJSON BotStatusSnapshot where
    parseJSON = Aeson.genericParseJSON (jsonOptions 3)

botStoppedSnapshotJson :: BotStatusSnapshot -> Aeson.Value
botStoppedSnapshotJson snap =
    object
        [ "running" .= False
        , "snapshotAtMs" .= bssSavedAtMs snap
        , "snapshot" .= bssStatus snap
        ]

botStoppedMultiJson :: [BotStatusSnapshot] -> Aeson.Value
botStoppedMultiJson snaps =
    let bots = map botStoppedSnapshotJson snaps
        snapshotAt =
            case snaps of
                [] -> Nothing
                _ -> Just (maximum (map bssSavedAtMs snaps))
     in object
            ( [ "running" .= False
              , "multi" .= True
              , "bots" .= bots
              ]
                ++ maybe [] (\t -> ["snapshotAtMs" .= t]) snapshotAt
            )

botSnapshotSymbol :: BotStatusSnapshot -> Maybe String
botSnapshotSymbol snap =
    case bssStatus snap of
        Aeson.Object o -> KM.lookup "symbol" o >>= AT.parseMaybe parseJSON
        _ -> Nothing

botStateFileName :: FilePath
botStateFileName = "bot-state.json"

botStateFilePrefix :: FilePath
botStateFilePrefix = "bot-state-"

defaultBotStateDir :: FilePath
defaultBotStateDir = ".tmp/bot"

resolveBotStateDir :: IO (Maybe FilePath)
resolveBotStateDir = do
    mDir <- lookupEnv "TRADER_BOT_STATE_DIR"
    case trim <$> mDir of
        Just dir | null dir -> pure Nothing
        Just dir -> pure (Just dir)
        Nothing -> do
            mStateDir <- stateSubdirFromEnv "bot"
            let baseDir = fromMaybe defaultBotStateDir mStateDir
            pure (Just baseDir)

tenantStateDirFor :: FilePath -> TenantKey -> FilePath
tenantStateDirFor dir tenantKey =
    dir </> "tenants" </> sanitizeFileComponent (T.unpack tenantKey)

botStatePathFor :: FilePath -> TenantKey -> String -> FilePath
botStatePathFor dir tenantKey sym =
    tenantStateDirFor dir tenantKey </> (botStateFilePrefix ++ sanitizeFileComponent sym ++ ".json")

s3BotSnapshotKey :: S3State -> TenantKey -> String -> String
s3BotSnapshotKey st tenantKey sym =
    s3KeyFor st ["bot", sanitizeFileComponent (T.unpack tenantKey), botStateFilePrefix ++ sanitizeFileComponent sym ++ ".json"]

s3BotSnapshotIndexKey :: S3State -> TenantKey -> String
s3BotSnapshotIndexKey st tenantKey =
    s3KeyFor st ["bot", sanitizeFileComponent (T.unpack tenantKey), "bot-state-index.json"]

writeBotStatusSnapshot :: FilePath -> BotStatusSnapshot -> IO ()
writeBotStatusSnapshot path snap = do
    createDirectoryIfMissing True (takeDirectory path)
    randId <- randomIO :: IO Word64
    let tmpPath = path ++ ".tmp-" ++ show randId
    BL.writeFile tmpPath (encode snap)
    -- Atomic on POSIX when within the same filesystem; on Windows, fall back to replace.
    r1 <- try (renameFile tmpPath path) :: IO (Either SomeException ())
    case r1 of
        Right _ -> pure ()
        Left _ -> do
            _ <- try (removeFile path) :: IO (Either SomeException ())
            _ <- try (renameFile tmpPath path) :: IO (Either SomeException ())
            pure ()

writeBotStatusSnapshotMaybe :: Maybe FilePath -> TenantKey -> String -> BotStatusSnapshot -> IO ()
writeBotStatusSnapshotMaybe mDir tenantKey sym snap = do
    case mDir of
        Nothing -> pure ()
        Just dir -> do
            let path = botStatePathFor dir tenantKey sym
            _ <- try (writeBotStatusSnapshot path snap) :: IO (Either SomeException ())
            pure ()
    mS3 <- resolveS3State
    case mS3 of
        Nothing -> pure ()
        Just st -> do
            let key = s3BotSnapshotKey st tenantKey sym
            _ <- try (s3PutObject st key (encode snap)) :: IO (Either SomeException (Either String ()))
            _ <- try (updateBotSnapshotIndex st tenantKey sym) :: IO (Either SomeException ())
            pure ()

persistBotStatusMaybe :: Maybe FilePath -> BotState -> IO ()
persistBotStatusMaybe mDir st =
    case mDir of
        Nothing -> pure ()
        Just _ -> do
            now <- getTimestampMs
            let snap =
                    BotStatusSnapshot
                        { bssSavedAtMs = now
                        , bssStatus = botStatusJson st
                        }
            writeBotStatusSnapshotMaybe mDir (botTenantKey st) (botSymbol st) snap

readBotStatusSnapshotAtPath :: FilePath -> IO (Maybe BotStatusSnapshot)
readBotStatusSnapshotAtPath path = do
    exists <- doesFileExist path
    if not exists
        then pure Nothing
        else do
            contentsOrErr <- (try (BL.readFile path) :: IO (Either SomeException BL.ByteString))
            case contentsOrErr of
                Left _ -> pure Nothing
                Right contents ->
                    case Aeson.eitherDecode' contents of
                        Left _ -> pure Nothing
                        Right snap -> pure (Just snap)

readBotStatusSnapshotMaybe :: Maybe FilePath -> TenantKey -> String -> IO (Maybe BotStatusSnapshot)
readBotStatusSnapshotMaybe mDir tenantKey sym = do
    localSnap <-
        case mDir of
            Nothing -> pure Nothing
            Just dir -> do
                let path = botStatePathFor dir tenantKey sym
                readBotStatusSnapshotAtPath path
    case localSnap of
        Just snap -> pure (Just snap)
        Nothing -> do
            mS3 <- resolveS3State
            s3Snap <-
                case mS3 of
                    Nothing -> pure Nothing
                    Just st -> readBotStatusSnapshotS3 st tenantKey sym
            case (s3Snap, mDir) of
                (Just snap, Just dir) -> do
                    let path = botStatePathFor dir tenantKey sym
                    _ <- try (writeBotStatusSnapshot path snap) :: IO (Either SomeException ())
                    pure (Just snap)
                (Just snap, _) -> pure (Just snap)
                (Nothing, _) -> pure Nothing

readBotStatusSnapshotsMaybe :: Maybe FilePath -> TenantKey -> IO [BotStatusSnapshot]
readBotStatusSnapshotsMaybe mDir tenantKey = do
    localSnaps <-
        case mDir of
            Nothing -> pure []
            Just dir -> do
                let tenantDir = tenantStateDirFor dir tenantKey
                dirExists <- doesDirectoryExist tenantDir
                if not dirExists
                    then pure []
                    else do
                        entries <- listDirectory tenantDir
                        let targets =
                                [ tenantDir </> name
                                | name <- entries
                                , botStateFilePrefix `isPrefixOf` name
                                , ".json" `isSuffixOf` name
                                ]
                        snaps <- mapM readBotStatusSnapshotAtPath targets
                        pure (catMaybes snaps)
    if not (null localSnaps)
        then pure localSnaps
        else do
            mS3 <- resolveS3State
            s3Snaps <-
                case mS3 of
                    Nothing -> pure []
                    Just st -> do
                        symbols <- readBotSnapshotIndex st tenantKey
                        snaps <- mapM (readBotStatusSnapshotS3 st tenantKey) symbols
                        pure (catMaybes snaps)
            case mDir of
                Nothing -> pure ()
                Just dir ->
                    forM_ s3Snaps $ \snap ->
                        case botSnapshotSymbol snap of
                            Nothing -> pure ()
                            Just sym -> do
                                let path = botStatePathFor dir tenantKey sym
                                _ <- try (writeBotStatusSnapshot path snap) :: IO (Either SomeException ())
                                pure ()
            pure (mergeBotSnapshots s3Snaps)

readBotSnapshotIndex :: S3State -> TenantKey -> IO [String]
readBotSnapshotIndex st tenantKey = do
    let key = s3BotSnapshotIndexKey st tenantKey
    r <- s3GetObject st key
    case r of
        Left _ -> pure []
        Right Nothing -> pure []
        Right (Just bytes) ->
            case Aeson.eitherDecode' bytes of
                Left _ -> pure []
                Right symbols -> pure (filter (not . null) (map normalizeSymbol symbols))

updateBotSnapshotIndex :: S3State -> TenantKey -> String -> IO ()
updateBotSnapshotIndex st tenantKey sym = do
    symbols <- readBotSnapshotIndex st tenantKey
    let symNorm = normalizeSymbol sym
        next = if symNorm `elem` symbols then symbols else symbols ++ [symNorm]
    _ <- s3PutObject st (s3BotSnapshotIndexKey st tenantKey) (encode next)
    pure ()

readBotStatusSnapshotS3 :: S3State -> TenantKey -> String -> IO (Maybe BotStatusSnapshot)
readBotStatusSnapshotS3 st tenantKey sym = do
    let key = s3BotSnapshotKey st tenantKey sym
    r <- s3GetObject st key
    case r of
        Left _ -> pure Nothing
        Right Nothing -> pure Nothing
        Right (Just bytes) ->
            case Aeson.eitherDecode' bytes of
                Left _ -> pure Nothing
                Right snap -> pure (Just snap)

mergeBotSnapshots :: [BotStatusSnapshot] -> [BotStatusSnapshot]
mergeBotSnapshots snaps =
    HM.elems (foldl' insertSnap HM.empty snaps)
  where
    insertSnap acc snap =
        case snapshotSymbol snap of
            Nothing -> acc
            Just sym ->
                case HM.lookup sym acc of
                    Nothing -> HM.insert sym snap acc
                    Just existing ->
                        if bssSavedAtMs snap >= bssSavedAtMs existing
                            then HM.insert sym snap acc
                            else acc

    snapshotSymbol :: BotStatusSnapshot -> Maybe String
    snapshotSymbol snap =
        case bssStatus snap of
            Aeson.Object o -> KM.lookup "symbol" o >>= AT.parseMaybe parseJSON
            _ -> Nothing

data BotOp = BotOp
    { boIndex :: !Int
    , boSide :: !String
    , boPrice :: !Double
    }
    deriving (Eq, Show, Generic)

instance ToJSON BotOp where
    toJSON = Aeson.genericToJSON (jsonOptions 2)

data BotOrderEvent = BotOrderEvent
    { boeIndex :: !Int
    , boeOpSide :: !String
    , boePrice :: !Double
    , boeOpenTime :: !Int64
