ensureBinanceKeysPresent :: BinanceEnv -> IO ()
ensureBinanceKeysPresent env =
    let missingKey = maybe True BS.null (beApiKey env)
        missingSecret = maybe True BS.null (beApiSecret env)
     in (when (missingKey || missingSecret) $ throwIO (userError "botTrade=true requires BINANCE_API_KEY and BINANCE_API_SECRET (or pass binanceApiKey/binanceApiSecret in request)"))

resolveTenantKeyFromApiParamsWithHint :: Maybe String -> Args -> ApiParams -> Either String (Maybe TenantKey)
resolveTenantKeyFromApiParamsWithHint tenantHint args p =
    resolveTenantKeyFromPlatformParams
        (argPlatform args)
        tenantHint
        (apBinanceApiKey p)
        (apBinanceApiSecret p)
        (apCoinbaseApiKey p)
        (apCoinbaseApiSecret p)
        (apCoinbaseApiPassphrase p)

resolveTenantKeyFromApiParams :: Args -> ApiParams -> Either String (Maybe TenantKey)
resolveTenantKeyFromApiParams args p =
    resolveTenantKeyFromApiParamsWithHint (apTenantKey p) args p

resolveTenantKeyFromListenKeyStart :: ApiListenKeyStartParams -> Either String (Maybe TenantKey)
resolveTenantKeyFromListenKeyStart p =
    resolveTenantKeyFromParams (alsTenantKey p) (alsBinanceApiKey p) (alsBinanceApiSecret p) Nothing Nothing Nothing

resolveTenantKeyFromListenKeyAction :: ApiListenKeyActionParams -> Either String (Maybe TenantKey)
resolveTenantKeyFromListenKeyAction p =
    resolveTenantKeyFromParams (alaTenantKey p) (alaBinanceApiKey p) (alaBinanceApiSecret p) Nothing Nothing Nothing

resolveTenantKeyFromBinanceTradesRequest :: ApiBinanceTradesRequest -> Either String (Maybe TenantKey)
resolveTenantKeyFromBinanceTradesRequest p =
    resolveTenantKeyFromParams (abrTenantKey p) (abrBinanceApiKey p) (abrBinanceApiSecret p) Nothing Nothing Nothing

resolveTenantKeyFromBinancePositionsRequest :: ApiBinancePositionsRequest -> Either String (Maybe TenantKey)
resolveTenantKeyFromBinancePositionsRequest p =
    resolveTenantKeyFromParams (abpTenantKey p) (abpBinanceApiKey p) (abpBinanceApiSecret p) Nothing Nothing Nothing

resolveTenantKeyFromBinanceClosePositionRequest :: ApiBinanceClosePositionRequest -> Either String (Maybe TenantKey)
resolveTenantKeyFromBinanceClosePositionRequest p =
    resolveTenantKeyFromParams (abcpTenantKey p) (abcpBinanceApiKey p) (abcpBinanceApiSecret p) Nothing Nothing Nothing

requireTenantKey :: String -> Maybe TenantKey -> Either String TenantKey
requireTenantKey label mTenant =
    case mTenant of
        Just tenant -> Right tenant
        Nothing -> Left (label ++ " requires tenantKey or API keys.")

tenantKeyFromRequest :: Wai.Request -> Maybe TenantKey
tenantKeyFromRequest req =
    let headers = Wai.requestHeaders req
        headerRaw = lookupHeaderNormalized "X-Tenant-Key" headers
        queryRaw =
            case lookup (BS.pack "tenantKey") (Wai.queryString req) of
                Just (Just raw) -> Just raw
                _ -> Nothing
        headerStr = fmap BS.unpack headerRaw
        queryStr = fmap BS.unpack queryRaw
     in normalizeTenantKey headerStr <|> normalizeTenantKey queryStr

requestOriginIp :: Wai.Request -> Maybe Text
requestOriginIp req =
    let headers = Wai.requestHeaders req
        forwardedRaw = lookupHeaderNormalized "X-Forwarded-For" headers
        realRaw = lookupHeaderNormalized "X-Real-IP" headers
        forwardedIp = forwardedRaw >>= parseForwardedIp
        realIp = realRaw >>= parseForwardedIp
        sockIp = Just (sockAddrToIpText (Wai.remoteHost req))
     in forwardedIp <|> realIp <|> sockIp
  where
    parseForwardedIp raw =
        let rawStr = trim (BS.unpack raw)
            first = trim (takeWhile (/= ',') rawStr)
         in if null first then Nothing else Just (T.pack first)

sockAddrToIpText :: SockAddr -> Text
sockAddrToIpText addr =
    case addr of
        SockAddrUnix path -> T.pack path
        _ ->
            let raw = show addr
             in case raw of
                    ('[' : rest) -> T.pack (takeWhile (/= ']') rest)
                    _ -> T.pack (takeWhile (/= ':') raw)

serverTenantKeyForPlatform :: Platform -> IO (Maybe TenantKey)
serverTenantKeyForPlatform platform =
    case platform of
        PlatformBinance -> do
            key <- lookupEnv "BINANCE_API_KEY"
            secret <- lookupEnv "BINANCE_API_SECRET"
            pure (tenantKeyFromBinanceKeys key secret)
        PlatformCoinbase -> do
            key <- lookupEnv "COINBASE_API_KEY"
            secret <- lookupEnv "COINBASE_API_SECRET"
            passphrase <- lookupEnv "COINBASE_API_PASSPHRASE"
            pure (tenantKeyFromCoinbaseKeys key secret passphrase)
        _ -> pure Nothing

applyBinanceKeyFallback :: Maybe String -> Maybe String -> Args -> Args
applyBinanceKeyFallback mKey mSecret args =
    let key = normalizeBinanceCredential (argBinanceApiKey args) <|> mKey
        secret = normalizeBinanceCredential (argBinanceApiSecret args) <|> mSecret
     in args
            { argBinanceApiKey = key
            , argBinanceApiSecret = secret
            }

argsWithBinanceEnvKeys :: BinanceEnv -> Args -> Args
argsWithBinanceEnvKeys env =
    applyBinanceKeyFallback
        (normalizeBinanceCredential (BS.unpack <$> beApiKey env))
        (normalizeBinanceCredential (BS.unpack <$> beApiSecret env))

argsWithBinanceKeysFromArgs :: Args -> Args -> Args
argsWithBinanceKeysFromArgs source =
    applyBinanceKeyFallback
        (normalizeBinanceCredential (argBinanceApiKey source))
        (normalizeBinanceCredential (argBinanceApiSecret source))

hasBinanceKeys :: Args -> Bool
hasBinanceKeys args =
    isJust (normalizeBinanceCredential (argBinanceApiKey args))
        && isJust (normalizeBinanceCredential (argBinanceApiSecret args))

hasCoinbaseKeys :: Args -> Bool
hasCoinbaseKeys args =
    isJust (normalizeBinanceCredential (argCoinbaseApiKey args))
        && isJust (normalizeBinanceCredential (argCoinbaseApiSecret args))
        && isJust (normalizeBinanceCredential (argCoinbaseApiPassphrase args))

fetchLongFlatAccountPos :: Args -> BinanceEnv -> String -> IO Int
fetchLongFlatAccountPos args env sym =
    case argBinanceMarket args of
        MarketFutures -> do
            summary <- fetchFuturesPositionSummary env sym
            let netAmt = fpsNetAmt summary
                hasLong = fpsHasLong summary
                hasShort = fpsHasShort summary
                label =
                    if hasLong && hasShort
                        then "both long and short futures positions"
                        else "a short futures position"
            if hasShort
                then
                    throwIO
                        ( userError
                            ( "bot/start positioning=long-flat cannot start with "
                                ++ label
                                ++ " for "
                                ++ sym
                                ++ " (net positionAmt="
                                ++ show netAmt
                                ++ ")"
                            )
                        )
                else pure (if hasLong then 1 else 0)
        _ -> do
            let (baseAsset, _quoteAsset) = splitSymbol sym
            mSf <- tryFetchFilters
            baseBal <- fetchFreeBalance env baseAsset
            pure (if isLongSpotBalance mSf baseBal then 1 else 0)
  where
    tryFetchFilters :: IO (Maybe SymbolFilters)
    tryFetchFilters = do
        r <- try (fetchSymbolFilters env sym) :: IO (Either SomeException SymbolFilters)
        pure $
            case r of
                Left _ -> Nothing
                Right sf -> Just sf

    effectiveMinQty sf = sfMarketMinQty sf <|> sfLotMinQty sf

    isLongSpotBalance :: Maybe SymbolFilters -> Double -> Bool
    isLongSpotBalance mSf baseBal =
        case mSf >>= effectiveMinQty of
            Nothing -> baseBal > 0
            Just minQ -> baseBal >= minQ

accountPosSign :: Double -> Int
accountPosSign posAmt
    | posAmt > 1e-12 = 1
    | posAmt < -1e-12 = -1
    | otherwise = 0

fetchLongShortAccountPos :: Args -> BinanceEnv -> String -> IO Int
fetchLongShortAccountPos args env sym =
    case argBinanceMarket args of
        MarketFutures -> do
            summary <- fetchFuturesPositionSummary env sym
            let hasLong = fpsHasLong summary
                hasShort = fpsHasShort summary
                netAmt = fpsNetAmt summary
            if hasLong && hasShort
                then
                    throwIO
                        ( userError
                            ( "bot/start positioning=long-short cannot start with both long and short futures positions for "
                                ++ sym
                                ++ "."
                            )
                        )
                else pure (accountPosSign netAmt)
        _ -> throwIO (userError "bot/start positioning=long-short requires market=futures")

fetchBotAccountPos :: Args -> BinanceEnv -> String -> IO Int
fetchBotAccountPos args env sym =
    case argPositioning args of
        LongFlat -> fetchLongFlatAccountPos args env sym
        LongShort -> fetchLongShortAccountPos args env sym

fetchAdoptedPositionSize :: Args -> BinanceEnv -> String -> Double -> IO (Maybe Double)
fetchAdoptedPositionSize args env sym price =
    if price <= 0 || isNaN price || isInfinite price
        then pure Nothing
        else do
            let safeMax0 = max 0
                (baseAsset, quoteAsset) = splitSymbol sym
                spotSizing = do
                    baseBal <- fetchFreeBalance env baseAsset
                    quoteBal <- fetchFreeBalance env quoteAsset
                    let baseVal = safeMax0 baseBal * price
                        quoteVal = safeMax0 quoteBal
                        totalVal = baseVal + quoteVal
                    if totalVal <= 0 || baseVal <= 0
                        then pure Nothing
                        else pure (Just (baseVal / totalVal))
                futuresSizing = do
                    summary <- fetchFuturesPositionSummary env sym
                    let posAmt = fpsNetAmt summary
                        notional = abs posAmt * price
                    if abs posAmt <= 1e-12 || notional <= 0
                        then pure Nothing
                        else do
                            quoteBal <- fetchFuturesAvailableBalance env quoteAsset
                            if quoteBal <= 0
                                then pure Nothing
                                else pure (Just (notional / quoteBal))
            r <-
                try
                    ( case argBinanceMarket args of
                        MarketFutures -> futuresSizing
                        _ -> spotSizing
                    ) ::
                    IO (Either SomeException (Maybe Double))
            case r of
                Right sized -> pure sized
                Left ex -> do
                    hPutStrLn stderr ("WARN: failed to infer adopted position size for " ++ sym ++ ": " ++ displayException ex)
                    pure Nothing

fetchAdoptableAccountPos :: Args -> BinanceEnv -> String -> IO Int
fetchAdoptableAccountPos args env sym =
    case argBinanceMarket args of
        MarketFutures -> do
            summary <- fetchFuturesPositionSummary env sym
            let hasLong = fpsHasLong summary
                hasShort = fpsHasShort summary
                netAmt = fpsNetAmt summary
            if hasLong && hasShort
                then
                    throwIO
                        ( userError
                            ( "bot/start cannot adopt both long and short futures positions for "
                                ++ sym
                                ++ ". Flatten one side first."
                            )
                        )
                else pure (accountPosSign netAmt)
        _ -> fetchLongFlatAccountPos args env sym

preflightBotStart :: Maybe OpsStore -> Args -> BotSettings -> String -> IO (Either String ())
preflightBotStart mOps args settings sym =
    if not (bsTradeEnabled settings)
        then pure (Right ())
        else do
            r <- try $ do
                env <- makeBinanceEnv mOps args
                ensureBinanceKeysPresent env
                pos <- fetchBotAccountPos args env sym
                if pos /= 0 && not (bsAdoptExistingPosition settings)
                    then
                        let sideLabel = if pos > 0 then "long" else "short"
                         in pure
                                ( Left
                                    ( "Refusing to start: existing "
                                        ++ sideLabel
                                        ++ " position detected for "
                                        ++ sym
                                        ++ " ("
                                        ++ marketCode (argBinanceMarket args)
                                        ++ "). Flatten first, or set botAdoptExistingPosition=true."
                                    )
                                )
                    else pure (Right ())
            case r of
                Left ex -> pure (Left (snd (exceptionToHttp ex)))
                Right out -> pure out

resolveBotSymbols :: Args -> ApiParams -> IO (Either String [String])
resolveBotSymbols args p = do
    envRaw <- lookupEnv "TRADER_BOT_SYMBOLS"
    let symbolsReq = maybe [] (map trim) (apBotSymbols p)
        symbolsEnv = maybe [] splitEnvList envRaw
        symbolsFallback = maybeToList (argBinanceSymbol args)
        raw =
            case symbolsReq of
                [] ->
                    case symbolsEnv of
                        [] -> symbolsFallback
                        xs -> xs
                xs -> xs
        normalized = filter (not . null) (dedupeStable (map normalizeSymbol raw))
    if null normalized
        then pure (Left "bot/start requires binanceSymbol or botSymbols")
        else pure (Right normalized)

resolveBotSymbolsAuto :: Args -> IO (Either String [String])
resolveBotSymbolsAuto args = do
    envRaw <- lookupEnv "TRADER_BOT_SYMBOLS"
    let symbolsEnv = maybe [] splitEnvList envRaw
        symbolsFallback = maybeToList (argBinanceSymbol args)
        raw =
            case symbolsEnv of
                [] -> symbolsFallback
                xs -> xs
        normalized = filter (not . null) (dedupeStable (map normalizeSymbol raw))
    if null normalized
        then pure (Left "bot autostart requires binanceSymbol or TRADER_BOT_SYMBOLS")
        else pure (Right normalized)

comboPollSecondsFromEnv :: IO Int
comboPollSecondsFromEnv = do
    pollEnv <- lookupEnv "TRADER_BOT_COMBOS_POLL_SEC"
    pure $
        case pollEnv >>= readMaybe of
            Just n | n >= 5 -> n
            _ -> 30

topComboBotCountFromEnv :: IO Int
topComboBotCountFromEnv = do
    raw <- lookupEnv "TRADER_BOT_TOP_COMBO_BOTS"
    pure $
        case raw >>= readMaybe of
            Just n | n >= 0 -> min 200 n
            _ -> 50

topComboStartupBotCountFromEnv :: Int -> IO Int
topComboStartupBotCountFromEnv fallback = do
    raw <- lookupEnv "TRADER_BOT_TOP_COMBO_BOTS_STARTUP"
    pure $
        case raw >>= readMaybe of
            Just n | n >= 0 -> min 200 n
            _ -> fallback

data AdoptRequirement = AdoptRequirement
    { arActive :: !Bool
    , arRequiresLongShort :: !Bool
    }
    deriving (Eq, Show)

openOrdersRequireShort :: BinanceMarket -> [BinanceOpenOrder] -> Bool
openOrdersRequireShort market orders =
    case market of
        MarketFutures -> any requiresShort orders
        _ -> False
  where
    requiresShort order =
        case fmap normalizeKey (booPositionSide order) of
            Just "short" -> True
            Just "long" -> False
            _ ->
                case (booReduceOnly order, booClosePosition order) of
                    (Just True, _) -> False
                    (_, Just True) -> False
                    _ ->
                        case booSide order of
                            Just Sell -> True
                            _ -> False

data FuturesPositionSummary = FuturesPositionSummary
    { fpsNetAmt :: !Double
    , fpsHasLong :: !Bool
    , fpsHasShort :: !Bool
    , fpsLeverage :: !(Maybe Double)
    }
    deriving (Eq, Show)

positionAmtSigned :: FuturesPositionRisk -> Double
positionAmtSigned pos =
    case fmap normalizeKey (fprPositionSide pos) of
        Just "short" -> negate (abs (fprPositionAmt pos))
        Just "long" -> abs (fprPositionAmt pos)
        _ -> fprPositionAmt pos

futuresPositionSummary :: String -> [FuturesPositionRisk] -> FuturesPositionSummary
futuresPositionSummary sym positions =
    let symNorm = normalizeSymbol sym
        matches = filter (\p -> normalizeSymbol (fprSymbol p) == symNorm) positions
        signed = map positionAmtSigned matches
        eps = 1e-12
        hasLong = any (> eps) signed
        hasShort = any (< -eps) signed
        netAmt = sum signed
        validLeverage l = l > 0 && not (isNaN l || isInfinite l)
        leverage = listToMaybe [fprLeverage p | p <- matches, validLeverage (fprLeverage p)]
     in FuturesPositionSummary{fpsNetAmt = netAmt, fpsHasLong = hasLong, fpsHasShort = hasShort, fpsLeverage = leverage}

fetchFuturesPositionSummary :: BinanceEnv -> String -> IO FuturesPositionSummary
fetchFuturesPositionSummary env sym = do
    positions <- fetchFuturesPositionRisks env
    pure (futuresPositionSummary sym positions)

argsCompatibleWithAdoption :: Args -> AdoptRequirement -> Bool
argsCompatibleWithAdoption args req
    | not (arActive req) = True
    | otherwise =
        case argBinanceMarket args of
            MarketFutures ->
                not (arRequiresLongShort req) || (argPositioning args == LongShort)
            _ ->
                not (arRequiresLongShort req) && argPositioning args /= LongShort

applyAdoptRequirementArgs :: Args -> AdoptRequirement -> Args
applyAdoptRequirementArgs args req
    | not (arActive req) = args
    | argBinanceMarket args == MarketFutures && arRequiresLongShort req && argPositioning args /= LongShort =
        args{argPositioning = LongShort}
    | otherwise = args

selectCompatibleTopComboArgs :: ApiComputeLimits -> String -> Args -> AdoptRequirement -> TopCombosExport -> Maybe (Args, Maybe Text)
selectCompatibleTopComboArgs limits sym args req export =
    let combos = filter (topComboMatchesSymbol sym Nothing) (tceCombos export)
        sortedCombos = sortOn topComboTradePriorityKey combos
        pick [] = Nothing
        pick (combo : rest) =
            case applyTopComboForStartWithUuid args combo of
                Left _ -> pick rest
                Right (args', mUuid) ->
                    let marketCompatible = argBinanceMarket args' == argBinanceMarket args
                     in if marketCompatible && argsCompatibleWithAdoption args' req
                            then case validateApiComputeLimits limits args' of
                                Left _ -> pick rest
                                Right args'' -> Just (args'', mUuid)
                            else pick rest
     in pick sortedCombos

applyLatestTopCombo :: Maybe OpsStore -> TopCombosStore -> ApiComputeLimits -> String -> Args -> AdoptRequirement -> IO (Args, Maybe Text)
applyLatestTopCombo mOps topCombosStore limits sym args req = do
    combosOrErr <- readTopCombosExportWithDbFallback mOps topCombosStore
    let baseArgs = applyAdoptRequirementArgs args req
    case combosOrErr of
        Left _ -> pure (baseArgs, Nothing)
        Right export ->
            case selectCompatibleTopComboArgs limits sym baseArgs req export of
                Nothing -> pure (baseArgs, Nothing)
                Just (args', mUuid) -> pure (args', mUuid)

clearPositionOriginIfFlatMaybe :: Maybe OpsStore -> TenantKey -> Args -> String -> IO ()
clearPositionOriginIfFlatMaybe mOps tenantKey args sym =
    case mOps of
        Nothing -> pure ()
        Just store -> do
            delRes <- (try (deletePositionOrigin store tenantKey args sym) :: IO (Either SomeException ()))
            case delRes of
                Left ex ->
                    putStrLn
                        ( "Warning: failed to clear persisted position origin for "
                            ++ sym
                            ++ ": "
                            ++ show ex
                        )
                Right () -> pure ()

applyOriginComboForAdoptionMaybe ::
    Maybe OpsStore ->
    TopCombosStore ->
    ApiComputeLimits ->
    TenantKey ->
    Args ->
    AdoptRequirement ->
    String ->
    IO (Args, Maybe Text)
applyOriginComboForAdoptionMaybe mOps topCombosStore limits tenantKey args req sym = do
    let baseArgs = applyAdoptRequirementArgs args req
    case mOps of
        Nothing -> pure (baseArgs, Nothing)
        Just store -> do
            origin <- readPositionOrigin store tenantKey baseArgs sym
            case origin of
                Nothing -> pure (baseArgs, Nothing)
                Just o ->
                    case poriComboUuid o of
                        Nothing -> pure (baseArgs, Nothing)
                        Just comboUuid -> do
                            posOrErr <-
                                ( try $ do
                                    env <- makeBinanceEnv mOps baseArgs
                                    ensureBinanceKeysPresent env
                                    fetchAdoptableAccountPos baseArgs env sym
                                ) ::
                                    IO (Either SomeException Int)
                            case posOrErr of
                                Left _ -> pure (baseArgs, Nothing)
                                Right posSign -> do
                                    let sideOk =
                                            (posSign > 0 && poriSide o == "long")
                                                || (posSign < 0 && poriSide o == "short")
                                    if posSign == 0 || not sideOk
                                        then do
                                            deletePositionOrigin store tenantKey baseArgs sym
                                            pure (baseArgs, Nothing)
                                        else do
                                            mComboDb <- readTopComboByUuidFromDb store comboUuid
                                            mCombo <-
                                                case mComboDb of
                                                    Just c -> pure (Just c)
                                                    Nothing -> do
                                                        combosOrErr <- readTopCombosExportWithDbFallback mOps topCombosStore
                                                        pure $
                                                            case combosOrErr of
                                                                Left _ -> Nothing
                                                                Right export ->
                                                                    find
                                                                        (\c -> uuidFromText (topComboUuid c) == Just comboUuid)
                                                                        (tceCombos export)
                                            case mCombo of
                                                Nothing -> pure (baseArgs, Nothing)
                                                Just combo ->
                                                    case applyTopComboForStartWithUuid baseArgs combo of
                                                        Left _ -> pure (baseArgs, Nothing)
                                                        Right (argsApplied0, mUuid) ->
                                                            case validateApiComputeLimits limits argsApplied0 of
                                                                Left _ -> pure (baseArgs, Nothing)
                                                                Right argsApplied -> pure (argsApplied, mUuid)

topComboSymbol :: TopCombo -> Maybe String
topComboSymbol combo =
    let platformRaw = topComboParamString "platform" combo
        symbolRaw = topComboParamString "binanceSymbol" combo <|> topComboParamString "symbol" combo
     in resolveComboSymbol platformRaw (tcSource combo) symbolRaw

dedupeTopComboTargets :: [(String, TopCombo)] -> [(String, TopCombo)]
dedupeTopComboTargets targets =
    reverse $
        snd $
            foldl'
                ( \(seen, acc) (sym, combo) ->
                    if HM.member sym seen
                        then (seen, acc)
                        else (HM.insert sym True seen, (sym, combo) : acc)
                )
                (HM.empty, [])
                targets

topCombosTopTargets :: Int -> TopCombosExport -> [(String, TopCombo)]
topCombosTopTargets topN export =
    let sorted = sortOn topComboTradePriorityKey (tceCombos export)
        targets =
            [ (normalizeSymbol sym, combo)
            | combo <- sorted
            , Just sym <- [topComboSymbol combo]
            , not (null sym)
            ]
     in take topN (dedupeTopComboTargets targets)

resolveOrphanOpenPositionSymbols :: Maybe OpsStore -> ApiComputeLimits -> Args -> [String] -> IO [String]
resolveOrphanOpenPositionSymbols mOps _limits args requested =
    if not (platformSupportsLiveBot (argPlatform args)) || argBinanceMarket args /= MarketFutures
        then pure []
        else do
            positionsOrErr <-
                ( try $ do
                    env <- makeBinanceEnv mOps args
                    ensureBinanceKeysPresent env
                    fetchFuturesPositionRisks env
                ) ::
                    IO (Either SomeException [FuturesPositionRisk])
            case positionsOrErr of
                Left _ -> pure []
                Right positions -> do
                    let openPositions = filter (\p -> accountPosSign (fprPositionAmt p) /= 0) positions
                        requestedNorm = map normalizeSymbol requested
                        isRequested sym = normalizeSymbol sym `elem` requestedNorm
                        openBySymbol =
                            foldl'
                                ( \acc pos ->
                                    let sym = normalizeSymbol (fprSymbol pos)
                                     in HM.insertWith (\_ old -> old) sym True acc
                                )
                                HM.empty
                                openPositions
                        orphans =
                            [ sym
                            | (sym, _requiresShort) <- sortOn fst (HM.toList openBySymbol)
                            , not (isRequested sym)
                            , let summary = futuresPositionSummary sym openPositions
                            , not (fpsHasLong summary && fpsHasShort summary)
                            ]
                    pure (dedupeStable orphans)

data RuntimeAdoptionInfo = RuntimeAdoptionInfo
    { raiRunning :: !Bool
    , raiStarting :: !Bool
    , raiTradeEnabled :: !Bool
    , raiSide :: !(Maybe Int)
    }

botPositionSign :: BotState -> Maybe Int
botPositionSign st =
    let pos = vectorLastOr 0 (botPositions st)
     in case compare pos 0 of
            GT -> Just 1
            LT -> Just (-1)
            EQ -> Nothing

runtimeAdoptionInfo :: BotRuntimeState -> IO RuntimeAdoptionInfo
runtimeAdoptionInfo rtState =
    case rtState of
        BotStarting rt ->
            pure
                RuntimeAdoptionInfo
                    { raiRunning = False
                    , raiStarting = True
                    , raiTradeEnabled = bsTradeEnabled (bsrSettings rt)
                    , raiSide = Nothing
                    }
        BotRunning rt -> do
            stOrErr <- try (readMVar (brStateVar rt)) :: IO (Either SomeException BotState)
            pure $
                case stOrErr of
                    Left _ ->
                        RuntimeAdoptionInfo
                            { raiRunning = True
                            , raiStarting = False
                            , raiTradeEnabled = False
                            , raiSide = Nothing
                            }
                    Right st ->
                        RuntimeAdoptionInfo
                            { raiRunning = True
                            , raiStarting = False
                            , raiTradeEnabled = bsTradeEnabled (botSettings st)
                            , raiSide = botPositionSign st
                            }

futuresPositionSideSign :: FuturesPositionRisk -> Maybe Int
futuresPositionSideSign pos =
    case accountPosSign (positionAmtSigned pos) of
        1 -> Just 1
        -1 -> Just (-1)
        _ -> Nothing

positionAdoptedByRuntime :: Maybe RuntimeAdoptionInfo -> FuturesPositionRisk -> Bool
positionAdoptedByRuntime mInfo pos =
    case mInfo of
        Nothing -> False
        Just info ->
            raiTradeEnabled info
                && case futuresPositionSideSign pos of
                    Nothing -> False
                    Just posSide ->
                        let activeSides = maybeToList (raiSide info)
                            hasStarting = raiStarting info
                            hasRunning = raiRunning info
                         in posSide `elem` activeSides || (null activeSides && (hasStarting || hasRunning))

resolveOrphanOpenPositionActions :: Maybe OpsStore -> Args -> BotRuntimeMap -> IO ([String], [String])
resolveOrphanOpenPositionActions mOps args tenantMap =
    if not (platformSupportsLiveBot (argPlatform args))
        then pure ([], [])
        else do
            let argsFutures =
                    args
                        { argBinanceFutures = True
                        , argBinanceMargin = False
                        }
            positionsOrErr <-
                ( try $ do
                    env <- makeBinanceEnv mOps argsFutures
                    ensureBinanceKeysPresent env
                    fetchFuturesPositionRisks env
                ) ::
                    IO (Either SomeException [FuturesPositionRisk])
            case positionsOrErr of
                Left _ -> pure ([], [])
                Right positions -> do
                    let openPositions = filter (\p -> accountPosSign (fprPositionAmt p) /= 0) positions
                        openBySymbol =
                            foldl'
                                ( \acc pos ->
                                    let sym = normalizeSymbol (fprSymbol pos)
                                     in HM.insertWith (++) sym [pos] acc
                                )
                                HM.empty
                                openPositions
                        symbolAdoptable symPositions =
                            let sides = dedupeStable [s | p <- symPositions, Just s <- [futuresPositionSideSign p]]
                             in not (1 `elem` sides && (-1) `elem` sides)
                        tenantMapNorm =
                            HM.fromList
                                [ (normalizeSymbol sym, st)
                                | (sym, st) <- HM.toList tenantMap
                                ]
                    runtimeInfos <- forM (HM.toList tenantMapNorm) $ \(sym, rtState) -> do
                        info <- runtimeAdoptionInfo rtState
                        pure (sym, info)
                    let runtimeBySymbol = HM.fromList runtimeInfos
                        orphanSymbols =
                            [ sym
                            | (sym, symPositions) <- sortOn fst (HM.toList openBySymbol)
                            , symbolAdoptable symPositions
                            , let mInfo = HM.lookup sym runtimeBySymbol
                            , not (all (positionAdoptedByRuntime mInfo) symPositions)
                            ]
                        orphanRestartSymbols =
                            [ sym
                            | sym <- orphanSymbols
                            , HM.member sym tenantMapNorm
                            ]
                    pure (dedupeStable orphanSymbols, dedupeStable orphanRestartSymbols)

resolveAdoptionRequirement :: Maybe OpsStore -> Args -> String -> IO (Either String AdoptRequirement)
resolveAdoptionRequirement mOps args sym = do
    r <- try $ do
        env <- makeBinanceEnv mOps args
        resolveAdoptionRequirementWithEnv args env sym
    pure $
        case r of
            Left ex -> Left (snd (exceptionToHttp ex))
            Right reqOrErr -> reqOrErr

resolveAdoptionRequirementWithEnv :: Args -> BinanceEnv -> String -> IO (Either String AdoptRequirement)
resolveAdoptionRequirementWithEnv args env sym = do
    r <- try $ do
        ensureBinanceKeysPresent env
        pos <- fetchAdoptableAccountPos args env sym
        orders <- fetchOpenOrders env sym
        let requiresShort = pos < 0 || openOrdersRequireShort (argBinanceMarket args) orders
            active = pos /= 0 || not (null orders)
        pure AdoptRequirement{arActive = active, arRequiresLongShort = requiresShort}
    pure $
        case r of
            Left ex -> Left (snd (exceptionToHttp ex))
            Right req -> Right req

adoptRequirementLongShortOverride :: Args -> AdoptRequirement -> Maybe Double
adoptRequirementLongShortOverride args req
    | not (arActive req) = Nothing
    | argBinanceMarket args == MarketFutures =
        if arRequiresLongShort req
            then Just 1.0
            else Nothing
    | otherwise = Just 0.0

botStartSymbol ::
    Bool ->
    Maybe OpsStore ->
    Metrics ->
    Maybe Journal ->
    Maybe Webhook ->
    Maybe FilePath ->
    TopCombosStore ->
    ApiComputeLimits ->
    TopCombosBacktestCtx ->
    AdoptRequirement ->
    BotController ->
    TenantKey ->
    Args ->
    Maybe Text ->
    Maybe Text ->
    ApiParams ->
    String ->
    IO (Either String BotStartOutcome)
botStartSymbol allowExisting mOps metrics mJournal mWebhook mBotStateDir topCombosStore limits topCombosCtx adoptReq ctrl tenantKey args mComboUuid originIp p symRaw =
    case botSettingsFromApi args p of
        Left e -> pure (Left e)
        Right settings ->
            botStartSymbolWithSettings
                allowExisting
                mOps
                metrics
                mJournal
                mWebhook
                mBotStateDir
                topCombosStore
                limits
                topCombosCtx
                adoptReq
                ctrl
                tenantKey
                args
                settings
                mComboUuid
                originIp
                symRaw

botStartSymbolWithSettings ::
    Bool ->
    Maybe OpsStore ->
    Metrics ->
    Maybe Journal ->
    Maybe Webhook ->
    Maybe FilePath ->
    TopCombosStore ->
    ApiComputeLimits ->
    TopCombosBacktestCtx ->
    AdoptRequirement ->
    BotController ->
    TenantKey ->
    Args ->
    BotSettings ->
    Maybe Text ->
    Maybe Text ->
    String ->
    IO (Either String BotStartOutcome)
botStartSymbolWithSettings allowExisting mOps metrics mJournal mWebhook mBotStateDir topCombosStore limits topCombosCtx adoptReq ctrl tenantKey args settings mComboUuid originIp symRaw =
    if not (platformSupportsLiveBot (argPlatform args))
        then pure (Left ("bot/start supports Binance only (platform=" ++ platformCode (argPlatform args) ++ ")"))
        else case argData args of
            Just _ -> pure (Left "bot/start supports binanceSymbol only (no CSV data source)")
            Nothing ->
                case trim symRaw of
                    "" -> pure (Left "bot/start requires binanceSymbol or botSymbols")
                    _ -> do
                        let sym = normalizeSymbol symRaw
                            argsSym = args{argBinanceSymbol = Just sym}
                            startReason = botStartReasonFromAdopt adoptReq
                        mrt0 <- readMVar (bcRuntime ctrl)
                        let tenantMap0 = fromMaybe HM.empty (HM.lookup tenantKey mrt0)
                        case HM.lookup sym tenantMap0 of
                            Just st ->
                                if allowExisting
                                    then pure (Right (BotStartOutcome sym st False))
                                    else case st of
                                        BotRunning _ -> pure (Left "Bot is already running")
                                        BotStarting _ -> pure (Left "Bot is starting")
                            Nothing -> do
                                preflight <- preflightBotStart mOps argsSym settings sym
                                case preflight of
                                    Left e | not (arActive adoptReq) -> pure (Left e)
                                    _ ->
                                        modifyMVar (bcRuntime ctrl) $ \mrt ->
                                            let tenantMap = fromMaybe HM.empty (HM.lookup tenantKey mrt)
                                             in case HM.lookup sym tenantMap of
                                                    Just st ->
                                                        if allowExisting
                                                            then pure (mrt, Right (BotStartOutcome sym st False))
                                                            else case st of
                                                                BotRunning _ -> pure (mrt, Left "Bot is already running")
                                                                BotStarting _ -> pure (mrt, Left "Bot is starting")
                                                    Nothing -> do
                                                        stopSig <- newEmptyMVar
                                                        tid <- forkIO (botStartWorker mOps metrics mJournal mWebhook mBotStateDir topCombosStore limits topCombosCtx adoptReq ctrl tenantKey argsSym settings mComboUuid originIp sym stopSig)
                                                        now <- getTimestampMs
                                                        let rt =
                                                                BotStartRuntime
                                                                    { bsrThreadId = tid
                                                                    , bsrStopSignal = stopSig
                                                                    , bsrArgs = sanitizeArgsKeys argsSym
                                                                    , bsrSettings = settings
                                                                    , bsrSymbol = sym
                                                                    , bsrTenantKey = tenantKey
                                                                    , bsrRequestedAtMs = now
                                                                    , bsrStartReason = startReason
                                                                    }
                                                            st = BotStarting rt
                                                            tenantMap' = HM.insert sym st tenantMap
                                                            mrt' = HM.insert tenantKey tenantMap' mrt
                                                        pure (mrt', Right (BotStartOutcome sym st True))

botStartWorker ::
    Maybe OpsStore ->
    Metrics ->
    Maybe Journal ->
    Maybe Webhook ->
    Maybe FilePath ->
    TopCombosStore ->
    ApiComputeLimits ->
    TopCombosBacktestCtx ->
    AdoptRequirement ->
    BotController ->
    TenantKey ->
    Args ->
    BotSettings ->
    Maybe Text ->
    Maybe Text ->
    String ->
    MVar () ->
    IO ()
botStartWorker mOps metrics mJournal mWebhook mBotStateDir topCombosStore limits topCombosCtx adoptReq ctrl tenantKey args settings mComboUuid originIp sym stopSig = do
    tid <- myThreadId
    let doStart baseArgs = do
            (argsFinal, comboUuidFinal) <-
                if arActive adoptReq
                    then
                        if shouldPreserveProvidedComboOnActiveAdopt (arActive adoptReq) mComboUuid
                            then pure (baseArgs, mComboUuid)
                            else applyLatestTopCombo mOps topCombosStore limits sym baseArgs adoptReq
                    else pure (baseArgs, mComboUuid)
            preflight <- preflightBotStart mOps argsFinal settings sym
            case preflight of
                Left e -> throwIO (userError e)
                Right () -> initBotState mOps tenantKey argsFinal settings comboUuidFinal originIp sym
    r <- try (doStart args) :: IO (Either SomeException BotState)
    case r of
        Left ex -> do
            now <- getTimestampMs
            journalWriteMaybe mJournal (object ["type" .= ("bot.start_failed" :: String), "atMs" .= now, "error" .= show ex])
            opsAppendMaybe
                mOps
                (Just tenantKey)
                "bot.start_failed"
                Nothing
                (Just (argsPublicJson args))
                (Just (object ["error" .= show ex]))
                Nothing
                mComboUuid
                (Just (T.pack sym))
                Nothing
            webhookNotifyMaybe mWebhook (webhookEventBotStartFailed args sym ex)
            modifyMVar_ (bcRuntime ctrl) $ \mrt ->
                case HM.lookup tenantKey mrt of
                    Just tenantMap ->
                        case HM.lookup sym tenantMap of
                            Just (BotStarting rt)
                                | bsrThreadId rt == tid ->
                                    let tenantMap' = HM.delete sym tenantMap
                                     in pure
                                            ( if HM.null tenantMap'
                                                then HM.delete tenantKey mrt
                                                else HM.insert tenantKey tenantMap' mrt
                                            )
                            _ -> pure mrt
                    Nothing -> pure mrt
        Right st0 -> do
            let eq0 =
                    vectorLastOr 1.0 (botEquityCurve st0)
            opsAppendMaybe
                mOps
                (Just tenantKey)
                "bot.started"
                Nothing
                (Just (argsPublicJson (botArgs st0)))
                (Just (object ["symbol" .= botSymbol st0, "market" .= marketCode (argBinanceMarket (botArgs st0)), "interval" .= argInterval (botArgs st0)]))
                (Just eq0)
                (botComboUuid st0)
                (Just (T.pack (botSymbol st0)))
                Nothing
            webhookNotifyMaybe mWebhook (webhookEventBotStarted (botArgs st0) (botSymbol st0))
            stVar <- newMVar st0
            persistBotStatusMaybe mBotStateDir st0
            optimizerStopSig <- newEmptyMVar
            optimizerPending <- newMVar Nothing
            optimizerTid <- forkIO (botOptimizerLoop mOps metrics mJournal topCombosStore stVar optimizerStopSig optimizerPending)
            let optimizerRt =
                    BotOptimizerRuntime
                        { borThreadId = optimizerTid
                        , borStopSignal = optimizerStopSig
                        , borPendingUpdate = optimizerPending
                        }
            startOk <-
                modifyMVar (bcRuntime ctrl) $ \mrt ->
                    case HM.lookup tenantKey mrt of
                        Just tenantMap ->
                            case HM.lookup sym tenantMap of
                                Just (BotStarting rt)
                                    | bsrThreadId rt == tid ->
                                        let tenantMap' = HM.insert sym (BotRunning (BotRuntime tid stVar stopSig (Just optimizerRt))) tenantMap
                                         in pure (HM.insert tenantKey tenantMap' mrt, True)
                                _ -> pure (mrt, False)
                        Nothing -> pure (mrt, False)
            if startOk
                then botLoop mOps metrics mJournal mWebhook mBotStateDir topCombosCtx ctrl stVar stopSig (Just optimizerPending)
                else do
                    _ <- tryPutMVar optimizerStopSig ()
                    killThread optimizerTid

botAutoStartLoop ::
    Maybe OpsStore ->
    Metrics ->
    Maybe Journal ->
    Maybe Webhook ->
    Maybe FilePath ->
    TopCombosStore ->
    ApiComputeLimits ->
    TopCombosBacktestCtx ->
    Args ->
    BotController ->
    TenantKey ->
    IO ()
botAutoStartLoop mOps metrics mJournal mWebhook mBotStateDir topCombosStore limits topCombosCtx baseArgs botCtrl tenantKey = do
    autostartEnv <- lookupEnv "TRADER_BOT_AUTOSTART"
    let autostartEnabled = readEnvBool autostartEnv True
    if not autostartEnabled
        then putStrLn "Live bot auto-start disabled (TRADER_BOT_AUTOSTART=false)."
        else do
            symbolsOrErr <- resolveBotSymbolsAuto baseArgs
            let baseSymbols =
                    case symbolsOrErr of
                        Left _ -> []
                        Right xs -> xs
            case symbolsOrErr of
                Left err -> putStrLn ("Live bot auto-start base symbols missing: " ++ err)
                Right _ -> pure ()
            if not (platformSupportsLiveBot (argPlatform baseArgs))
                then
                    putStrLn
                        ( "Live bot auto-start disabled: platform="
                            ++ platformCode (argPlatform baseArgs)
                            ++ " does not support live bots."
                        )
                else case argData baseArgs of
                    Just _ -> putStrLn "Live bot auto-start disabled: CSV data source is not supported."
                    Nothing -> do
                        let argsBase = baseArgs{argTradeOnly = True}
                            settings = defaultBotSettings argsBase
                        topComboBotCount <- topComboBotCountFromEnv
                        topComboStartupBotCount <- topComboStartupBotCountFromEnv topComboBotCount
                        pollSec <- comboPollSecondsFromEnv
                        let topJsonPath = tcsPath topCombosStore
                        errRef <- newIORef HM.empty
                        topErrRef <- newIORef Nothing
                        topTargetsRef <- newIORef []
                        topTargetsWarnRef <- newIORef Nothing
                        targetsRef <- newIORef []
                        startupPhaseRef <- newIORef (topComboStartupBotCount /= topComboBotCount)
                        let formatList xs =
                                if null xs
                                    then "none"
                                    else intercalate ", " xs
                        putStrLn
                            ( "Live bot auto-start enabled. Base symbols: "
                                ++ formatList baseSymbols
                                ++ ". Top combo bot target count: startup="
                                ++ show topComboStartupBotCount
                                ++ ", steady="
                                ++ show topComboBotCount
                                ++ ". Top combos path: "
                                ++ topJsonPath
                            )

                        let sleepSec s = threadDelay (max 1 s * 1000000)
                            recordError sym msg = do
                                prev <- readIORef errRef
                                if HM.lookup sym prev == Just msg
                                    then pure ()
                                    else do
                                        writeIORef errRef (HM.insert sym msg prev)
                                        putStrLn ("Live bot auto-start failed for " ++ sym ++ ": " ++ msg)
                            clearError sym = modifyIORef' errRef (HM.delete sym)
                            loadTopTargets topComboTargetCount = do
                                combosOrErr <- readTopCombosExportWithDbFallback mOps topCombosStore
                                case combosOrErr of
                                    Left err -> do
                                        prev <- readIORef topErrRef
                                        if prev == Just err
                                            then readIORef topTargetsRef
                                            else do
                                                writeIORef topErrRef (Just err)
                                                putStrLn ("Live bot auto-start top combos unavailable: " ++ err)
                                                readIORef topTargetsRef
                                    Right export -> do
                                        let targets = topCombosTopTargets topComboTargetCount export
                                            targetCount = length targets
                                        writeIORef topTargetsRef targets
                                        writeIORef topErrRef Nothing
                                        if targetCount < topComboTargetCount
                                            then do
                                                prev <- readIORef topTargetsWarnRef
                                                when (prev /= Just targetCount) $ do
                                                    writeIORef topTargetsWarnRef (Just targetCount)
                                                    putStrLn
                                                        ( "Live bot auto-start warning: only "
                                                            ++ show targetCount
                                                            ++ " unique top-combo symbol(s) available; unable to start all "
                                                            ++ show topComboTargetCount
                                                            ++ " top-combo bots."
                                                        )
                                            else writeIORef topTargetsWarnRef Nothing
                                        pure targets
                            startSymbol argsStart sym mCombo preferFutures = do
                                let argsSym0 = argsStart{argBinanceSymbol = Just sym}
                                    argsSym =
                                        if preferFutures
                                            then
                                                argsSym0
                                                    { argBinanceFutures = True
                                                    , argBinanceMargin = False
                                                    }
                                            else argsSym0
                                    adoptable = bsTradeEnabled settings && platformSupportsLiveBot (argPlatform argsSym)
                                adoptReqOrErr <-
                                    if adoptable
                                        then resolveAdoptionRequirement mOps argsSym sym
                                        else pure (Right (AdoptRequirement False False))
                                case adoptReqOrErr of
                                    Left err -> recordError sym err
                                    Right adoptReq -> do
                                        (argsCombo, mComboUuid) <-
                                            if shouldResolveOriginComboOnAutoStart (arActive adoptReq)
                                                then do
                                                    (argsOrigin, mOriginUuid) <-
                                                        applyOriginComboForAdoptionMaybe
                                                            mOps
                                                            topCombosStore
                                                            limits
                                                            tenantKey
                                                            argsSym
                                                            adoptReq
                                                            sym
                                                    case mOriginUuid of
                                                        Just _ -> pure (argsOrigin, mOriginUuid)
                                                        Nothing ->
                                                            case mCombo of
                                                                Nothing -> applyLatestTopCombo mOps topCombosStore limits sym argsSym adoptReq
                                                                Just combo ->
                                                                    case applyTopComboForStartWithUuid argsSym combo of
                                                                        Left err -> do
                                                                            recordError sym ("Top combo parse failed: " ++ err)
                                                                            applyLatestTopCombo mOps topCombosStore limits sym argsSym adoptReq
                                                                        Right (args', uuid) ->
                                                                            if argBinanceMarket args' == argBinanceMarket argsSym
                                                                                then pure (args', uuid)
                                                                                else do
                                                                                    recordError sym "Top combo market mismatch; falling back to latest compatible combo."
                                                                                    applyLatestTopCombo mOps topCombosStore limits sym argsSym adoptReq
                                                else do
                                                    when (shouldClearPositionOriginOnStart adoptable (arActive adoptReq)) $
                                                        clearPositionOriginIfFlatMaybe mOps tenantKey argsSym sym
                                                    case mCombo of
                                                        Nothing -> applyLatestTopCombo mOps topCombosStore limits sym argsSym adoptReq
                                                        Just combo ->
                                                            case applyTopComboForStartWithUuid argsSym combo of
                                                                Left err -> do
                                                                    recordError sym ("Top combo parse failed: " ++ err)
                                                                    applyLatestTopCombo mOps topCombosStore limits sym argsSym adoptReq
                                                                Right (args', uuid) ->
                                                                    if argBinanceMarket args' == argBinanceMarket argsSym
                                                                        then pure (args', uuid)
                                                                        else do
                                                                            recordError sym "Top combo market mismatch; falling back to latest compatible combo."
                                                                            applyLatestTopCombo mOps topCombosStore limits sym argsSym adoptReq
                                        case validateApiComputeLimits limits argsCombo of
                                            Left err -> recordError sym err
                                            Right argsOk -> do
                                                r <-
                                                    botStartSymbolWithSettings
                                                        True
                                                        mOps
                                                        metrics
                                                        mJournal
                                                        mWebhook
                                                        mBotStateDir
                                                        topCombosStore
                                                        limits
                                                        topCombosCtx
                                                        adoptReq
                                                        botCtrl
                                                        tenantKey
                                                        argsOk
                                                        settings
                                                        mComboUuid
                                                        Nothing
                                                        sym
                                                case r of
                                                    Left err -> recordError sym err
                                                    Right _ -> clearError sym
                            loop = do
                                startupPhase <- readIORef startupPhaseRef
                                let topComboTargetCount =
                                        if startupPhase
                                            then topComboStartupBotCount
                                            else topComboBotCount
                                topTargets <- loadTopTargets topComboTargetCount
                                let topTargetMap =
                                        foldl'
                                            (\acc (sym, combo) -> HM.insertWith (\_ old -> old) sym combo acc)
                                            HM.empty
                                            topTargets
                                    topSymbols = map fst topTargets
                                    targetSymbolsBase = dedupeStable (baseSymbols ++ topSymbols)
                                mrt <- readMVar (bcRuntime botCtrl)
                                let tenantMap0 = fromMaybe HM.empty (HM.lookup tenantKey mrt)
                                    argsWithKeys = argsBase
                                (orphanSymbols, orphanRestartSymbols) <- resolveOrphanOpenPositionActions mOps argsWithKeys tenantMap0
                                let targetSymbols = dedupeStable (targetSymbolsBase ++ orphanSymbols)
                                prevTargets <- readIORef targetsRef
                                when (prevTargets /= targetSymbols) $ do
                                    writeIORef targetsRef targetSymbols
                                    putStrLn ("Live bot auto-start targets: " ++ formatList targetSymbols)
                                let restartSymbols = dedupeStable (filter (`HM.member` tenantMap0) orphanRestartSymbols)
                                unless (null restartSymbols) $ do
                                    putStrLn ("Live bot auto-start restarting orphaned symbols: " ++ formatList restartSymbols)
                                    mapM_ (botStop botCtrl tenantKey . Just) restartSymbols
                                mrtAfterRestart <- readMVar (bcRuntime botCtrl)
                                let tenantMap = fromMaybe HM.empty (HM.lookup tenantKey mrtAfterRestart)
                                let missing = filter (not . (`HM.member` tenantMap)) targetSymbols
                                mapM_ (\sym -> startSymbol argsWithKeys sym (HM.lookup sym topTargetMap) (sym `elem` orphanSymbols)) missing
                                when startupPhase $ do
                                    writeIORef startupPhaseRef False
                                    putStrLn "Live bot auto-start startup phase complete; enabling steady-state top-combo targets."
                                sleepSec pollSec
                                loop
                        loop

botStop :: BotController -> TenantKey -> Maybe String -> IO [BotState]
botStop ctrl tenantKey mSymbol =
    modifyMVar (bcRuntime ctrl) $ \mrt -> do
        let tenantMap = fromMaybe HM.empty (HM.lookup tenantKey mrt)
            (targets, remainingTenant) =
                case mSymbol of
                    Nothing -> (HM.toList tenantMap, HM.empty)
                    Just symRaw ->
                        let sym = normalizeSymbol symRaw
                         in case HM.lookup sym tenantMap of
                                Nothing -> ([], tenantMap)
                                Just st -> ([(sym, st)], HM.delete sym tenantMap)
            mrt' =
                if HM.null remainingTenant
                    then HM.delete tenantKey mrt
                    else HM.insert tenantKey remainingTenant mrt
        stopped <- mapM (stopRuntime . snd) targets
        pure (mrt', catMaybes stopped)
  where
    stopRuntime st =
        case st of
            BotStarting rt -> do
                _ <- tryPutMVar (bsrStopSignal rt) ()
                killThread (bsrThreadId rt)
                pure Nothing
            BotRunning rt -> do
                mSt <- try (readMVar (brStateVar rt)) :: IO (Either SomeException BotState)
                case brOptimizer rt of
                    Nothing -> pure ()
                    Just optRt -> do
                        _ <- tryPutMVar (borStopSignal optRt) ()
                        killThread (borThreadId optRt)
                _ <- tryPutMVar (brStopSignal rt) ()
                killThread (brThreadId rt)
                pure (either (const Nothing) Just mSt)

runtimeStateToState :: BotRuntimeState -> IO (Maybe BotState)
runtimeStateToState st =
    case st of
        BotRunning rt -> Just <$> readMVar (brStateVar rt)
        _ -> pure Nothing

botGetStates :: BotController -> TenantKey -> IO [BotState]
botGetStates ctrl tenantKey = do
    mrt <- readMVar (bcRuntime ctrl)
    let tenantMap = fromMaybe HM.empty (HM.lookup tenantKey mrt)
    states <- mapM runtimeStateToState (HM.elems tenantMap)
    pure (catMaybes states)

botGetStatesAll :: BotController -> IO [BotState]
botGetStatesAll ctrl = do
    mrt <- readMVar (bcRuntime ctrl)
    let allStates = concatMap HM.elems (HM.elems mrt)
    states <- mapM runtimeStateToState allStates
    pure (catMaybes states)

botGetStateFor :: BotController -> TenantKey -> String -> IO (Maybe BotState)
botGetStateFor ctrl tenantKey symRaw = do
    mrt <- readMVar (bcRuntime ctrl)
    let tenantMap = fromMaybe HM.empty (HM.lookup tenantKey mrt)
    case HM.lookup (normalizeSymbol symRaw) tenantMap of
        Just (BotRunning rt) -> Just <$> readMVar (brStateVar rt)
        _ -> pure Nothing

initBotState :: Maybe OpsStore -> TenantKey -> Args -> BotSettings -> Maybe Text -> Maybe Text -> String -> IO BotState
initBotState mOps tenantKey args settings mComboUuid originIp sym = do
    let lookback = argLookback args
    now <- getTimestampMs
    env <- makeBinanceEnv mOps args
    let argsWithKeys = argsWithBinanceEnvKeys env args
        tradeEnabled = bsTradeEnabled settings
    startPos0 <-
        if tradeEnabled
            then do
                ensureBinanceKeysPresent env
                pos <- fetchBotAccountPos args env sym
                if pos /= 0 && not (bsAdoptExistingPosition settings)
                    then
                        let sideLabel = if pos > 0 then "long" else "short"
                         in throwIO
                                ( userError
                                    ( "Refusing to start: existing "
                                        ++ sideLabel
                                        ++ " position detected for "
                                        ++ sym
                                        ++ " ("
                                        ++ marketCode (argBinanceMarket args)
                                        ++ "). Flatten first, or set botAdoptExistingPosition=true."
                                    )
                                )
                    else pure pos
            else pure 0
    let initBars = clampInt 2 1000 (max 2 (resolveBarsForBinance args))
    ks <- fetchKlines env sym (argInterval args) initBars
    when (length ks < 2) $ throwIO (userError "Not enough klines to start bot")
    let closes = map kClose ks
        opens = map kOpen ks
        highs = map kHigh ks
        lows = map kLow ks
        volumes = map kVolume ks
        openTimes = map kOpenTime ks
        pricesV = V.fromList closes
        opensV = V.fromList opens
        highsV = V.fromList highs
        lowsV = V.fromList lows
        volumesV = V.fromList volumes
        featureInputs = mkFeatureInputs pricesV (Just opensV) (Just highsV) (Just lowsV) (Just volumesV)
        openV = V.fromList openTimes
        n = V.length pricesV

    let method = runtimeMethod (argMethod args)
        methodForCtx =
            if argOptimizeOperations args
                then MethodBoth
                else case method of
                    MethodConfBlend -> MethodBoth
                    MethodConfPick -> MethodBoth
                    MethodConformalClip -> MethodBoth
                    MethodCostPick -> MethodBoth
                    MethodHarmonicBlend -> MethodBoth
                    MethodDisagreementGuard -> MethodBoth
                    MethodMedianBlend -> MethodBoth
                    MethodNeutralGuard -> MethodBoth
                    MethodRiskParityBlend -> MethodBoth
                    MethodConsensusBoost -> MethodBoth
                    MethodAnchorBlend -> MethodBoth
                    MethodTensionGate -> MethodBoth
                    MethodEntropyBlend -> MethodBoth
                    MethodCoherenceGate -> MethodBoth
                    MethodDivergenceGate -> MethodBoth
                    MethodFractalBlend -> MethodBoth
                    MethodPhaseCancel -> MethodBoth
                    MethodSoftmaxBlend -> MethodBoth
                    MethodSmoothSoftmaxBlend -> MethodBoth
                    MethodHedgeBlend -> MethodBoth
                    MethodNetSoftmaxBlend -> MethodBoth
                    MethodEdgeBlend -> MethodBoth
                    MethodEdgePick -> MethodBoth
                    MethodGeoBlend -> MethodBoth
                    MethodRegimeSwitch -> MethodBoth
                    MethodRouter -> MethodBoth
                    MethodBanditRouter -> MethodBoth
                    _ -> method
        nan = 0 / 0 :: Double

    mLstmCtx <-
        case methodForCtx of
            MethodKalmanOnly -> pure Nothing
            _ -> do
                let normState = fitNorm (argNormalization args) closes
                    obsAll = forwardSeries normState closes
                    lstmCfg =
                        LSTMConfig
                            { lcLookback = lookback
                            , lcHiddenSize = argHiddenSize args
                            , lcEpochs = argEpochs args
                            , lcLearningRate = argLr args
                            , lcValRatio = argValRatio args
                            , lcPatience = argPatience args
                            , lcGradClip = argGradClip args
                            , lcSeed = argSeed args
                            }
                (lstmModel, _) <- trainLstmWithPersistence args lookback lstmCfg obsAll
                pure (Just (normState, obsAll, lstmModel))

    (mKalmanCtx, kalPred0) <-
        case methodForCtx of
            MethodLstmOnly -> pure (Nothing, V.replicate n nan)
            _ -> do
                let predictors = trainPredictorsWithInputsWithMarket (argPredictors args) lookback Nothing featureInputs
                    hmm0 = initHMMFilter predictors []
                    kal0 =
                        initKalman1
                            0
                            (max 1e-12 (argKalmanMeasurementVar args))
                            (max 0 (argKalmanProcessVar args) * max 0 (argKalmanDt args))
                    sv0 = emptySensorVar

                    step (kal, hmm, sv, predsAcc) t =
                        let priceT = pricesV V.! t
                            nextP = pricesV V.! (t + 1)
                            realizedR = if priceT == 0 then 0 else nextP / priceT - 1
                            (sensorOuts, predState) = predictSensorsWithInputs predictors featureInputs hmm t
                            meas = mapMaybe (toMeasurement args sv) sensorOuts
                            kal' = stepMulti meas kal
                            fusedR = kMean kal'
                            kalNext = priceT * (1 + fusedR)
                            sv' =
                                foldl'
                                    (\acc (sid, out) -> updateResidual sid (realizedR - soMu out) acc)
                                    sv
                                    sensorOuts
                            hmm' = updateHMM predictors predState realizedR
                         in (kal', hmm', sv', kalNext : predsAcc)

                    (kalPrev, hmmPrev, svPrev, predsRev) = foldl' step (kal0, hmm0, sv0, []) [0 .. n - 2]
                    preds = reverse predsRev
                    lastPrice = vectorLastOr 0 pricesV
                    (sensorOutsLast, _) = predictSensorsWithInputs predictors featureInputs hmmPrev (n - 1)
                    measLast = mapMaybe (toMeasurement args svPrev) sensorOutsLast
                    kalLast = stepMulti measLast kalPrev
                    kalLastNext = lastPrice * (1 + kMean kalLast)
                    kalPred = V.fromList (preds ++ [kalLastNext])

                pure (Just (predictors, kalPrev, hmmPrev, svPrev), kalPred)

    let lstmPred0 =
            case mLstmCtx of
                Nothing -> V.replicate n nan
                Just (normState, obsAll, lstmModel) ->
                    V.generate n $ \t ->
                        if t < lookback - 1
                            then nan
                            else
                                let start = t - lookback + 1
                                    window = take lookback (drop start obsAll)
                                    predObs = predictNext lstmModel window
                                 in inverseNorm normState predObs

    latest0Raw <-
        case computeLatestSignal
            args
            lookback
            featureInputs
            mLstmCtx
            mKalmanCtx
            Nothing
            ( Just
                PredHistory
                    { phKalman = kalPred0
                    , phLstm = lstmPred0
                    , phMeta = Nothing
                    , phLstmHealth = Nothing
                    }
            ) of
            Left err -> throwIO (userError err)
            Right sig -> pure sig

    let
        -- Startup decision:
        -- - Adopted positions are kept only if the open-threshold signal still agrees.
        -- - Otherwise, entry uses openThreshold via lsChosenDir.
        allowShort = argPositioning args == LongShort
        chosenDir = lsChosenDir latest0Raw
        volConfHoldActive = "VOL_CONF_GATE_HOLD" `isInfixOf` lsAction latest0Raw
        closeDir = lsCloseDir latest0Raw

        desiredPosSignal =
            if startPos0 /= 0 && volConfHoldActive
                then startPos0
                else case startPos0 of
                    1 ->
                        case chosenDir of
                            Just 1 -> 1
                            Just (-1) | allowShort -> -1
                            _ ->
                                case closeDir of
                                    Just 1 -> 1
                                    _ -> 0
                    (-1) ->
                        case chosenDir of
                            Just (-1) -> -1
                            Just 1 | allowShort -> 1
                            _ ->
                                case closeDir of
                                    Just (-1) -> -1
                                    _ -> 0
                    _ ->
                        case chosenDir of
                            Just 1 -> 1
                            Just (-1) | allowShort -> -1
                            _ -> 0

        latest =
            case (startPos0, desiredPosSignal) of
                (1, 0) ->
                    if lsChosenDir latest0Raw /= Just (-1)
                        then latest0Raw{lsChosenDir = Just (-1), lsAction = "FLAT (close)"}
                        else latest0Raw
                (-1, 0) ->
                    if lsChosenDir latest0Raw /= Just 1
                        then latest0Raw{lsChosenDir = Just 1, lsAction = "FLAT (close)"}
                        else latest0Raw
                _ -> latest0Raw

        baseEq = 1.0
        eq0 = V.replicate n baseEq
        pos0 = V.replicate n 0
        lastPrice = vectorLastOr 0 pricesV
        lastOt = vectorLastOr now openV
        wantSwitch = desiredPosSignal /= startPos0
        opSide =
            if desiredPosSignal > startPos0
                then "BUY"
                else "SELL"
        latestOrder =
            case desiredPosSignal of
                1 -> latest{lsChosenDir = Just 1}
                -1 -> latest{lsChosenDir = Just (-1)}
                0 ->
                    if startPos0 == 0
                        then latest{lsChosenDir = Nothing}
                        else latest{lsChosenDir = Just (negate startPos0)}
                x ->
                    if x > 0
                        then latest{lsChosenDir = Just 1}
                        else latest{lsChosenDir = Just (-1)}
        entrySize = entryScaleForSignal args (beMarket env) latest

    mStartSize <-
        if tradeEnabled && startPos0 /= 0
            then fetchAdoptedPositionSize args env sym lastPrice
            else pure Nothing
    let startSize =
            case mStartSize of
                Just s | s > 0 -> s
                _ -> if entrySize > 0 then entrySize else 1

    mOrder <-
        if not wantSwitch
            then pure Nothing
            else
                if argPositioning args == LongShort && desiredPosSignal == 0 && startPos0 /= 0
                    then Just <$> placeBotCloseIfEnabled args settings latestOrder env sym
                    else Just <$> placeIfEnabled args settings latestOrder env sym

    let qtyEps = 1e-9
        isPositiveQty q = q > qtyEps
        alreadyMsg =
            case mOrder of
                Nothing -> False
                Just o ->
                    let msg = aorMessage o
                     in "already long" `isInfixOf` msg || "already short" `isInfixOf` msg || "already flat" `isInfixOf` msg
        requestedQtyFromOrder fallbackQty o =
            case aorQuantity o of
                Just q | not (isNaN q || isInfinite q) && q > 0 -> q
                _ ->
                    if not (isNaN fallbackQty || isInfinite fallbackQty) && fallbackQty > 0
                        then fallbackQty
                        else 0
        executedQtyFromOrder fallbackQty o =
            let evidence =
                    OrderExecutionEvidence
                        { oeeSent = aorSent o
                        , oeeLive = argBinanceLive args
                        , oeeStatus = aorStatus o
                        , oeeExecutedQty = aorExecutedQty o
                        }
             in orderAppliedQuantity evidence fallbackQty
        targetQtyForSwitch =
            case (startPos0, desiredPosSignal) of
                (0, 1) -> entrySize
                (0, -1) -> entrySize
                (1, 0) -> startSize
                (-1, 0) -> startSize
                (1, -1) -> startSize + entrySize
                (-1, 1) -> startSize + entrySize
                _ -> max startSize entrySize
        closeOnlySwitch = desiredPosSignal == 0 && startPos0 /= 0
        requestedQty =
            case mOrder of
                Just o -> requestedQtyFromOrder targetQtyForSwitch o
                Nothing -> 0
        executedQtyRaw
            | not wantSwitch = 0
            | not tradeEnabled = requestedQty
            | alreadyMsg = requestedQty
            | otherwise =
                case mOrder of
                    Nothing -> 0
                    Just o -> fromMaybe 0 (executedQtyFromOrder requestedQty o)
        (desiredPos, desiredSize, closeQty, openQty)
            | not wantSwitch =
                let size0 =
                        if startPos0 == 0
                            then 0
                            else startSize
                 in (startPos0, size0, 0, 0)
            | closeOnlySwitch = applyReduceOnlyExecutedQuantity startPos0 startSize executedQtyRaw
            | otherwise = applyExecutedQuantity startPos0 startSize (opSide == "BUY") executedQtyRaw
        appliedExecution = isPositiveQty closeQty || isPositiveQty openQty
        stateReconciled = alreadyMsg || appliedExecution
        appliedSwitch =
            stateReconciled && desiredPos /= startPos0
        didTradeNow = wantSwitch && appliedExecution && not alreadyMsg
        volPerBar = volPerBarFromSignal args latest
        applyCostForSize eq size =
            if isPositiveQty size
                then
                    let feeFrac = costPerSideTotal args size volPerBar
                     in eq * (1 - feeFrac)
                else eq
        eqAfterCost = applyCostForSize (applyCostForSize baseEq closeQty) openQty
        eq1 =
            if didTradeNow
                then eq0 V.// [(n - 1, eqAfterCost)]
                else eq0
        pos1 = pos0 V.// [(n - 1, desiredPos)]
        openTrade =
            case desiredPos of
                1 ->
                    let px = lastPrice
                        openSize = max 0 desiredSize
                        entryHv = rpHighVol <$> lsRegimes latest
                     in Just
                            BotOpenTrade
                                { botOpenEntryIndex = n - 1
                                , botOpenEntryEquity = eq1 V.! (n - 1)
                                , botOpenEntryIp = originIp
                                , botOpenComboUuid = mComboUuid
                                , botOpenEntryHighVolProb = entryHv
                                , botOpenHoldingPeriods = 0
                                , botOpenEntryPrice = px
                                , botOpenSize = openSize
                                , botOpenTrail = px
                                , botOpenSide = SideLong
                                , botOpenPartialTaken = False
                                }
                (-1) ->
                    let px = lastPrice
                        openSize = max 0 desiredSize
                        entryHv = rpHighVol <$> lsRegimes latest
                     in Just
                            BotOpenTrade
                                { botOpenEntryIndex = n - 1
                                , botOpenEntryEquity = eq1 V.! (n - 1)
                                , botOpenEntryIp = originIp
                                , botOpenComboUuid = mComboUuid
                                , botOpenEntryHighVolProb = entryHv
                                , botOpenHoldingPeriods = 0
                                , botOpenEntryPrice = px
                                , botOpenSize = openSize
                                , botOpenTrail = px
                                , botOpenSide = SideShort
                                , botOpenPartialTaken = False
                                }
                _ -> Nothing
        ops =
            ([BotOp (n - 1) opSide lastPrice | wantSwitch && appliedSwitch])

        orders =
            case (wantSwitch, mOrder) of
                (True, Just o) -> [BotOrderEvent (n - 1) opSide lastPrice lastOt now o]
                _ -> []

        maxPoints = max (lookback + 3) (bsMaxPoints settings)
        dropCount = max 0 (V.length pricesV - maxPoints)

        (pricesV2, opensV2, highsV2, lowsV2, volumesV2, openV2, kalPred2, lstmPred2, eq2, pos2, ops2, orders2, openTrade2, startIndex2, mLstmCtx2) =
            if dropCount <= 0
                then (pricesV, opensV, highsV, lowsV, volumesV, openV, kalPred0, lstmPred0, eq1, pos1, ops, orders, openTrade, 0, mLstmCtx)
                else
                    let openTradeShifted =
                            case openTrade of
                                Nothing -> Nothing
                                Just ot -> Just (shiftOpenTradeIndex dropCount ot)
                        opsShifted =
                            [ op{boIndex = boIndex op - dropCount}
                            | op <- ops
                            , boIndex op >= dropCount
                            ]
                        ordersShifted =
                            [ e{boeIndex = boeIndex e - dropCount}
                            | e <- orders
                            , boeIndex e >= dropCount
                            ]
                        lstmCtxShifted =
                            case mLstmCtx of
                                Nothing -> Nothing
                                Just (normState, obsAll, lstmModel) ->
                                    Just (normState, drop dropCount obsAll, lstmModel)
                     in ( V.drop dropCount pricesV
                        , V.drop dropCount opensV
                        , V.drop dropCount highsV
                        , V.drop dropCount lowsV
                        , V.drop dropCount volumesV
                        , V.drop dropCount openV
                        , V.drop dropCount kalPred0
                        , V.drop dropCount lstmPred0
                        , V.drop dropCount eq1
                        , V.drop dropCount pos1
                        , opsShifted
                        , ordersShifted
                        , openTradeShifted
                        , dropCount
                        , lstmCtxShifted
                        )

        peakEq = if V.null eq2 then 1.0 else V.maximum eq2
        dayMs = 86400000 :: Int64
        dayKey = vectorLastOr now openV2 `div` dayMs
        dayStartEq = vectorLastOr 1.0 eq2
        weekMs = 7 * dayMs
        weekKey = vectorLastOr now openV2 `div` weekMs
        weekStartEq = vectorLastOr 1.0 eq2
        initOrderErrors =
            if tradeEnabled && wantSwitch && not stateReconciled
                then 1
                else 0
        (haltReason0, haltedAt0) =
            case argMaxOrderErrors args of
                Just lim | initOrderErrors >= lim -> (Just "MAX_ORDER_ERRORS", Just now)
                _ -> (Nothing, Nothing)

        argsStored = sanitizeArgsKeys argsWithKeys
        st0 =
            BotState
                { botArgs = argsStored
                , botSettings = settings
                , botSymbol = sym
                , botTenantKey = tenantKey
                , botTradeOriginIp = originIp
                , botComboUuid = mComboUuid
                , botEnv = env
                , botLookback = lookback
                , botPrices = pricesV2
                , botOpens = opensV2
                , botHighs = highsV2
                , botLows = lowsV2
                , botVolumes = volumesV2
                , botOpenTimes = openV2
                , botKalmanPredNext = kalPred2
                , botLstmPredNext = lstmPred2
                , botEquityCurve = eq2
                , botPositions = pos2
                , botOps = ops2
                , botOrders = orders2
                , botTrades = []
                , botPerfStats = emptyBotPerfStats (argPerfLookback argsWithKeys)
                , botAdjustments = emptyBotAdjustments
                , botLossStreak = 0
                , botOpenTrade = openTrade2
                , botCooldownLeft = 0
                , botLatestSignal = latest
                , botLastOrder = mOrder
                , botHaltReason = haltReason0
                , botHaltedAtMs = haltedAt0
                , botPeakEquity = peakEq
                , botDayKey = dayKey
                , botDayStartEquity = dayStartEq
                , botWeekKey = weekKey
                , botWeekStartEquity = weekStartEq
                , botDayTrades = 0
                , botConsecutiveOrderErrors = initOrderErrors
                , botLstmCtx = mLstmCtx2
                , botKalmanCtx = mKalmanCtx
                , botLastOpenTime = lastOt
                , botStartIndex = startIndex2
                , botStartedAtMs = now
                , botUpdatedAtMs = now
                , botPolledAtMs = now
                , botPollLatencyMs = 0
                , botFetchedKlines = length ks
                , botFetchedLastKline = lastMaybe ks
                , botLastBatchAtMs = now
                , botLastBatchSize = length ks
                , botLastBatchMs = 0
                , botError = Nothing
                }

    if wantSwitch && appliedSwitch && desiredPos /= 0
        then botOptimizeAfterOperation st0
        else pure st0

botOptimizeAfterOperation :: BotState -> IO BotState
botOptimizeAfterOperation st = do
    let args = botArgs st
        optimizeOps = argOptimizeOperations args
        sweepThr = argSweepThreshold args
        methodRuntime = runtimeMethod (argMethod args)
        methodForReporting =
            case argMethod args of
                MethodKalmanPhysicsError -> MethodKalmanPhysicsError
                _ -> methodRuntime
    if not (optimizeOps || sweepThr)
        then pure st
        else do
            let lookback = botLookback st
                settings = botSettings st
                pricesV = botPrices st
                n = V.length pricesV
            if n < max 3 (lookback + 3)
                then pure st
                else do
                    let win = min n (min 1000 (max (lookback + 3) (bsTrainBars settings)))
                        start = n - win
                        prices = V.toList (V.drop start pricesV)
                        highs = V.toList (V.drop start (botHighs st))
                        lows = V.toList (V.drop start (botLows st))
                        kalPred = V.toList (V.slice start (win - 1) (botKalmanPredNext st))
                        lstmPred = V.toList (V.slice start (win - 1) (botLstmPredNext st))
                        baseOpenThr = argOpenThreshold args
                        baseCloseThr = argCloseThreshold args
                        fee = argFee args
                        volPerBar = volPerBarFromPrices prices
                        sizeRef = max 1e-6 (argMaxPositionSize args)
                        perSideCost = estimatedPerSideCost args sizeRef volPerBar
                        rebalanceThresholdBase = max 0 (argRebalanceThreshold args)
                        rebalanceCostMult = max 0 (argRebalanceCostMult args)
                        rebalanceThreshold =
                            if rebalanceCostMult <= 0
                                then rebalanceThresholdBase
                                else max rebalanceThresholdBase (rebalanceCostMult * perSideCost)
                        minEdgeBase = max 0 (argMinEdge args)
                        minEdge =
                            if argCostAwareEdge args
                                then max minEdgeBase (breakEvenThresholdFromPerSideCost perSideCost + max 0 (argEdgeBuffer args))
                                else minEdgeBase
                        baseCfg =
                            EnsembleConfig
                                { ecOpenThreshold = baseOpenThr
                                , ecCloseThreshold = baseCloseThr
                                , ecFee = fee
                                , ecSlippage = argSlippage args
                                , ecSpread = argSpread args
                                , ecFeeFixed = argFeeFixed args
                                , ecFeeMin = argFeeMin args
                                , ecSlippageVolMult = argSlippageVolMult args
                                , ecSlippageImpact = argSlippageImpact args
                                , ecSlippageImpactPower = argSlippageImpactPower args
                                , ecSpreadVolMult = argSpreadVolMult args
                                , ecStopLoss = argStopLoss args
                                , ecTakeProfit = argTakeProfit args
                                , ecTrailingStop = argTrailingStop args
                                , ecStopLossVolMult = argStopLossVolMult args
                                , ecTakeProfitVolMult = argTakeProfitVolMult args
                                , ecTrailingStopVolMult = argTrailingStopVolMult args
                                , ecMinHoldBars = argMinHoldBars args
                                , ecCooldownBars = argCooldownBars args
                                , ecMaxHoldBars = argMaxHoldBars args
                                , ecMaxDrawdown = argMaxDrawdown args
                                , ecMaxDailyLoss = argMaxDailyLoss args
                                , ecMaxWeeklyLoss = argMaxWeeklyLoss args
                                , ecRiskPerTrade = argRiskPerTrade args
                                , ecMaxTradesPerDay = argMaxTradesPerDay args
                                , ecExpectancyLookback = argExpectancyLookback args
                                , ecMinExpectancy = argMinExpectancy args
                                , ecPerfLookback = argPerfLookback args
                                , ecPerfMinWinRate = argPerfMinWinRate args
                                , ecPerfMinProfitFactor = argPerfMinProfitFactor args
                                , ecAdaptiveFilters = argAdaptiveFilters args
                                , ecAdaptiveEdgeBufferMax = argAdaptiveEdgeBufferMax args
                                , ecAdaptiveMinSignalToNoiseMax = argAdaptiveMinSignalToNoiseMax args
                                , ecAdaptiveKalmanZMinMax = argAdaptiveKalmanZMinMax args
                                , ecAdaptiveTrendLookbackMax = argAdaptiveTrendLookbackMax args
                                , ecLossStreakMax = argLossStreakMax args
                                , ecLossStreakCooldownBars = argLossStreakCooldownBars args
                                , ecNoTradeWindows = argNoTradeWindows args
                                , ecIntervalSeconds = parseIntervalSeconds (argInterval args)
                                , ecOpenTimes = Just (V.drop start (botOpenTimes st))
                                , ecOpenPrices = Nothing
                                , ecMetaMask = Nothing
                                , ecPositioning = argPositioning args
                                , ecIntrabarFill = argIntrabarFill args
                                , ecMaxPositionSize = argMaxPositionSize args
                                , ecMinEdge = minEdge
                                , ecMinSignalToNoise = argMinSignalToNoise args
                                , ecSnrSizeWeight = argSnrSizeWeight args
                                , ecThresholdFactorEnabled = argThresholdFactorEnabled args
                                , ecThresholdFactorAlpha = argThresholdFactorAlpha args
                                , ecThresholdFactorMin = argThresholdFactorMin args
                                , ecThresholdFactorMax = argThresholdFactorMax args
                                , ecThresholdFactorFloor = argThresholdFactorFloor args
                                , ecThresholdFactorEdgeKalWeight = argThresholdFactorEdgeKalWeight args
                                , ecThresholdFactorEdgeLstmWeight = argThresholdFactorEdgeLstmWeight args
                                , ecThresholdFactorKalmanZWeight = argThresholdFactorKalmanZWeight args
                                , ecThresholdFactorHighVolWeight = argThresholdFactorHighVolWeight args
                                , ecThresholdFactorConformalWeight = argThresholdFactorConformalWeight args
                                , ecThresholdFactorQuantileWeight = argThresholdFactorQuantileWeight args
                                , ecThresholdFactorLstmConfWeight = argThresholdFactorLstmConfWeight args
                                , ecThresholdFactorLstmHealthWeight = argThresholdFactorLstmHealthWeight args
                                , ecLstmTrainingHealth = Nothing
                                , ecTrendLookback = argTrendLookback args
                                , ecPeriodsPerYear = periodsPerYear args
                                , ecVolTarget = argVolTarget args
                                , ecVolLookback = argVolLookback args
                                , ecVolEwmaAlpha = argVolEwmaAlpha args
                                , ecVolFloor = argVolFloor args
                                , ecVolScaleMax = argVolScaleMax args
                                , ecMaxVolatility = argMaxVolatility args
                                , ecVolConfGate = argVolConfGate args
                                , ecRebalanceBars = argRebalanceBars args
                                , ecRebalanceThreshold = rebalanceThreshold
                                , ecRebalanceGlobal = argRebalanceGlobal args
                                , ecRebalanceResetOnSignal = argRebalanceResetOnSignal args
                                , ecFundingRate = argFundingRate args
                                , ecFundingBySide = argFundingBySide args
                                , ecFundingOnOpen = argFundingOnOpen args
                                , ecBlendWeight = argBlendWeight args
                                , ecRouterLookback = argRouterLookback args
                                , ecRouterMinScore = argRouterMinScore args
                                , ecRouterScorePnlWeight = argRouterScorePnlWeight args
                                , ecKalmanDt = argKalmanDt args
                                , ecKalmanProcessVar = argKalmanProcessVar args
                                , ecKalmanMeasurementVar = argKalmanMeasurementVar args
                                , ecTriLayer = argTriLayer args
                                , ecTriLayerFastMult = argTriLayerFastMult args
                                , ecTriLayerSlowMult = argTriLayerSlowMult args
                                , ecTriLayerCloudPadding = argTriLayerCloudPadding args
                                , ecTriLayerCloudSlope = argTriLayerCloudSlope args
                                , ecTriLayerCloudWidth = argTriLayerCloudWidth args
                                , ecTriLayerTouchLookback = argTriLayerTouchLookback args
                                , ecTriLayerRequirePriceAction = argTriLayerRequirePriceAction args
                                , ecTriLayerPriceActionBody = argTriLayerPriceActionBody args
                                , ecTriLayerExitOnSlow = argTriLayerExitOnSlow args
                                , ecKalmanBandLookback = argKalmanBandLookback args
                                , ecKalmanBandStdMult = argKalmanBandStdMult args
                                , ecLstmExitFlipBars = argLstmExitFlipBars args
                                , ecLstmExitFlipGraceBars = argLstmExitFlipGraceBars args
                                , ecLstmExitFlipStrong = argLstmExitFlipStrong args
                                , ecLstmConfidenceSoft = argLstmConfidenceSoft args
                                , ecLstmConfidenceHard = argLstmConfidenceHard args
                                , ecKalmanZMin = argKalmanZMin args
                                , ecKalmanZMax = argKalmanZMax args
                                , ecMaxHighVolProb = argMaxHighVolProb args
                                , ecMaxConformalWidth = argMaxConformalWidth args
                                , ecMaxQuantileWidth = argMaxQuantileWidth args
                                , ecConfirmConformal = argConfirmConformal args
                                , ecConfirmQuantiles = argConfirmQuantiles args
                                , ecConfidenceSizing = argConfidenceSizing args
                                , ecMinPositionSize = argMinPositionSize args
                                }
                        hasBothCtx = isJust (botLstmCtx st) && isJust (botKalmanCtx st)
                        ppy = periodsPerYear args
                        tuneCfg =
                            TuneConfig
                                { tcObjective = argTuneObjective args
                                , tcPenaltyMaxDrawdown = argTunePenaltyMaxDrawdown args
                                , tcPenaltyTurnover = argTunePenaltyTurnover args
                                , tcPeriodsPerYear = ppy
                                , tcWalkForwardFolds = argWalkForwardFolds args
                                , tcWalkForwardEmbargoBars = argWalkForwardEmbargoBars args
                                , tcMinRoundTrips = argMinRoundTrips args
                                , tcStressVolMultiplier = argTuneStressVolMult args
                                , tcStressShock = argTuneStressShock args
                                , tcStressWeight = argTuneStressWeight args
                                }
                        thresholdResult =
                            if optimizeOps && hasBothCtx
                                then
                                    fmap
                                        (\(m, openThr, closeThr, _bt, _stats) -> (m, openThr, closeThr))
                                        (optimizeOperationsWithHLWith tuneCfg baseCfg prices highs lows kalPred lstmPred Nothing)
                                else
                                    fmap
                                        (\(openThr, closeThr, _bt, _stats) -> (methodForReporting, openThr, closeThr))
                                        (sweepThresholdWithHLWith tuneCfg methodRuntime baseCfg prices highs lows kalPred lstmPred Nothing)
                    (newMethod, newOpenThr, newCloseThr) <-
                        case thresholdResult of
                            Right res -> pure res
                            Left err -> do
                                hPutStrLn stderr ("Warning: Threshold tuning failed and was skipped: " ++ err)
                                pure (methodForReporting, baseOpenThr, baseCloseThr)
                    let args' =
                            args
                                { argMethod = newMethod
                                , argOpenThreshold = newOpenThr
                                , argCloseThreshold = newCloseThr
                                }
                        argsSignal = applyBotAdjustments (botAdjustments st) args'
                    case computeLatestSignal
                        argsSignal
                        lookback
                        (botFeatureInputs st)
                        (botLstmCtx st)
                        (botKalmanCtx st)
                        Nothing
                        ( Just
                            PredHistory
                                { phKalman = botKalmanPredNext st
                                , phLstm = botLstmPredNext st
                                , phMeta = Nothing
                                , phLstmHealth = Nothing
                                }
                        ) of
                        Left err ->
                            pure st{botError = Just ("Latest signal update failed: " ++ err)}
                        Right latest' ->
                            pure st{botArgs = sanitizeArgsKeys args', botLatestSignal = latest', botError = Nothing}

argLookbackEither :: Args -> Either String Int
argLookbackEither args =
    case argLookbackBars args of
        Just n ->
            if n < 2
                then Left "--lookback-bars must be >= 2"
                else Right n
        Nothing ->
            case lookbackBarsFrom (argInterval args) (argLookbackWindow args) of
                Left err -> Left err
                Right n ->
                    if n < 2
                        then
                            Left
                                ( "Lookback window too small: "
                                    ++ show (argLookbackWindow args)
                                    ++ " at interval "
                                    ++ show (argInterval args)
                                    ++ " yields "
                                    ++ show n
                                    ++ " bars; need at least 2 bars."
                                )
                        else Right n

botApplyOptimizerUpdate :: BotState -> BotOptimizerUpdate -> IO BotState
botApplyOptimizerUpdate st upd = do
    now <- getTimestampMs
    let baseArgs = botArgs st
        args' =
            (bouArgs upd)
                { argOptimizeOperations = False
                , argSweepThreshold = False
                }
        argsWithKeys = argsWithBinanceKeysFromArgs baseArgs args'
        lookback' = max 2 (bouLookback upd)
        pricesV = botPrices st
        n = V.length pricesV
        mLstmCtx' = bouLstmCtx upd <|> botLstmCtx st
        mKalmanCtx' = bouKalmanCtx upd <|> botKalmanCtx st
        method = runtimeMethod (argMethod argsWithKeys)
        ctxOk =
            case method of
                MethodBoth -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodRouter -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodKalmanOnly -> isJust mKalmanCtx'
                MethodKalmanPhysicsError -> isJust mKalmanCtx'
                MethodLstmOnly -> isJust mLstmCtx'
                MethodBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodConfBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodConfPick -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodConformalClip -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodCostPick -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodHarmonicBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodDisagreementGuard -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodMedianBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodNeutralGuard -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodRiskParityBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodConsensusBoost -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodAnchorBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodTensionGate -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodEntropyBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodCoherenceGate -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodDivergenceGate -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodFractalBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodPhaseCancel -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodSoftmaxBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodSmoothSoftmaxBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodHedgeBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodNetSoftmaxBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodEdgeBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodEdgePick -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodGeoBlend -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodRegimeSwitch -> isJust mLstmCtx' && isJust mKalmanCtx'
                MethodBanditRouter -> isJust mLstmCtx' && isJust mKalmanCtx'
        hasRequiredWindow =
            case method of
                MethodKalmanOnly -> n >= 1
                _ -> n >= lookback'

    if not ctxOk
        then pure st{botError = Just "Optimizer update skipped: missing model context.", botUpdatedAtMs = now}
        else
            if not hasRequiredWindow
                then pure st{botError = Just "Optimizer update skipped: not enough data for lookback.", botUpdatedAtMs = now}
                else do
                    let argsSignal = applyBotAdjustments (botAdjustments st) argsWithKeys
                    case computeLatestSignal
                        argsSignal
                        lookback'
                        (botFeatureInputs st)
                        mLstmCtx'
                        mKalmanCtx'
                        Nothing
                        Nothing of
                        Left err ->
                            pure st{botError = Just ("Optimizer update skipped: " ++ err), botUpdatedAtMs = now}
                        Right latest ->
                            pure
                                st
                                    { botArgs = sanitizeArgsKeys argsWithKeys
                                    , botLookback = lookback'
                                    , botLstmCtx = mLstmCtx'
                                    , botKalmanCtx = mKalmanCtx'
                                    , botComboUuid = bouComboUuid upd <|> botComboUuid st
                                    , botLatestSignal = latest
                                    , botUpdatedAtMs = now
                                    , botError = Nothing
                                    }

rebuildLstmCtx :: Args -> Int -> V.Vector Double -> IO (Either String LstmCtx)
rebuildLstmCtx args lookback pricesV =
    let closes = V.toList pricesV
        n = length closes
     in if n <= lookback
            then pure (Left "Not enough bars to rebuild LSTM context.")
            else do
                let normState = fitNorm (argNormalization args) closes
                    obsAll = forwardSeries normState closes
                    lstmCfg =
                        LSTMConfig
                            { lcLookback = lookback
                            , lcHiddenSize = argHiddenSize args
                            , lcEpochs = argEpochs args
                            , lcLearningRate = argLr args
                            , lcValRatio = argValRatio args
                            , lcPatience = argPatience args
                            , lcGradClip = argGradClip args
                            , lcSeed = argSeed args
                            }
                (lstmModel, _) <- trainLstmWithPersistence args lookback lstmCfg obsAll
                pure (Right (normState, obsAll, lstmModel))

rebuildKalmanCtx :: Args -> Int -> FeatureInputs -> Either String KalmanCtx
rebuildKalmanCtx args lookback featureInputs =
    let pricesV = fiClose featureInputs
        n = V.length pricesV
     in if n < 2
            then Left "Not enough bars to rebuild Kalman context."
            else
                let predictors = trainPredictorsWithInputsWithMarket (argPredictors args) lookback Nothing featureInputs
                    hmm0 = initHMMFilter predictors []
                    kal0 =
                        initKalman1
                            0
                            (max 1e-12 (argKalmanMeasurementVar args))
                            (max 0 (argKalmanProcessVar args) * max 0 (argKalmanDt args))
                    sv0 = emptySensorVar

                    step (kal, hmm, sv) t =
                        let priceT = pricesV V.! t
                            nextP = pricesV V.! (t + 1)
                            realizedR = if priceT == 0 then 0 else nextP / priceT - 1
                            (sensorOuts, predState) = predictSensorsWithInputs predictors featureInputs hmm t
                            meas = mapMaybe (toMeasurement args sv) sensorOuts
                            kal' = stepMulti meas kal
                            sv' =
                                foldl'
                                    (\acc (sid, out) -> updateResidual sid (realizedR - soMu out) acc)
                                    sv
                                    sensorOuts
                            hmm' = updateHMM predictors predState realizedR
                         in (kal', hmm', sv')

                    (kalPrev, hmmPrev, svPrev) = foldl' step (kal0, hmm0, sv0) [0 .. n - 2]
                 in Right (predictors, kalPrev, hmmPrev, svPrev)

parseTopComboToArgs :: Args -> TopCombo -> Either String Args
parseTopComboToArgs base combo = do
    let params = tcParams combo
        getStr k = KM.lookup k params >>= AT.parseMaybe parseJSON
        getInt k = KM.lookup k params >>= AT.parseMaybe parseJSON
        getDbl k = KM.lookup k params >>= AT.parseMaybe parseJSON
        getBool k = KM.lookup k params >>= AT.parseMaybe parseJSON
        getMaybeDbl k =
            case KM.lookup k params of
                Nothing -> Nothing
                Just Aeson.Null -> Just Nothing
                Just v ->
                    case AT.parseMaybe parseJSON v of
                        Nothing -> Nothing
                        Just d -> Just (Just d)

        methodRaw = getStr "method"
        normRaw = getStr "normalization"
        positioningRaw = getStr "positioning"
        intrabarFillRaw = getStr "intrabarFill"

    method <-
        case methodRaw of
            Nothing -> Right (argMethod base)
            Just v -> parseMethod v
    let normalization =
            case normRaw >>= parseNormType of
                Just n -> n
                Nothing -> argNormalization base
    _positioning <-
        case positioningRaw of
            Nothing -> Right (argPositioning base)
            Just v -> parsePositioning v
    intrabarFill <-
        case intrabarFillRaw of
            Nothing -> Right (argIntrabarFill base)
            Just v -> parseIntrabarFill v

    let openThr = max 0 (fromMaybe (argOpenThreshold base) (tcOpenThreshold combo))
        closeThr = max 0 (fromMaybe (argCloseThreshold base) (tcCloseThreshold combo <|> tcOpenThreshold combo))

        clamp01 x = max 0 (min 1 x)

        readMaybeInt = fmap (max 0) . getInt
        readMaybeDouble = fmap (\x -> if isNaN x || isInfinite x then 0 else x) . getDbl

        pickMaybeMaybeDbl k current =
            fromMaybe current (getMaybeDbl k)

        pickMaybeMaybeInt k current =
            case KM.lookup k params of
                Nothing -> current
                Just Aeson.Null -> Nothing
                Just v ->
                    case AT.parseMaybe parseJSON v of
                        Nothing -> current
                        Just n -> Just (max 0 n)

        pickMaybeMaybePositiveDbl k current =
            case getMaybeDbl k of
                Nothing -> current
                Just Nothing -> Nothing
                Just (Just v) -> if v > 0 then Just v else Nothing

        pickMaybeMaybeFraction k current =
            case getMaybeDbl k of
                Nothing -> current
                Just Nothing -> Nothing
                Just (Just v) -> if v > 0 && v <= 1 then Just v else Nothing

        pickBool k current =
            fromMaybe current (getBool k)

        pickD k current =
            fromMaybe current (readMaybeDouble k)

        pickI k current =
            fromMaybe current (readMaybeInt k)

        gradClip =
            case getMaybeDbl "gradClip" of
                Nothing -> argGradClip base
                Just Nothing -> Nothing
                Just (Just v) -> Just (max 0 v)

        fee = max 0 (pickD "fee" (argFee base))
        slippage = max 0 (pickD "slippage" (argSlippage base))
        spread = max 0 (pickD "spread" (argSpread base))
        feeFixed = max 0 (pickD "feeFixed" (argFeeFixed base))
        feeMin = max 0 (pickD "feeMin" (argFeeMin base))
        slippageVolMult = max 0 (pickD "slippageVolMult" (argSlippageVolMult base))
        slippageImpact = max 0 (pickD "slippageImpact" (argSlippageImpact base))
        slippageImpactPower = max 0 (pickD "slippageImpactPower" (argSlippageImpactPower base))
        spreadVolMult = max 0 (pickD "spreadVolMult" (argSpreadVolMult base))

        kalZMin = max 0 (pickD "kalmanZMin" (argKalmanZMin base))
        kalZMaxRaw = max 0 (pickD "kalmanZMax" (argKalmanZMax base))
        kalZMax = max kalZMin kalZMaxRaw

        maxHighVolProb = pickMaybeMaybeDbl "maxHighVolProb" (argMaxHighVolProb base)
        maxConformalWidth = pickMaybeMaybeDbl "maxConformalWidth" (argMaxConformalWidth base)
        maxQuantileWidth = pickMaybeMaybeDbl "maxQuantileWidth" (argMaxQuantileWidth base)

        maxDD = pickMaybeMaybeDbl "maxDrawdown" (argMaxDrawdown base)
        maxDL = pickMaybeMaybeDbl "maxDailyLoss" (argMaxDailyLoss base)
        maxOE = pickMaybeMaybeInt "maxOrderErrors" (argMaxOrderErrors base)

        orderQuantity = pickMaybeMaybePositiveDbl "orderQuantity" (argOrderQuantity base)
        orderQuote = pickMaybeMaybePositiveDbl "orderQuote" (argOrderQuote base)
        orderQuoteFraction = pickMaybeMaybeFraction "orderQuoteFraction" (argOrderQuoteFraction base)
        maxOrderQuote = pickMaybeMaybePositiveDbl "maxOrderQuote" (argMaxOrderQuote base)

        stopLoss = pickMaybeMaybeDbl "stopLoss" (argStopLoss base)
        takeProfit = pickMaybeMaybeDbl "takeProfit" (argTakeProfit base)
        trailingStop = pickMaybeMaybeDbl "trailingStop" (argTrailingStop base)

        confidenceSizing = pickBool "confidenceSizing" (argConfidenceSizing base)
        confirmConformal = pickBool "confirmConformal" (argConfirmConformal base)
        confirmQuantiles = pickBool "confirmQuantiles" (argConfirmQuantiles base)

        minPositionSize =
            case readMaybeDouble "minPositionSize" of
                Nothing -> argMinPositionSize base
                Just v -> clamp01 v

        minHoldBars = max 0 (pickI "minHoldBars" (argMinHoldBars base))
        cooldownBars = max 0 (pickI "cooldownBars" (argCooldownBars base))
        maxHoldBars =
            case pickMaybeMaybeInt "maxHoldBars" (argMaxHoldBars base) of
                Nothing -> Nothing
                Just n -> if n <= 0 then Nothing else Just n

        minEdge = max 0 (pickD "minEdge" (argMinEdge base))
        edgeBuffer = max 0 (pickD "edgeBuffer" (argEdgeBuffer base))
        costAwareEdge = pickBool "costAwareEdge" (argCostAwareEdge base)
        trendLookback = max 0 (pickI "trendLookback" (argTrendLookback base))
        maxPositionSize = max 0 (pickD "maxPositionSize" (argMaxPositionSize base))
        maxGrossExposure = pickMaybeMaybeDbl "maxGrossExposure" (argMaxGrossExposure base)
        maxNetExposure = pickMaybeMaybeDbl "maxNetExposure" (argMaxNetExposure base)
        maxExposurePerBase = pickMaybeMaybeDbl "maxExposurePerBase" (argMaxExposurePerBase base)

        volTarget =
            case pickMaybeMaybeDbl "volTarget" (argVolTarget base) of
                Nothing -> Nothing
                Just v -> if v <= 0 then Nothing else Just v
        volLookback = max 0 (pickI "volLookback" (argVolLookback base))
        volEwmaAlpha =
            case pickMaybeMaybeDbl "volEwmaAlpha" (argVolEwmaAlpha base) of
                Nothing -> Nothing
                Just v ->
                    if v > 0 && v < 1
                        then Just v
                        else Nothing
        volFloor = max 0 (pickD "volFloor" (argVolFloor base))
        volScaleMax = max 0 (pickD "volScaleMax" (argVolScaleMax base))
        maxVolatility =
            case pickMaybeMaybeDbl "maxVolatility" (argMaxVolatility base) of
                Nothing -> Nothing
                Just v -> if v <= 0 then Nothing else Just v

        rebalanceBars = max 0 (pickI "rebalanceBars" (argRebalanceBars base))
        rebalanceThreshold = max 0 (pickD "rebalanceThreshold" (argRebalanceThreshold base))
        rebalanceCostMult = max 0 (pickD "rebalanceCostMult" (argRebalanceCostMult base))
        rebalanceGlobal = pickBool "rebalanceGlobal" (argRebalanceGlobal base)
        rebalanceResetOnSignal = pickBool "rebalanceResetOnSignal" (argRebalanceResetOnSignal base)
        fundingRate = pickD "fundingRate" (argFundingRate base)
        fundingBySide = pickBool "fundingBySide" (argFundingBySide base)
        fundingOnOpen = pickBool "fundingOnOpen" (argFundingOnOpen base)

        blendWeight = clamp01 (pickD "blendWeight" (argBlendWeight base))
        triLayer = pickBool "triLayer" (argTriLayer base)
        triLayerFastMult = max 1e-6 (pickD "triLayerFastMult" (argTriLayerFastMult base))
        triLayerSlowMult = max 1e-6 (pickD "triLayerSlowMult" (argTriLayerSlowMult base))
        periodsPerYear =
            case pickMaybeMaybeDbl "periodsPerYear" (argPeriodsPerYear base) of
                Nothing -> Nothing
                Just v -> if v <= 0 then Nothing else Just v
        kalmanMarketTopN = max 0 (pickI "kalmanMarketTopN" (argKalmanMarketTopN base))

        walkForwardFolds = max 1 (pickI "walkForwardFolds" (argWalkForwardFolds base))
        walkForwardEmbargoBars = max 0 (pickI "walkForwardEmbargoBars" (argWalkForwardEmbargoBars base))
        tuneStressVolMult = max 1e-12 (pickD "tuneStressVolMult" (argTuneStressVolMult base))
        tuneStressShock = pickD "tuneStressShock" (argTuneStressShock base)
        tuneStressWeight = max 0 (pickD "tuneStressWeight" (argTuneStressWeight base))

        out =
            base
                { argMethod = method
                , argPositioning = _positioning
                , argNormalization = normalization
                , argOpenThreshold = openThr
                , argCloseThreshold = closeThr
                , argFee = fee
                , argFeeFixed = feeFixed
                , argFeeMin = feeMin
                , argEpochs = max 1 (pickI "epochs" (argEpochs base))
                , argHiddenSize = max 1 (pickI "hiddenSize" (argHiddenSize base))
                , argLr = max 1e-12 (pickD "learningRate" (argLr base))
                , argValRatio = clamp01 (pickD "valRatio" (argValRatio base))
                , argPatience = max 0 (pickI "patience" (argPatience base))
                , argGradClip = gradClip
                , argSlippage = slippage
                , argSpread = spread
                , argSlippageVolMult = slippageVolMult
                , argSlippageImpact = slippageImpact
                , argSlippageImpactPower = slippageImpactPower
                , argSpreadVolMult = spreadVolMult
                , argIntrabarFill = intrabarFill
                , argStopLoss = stopLoss
                , argTakeProfit = takeProfit
                , argTrailingStop = trailingStop
                , argMinHoldBars = minHoldBars
                , argCooldownBars = cooldownBars
                , argMaxHoldBars = maxHoldBars
                , argMaxDrawdown = maxDD
                , argMaxDailyLoss = maxDL
                , argMaxOrderErrors = maxOE
                , argOrderQuantity = orderQuantity
                , argOrderQuote = orderQuote
                , argOrderQuoteFraction = orderQuoteFraction
                , argMaxOrderQuote = maxOrderQuote
                , argMinEdge = minEdge
                , argCostAwareEdge = costAwareEdge
                , argEdgeBuffer = edgeBuffer
                , argTrendLookback = trendLookback
                , argMaxPositionSize = maxPositionSize
                , argMaxGrossExposure = maxGrossExposure
                , argMaxNetExposure = maxNetExposure
                , argMaxExposurePerBase = maxExposurePerBase
                , argVolTarget = volTarget
                , argVolLookback = volLookback
                , argVolEwmaAlpha = volEwmaAlpha
                , argVolFloor = volFloor
                , argVolScaleMax = volScaleMax
                , argMaxVolatility = maxVolatility
                , argRebalanceBars = rebalanceBars
                , argRebalanceThreshold = rebalanceThreshold
                , argRebalanceCostMult = rebalanceCostMult
                , argRebalanceGlobal = rebalanceGlobal
                , argRebalanceResetOnSignal = rebalanceResetOnSignal
                , argFundingRate = fundingRate
                , argFundingBySide = fundingBySide
                , argFundingOnOpen = fundingOnOpen
                , argBlendWeight = blendWeight
                , argTriLayer = triLayer
                , argTriLayerFastMult = triLayerFastMult
                , argTriLayerSlowMult = triLayerSlowMult
                , argKalmanDt = max 1e-12 (pickD "kalmanDt" (argKalmanDt base))
                , argKalmanProcessVar = max 1e-12 (pickD "kalmanProcessVar" (argKalmanProcessVar base))
                , argKalmanMeasurementVar = max 1e-12 (pickD "kalmanMeasurementVar" (argKalmanMeasurementVar base))
                , argKalmanMarketTopN = kalmanMarketTopN
                , argKalmanZMin = kalZMin
                , argKalmanZMax = kalZMax
                , argMaxHighVolProb = maxHighVolProb
                , argMaxConformalWidth = maxConformalWidth
                , argMaxQuantileWidth = maxQuantileWidth
                , argConfirmConformal = confirmConformal
                , argConfirmQuantiles = confirmQuantiles
                , argConfidenceSizing = confidenceSizing
                , argMinPositionSize = minPositionSize
                , argPeriodsPerYear = periodsPerYear
                , argWalkForwardFolds = walkForwardFolds
                , argWalkForwardEmbargoBars = walkForwardEmbargoBars
                , argTuneStressVolMult = tuneStressVolMult
                , argTuneStressShock = tuneStressShock
                , argTuneStressWeight = tuneStressWeight
                , argOptimizeOperations = False
                , argSweepThreshold = False
                }

    pure out

buildOptimizerUpdate :: BotState -> TopCombo -> IO (Either String BotOptimizerUpdate)
buildOptimizerUpdate st combo = do
    let curArgs = botArgs st
    case parseTopComboToArgs curArgs combo of
        Left e -> pure (Left e)
        Right args0 ->
            case argLookbackEither args0 of
                Left e -> pure (Left e)
                Right lookback -> do
                    let pricesV = botPrices st
                        n = V.length pricesV
                        hasLstmCtx = isJust (botLstmCtx st)
                        hasKalmanCtx = isJust (botKalmanCtx st)
                        method0 = runtimeMethod (argMethod args0)
                        needsLstm' =
                            method0 /= MethodKalmanOnly
                                && ( not hasLstmCtx
                                        || argHiddenSize args0 /= argHiddenSize curArgs
                                        || argNormalization args0 /= argNormalization curArgs
                                        || lookback /= botLookback st
                                   )
                        needsKalman' =
                            method0 /= MethodLstmOnly
                                && ( not hasKalmanCtx
                                        || argKalmanDt args0 /= argKalmanDt curArgs
                                        || argKalmanProcessVar args0 /= argKalmanProcessVar curArgs
                                        || argKalmanMeasurementVar args0 /= argKalmanMeasurementVar curArgs
                                        || argPredictors args0 /= argPredictors curArgs
                                        || lookback /= botLookback st
                                   )

                    let minBarsRequired
                            | needsLstm' = lookback + 1
                            | needsKalman' = 2
                            | otherwise = 1
                    if n < minBarsRequired
                        then
                            pure
                                ( Left
                                    ( printf
                                        "Not enough bars to apply optimizer update (need >= %d, got %d)."
                                        minBarsRequired
                                        n
                                    )
                                )
                        else do
                            mLstmE <- if needsLstm' then Just <$> rebuildLstmCtx args0 lookback pricesV else pure Nothing
                            let mKalE = if needsKalman' then Just (rebuildKalmanCtx args0 lookback (botFeatureInputs st)) else Nothing
                                collect =
                                    case (mLstmE, mKalE) of
                                        (Just (Left e), _) -> Left e
                                        (_, Just (Left e)) -> Left e
                                        (Just (Right l), Just (Right k)) -> Right (Just l, Just k)
                                        (Just (Right l), Nothing) -> Right (Just l, Nothing)
                                        (Nothing, Just (Right k)) -> Right (Nothing, Just k)
                                        (Nothing, Nothing) -> Right (Nothing, Nothing)
                            pure $
                                case collect of
                                    Left e -> Left e
                                    Right (mLstm, mKal) ->
                                        Right
                                            BotOptimizerUpdate
                                                { bouArgs = args0
                                                , bouLookback = lookback
                                                , bouLstmCtx = mLstm
                                                , bouKalmanCtx = mKal
                                                , bouComboUuid = Just (topComboUuid combo)
                                                , bouFinalEquity = tcFinalEquity combo
                                                , bouObjective = tcObjectiveLabel combo
                                                , bouScore = tcScore combo
                                                }

sanitizeFileComponent :: String -> String
sanitizeFileComponent raw =
    let go c = if isAlphaNum c || c == '-' || c == '_' then c else '-'
     in map go raw

botOptimizerLoop :: Maybe OpsStore -> Metrics -> Maybe Journal -> TopCombosStore -> MVar BotState -> MVar () -> MVar (Maybe BotOptimizerUpdate) -> IO ()
botOptimizerLoop mOps _metrics mJournal topCombosStore stVar stopSig pending = do
    let topJsonPath = tcsPath topCombosStore
    pollEnv <- lookupEnv "TRADER_BOT_COMBOS_POLL_SEC"
    let pollSec =
            case pollEnv >>= readMaybe of
                Just n | n >= 5 -> n
                _ -> 30
    lastErrRef <- newIORef (Nothing :: Maybe (String, String))

    let sleepSec s = threadDelay (max 1 s * 1000000)

        recordError kind msg tenantKey sym interval mComboUuid = do
            prev <- readIORef lastErrRef
            let cur = Just (kind, msg)
            if prev == cur
                then pure ()
                else do
                    writeIORef lastErrRef cur
                    now <- getTimestampMs
                    journalWriteMaybe
                        mJournal
                        ( object
                            [ "type" .= kind
                            , "atMs" .= now
                            , "error" .= msg
                            , "symbol" .= sym
                            , "interval" .= interval
                            , "path" .= topJsonPath
                            ]
                        )
                    opsAppendMaybe
                        mOps
                        (Just tenantKey)
                        (T.pack kind)
                        Nothing
                        Nothing
                        (Just (object ["error" .= msg, "symbol" .= sym, "interval" .= interval, "path" .= topJsonPath]))
                        Nothing
                        mComboUuid
                        (Just (T.pack sym))
                        Nothing

        clearError = writeIORef lastErrRef Nothing

        loop = do
            stopReq <- isJust <$> tryReadMVar stopSig
            if stopReq
                then pure ()
                else do
                    st <- readMVar stVar
                    let sym = botSymbol st
                        interval = argInterval (botArgs st)
                    combosOrErr <- readTopCombosExportWithDbFallback mOps topCombosStore
                    case combosOrErr of
                        Left e -> recordError "bot.combo.sync_failed" e (botTenantKey st) sym interval (botComboUuid st)
                        Right export ->
                            case bestTopComboForSymbol sym (Just interval) export of
                                Nothing -> recordError "bot.combo.sync_failed" "No top combo for symbol+interval." (botTenantKey st) sym interval (botComboUuid st)
                                Just bestCombo -> do
                                    clearError
                                    updOrErr <- buildOptimizerUpdate st bestCombo
                                    case updOrErr of
                                        Left e -> recordError "bot.combo.apply_failed" e (botTenantKey st) sym interval (botComboUuid st)
                                        Right upd -> do
                                            let argsChanged = bouArgs upd /= botArgs st || bouLookback upd /= botLookback st
                                                ctxChanged = isJust (bouLstmCtx upd) || isJust (bouKalmanCtx upd)
                                                shouldApply = argsChanged || ctxChanged
                                            when shouldApply $ do
                                                _ <- swapMVar pending (Just upd)
                                                now <- getTimestampMs
                                                opsAppendMaybe
                                                    mOps
                                                    (Just (botTenantKey st))
                                                    "bot.optimizer.best"
                                                    Nothing
                                                    (Just (argsPublicJson (botArgs st)))
                                                    ( Just
                                                        ( object
                                                            [ "symbol" .= sym
                                                            , "interval" .= interval
                                                            , "finalEquity" .= bouFinalEquity upd
                                                            , "objective" .= bouObjective upd
                                                            , "score" .= bouScore upd
                                                            , "appliedAtMs" .= now
                                                            ]
                                                        )
                                                    )
                                                    (bouFinalEquity upd)
                                                    (bouComboUuid upd <|> botComboUuid st)
                                                    (Just (T.pack sym))
                                                    Nothing
                    sleepSec pollSec
                    loop

    loop

autoOptimizerLoop :: Args -> Maybe StateSyncTarget -> Maybe OpsStore -> Maybe Journal -> FilePath -> TopCombosStore -> IO ()
autoOptimizerLoop baseArgs mStateSyncTarget mOps mJournal optimizerTmp topCombosStore = do
    enabledEnv <- lookupEnv "TRADER_OPTIMIZER_ENABLED"
    let enabled = readEnvBool enabledEnv True
    if not enabled
        then pure ()
        else
            if argPlatform baseArgs /= PlatformBinance
                then do
                    now <- getTimestampMs
                    let msg :: String
                        msg = "Auto optimizer supports Binance only."
                    journalWriteMaybe
                        mJournal
                        ( object
                            [ "type" .= ("optimizer.auto.platform_unsupported" :: String)
                            , "atMs" .= now
                            , "platform" .= platformCode (argPlatform baseArgs)
                            , "error" .= msg
                            ]
                        )
                    opsAppendMaybe
                        mOps
                        Nothing
                        "optimizer.auto.platform_unsupported"
                        Nothing
                        (Just (argsPublicJson baseArgs))
                        (Just (object ["error" .= msg]))
                        Nothing
                        Nothing
                        Nothing
                        Nothing
                else do
                    projectRoot <- getCurrentDirectory
                    let topJsonPath = tcsPath topCombosStore
                    optimizerExe <- resolveOptimizerExecutable projectRoot "optimize-equity"
                    mergeExe <- resolveOptimizerExecutable projectRoot "merge-top-combos"
                    let missing = [(name, err) | (name, Left err) <- [("optimize-equity", optimizerExe), ("merge-top-combos", mergeExe)]]
                    if not (null missing)
                        then do
                            now <- getTimestampMs
                            let missingNames = intercalate ", " (map fst missing)
                                missingErrs = intercalate "; " (map snd missing)
                            journalWriteMaybe
                                mJournal
                                ( object
                                    [ "type" .= ("optimizer.auto.missing_script" :: String)
                                    , "atMs" .= now
                                    , "script" .= missingNames
                                    , "error" .= missingErrs
                                    ]
                                )
                            opsAppendMaybe
                                mOps
                                Nothing
                                "optimizer.auto.missing_script"
                                Nothing
                                Nothing
                                (Just (object ["script" .= missingNames, "error" .= missingErrs]))
                                Nothing
                                Nothing
                                Nothing
                                Nothing
                        else do
                            envOrErr <- try (makeBinanceEnv mOps baseArgs) :: IO (Either SomeException BinanceEnv)
                            case envOrErr of
                                Left ex -> do
                                    now <- getTimestampMs
                                    journalWriteMaybe mJournal (object ["type" .= ("optimizer.auto.env_failed" :: String), "atMs" .= now, "error" .= show ex])
                                Right env -> do
                                    everySecEnv <- lookupEnv "TRADER_OPTIMIZER_EVERY_SEC"
                                    trialsEnv <- lookupEnv "TRADER_OPTIMIZER_TRIALS"
                                    timeoutEnv <- lookupEnv "TRADER_OPTIMIZER_TIMEOUT_SEC"
                                    objectiveEnv <- lookupEnv "TRADER_OPTIMIZER_OBJECTIVE"
                                    lookbackEnv <- lookupEnv "TRADER_OPTIMIZER_LOOKBACK_WINDOW"
                                    backtestEnv <- lookupEnv "TRADER_OPTIMIZER_BACKTEST_RATIO"
                                    tuneEnv <- lookupEnv "TRADER_OPTIMIZER_TUNE_RATIO"
                                    maxPointsEnv <- lookupEnv "TRADER_OPTIMIZER_MAX_POINTS"
                                    symbolsEnv <- lookupEnv "TRADER_OPTIMIZER_SYMBOLS"
                                    intervalsEnv <- lookupEnv "TRADER_OPTIMIZER_INTERVALS"
                                    maxCombos <- optimizerMaxCombosFromEnv
                                    maxOutputBytes <- optimizerOutputCapFromEnv
                                    exePath <- getExecutablePath

                                    let everySec :: Int
                                        everySec =
                                            case everySecEnv >>= readMaybe of
                                                Just n | n >= 5 -> n
                                                _ -> 300
                                        trials :: Int
                                        trials =
                                            case trialsEnv >>= readMaybe of
                                                Just n | n >= 1 -> n
                                                _ -> 20
                                        timeoutSec :: Int
                                        timeoutSec =
                                            case timeoutEnv >>= readMaybe of
                                                Just n | n >= 1 -> n
                                                _ -> 45
                                        maxPointsCap :: Int
                                        maxPointsCap = 5000
                                        maxPoints :: Int
                                        maxPoints =
                                            case maxPointsEnv >>= readMaybe of
                                                Just n | n >= 2 -> clampInt 2 maxPointsCap n
                                                _ -> 1000
                                        lookbackWindow = pickDefaultString "7d" lookbackEnv
                                        backtestRatio =
                                            case backtestEnv >>= readMaybe of
                                                Just n -> clamp01 n
                                                _ -> 0.2
                                        tuneRatio =
                                            case tuneEnv >>= readMaybe of
                                                Just n -> clamp01 n
                                                _ -> 0.25
                                        objectiveAllowed =
                                            [ "annualized-equity"
                                            , "roi"
                                            , "final-equity"
                                            , "sharpe"
                                            , "calmar"
                                            , "equity-dd"
                                            , "equity-dd-turnover"
                                            ]
                                        objectiveRaw = fmap (map toLower . trim) objectiveEnv
                                        objective =
                                            case objectiveRaw of
                                                Just v ->
                                                    case normalizeObjectiveCode v of
                                                        Right objectiveCode -> objectiveCode
                                                        Left _ -> "roi"
                                                _ -> "roi"
                                        symbols =
                                            case symbolsEnv of
                                                Just raw ->
                                                    let parsed = map normalizeSymbol (splitEnvList raw)
                                                     in if null parsed then defaultOptimizerSymbols else parsed
                                                Nothing -> defaultOptimizerSymbols
                                        intervalsRaw =
                                            case intervalsEnv of
                                                Just raw -> filter (isPlatformInterval PlatformBinance) (splitEnvList raw)
                                                Nothing -> ["1h", "2h", "4h", "6h", "12h", "1d"]
                                        intervals =
                                            filter
                                                ( \v -> case lookbackBarsFrom v lookbackWindow of
                                                    Left _ -> False
                                                    Right lb -> lb >= 2 && lb + 3 <= maxPoints
                                                )
                                                intervalsRaw
                                    if null symbols || null intervals
                                        then do
                                            now <- getTimestampMs
                                            journalWriteMaybe
                                                mJournal
                                                (object ["type" .= ("optimizer.auto.config_invalid" :: String), "atMs" .= now, "symbols" .= symbols, "intervals" .= intervals])
                                        else do
                                            putStrLn
                                                ( printf
                                                    "Auto optimizer enabled: symbols=%d intervals=%d everySec=%d trials=%d"
                                                    (length symbols)
                                                    (length intervals)
                                                    everySec
                                                    trials
                                                )
                                            let sleepSec s = threadDelay (max 1 s * 1000000)

                                                loop = do
                                                    mSym <- pickRandom symbols
                                                    mInterval <- pickRandom intervals
                                                    case (mSym, mInterval) of
                                                        (Just sym, Just interval) -> do
                                                            let csvPath = optimizerTmp </> ("auto-" ++ sanitizeFileComponent sym ++ "-" ++ sanitizeFileComponent interval ++ ".csv")
                                                                argsSym = baseArgs{argBinanceSymbol = Just sym}

                                                            ksOrErr <- try (fetchKlines env sym interval maxPoints) :: IO (Either SomeException [Kline])
                                                            case ksOrErr of
                                                                Left ex -> do
                                                                    now <- getTimestampMs
                                                                    journalWriteMaybe mJournal (object ["type" .= ("optimizer.auto.fetch_failed" :: String), "atMs" .= now, "error" .= show ex])
                                                                    sleepSec everySec
                                                                    loop
                                                                Right ks -> do
                                                                    if length ks < 2
                                                                        then do
                                                                            sleepSec everySec
                                                                            loop
                                                                        else do
                                                                            writeKlinesCsv csvPath ks
                                                                            ts <- fmap (floor . (* 1000)) getPOSIXTime
                                                                            randId <- randomIO :: IO Word64
                                                                            seedId <- randomIO :: IO Word64
                                                                            adoptOverride <-
                                                                                fmap
                                                                                    (either (const Nothing) (adoptRequirementLongShortOverride argsSym))
                                                                                    (resolveAdoptionRequirementWithEnv argsSym env sym)
                                                                            let recordsPath = optimizerTmp </> printf "optimizer-auto-%d-%016x.jsonl" (ts :: Integer) randId
                                                                                seed = fromIntegral (seedId `mod` 2000000000)
                                                                                cliArgs =
                                                                                    [ "--data"
                                                                                    , csvPath
                                                                                    , "--price-column"
                                                                                    , "close"
                                                                                    , "--high-column"
                                                                                    , "high"
                                                                                    , "--low-column"
                                                                                    , "low"
                                                                                    , "--interval"
                                                                                    , interval
                                                                                    , "--lookback-window"
                                                                                    , lookbackWindow
                                                                                    , "--backtest-ratio"
                                                                                    , show backtestRatio
                                                                                    , "--tune-ratio"
                                                                                    , show tuneRatio
                                                                                    , "--trials"
                                                                                    , show trials
                                                                                    , "--timeout-sec"
                                                                                    , show (timeoutSec :: Int)
                                                                                    , "--seed"
                                                                                    , show (seed :: Int)
                                                                                    , "--output"
                                                                                    , recordsPath
                                                                                    , "--symbol-label"
                                                                                    , sym
                                                                                    , "--source-label"
                                                                                    , "binance"
                                                                                    , "--objective"
                                                                                    , objective
                                                                                    , "--binary"
                                                                                    , exePath
                                                                                    , "--disable-lstm-persistence"
                                                                                    ]
                                                                                cliArgs' =
                                                                                    case adoptOverride of
                                                                                        Nothing -> cliArgs
                                                                                        Just pLongShort -> cliArgs ++ ["--p-long-short", show pLongShort]

                                                                            runResult <- runOptimizerProcess projectRoot recordsPath maxOutputBytes cliArgs'
                                                                            case runResult of
                                                                                Left (msg, out, err) -> do
                                                                                    now <- getTimestampMs
                                                                                    journalWriteMaybe
                                                                                        mJournal
                                                                                        ( object
                                                                                            [ "type" .= ("optimizer.auto.run_failed" :: String)
                                                                                            , "atMs" .= now
                                                                                            , "error" .= msg
                                                                                            , "stdout" .= out
                                                                                            , "stderr" .= err
                                                                                            ]
                                                                                        )
                                                                                Right _ -> do
                                                                                    mergeResult <- withTopCombosLock topCombosStore (runMergeTopCombos mStateSyncTarget projectRoot topJsonPath recordsPath maxCombos)
                                                                                    case mergeResult of
                                                                                        Left (msg, out, err) -> do
                                                                                            now <- getTimestampMs
                                                                                            journalWriteMaybe
                                                                                                mJournal
                                                                                                ( object
                                                                                                    [ "type" .= ("optimizer.auto.merge_failed" :: String)
                                                                                                    , "atMs" .= now
                                                                                                    , "error" .= msg
                                                                                                    , "stdout" .= out
                                                                                                    , "stderr" .= err
                                                                                                    ]
                                                                                                )
                                                                                        Right _ -> do
                                                                                            persistTopCombosDbMaybe mOps topCombosStore
                                                                                            opsAppendMaybe
                                                                                                mOps
                                                                                                Nothing
                                                                                                "optimizer.auto.updated"
                                                                                                Nothing
                                                                                                (Just (object ["symbol" .= sym, "interval" .= interval]))
                                                                                                Nothing
                                                                                                Nothing
                                                                                                Nothing
                                                                                                (Just (T.pack sym))
                                                                                                Nothing
                                                                                    _ <- try (removeFile recordsPath) :: IO (Either SomeException ())
                                                                                    pure ()
                                                                            sleepSec everySec
                                                                            loop
                                                        _ -> do
                                                            now <- getTimestampMs
                                                            journalWriteMaybe
                                                                mJournal
                                                                ( object
                                                                    [ "type" .= ("optimizer.auto.pick_failed" :: String)
                                                                    , "atMs" .= now
                                                                    , "symbols" .= length symbols
                                                                    , "intervals" .= length intervals
                                                                    ]
                                                                )
                                                            sleepSec everySec
                                                            loop

                                            loop

data TopCombosBacktestCtx = TopCombosBacktestCtx
    { tcbcBaseArgs :: !Args
    , tcbcLimits :: !ApiComputeLimits
    , tcbcGate :: !BacktestGate
    , tcbcOps :: !(Maybe OpsStore)
    , tcbcJournal :: !(Maybe Journal)
    , tcbcStore :: !TopCombosStore
    , tcbcStateSync :: !(Maybe StateSyncTarget)
    , tcbcLock :: !(MVar ())
    , tcbcCandleQueue :: !(TBQueue ())
    , tcbcEnabled :: !Bool
    }

withTopCombosBacktestLock :: TopCombosBacktestCtx -> IO a -> IO a
withTopCombosBacktestLock ctx action =
    withMVar (tcbcLock ctx) (const action)

backtestTopCombosOnce :: Int -> TopCombosBacktestCtx -> IO ()
backtestTopCombosOnce topNRaw ctx = do
    let topN = max 1 topNRaw
        baseArgs = tcbcBaseArgs ctx
        limits = tcbcLimits ctx
        backtestGate = tcbcGate ctx
        mOps = tcbcOps ctx
        mJournal = tcbcJournal ctx
    let store = tcbcStore ctx
        topJsonPath = tcsPath store
    let recordEvent :: String -> [(AK.Key, Aeson.Value)] -> IO ()
        recordEvent kind details = do
            now <- getTimestampMs
            journalWriteMaybe mJournal (object ("type" .= kind : "atMs" .= now : details))
            opsAppendMaybe mOps Nothing (T.pack kind) Nothing Nothing (Just (object details)) Nothing Nothing Nothing Nothing

        recordError :: String -> String -> Maybe String -> Maybe String -> IO ()
        recordError kind err sym interval = do
            let details =
                    [ "error" .= err
                    , "symbol" .= sym
                    , "interval" .= interval
                    , "path" .= topJsonPath
                    ]
            recordEvent kind details

        backtestCombo comboVal = do
            let mKey = comboIdentityKey comboVal
            case mKey of
                Nothing -> do
                    recordError "optimizer.combos.backtest_failed" "Missing combo identity." Nothing Nothing
                    pure Nothing
                Just key ->
                    case Aeson.fromJSON comboVal :: Aeson.Result TopCombo of
                        Aeson.Error err -> do
                            recordError "optimizer.combos.backtest_failed" err Nothing Nothing
                            pure Nothing
                        Aeson.Success combo -> do
                            let mSymbol = topComboSymbol combo
                                mInterval = topComboParamString "interval" combo
                                mPlatformRaw = topComboParamString "platform" combo
                                platformOrErr =
                                    case mPlatformRaw of
                                        Nothing -> Right (argPlatform baseArgs)
                                        Just raw ->
                                            if normalizeKey raw == "csv"
                                                then Left "CSV combos require --data."
                                                else parsePlatform raw
                            case (mSymbol, platformOrErr) of
                                (Nothing, _) -> do
                                    recordError "optimizer.combos.backtest_failed" "Missing combo symbol." Nothing mInterval
                                    pure Nothing
                                (_, Left e) -> do
                                    recordError "optimizer.combos.backtest_failed" e mSymbol mInterval
                                    pure Nothing
                                (Just sym, Right platform) -> do
                                    args0 <-
                                        case applyTopComboForStart baseArgs combo of
                                            Left e -> do
                                                recordError "optimizer.combos.backtest_failed" e (Just sym) mInterval
                                                pure Nothing
                                            Right out -> pure (Just out)
                                    case args0 of
                                        Nothing -> pure Nothing
                                        Just argsBase -> do
                                            let args1 =
                                                    argsBase
                                                        { argBinanceSymbol = Just sym
                                                        , argPlatform = platform
                                                        , argData = Nothing
                                                        , argTradeOnly = False
                                                        , argBinanceTrade = False
                                                        , argOptimizeOperations = False
                                                        , argSweepThreshold = False
                                                        }
                                            case validateApiComputeLimits limits args1 of
                                                Left e -> do
                                                    recordError "optimizer.combos.backtest_failed" e (Just sym) mInterval
                                                    pure Nothing
                                                Right argsOk -> do
                                                    backtestResult <- runBacktestWithGate backtestGate (computeBacktestFromArgs mOps argsOk)
                                                    case backtestResult of
                                                        Left failure ->
                                                            case failure of
                                                                BacktestBusy -> do
                                                                    recordEvent
                                                                        "optimizer.combos.backtest_skipped"
                                                                        [ "reason" .= ("busy" :: String)
                                                                        , "symbol" .= sym
                                                                        , "interval" .= mInterval
                                                                        , "path" .= topJsonPath
                                                                        ]
                                                                    pure Nothing
                                                                _ -> do
                                                                    recordError "optimizer.combos.backtest_failed" (backtestFailureMessage backtestGate failure) (Just sym) mInterval
                                                                    pure Nothing
                                                        Right out ->
                                                            case extractBacktestMetrics out of
                                                                Nothing -> do
                                                                    recordError "optimizer.combos.backtest_failed" "Backtest missing metrics." (Just sym) mInterval
                                                                    pure Nothing
                                                                Just metricsVal -> do
                                                                    let mFinalEq = comboMetricDouble "finalEquity" metricsVal
                                                                        objective = fromMaybe "final-equity" (tcObjectiveLabel combo)
                                                                        mScore = objectiveScoreFromMetrics argsOk objective metricsVal
                                                                        mOps = extractBacktestOperations out
                                                                        update =
                                                                            ComboBacktestUpdate
                                                                                { cbuMetrics = metricsVal
                                                                                , cbuFinalEquity = mFinalEq
                                                                                , cbuScore = mScore
                                                                                , cbuOperations = mOps
                                                                                }
                                                                    recordEvent
                                                                        "optimizer.combos.backtest"
                                                                        ( [ "symbol" .= sym
                                                                          , "interval" .= mInterval
                                                                          , "finalEquity" .= mFinalEq
                                                                          , "score" .= mScore
                                                                          ]
                                                                            ++ maybe [] (\v -> ["objective" .= v]) (tcObjectiveLabel combo)
                                                                        )
                                                                    pure (Just (key, update))

    baseValOrErr <- readTopCombosValueWithDbFallback (tcbcOps ctx) (tcbcStore ctx)
    case baseValOrErr of
        Left err -> recordError "optimizer.combos.backtest_failed" err Nothing Nothing
        Right baseVal ->
            case baseVal of
                Aeson.Object o ->
                    case KM.lookup (AK.fromString "combos") o of
                        Just (Aeson.Array combos) -> do
                            let combosList = V.toList combos
                                ranked = take topN (sortOn (\(_, v) -> comboPerformanceKey v) (zip [0 ..] combosList))
                            updates <- fmap catMaybes (forM ranked (\(_, v) -> backtestCombo v))
                            if null updates
                                then recordEvent "optimizer.combos.backtest_skipped" ["reason" .= ("no updates" :: String)]
                                else do
                                    withTopCombosLock store $ do
                                        latestValOrErr <- readTopCombosValueWithDbFallbackUnlocked (tcbcOps ctx) store
                                        case latestValOrErr of
                                            Left err ->
                                                recordError
                                                    "optimizer.combos.backtest_failed"
                                                    ("Failed to read latest top combos before applying updates: " ++ err)
                                                    Nothing
                                                    Nothing
                                            Right latestVal -> do
                                                now <- getTimestampMs
                                                let updateMap = HM.fromList updates
                                                case applyComboUpdates now updateMap latestVal of
                                                    Left err -> recordError "optimizer.combos.backtest_failed" err Nothing Nothing
                                                    Right (updatedVal, updatedCount) ->
                                                        if updatedCount <= 0
                                                            then recordEvent "optimizer.combos.backtest_skipped" ["reason" .= ("no matching combos" :: String)]
                                                            else do
                                                                writeResult <- writeTopCombosValue topJsonPath updatedVal
                                                                case writeResult of
                                                                    Left err -> recordError "optimizer.combos.backtest_failed" err Nothing Nothing
                                                                    Right _ -> do
                                                                        persistTopCombosMaybe (tcbcStateSync ctx) topJsonPath
                                                                        persistTopCombosDbMaybeUnlocked mOps store
                                                                        recordEvent
                                                                            "optimizer.combos.backtest_updated"
                                                                            [ "updated" .= updatedCount
                                                                            , "topN" .= topN
                                                                            , "path" .= topJsonPath
                                                                            ]
                        _ -> recordError "optimizer.combos.backtest_failed" "Top combos JSON missing combos array." Nothing Nothing
                _ -> recordError "optimizer.combos.backtest_failed" "Top combos JSON root must be an object." Nothing Nothing

topCombosCandleWorker :: TopCombosBacktestCtx -> IO ()
topCombosCandleWorker ctx = do
    let loop = do
            _ <- atomically (readTBQueue (tcbcCandleQueue ctx))
            when (tcbcEnabled ctx) $ do
                _ <- try (withTopCombosBacktestLock ctx (backtestTopCombosOnce 5 ctx)) :: IO (Either SomeException ())
                pure ()
            loop
    loop

triggerTopCombosBacktestOnCandle :: TopCombosBacktestCtx -> IO ()
triggerTopCombosBacktestOnCandle ctx =
    when (tcbcEnabled ctx) $
        atomically $ do
            let q = tcbcCandleQueue ctx
            full <- isFullTBQueue q
            unless full (writeTBQueue q ())

forkSupervisedWorker :: String -> IO () -> IO ThreadId
forkSupervisedWorker name action =
    forkIO (loop 0)
  where
    restartDelayUs = 1000000

    loop :: Int -> IO ()
    loop restartCount = do
        result <- try action
        case result of
            Right () -> do
                putStrLn (printf "Background worker '%s' exited; restarting (count=%d)." name (restartCount + 1))
                threadDelay restartDelayUs
                loop (restartCount + 1)
            Left ex ->
                case fromException ex :: Maybe AsyncException of
                    Just asyncEx -> throwIO asyncEx
                    Nothing -> do
                        putStrLn (printf "Background worker '%s' crashed: %s" name (displayException ex))
                        threadDelay restartDelayUs
                        loop (restartCount + 1)

autoTopCombosBacktestLoop :: TopCombosBacktestCtx -> IO ()
autoTopCombosBacktestLoop ctx =
    if not (tcbcEnabled ctx)
        then pure ()
        else do
            topNEnv <- lookupEnv "TRADER_TOP_COMBOS_BACKTEST_TOP_N"
            everySecEnv <- lookupEnv "TRADER_TOP_COMBOS_BACKTEST_EVERY_SEC"
            let minTopN = 5
                topNRequested =
                    case topNEnv >>= readMaybe of
                        Just n | n >= 1 -> n
                        _ -> minTopN
                topN = max minTopN topNRequested
                everySec =
                    case everySecEnv >>= readMaybe of
                        Just n | n >= 60 -> n
                        _ -> 86400
            let topJsonPath = tcsPath (tcbcStore ctx)
            putStrLn (printf "Top combos backtest enabled: topN=%d everySec=%d path=%s" topN everySec topJsonPath)
            let sleepSec s = threadDelay (max 1 s * 1000000)
                runOnce = withTopCombosBacktestLock ctx (backtestTopCombosOnce topN ctx)
                loop = do
                    runOnce
                    sleepSec everySec
                    loop
            loop

makeBinanceEnv :: Maybe OpsStore -> Args -> IO BinanceEnv
makeBinanceEnv mOps args = do
    when (argPlatform args /= PlatformBinance) $
        throwIO (userError ("Binance environment requires platform=binance (got " ++ platformCode (argPlatform args) ++ ")."))
    let market = argBinanceMarket args
    when (market == MarketMargin && argBinanceTestnet args) $
        throwIO (userError "--binance-testnet is not supported for margin operations")
    urls <- resolveBinanceBaseUrls
    let base = selectBinanceBaseUrl urls (argBinanceTestnet args) market
    apiKey <- resolveEnv "BINANCE_API_KEY" (argBinanceApiKey args)
    apiSecret <- resolveEnv "BINANCE_API_SECRET" (argBinanceApiSecret args)
    newBinanceEnvWithOps mOps market base (BS.pack <$> apiKey) (BS.pack <$> apiSecret)

makeCoinbaseEnv :: Args -> IO CoinbaseEnv
makeCoinbaseEnv args = do
    when (argPlatform args /= PlatformCoinbase) $
        throwIO (userError ("Coinbase environment requires platform=coinbase (got " ++ platformCode (argPlatform args) ++ ")."))
    apiKey <- resolveEnv "COINBASE_API_KEY" (argCoinbaseApiKey args)
    apiSecret <- resolveEnv "COINBASE_API_SECRET" (argCoinbaseApiSecret args)
    apiPassphrase <- resolveEnv "COINBASE_API_PASSPHRASE" (argCoinbaseApiPassphrase args)
    newCoinbaseEnv (BS.pack <$> apiKey) (BS.pack <$> apiSecret) (BS.pack <$> apiPassphrase)

botLoop :: Maybe OpsStore -> Metrics -> Maybe Journal -> Maybe Webhook -> Maybe FilePath -> TopCombosBacktestCtx -> BotController -> MVar BotState -> MVar () -> Maybe (MVar (Maybe BotOptimizerUpdate)) -> IO ()
botLoop mOps metrics mJournal mWebhook mBotStateDir topCombosCtx ctrl stVar stopSig mOptimizerPending = do
    tid <- myThreadId
    sym <- botSymbol <$> readMVar stVar
    lastStatusLogRef <- newIORef 0
    st0 <- readMVar stVar
    now0 <- getTimestampMs
    botStatusLogMaybe mOps True st0
    writeIORef lastStatusLogRef now0
    let sleepSec s = threadDelay (max 1 s * 1000000)
        logStatusIfDue st = do
            now <- getTimestampMs
            lastAt <- readIORef lastStatusLogRef
            when (now - lastAt >= botStatusLogIntervalMs) $ do
                writeIORef lastStatusLogRef now
                botStatusLogMaybe mOps True st

        loop = do
            stopReq <- isJust <$> tryReadMVar stopSig
            if stopReq
                then pure ()
                else do
                    case mOptimizerPending of
                        Nothing -> pure ()
                        Just pending -> do
                            mUpd <- modifyMVar pending $ \v -> pure (Nothing, v)
                            case mUpd of
                                Nothing -> pure ()
                                Just upd -> do
                                    st0 <- readMVar stVar
                                    st1 <- botApplyOptimizerUpdate st0 upd
                                    _ <- swapMVar stVar st1
                                    persistBotStatusMaybe mBotStateDir st1
                                    pure ()
                    st <- readMVar stVar
                    let env = botEnv st
                        sym = botSymbol st
                        pollSec = bsPollSeconds (botSettings st)
                    t0 <- getTimestampMs
                    r <- try (fetchKlines env sym (argInterval (botArgs st)) 10) :: IO (Either SomeException [Kline])
                    t1 <- getTimestampMs
                    let latMs = max 0 (fromIntegral (t1 - t0) :: Int)
                    case r of
                        Left ex -> do
                            let st' =
                                    st
                                        { botError = Just (show ex)
                                        , botUpdatedAtMs = t1
                                        , botPolledAtMs = t1
                                        , botPollLatencyMs = latMs
                                        }
                            _ <- swapMVar stVar st'
                            persistBotStatusMaybe mBotStateDir st'
                            logStatusIfDue st'
                            sleepSec pollSec
                            loop
                        Right ks -> do
                            let fetchedLast = lastMaybe ks
                                stPolled =
                                    st
                                        { botError = Nothing
                                        , botPolledAtMs = t1
                                        , botPollLatencyMs = latMs
                                        , botFetchedKlines = length ks
                                        , botFetchedLastKline = fetchedLast
                                        }
                                lastSeen = botLastOpenTime stPolled
                                newKs = filter (\k -> kOpenTime k > lastSeen) ks
                            if null newKs
                                then do
                                    _ <- swapMVar stVar stPolled
                                    persistBotStatusMaybe mBotStateDir stPolled
                                    logStatusIfDue stPolled
                                    sleepSec pollSec
                                    loop
                                else do
                                    tProc0 <- getTimestampMs
                                    st1 <- foldl' (\ioAcc k -> ioAcc >>= \s0 -> botApplyKlineSafe mOps metrics mJournal mWebhook topCombosCtx ctrl s0 k) (pure stPolled) newKs
                                    tProc1 <- getTimestampMs
                                    let batchMs = max 0 (fromIntegral (tProc1 - tProc0) :: Int)
                                        batchSize = length newKs
                                        st1' =
                                            st1
                                                { botLastBatchAtMs = tProc1
                                                , botLastBatchSize = batchSize
                                                , botLastBatchMs = batchMs
                                                }
                                    _ <- swapMVar stVar st1'
                                    persistBotStatusMaybe mBotStateDir st1'
                                    logStatusIfDue st1'
                                    loop

        cleanup = do
            st <- readMVar stVar
            let tenantKey = botTenantKey st
            modifyMVar_ (bcRuntime ctrl) $ \mrt ->
                case HM.lookup tenantKey mrt of
                    Just tenantMap ->
                        case HM.lookup sym tenantMap of
                            Just (BotRunning rt) | brThreadId rt == tid -> do
                                case brOptimizer rt of
                                    Nothing -> pure ()
                                    Just optRt -> do
                                        _ <- tryPutMVar (borStopSignal optRt) ()
                                        killThread (borThreadId optRt)
                                let tenantMap' = HM.delete sym tenantMap
                                pure
                                    ( if HM.null tenantMap'
                                        then HM.delete tenantKey mrt
                                        else HM.insert tenantKey tenantMap' mrt
                                    )
                            _ -> pure mrt
                    Nothing -> pure mrt

    loop `finally` cleanup

botApplyKlineSafe :: Maybe OpsStore -> Metrics -> Maybe Journal -> Maybe Webhook -> TopCombosBacktestCtx -> BotController -> BotState -> Kline -> IO BotState
botApplyKlineSafe mOps metrics mJournal mWebhook topCombosCtx ctrl st k = do
    r <- try (botApplyKline mOps metrics mJournal mWebhook topCombosCtx ctrl st k) :: IO (Either SomeException BotState)
    case r of
        Right st' -> pure st'
        Left ex -> do
            now <- getTimestampMs
            pure st{botError = Just (show ex), botUpdatedAtMs = now, botLastOpenTime = kOpenTime k}

botApplyKline :: Maybe OpsStore -> Metrics -> Maybe Journal -> Maybe Webhook -> TopCombosBacktestCtx -> BotController -> BotState -> Kline -> IO BotState
botApplyKline mOps metrics mJournal mWebhook topCombosCtx ctrl st k = do
    now <- getTimestampMs
    let args = botArgs st
        argsSignal = applyBotAdjustments (botAdjustments st) args
        lookback = botLookback st
        settings = botSettings st

        priceNew = kClose k
        openTimeNew = kOpenTime k

        pricesPrev = botPrices st
        nPrev = V.length pricesPrev

    when (nPrev < 1) $ throwIO (userError "botApplyKline: empty prices")

    let prevPrice = pricesPrev V.! (nPrev - 1)
        prevEq = botEquityCurve st V.! (nPrev - 1)
        prevPos = botPositions st V.! (nPrev - 1)
        barHigh0 = kHigh k
        barLow0 = kLow k
        barHigh1 =
            if isNaN barHigh0 || isInfinite barHigh0
                then priceNew
                else barHigh0
        barLow1 =
            if isNaN barLow0 || isInfinite barLow0
                then priceNew
                else barLow0
        barHigh = max priceNew (max barHigh1 barLow1)
        barLow = min priceNew (min barHigh1 barLow1)
        prevSize =
            case botOpenTrade st of
                Just ot | prevPos /= 0 -> max 0 (botOpenSize ot)
                _ -> if prevPos == 0 then 0 else 1
        markToMarket side basePx px =
            if basePx == 0
                then 1
                else case side of
                    SideLong -> px / basePx
                    SideShort -> 2 - px / basePx
        eqAfterReturn =
            case prevPos of
                1
                    | prevPrice > 0 ->
                        prevEq * (1 + prevSize * (markToMarket SideLong prevPrice priceNew - 1))
                (-1)
                    | prevPrice > 0 ->
                        prevEq * (1 + prevSize * (markToMarket SideShort prevPrice priceNew - 1))
                _ -> prevEq
        openTrade1 =
            case botOpenTrade st of
                Nothing -> Nothing
                Just ot ->
                    let side = botOpenSide ot
                        expectedPos =
                            case side of
                                SideLong -> 1
                                SideShort -> -1
                     in if prevPos /= expectedPos
                            then Nothing
                            else
                                let trail1 =
                                        case side of
                                            SideLong -> max (botOpenTrail ot) barHigh
                                            SideShort -> min (botOpenTrail ot) barLow
                                 in Just
                                        ot
                                            { botOpenHoldingPeriods = botOpenHoldingPeriods ot + 1
                                            , botOpenTrail = trail1
                                            }
        dayMs = 86400000 :: Int64
        dayKeyNew = openTimeNew `div` dayMs
        (dayKey1, dayStartEq1, dayTrades1) =
            if dayKeyNew /= botDayKey st
                then (dayKeyNew, prevEq, 0)
                else (botDayKey st, botDayStartEquity st, botDayTrades st)
        weekMs = 7 * dayMs
        weekKeyNew = openTimeNew `div` weekMs
        (weekKey1, weekStartEq1) =
            if weekKeyNew /= botWeekKey st
                then (weekKeyNew, prevEq)
                else (botWeekKey st, botWeekStartEquity st)
        peakEq0 = botPeakEquity st
        drawdown =
            if peakEq0 > 0
                then max 0 (1 - eqAfterReturn / peakEq0)
                else 0
        dailyLoss =
            if dayStartEq1 > 0
                then max 0 (1 - eqAfterReturn / dayStartEq1)
                else 0
        weeklyLoss =
            if weekStartEq1 > 0
                then max 0 (1 - eqAfterReturn / weekStartEq1)
                else 0
        expectancy =
            case (argMinExpectancy args, argExpectancyLookback args) of
                (Just _, n)
                    | n > 0 ->
                        let recent = take n (reverse (botTrades st))
                         in if length recent < n
                                then Nothing
                                else
                                    let returns = map trReturn recent
                                        vals = filter (\x -> not (isNaN x || isInfinite x)) returns
                                     in if null vals then Nothing else Just (sum vals / fromIntegral (length vals))
                _ -> Nothing
        riskHaltReason =
            if isJust (botHaltReason st)
                then Nothing
                else case () of
                    _
                        | maybe False (dailyLoss >=) (argMaxDailyLoss args) -> Just "MAX_DAILY_LOSS"
                        | maybe False (weeklyLoss >=) (argMaxWeeklyLoss args) -> Just "MAX_WEEKLY_LOSS"
                        | maybe False (drawdown >=) (argMaxDrawdown args) -> Just "MAX_DRAWDOWN"
                        | maybe False (\lim -> maybe False (< lim) expectancy) (argMinExpectancy args) -> Just "NEGATIVE_EXPECTANCY"
                        | otherwise -> Nothing
        haltReason1 = botHaltReason st <|> riskHaltReason
        haltedAt1 = botHaltedAtMs st <|> (if isJust riskHaltReason then Just now else Nothing)
        halted = isJust haltReason1

        pricesV = V.snoc pricesPrev priceNew
        opensV = V.snoc (botOpens st) (kOpen k)
        highsV = V.snoc (botHighs st) (kHigh k)
        lowsV = V.snoc (botLows st) (kLow k)
        volumesV = V.snoc (botVolumes st) (kVolume k)
        openTimesV = V.snoc (botOpenTimes st) openTimeNew
        featureInputs = mkFeatureInputs pricesV (Just opensV) (Just highsV) (Just lowsV) (Just volumesV)

    -- Update Kalman/HMM/sensor variance with the realized return on the last step.
    mKalmanCtx1 <-
        case botKalmanCtx st of
            Nothing -> pure Nothing
            Just (predictors, kalPrev, hmmPrev, svPrev) -> do
                let t = nPrev - 1
                    realizedR = if prevPrice == 0 then 0 else priceNew / prevPrice - 1
                    (sensorOuts, predState) = predictSensorsWithInputs predictors featureInputs hmmPrev t
                    meas = mapMaybe (toMeasurement args svPrev) sensorOuts
                    kal' = stepMulti meas kalPrev
                    sv' =
                        foldl'
                            (\acc (sid, out) -> updateResidual sid (realizedR - soMu out) acc)
                            svPrev
                            sensorOuts
                    hmm' = updateHMM predictors predState realizedR
                pure (Just (predictors, kal', hmm', sv'))

    -- LSTM: append the new observation and fine-tune for a few epochs.
    mLstmCtx1 <-
        case botLstmCtx st of
            Nothing -> pure Nothing
            Just (normState, obsAll, lstmModel0) -> do
                let obsAll' = obsAll ++ forwardSeries normState [priceNew]
                    trainBars = max (lookback + 2) (bsTrainBars settings)
                    obsTrain = takeLast trainBars obsAll'
                    epochs = bsOnlineEpochs settings
                    cfg =
                        LSTMConfig
                            { lcLookback = lookback
                            , lcHiddenSize = argHiddenSize args
                            , lcEpochs = epochs
                            , lcLearningRate = argLr args
                            , lcValRatio = 0
                            , lcPatience = 0
                            , lcGradClip = argGradClip args
                            , lcSeed = argSeed args
                            }
                    (lstmModel1, _) =
                        if epochs <= 0
                            then (lstmModel0, [])
                            else fineTuneLSTM cfg lstmModel0 obsTrain
                mPath <- lstmWeightsPath args lookback
                savePersistedLstmModelMaybe mPath (length obsTrain) lstmModel1
                pure (Just (normState, obsAll', lstmModel1))

    allStates <- botGetStates ctrl (botTenantKey st)

    latest0Raw <-
        case computeLatestSignal
            argsSignal
            lookback
            featureInputs
            mLstmCtx1
            mKalmanCtx1
            Nothing
            ( Just
                PredHistory
                    { phKalman = botKalmanPredNext st
                    , phLstm = botLstmPredNext st
                    , phMeta = Nothing
                    , phLstmHealth = Nothing
                    }
            ) of
            Left err -> throwIO (userError err)
            Right sig -> pure sig

    let nan = 0 / 0 :: Double
        kalPred1 = V.snoc (botKalmanPredNext st) (fromMaybe nan (lsKalmanNext latest0Raw))
        lstmPred1 = V.snoc (botLstmPredNext st) (fromMaybe nan (lsLstmNext latest0Raw))

        -- Stateful decision:
        -- - Entry uses the open-threshold signal.
        -- - Holds use the close-threshold direction when the open signal is neutral.
        allowShort = argPositioning args == LongShort
        chosenDir = lsChosenDir latest0Raw
        closeDir = lsCloseDir latest0Raw
        volConfHoldActive = "VOL_CONF_GATE_HOLD" `isInfixOf` lsAction latest0Raw

        desiredPosSignal =
            if prevPos /= 0 && volConfHoldActive
                then prevPos
                else case prevPos of
                    1 ->
                        case chosenDir of
                            Just 1 -> 1
                            Just (-1) ->
                                if allowShort
                                    then -1
                                    else 0
                            _ ->
                                case closeDir of
                                    Just 1 -> 1
                                    _ -> 0
                    (-1) ->
                        case chosenDir of
                            Just (-1) -> -1
                            Just 1 ->
                                if allowShort
                                    then 1
                                    else 0
                            _ ->
                                case closeDir of
                                    Just (-1) -> -1
                                    _ -> 0
                    _ ->
                        case chosenDir of
                            Just 1 -> 1
                            Just (-1) | allowShort -> -1
                            _ -> 0

        -- If we decide to exit (open/close signal neutral/opposite), force chosenDir to the exit side
        -- so a closing order can be placed when trading is enabled.
        latest0 =
            case (prevPos, desiredPosSignal) of
                (1, 0) ->
                    if lsChosenDir latest0Raw /= Just (-1)
                        then latest0Raw{lsChosenDir = Just (-1), lsAction = "FLAT (close)"}
                        else latest0Raw
                (-1, 0) ->
                    if lsChosenDir latest0Raw /= Just 1
                        then latest0Raw{lsChosenDir = Just 1, lsAction = "FLAT (close)"}
                        else latest0Raw
                _ -> latest0Raw

        volPerBar =
            case lsVolatility latest0Raw of
                Just vol ->
                    let perBar = vol / sqrt (max 1e-12 (periodsPerYear args))
                     in if isNaN perBar || isInfinite perBar || perBar <= 0 then Nothing else Just perBar
                _ -> Nothing

        clampFrac x = min 0.999999 (max 0 x)

        stopFromVol mult =
            if mult <= 0
                then Nothing
                else case volPerBar of
                    Just v ->
                        let frac = clampFrac (mult * v)
                         in if isNaN frac || isInfinite frac || frac <= 0 then Nothing else Just frac
                    _ -> Nothing

        stopLoss0 =
            case stopFromVol (argStopLossVolMult args) of
                Just v -> Just v
                Nothing ->
                    case argStopLoss args of
                        Just v | v > 0 -> Just (clampFrac v)
                        _ -> Nothing

        takeProfit0 =
            case stopFromVol (argTakeProfitVolMult args) of
                Just v -> Just v
                Nothing ->
                    case argTakeProfit args of
                        Just v | v > 0 -> Just (clampFrac v)
                        _ -> Nothing

        trailingStop0 =
            case stopFromVol (argTrailingStopVolMult args) of
                Just v -> Just v
                Nothing ->
                    case argTrailingStop args of
                        Just v | v > 0 -> Just (clampFrac v)
                        _ -> Nothing

        bracketExitReason side entryPx trail =
            case side of
                SideLong ->
                    let mTp =
                            case takeProfit0 of
                                Just tp -> Just (entryPx * (1 + tp))
                                Nothing -> Nothing
                        mSl =
                            case stopLoss0 of
                                Just sl -> Just (entryPx * (1 - sl))
                                Nothing -> Nothing
                        stopPx trailHigh0 =
                            let mTs =
                                    case trailingStop0 of
                                        Just ts -> Just (trailHigh0 * (1 - ts))
                                        Nothing -> Nothing
                             in case (mSl, mTs) of
                                    (Nothing, Nothing) -> (Nothing, Nothing)
                                    (Just slPx, Nothing) -> (Just slPx, Just "STOP_LOSS")
                                    (Nothing, Just tsPx) -> (Just tsPx, Just "TRAILING_STOP")
                                    (Just slPx, Just tsPx) ->
                                        if tsPx > slPx
                                            then (Just tsPx, Just "TRAILING_STOP")
                                            else (Just slPx, Just "STOP_LOSS")
                        tpHit = maybe False (barHigh >=) mTp
                     in case argIntrabarFill args of
                            StopFirst ->
                                let (mStop, stopWhy) = stopPx trail
                                    stopHit = maybe False (barLow <=) mStop
                                 in if stopHit
                                        then stopWhy
                                        else
                                            if tpHit
                                                then Just "TAKE_PROFIT"
                                                else Nothing
                            TakeProfitFirst ->
                                if tpHit
                                    then Just "TAKE_PROFIT"
                                    else
                                        let trailHigh1 = max trail barHigh
                                            (mStop, stopWhy) = stopPx trailHigh1
                                            stopHit = maybe False (barLow <=) mStop
                                         in if stopHit then stopWhy else Nothing
                SideShort ->
                    let mTp =
                            case takeProfit0 of
                                Just tp -> Just (entryPx * (1 - tp))
                                Nothing -> Nothing
                        mSl =
                            case stopLoss0 of
                                Just sl -> Just (entryPx * (1 + sl))
                                Nothing -> Nothing
                        stopPx trailLow0 =
                            let mTs =
                                    case trailingStop0 of
                                        Just ts -> Just (trailLow0 * (1 + ts))
                                        Nothing -> Nothing
                             in case (mSl, mTs) of
                                    (Nothing, Nothing) -> (Nothing, Nothing)
                                    (Just slPx, Nothing) -> (Just slPx, Just "STOP_LOSS")
                                    (Nothing, Just tsPx) -> (Just tsPx, Just "TRAILING_STOP")
                                    (Just slPx, Just tsPx) ->
                                        if tsPx < slPx
                                            then (Just tsPx, Just "TRAILING_STOP")
                                            else (Just slPx, Just "STOP_LOSS")
                        tpHit = maybe False (barLow <=) mTp
                     in case argIntrabarFill args of
                            StopFirst ->
                                let (mStop, stopWhy) = stopPx trail
                                    stopHit = maybe False (barHigh >=) mStop
                                 in if stopHit
                                        then stopWhy
                                        else
                                            if tpHit
                                                then Just "TAKE_PROFIT"
                                                else Nothing
                            TakeProfitFirst ->
                                if tpHit
                                    then Just "TAKE_PROFIT"
                                    else
                                        let trailLow1 = min trail barLow
                                            (mStop, stopWhy) = stopPx trailLow1
                                            stopHit = maybe False (barHigh >=) mStop
                                         in if stopHit then stopWhy else Nothing

        mBracketExit =
            case openTrade1 of
                Just ot ->
                    let side = botOpenSide ot
                        expectedPos =
                            case side of
                                SideLong -> 1
                                SideShort -> -1
                     in if prevPos == expectedPos
                            then bracketExitReason side (botOpenEntryPrice ot) (botOpenTrail ot)
                            else Nothing
                _ -> Nothing

        partialTpFrac = clamp01 (argTakeProfitPartial args)
        partialTpEligible =
            partialTpFrac > 0
                && partialTpFrac < 1
                && prevPos /= 0
                && desiredPosSignal == prevPos
                && mBracketExit == Just "TAKE_PROFIT"
                && not halted
                && maybe False (not . botOpenPartialTaken) openTrade1

        (mBracketExit1, mPartialExitReason) =
            if partialTpEligible
                then (Nothing, Just "TAKE_PROFIT_PARTIAL")
                else (mBracketExit, Nothing)

        (latestPre, desiredPosPre, mExitReasonPre) =
            case mBracketExit1 of
                Just why ->
                    let closeDir = if prevPos > 0 then Just (-1) else Just 1
                        sigExit = latest0{lsChosenDir = closeDir, lsAction = "EXIT_" ++ why}
                     in (sigExit, 0, Just why)
                Nothing ->
                    let exitReason =
                            if prevPos /= 0 && desiredPosSignal /= prevPos
                                then Just "SIGNAL"
                                else Nothing
                     in (latest0, desiredPosSignal, exitReason)

        (latest0b, desiredPosWanted0b, mExitReason0b) =
            if halted
                then
                    let why = haltReason1
                        latestHalt =
                            case (prevPos, why) of
                                (1, Just r) -> latestPre{lsChosenDir = Just (-1), lsAction = "EXIT_" ++ r}
                                (-1, Just r) -> latestPre{lsChosenDir = Just 1, lsAction = "EXIT_" ++ r}
                                (0, Just r) -> latestPre{lsChosenDir = Nothing, lsAction = "HALTED_" ++ r}
                                _ -> latestPre
                        exitReason =
                            case (prevPos, why) of
                                (1, Just r) -> Just r
                                (-1, Just r) -> Just r
                                _ -> mExitReasonPre
                     in (latestHalt, 0, exitReason)
                else (latestPre, desiredPosPre, mExitReasonPre)

        holdBars =
            maybe 0 botOpenHoldingPeriods openTrade1

        minHoldBars = max 0 (argMinHoldBars args)
        maxHoldBars =
            case argMaxHoldBars args of
                Just v | v > 0 -> Just v
                _ -> Nothing
        cooldownBars = max 0 (argCooldownBars args)
        cooldownLeft0 = max 0 (botCooldownLeft st)
        cooldownBlocked = prevPos == 0 && cooldownLeft0 > 0
        positionNow st' = vectorLastOr 0 (botPositions st')
        baseAssetFor st' =
            fst
                ( splitSymbolForPlatform
                    (Just (T.pack (platformCode (argPlatform (botArgs st')))))
                    (T.pack (botSymbol st'))
                )
        baseAssetNow = baseAssetFor st
        entrySizePre = entryScaleForSignal args (beMarket (botEnv st)) latest2
        openPositionsTotal = length [s | s <- allStates, positionNow s /= 0]
        openPositionsBase =
            case baseAssetNow of
                Nothing -> 0
                Just base -> length [s | s <- allStates, positionNow s /= 0, baseAssetFor s == Just base]
        countBlocked =
            case argMaxOpenPositions args of
                Just lim | lim > 0 -> openPositionsTotal >= lim
                _ -> False
        baseCountBlocked =
            case argMaxOpenPerBase args of
                Just lim | lim > 0 -> openPositionsBase >= lim
                _ -> False
        positionSizeFor st' =
            case botOpenTrade st' of
                Just ot | positionNow st' /= 0 -> max 0 (botOpenSize ot)
                _ ->
                    if positionNow st' == 0
                        then 0
                        else max 0 (argMaxPositionSize (botArgs st'))
        signedSizeFor st' =
            let s = positionSizeFor st'
             in fromIntegral (positionNow st') * s
        grossExposureNow =
            sum [abs (signedSizeFor s) | s <- allStates]
        netExposureNow =
            sum [signedSizeFor s | s <- allStates]
        baseExposureNow =
            case baseAssetNow of
                Nothing -> 0
                Just base ->
                    sum
                        [ abs (signedSizeFor s)
                        | s <- allStates
                        , positionNow s /= 0
                        , baseAssetFor s == Just base
                        ]
        desiredSize =
            if desiredPosWanted2 /= 0
                then entrySizePre
                else 0
        currentSigned = fromIntegral prevPos * prevSize
        desiredSigned = fromIntegral desiredPosWanted2 * desiredSize
        grossExposureAfter = grossExposureNow - abs currentSigned + abs desiredSigned
        netExposureAfter = netExposureNow - currentSigned + desiredSigned
        baseExposureAfter = baseExposureNow - abs currentSigned + abs desiredSigned
        grossExposureBlocked =
            case argMaxGrossExposure args of
                Just lim | lim > 0 -> grossExposureAfter > lim
                _ -> False
        netExposureBlocked =
            case argMaxNetExposure args of
                Just lim | lim > 0 -> abs netExposureAfter > lim
                _ -> False
        baseExposureBlocked =
            case argMaxExposurePerBase args of
                Just lim | lim > 0 -> baseExposureAfter > lim
                _ -> False

        (latest1, desiredPosWanted1, mExitReason1) =
            if prevPos /= 0 && desiredPosWanted0b /= prevPos && mExitReason0b == Just "SIGNAL" && holdBars < minHoldBars
                then (latest0b{lsAction = "HOLD_MIN_HOLD"}, prevPos, Nothing)
                else (latest0b, desiredPosWanted0b, mExitReason0b)

        holdTooLong =
            case maxHoldBars of
                Nothing -> False
                Just lim -> prevPos /= 0 && holdBars >= lim && desiredPosWanted1 == prevPos

        maxHoldExit = holdTooLong

        (latest2, desiredPosWanted2, mExitReason2) =
            if holdTooLong
                then
                    let closeDir = if prevPos > 0 then Just (-1) else Just 1
                     in (latest1{lsChosenDir = closeDir, lsAction = "EXIT_MAX_HOLD"}, 0, Just "MAX_HOLD")
                else (latest1, desiredPosWanted1, mExitReason1)

        noTradeActive =
            case argNoTradeWindows args of
                [] -> False
                windows -> any (\w -> timeWindowContains w (minuteOfDayFromMs openTimeNew)) windows
        tradeLimitReached =
            case argMaxTradesPerDay args of
                Just lim | lim > 0 -> dayTrades1 >= lim
                _ -> False
        (perfStatsForGate, _perfMode) =
            selectPerfStatsForPerfGate args latest0Raw (botPerfStats st) (botTrades st)
        perfGateReasonMaybe = perfGateReason args perfStatsForGate
        entryAttempt = desiredPosWanted2 /= 0 && desiredPosWanted2 /= prevPos
        entryAttemptFromFlat = prevPos == 0 && desiredPosWanted2 /= 0
        entryBlockReason
            | entryAttemptFromFlat && countBlocked = Just "MAX_OPEN_POSITIONS"
            | entryAttemptFromFlat && baseCountBlocked = Just "MAX_OPEN_PER_BASE"
            | entryAttempt && grossExposureBlocked = Just "MAX_GROSS_EXPOSURE"
            | entryAttempt && netExposureBlocked = Just "MAX_NET_EXPOSURE"
            | entryAttempt && baseExposureBlocked = Just "MAX_EXPOSURE_PER_BASE"
            | entryAttempt && noTradeActive = Just "NO_TRADE_WINDOW"
            | entryAttempt && tradeLimitReached = Just "MAX_TRADES_PER_DAY"
            | entryAttempt = perfGateReasonMaybe
            | otherwise = Nothing

        (latest2b, desiredPosWanted2b, mExitReason2b) =
            case entryBlockReason of
                Just reason ->
                    let isPerfGate = reason == "PERF_WIN_RATE" || reason == "PERF_PROFIT_FACTOR"
                        flipAttempt = prevPos /= 0 && desiredPosWanted2 /= 0 && desiredPosWanted2 /= prevPos
                        action =
                            if isPerfGate && flipAttempt
                                then "EXIT_" ++ reason
                                else "HOLD_" ++ reason
                     in if prevPos == 0
                            then (latest2{lsAction = action}, 0, Nothing)
                            else
                                if isPerfGate && flipAttempt
                                    then (latest2{lsAction = action}, 0, Just reason)
                                    else (latest2{lsAction = action}, prevPos, Nothing)
                Nothing -> (latest2, desiredPosWanted2, mExitReason2)

        (latest, desiredPosWanted, mExitReason) =
            if prevPos == 0 && desiredPosWanted2b /= 0 && cooldownBlocked
                then (latest2b{lsAction = "HOLD_COOLDOWN"}, 0, Nothing)
                else (latest2b, desiredPosWanted2b, mExitReason2b)

        partialExitWanted =
            case mPartialExitReason of
                Just _ -> prevPos /= 0 && desiredPosWanted == prevPos
                Nothing -> False
        latestFinal =
            if partialExitWanted
                then latest{lsAction = fromMaybe (lsAction latest) mPartialExitReason, lsExitSize = Just partialTpFrac}
                else latest

        wantSwitch = desiredPosWanted /= prevPos
        latestOrder =
            case desiredPosWanted of
                1 -> latestFinal{lsChosenDir = Just 1}
                -1 -> latestFinal{lsChosenDir = Just (-1)}
                0 ->
                    if prevPos == 0
                        then latestFinal{lsChosenDir = Nothing}
                        else latestFinal{lsChosenDir = Just (negate prevPos)}
                x ->
                    if x > 0
                        then latestFinal{lsChosenDir = Just 1}
                        else latestFinal{lsChosenDir = Just (-1)}
        entrySize = entryScaleForSignal args (beMarket (botEnv st)) latestFinal
        qtyEps = 1e-9
        isPositiveQty q = q > qtyEps
        requestedQtyFromOrder fallbackQty o =
            case aorQuantity o of
                Just q | not (isNaN q || isInfinite q) && q > 0 -> q
                _ ->
                    if not (isNaN fallbackQty || isInfinite fallbackQty) && fallbackQty > 0
                        then fallbackQty
                        else 0
        executedQtyFromOrder fallbackQty o =
            let evidence =
                    OrderExecutionEvidence
                        { oeeSent = aorSent o
                        , oeeLive = argBinanceLive args
                        , oeeStatus = aorStatus o
                        , oeeExecutedQty = aorExecutedQty o
                        }
             in orderAppliedQuantity evidence fallbackQty
        applyCostForSize eq size =
            if isPositiveQty size
                then
                    let feeFrac = costPerSideTotal args size volPerBar
                     in eq * (1 - feeFrac)
                else eq
        openTradeFor side eqEntry size =
            BotOpenTrade
                { botOpenEntryIndex = nPrev
                , botOpenEntryEquity = eqEntry
                , botOpenEntryIp = botTradeOriginIp st
                , botOpenComboUuid = botComboUuid st
                , botOpenEntryHighVolProb = rpHighVol <$> lsRegimes latestFinal
                , botOpenHoldingPeriods = 0
                , botOpenEntryPrice = priceNew
                , botOpenSize = size
                , botOpenTrail = priceNew
                , botOpenSide = side
                , botOpenPartialTaken = False
                }
        closeTradeAt exitEq ot =
            Trade
                { trEntryIndex = botOpenEntryIndex ot
                , trExitIndex = nPrev
                , trEntryEquity = botOpenEntryEquity ot
                , trExitEquity = exitEq
                , trReturn = exitEq / botOpenEntryEquity ot - 1
                , trHoldingPeriods = botOpenHoldingPeriods ot
                , trEntryHighVolProb = botOpenEntryHighVolProb ot
                , trExitReason = exitReasonFromCode <$> mExitReason
                , trEntryIp = botOpenEntryIp ot
                , trExitIp = botTradeOriginIp st
                }
        sideFromPos p = if p >= 0 then SideLong else SideShort
        targetQtyForSwitch =
            case (prevPos, desiredPosWanted) of
                (0, 1) -> entrySize
                (0, -1) -> entrySize
                (1, 0) -> prevSize
                (-1, 0) -> prevSize
                (1, -1) -> prevSize + entrySize
                (-1, 1) -> prevSize + entrySize
                _ -> max prevSize entrySize

    (ops', orders', trades', openTrade', mOrder, posFinal, eqFinal, switchedApplied, orderErrors1, haltReason2, haltedAt2) <-
        if partialExitWanted
            then do
                oPartial <- placeBotCloseIfEnabled args settings latestFinal (botEnv st) (botSymbol st)
                let opSide = if prevPos > 0 then "SELL" else "BUY"
                    orderEv = BotOrderEvent nPrev opSide priceNew openTimeNew now oPartial
                    ordersNew = botOrders st ++ [orderEv]
                    tradeEnabled = bsTradeEnabled settings
                    targetQty = max 0 (min prevSize (prevSize * partialTpFrac))
                    requestedQty = requestedQtyFromOrder targetQty oPartial
                    executedQtyRaw =
                        if not tradeEnabled
                            then requestedQty
                            else fromMaybe 0 (executedQtyFromOrder requestedQty oPartial)
                    (posAfterPartial, remainingSizeRaw, closedQty, _) =
                        applyReduceOnlyExecutedQuantity prevPos prevSize executedQtyRaw
                    partialSize = max 0 (min prevSize closedQty)
                    remainingSize = max 0 remainingSizeRaw
                    appliedPartial = isPositiveQty partialSize
                    eqAfterFee =
                        if appliedPartial
                            then applyCostForSize eqAfterReturn partialSize
                            else eqAfterReturn
                    (openTradeNew, tradesNew) =
                        if not appliedPartial
                            then (openTrade1, botTrades st)
                            else case (prevPos, posAfterPartial, openTrade1) of
                                (p, newPos, Just ot)
                                    | newPos == p && remainingSize > qtyEps ->
                                        (Just ot{botOpenSize = remainingSize, botOpenPartialTaken = True}, botTrades st)
                                (_, 0, Just ot) ->
                                    (Nothing, botTrades st ++ [closeTradeAt eqAfterFee ot])
                                (_, newPos, _)
                                    | newPos /= 0 ->
                                        (Just (openTradeFor (sideFromPos newPos) eqAfterFee remainingSize), botTrades st)
                                _ -> (openTrade1, botTrades st)
                    errors0 = botConsecutiveOrderErrors st
                    errors1 =
                        if tradeEnabled
                            then if appliedPartial then 0 else errors0 + 1
                            else 0
                    (haltReason3, haltedAt3) =
                        case haltReason1 of
                            Just _ -> (haltReason1, haltedAt1)
                            Nothing ->
                                case argMaxOrderErrors args of
                                    Just lim | errors1 >= lim -> (Just "MAX_ORDER_ERRORS", Just now)
                                    _ -> (Nothing, Nothing)

                metricsRecordOrder metrics oPartial
                journalWriteMaybe
                    mJournal
                    ( object
                        [ "type" .= ("bot.order" :: String)
                        , "atMs" .= now
                        , "symbol" .= botSymbol st
                        , "market" .= marketCode (argBinanceMarket args)
                        , "event" .= orderEv
                        , "partial" .= True
                        , "partialSize" .= partialSize
                        , "remainingSize" .= remainingSize
                        ]
                    )
                opsAppendMaybe
                    mOps
                    (Just (botTenantKey st))
                    "bot.order"
                    Nothing
                    (Just (argsPublicJson args))
                    ( Just
                        ( object
                            [ "symbol" .= botSymbol st
                            , "market" .= marketCode (argBinanceMarket args)
                            , "interval" .= argInterval args
                            , "event" .= orderEv
                            , "signal" .= latestFinal
                            , "position" .= posAfterPartial
                            , "partial" .= True
                            , "partialSize" .= partialSize
                            , "remainingSize" .= remainingSize
                            , "originIp" .= botTradeOriginIp st
                            ]
                        )
                    )
                    (Just eqAfterFee)
                    (orderComboUuid (prevPos /= 0) (botOpenTradeComboUuidMaybe openTrade1) (botComboUuid st))
                    (Just (T.pack (botSymbol st)))
                    (orderIdFromOrderResult oPartial)
                webhookNotifyMaybe mWebhook (webhookEventBotOrder args (botSymbol st) opSide priceNew oPartial)

                pure
                    ( if posAfterPartial /= prevPos
                        then botOps st ++ [BotOp nPrev opSide priceNew]
                        else botOps st
                    , ordersNew
                    , tradesNew
                    , openTradeNew
                    , Just oPartial
                    , posAfterPartial
                    , eqAfterFee
                    , posAfterPartial /= prevPos
                    , errors1
                    , haltReason3
                    , haltedAt3
                    )
            else
                if not wantSwitch
                    then
                        pure
                            ( botOps st
                            , botOrders st
                            , botTrades st
                            , openTrade1
                            , Nothing
                            , prevPos
                            , eqAfterReturn
                            , False
                            , botConsecutiveOrderErrors st
                            , haltReason1
                            , haltedAt1
                            )
                    else do
                        let closeOnlySwitch = desiredPosWanted == 0 && prevPos /= 0
                        o <-
                            if argPositioning args == LongShort && closeOnlySwitch
                                then placeBotCloseIfEnabled args settings latestOrder (botEnv st) (botSymbol st)
                                else placeIfEnabled args settings latestOrder (botEnv st) (botSymbol st)
                        let opSide =
                                if desiredPosWanted > prevPos
                                    then "BUY"
                                    else "SELL"
                            orderEv = BotOrderEvent nPrev opSide priceNew openTimeNew now o
                            ordersNew = botOrders st ++ [orderEv]
                            tradeEnabled = bsTradeEnabled settings
                            alreadyMsg =
                                let msg = aorMessage o
                                 in "already long" `isInfixOf` msg || "already short" `isInfixOf` msg || "already flat" `isInfixOf` msg
                            requestedQty = requestedQtyFromOrder targetQtyForSwitch o
                            executedQtyRaw
                                | not tradeEnabled = requestedQty
                                | alreadyMsg = requestedQty
                                | otherwise = fromMaybe 0 (executedQtyFromOrder requestedQty o)
                            (posNew, sizeNew, closeQty, openQty) =
                                if closeOnlySwitch
                                    then applyReduceOnlyExecutedQuantity prevPos prevSize executedQtyRaw
                                    else applyExecutedQuantity prevPos prevSize (opSide == "BUY") executedQtyRaw
                            appliedExecution =
                                isPositiveQty closeQty || isPositiveQty openQty
                            eqAfterFee =
                                if appliedExecution
                                    then applyCostForSize (applyCostForSize eqAfterReturn closeQty) openQty
                                    else eqAfterReturn
                            switchedApplied1 = posNew /= prevPos
                            opsNew =
                                if switchedApplied1
                                    then botOps st ++ [BotOp nPrev opSide priceNew]
                                    else botOps st
                            (openTradeNew, tradesNew) =
                                if not appliedExecution
                                    then (openTrade1, botTrades st)
                                    else case (prevPos, posNew, openTrade1) of
                                        (0, 1, _) -> (Just (openTradeFor SideLong eqAfterFee sizeNew), botTrades st)
                                        (0, -1, _) -> (Just (openTradeFor SideShort eqAfterFee sizeNew), botTrades st)
                                        (1, 0, Just ot) -> (Nothing, botTrades st ++ [closeTradeAt eqAfterFee ot])
                                        (-1, 0, Just ot) -> (Nothing, botTrades st ++ [closeTradeAt eqAfterFee ot])
                                        (1, 1, Just ot) -> (Just ot{botOpenSize = sizeNew}, botTrades st)
                                        (-1, -1, Just ot) -> (Just ot{botOpenSize = sizeNew}, botTrades st)
                                        (1, -1, Just ot) -> (Just (openTradeFor SideShort eqAfterFee sizeNew), botTrades st ++ [closeTradeAt eqAfterFee ot])
                                        (-1, 1, Just ot) -> (Just (openTradeFor SideLong eqAfterFee sizeNew), botTrades st ++ [closeTradeAt eqAfterFee ot])
                                        (_, p, _) | p /= 0 -> (Just (openTradeFor (sideFromPos p) eqAfterFee sizeNew), botTrades st)
                                        _ -> (openTrade1, botTrades st)
                            errors0 = botConsecutiveOrderErrors st
                            errors1 =
                                if tradeEnabled
                                    then if appliedExecution then 0 else errors0 + 1
                                    else 0
                            (haltReason3, haltedAt3) =
                                case haltReason1 of
                                    Just _ -> (haltReason1, haltedAt1)
                                    Nothing ->
                                        case argMaxOrderErrors args of
                                            Just lim | errors1 >= lim -> (Just "MAX_ORDER_ERRORS", Just now)
                                            _ -> (Nothing, Nothing)

                        metricsRecordOrder metrics o
                        journalWriteMaybe
                            mJournal
                            ( object
                                [ "type" .= ("bot.order" :: String)
                                , "atMs" .= now
                                , "symbol" .= botSymbol st
                                , "market" .= marketCode (argBinanceMarket args)
                                , "event" .= orderEv
                                ]
                            )
                        opsAppendMaybe
                            mOps
                            (Just (botTenantKey st))
                            "bot.order"
                            Nothing
                            (Just (argsPublicJson args))
                            ( Just
                                ( object
                                    [ "symbol" .= botSymbol st
                                    , "market" .= marketCode (argBinanceMarket args)
                                    , "interval" .= argInterval args
                                    , "event" .= orderEv
                                    , "signal" .= latestFinal
                                    , "position" .= posNew
                                    , "originIp" .= botTradeOriginIp st
                                    ]
                                )
                            )
                            (Just eqAfterFee)
                            (orderComboUuid (prevPos /= 0) (botOpenTradeComboUuidMaybe openTrade1) (botComboUuid st))
                            (Just (T.pack (botSymbol st)))
                            (orderIdFromOrderResult o)
                        when (shouldPersistPositionOriginOnSwitch tradeEnabled (argBinanceLive args) switchedApplied1 (aorSent o)) $
                            persistPositionOriginMaybe
                                mOps
                                (botTenantKey st)
                                args
                                (botSymbol st)
                                posNew
                                (botComboUuid st)
                                (orderIdFromOrderResult o)
                                now
                        webhookNotifyMaybe mWebhook (webhookEventBotOrder args (botSymbol st) opSide priceNew o)

                        pure (opsNew, ordersNew, tradesNew, openTradeNew, Just o, posNew, eqAfterFee, switchedApplied1, errors1, haltReason3, haltedAt3)

    case (botHaltReason st, haltReason2) of
        (Nothing, Just r) -> do
            metricsRecordBotHalt metrics
            journalWriteMaybe
                mJournal
                ( object
                    [ "type" .= ("bot.halt" :: String)
                    , "atMs" .= now
                    , "symbol" .= botSymbol st
                    , "market" .= marketCode (argBinanceMarket args)
                    , "reason" .= r
                    , "equity" .= eqFinal
                    , "drawdown" .= drawdown
                    , "dailyLoss" .= dailyLoss
                    , "weeklyLoss" .= weeklyLoss
                    , "consecutiveOrderErrors" .= orderErrors1
                    ]
                )
            opsAppendMaybe
                mOps
                (Just (botTenantKey st))
                "bot.halt"
                Nothing
                (Just (argsPublicJson args))
                ( Just
                    ( object
                        [ "symbol" .= botSymbol st
                        , "market" .= marketCode (argBinanceMarket args)
                        , "interval" .= argInterval args
                        , "reason" .= r
                        , "drawdown" .= drawdown
                        , "dailyLoss" .= dailyLoss
                        , "weeklyLoss" .= weeklyLoss
                        , "consecutiveOrderErrors" .= orderErrors1
                        ]
                    )
                )
                (Just eqFinal)
                (activeComboUuid (botOpenTradeComboUuidMaybe openTrade') (botComboUuid st))
                (Just (T.pack (botSymbol st)))
                Nothing
            webhookNotifyMaybe mWebhook (webhookEventBotHalt args (botSymbol st) r drawdown dailyLoss orderErrors1)
        _ -> pure ()

    let entryApplied = switchedApplied && posFinal /= 0 && posFinal /= prevPos
        dayTradesFinal =
            if entryApplied
                then dayTrades1 + 1
                else dayTrades1
        oldTradeCount = length (botTrades st)
        newTradeCount = length trades'
        mNewTrade =
            if newTradeCount > oldTradeCount
                then lastMaybe trades'
                else Nothing
        (perfStatsNext, adjustmentsNext, lossStreakNext, lossStreakTriggered) =
            case mNewTrade of
                Nothing -> (botPerfStats st, botAdjustments st, botLossStreak st, False)
                Just tr ->
                    let perfStatsNewAll = computeBotPerfStats (argPerfLookback args) trades'
                        (perfStatsNewForAdaptive, _mode) =
                            selectPerfStatsForPerfGate args latest perfStatsNewAll trades'
                        adjustmentsNew = computeAdaptiveAdjustments args perfStatsNewForAdaptive
                        r = trReturn tr
                        lossStreakNew =
                            if isNaN r || isInfinite r || r <= 0
                                then botLossStreak st + 1
                                else 0
                        triggered =
                            case argLossStreakMax args of
                                v | v > 0 -> lossStreakNew >= v
                                _ -> False
                     in (perfStatsNewAll, adjustmentsNew, lossStreakNew, triggered)
        cooldownDec =
            if prevPos == 0
                then max 0 (cooldownLeft0 - 1)
                else 0
        cooldownBarsEffective =
            if maxHoldExit
                then max cooldownBars 1
                else cooldownBars
        cooldownLeftBase =
            if posFinal == 0
                then if prevPos /= 0 then cooldownBarsEffective else cooldownDec
                else 0
        cooldownLeftNext =
            if lossStreakTriggered
                then max cooldownLeftBase (argLossStreakCooldownBars args)
                else cooldownLeftBase
        eqV1 = V.snoc (botEquityCurve st) eqFinal
        posV1 = V.snoc (botPositions st) posFinal

        maxPoints = max (lookback + 3) (bsMaxPoints settings)
        dropCount = max 0 (V.length pricesV - maxPoints)

        (pricesV2, opensV2, highsV2, lowsV2, volumesV2, openTimesV2, kalPred2, lstmPred2, eqV2, posV2, ops2, orders2, trades2, openTrade2, startIndex2) =
            if dropCount <= 0
                then (pricesV, opensV, highsV, lowsV, volumesV, openTimesV, kalPred1, lstmPred1, eqV1, posV1, ops', orders', trades', openTrade', botStartIndex st)
                else
                    let shiftTrade tr =
                            tr{trEntryIndex = trEntryIndex tr - dropCount, trExitIndex = trExitIndex tr - dropCount}
                        tradesShifted =
                            [ shiftTrade tr
                            | tr <- trades'
                            , trEntryIndex tr >= dropCount
                            , trExitIndex tr >= dropCount
                            ]
                        openTradeShifted =
                            case openTrade' of
                                Nothing -> Nothing
                                Just ot -> Just (shiftOpenTradeIndex dropCount ot)
                        opsShifted =
                            [ op{boIndex = boIndex op - dropCount}
                            | op <- ops'
                            , boIndex op >= dropCount
                            ]
                        ordersShifted =
                            [ e{boeIndex = boeIndex e - dropCount}
                            | e <- orders'
                            , boeIndex e >= dropCount
                            ]
                     in ( V.drop dropCount pricesV
                        , V.drop dropCount opensV
                        , V.drop dropCount highsV
                        , V.drop dropCount lowsV
                        , V.drop dropCount volumesV
                        , V.drop dropCount openTimesV
                        , V.drop dropCount kalPred1
                        , V.drop dropCount lstmPred1
                        , V.drop dropCount eqV1
                        , V.drop dropCount posV1
                        , opsShifted
                        , ordersShifted
                        , tradesShifted
                        , openTradeShifted
                        , botStartIndex st + dropCount
                        )

        mLstmCtx2 =
            case mLstmCtx1 of
                Nothing -> Nothing
                Just (normState, obsAll, lstmModel) ->
                    if dropCount <= 0
                        then Just (normState, obsAll, lstmModel)
                        else Just (normState, drop dropCount obsAll, lstmModel)

    let st1 =
            st
                { botPrices = pricesV2
                , botOpens = opensV2
                , botHighs = highsV2
                , botLows = lowsV2
                , botVolumes = volumesV2
                , botOpenTimes = openTimesV2
                , botKalmanPredNext = kalPred2
                , botLstmPredNext = lstmPred2
                , botEquityCurve = eqV2
                , botPositions = posV2
                , botOps = ops2
                , botOrders = orders2
                , botTrades = trades2
                , botPerfStats = perfStatsNext
                , botAdjustments = adjustmentsNext
                , botLossStreak = lossStreakNext
                , botOpenTrade = openTrade2
                , botCooldownLeft = cooldownLeftNext
                , botLatestSignal = latest
                , botLastOrder = mOrder <|> botLastOrder st
                , botHaltReason = haltReason2
                , botHaltedAtMs = haltedAt2
                , botPeakEquity = max (botPeakEquity st) eqFinal
                , botDayKey = dayKey1
                , botDayStartEquity = dayStartEq1
                , botWeekKey = weekKey1
                , botWeekStartEquity = weekStartEq1
                , botDayTrades = dayTradesFinal
                , botConsecutiveOrderErrors = orderErrors1
                , botLstmCtx = mLstmCtx2
                , botKalmanCtx = mKalmanCtx1
                , botLastOpenTime = openTimeNew
                , botStartIndex = startIndex2
                , botUpdatedAtMs = now
                , botError = Nothing
                }

    stOut <- if switchedApplied then botOptimizeAfterOperation st1 else pure st1
    case mNewTrade of
        Nothing -> pure ()
        Just tr -> do
            let argsAdjusted = applyBotAdjustments adjustmentsNext args
                pfLabel :: String
                pfLabel =
                    case bpsProfitFactor perfStatsNext of
                        Nothing -> "inf"
                        Just pf -> printf "%.3f" pf
                msg =
                    printf
                        "bot.adjust symbol=%s return=%.4f winRate=%.2f pf=%s edgeBuffer=%.6f minSNR=%.3f kalmanZMin=%.3f trendLookback=%d lossStreak=%d"
                        (botSymbol stOut)
                        (trReturn tr)
                        (bpsWinRate perfStatsNext)
                        pfLabel
                        (argEdgeBuffer argsAdjusted)
                        (argMinSignalToNoise argsAdjusted)
                        (argKalmanZMin argsAdjusted)
                        (argTrendLookback argsAdjusted)
                        lossStreakNext
            putStrLn msg
            journalWriteMaybe
                mJournal
                ( object
                    [ "type" .= ("bot.adjust" :: String)
                    , "atMs" .= now
                    , "symbol" .= botSymbol stOut
                    , "market" .= marketCode (argBinanceMarket args)
                    , "interval" .= argInterval args
                    , "trade" .= tradeToJson tr
                    , "performance"
                        .= object
                            [ "lookback" .= bpsLookback perfStatsNext
                            , "trades" .= bpsTrades perfStatsNext
                            , "wins" .= bpsWins perfStatsNext
                            , "losses" .= bpsLosses perfStatsNext
                            , "winRate" .= bpsWinRate perfStatsNext
                            , "profitFactor" .= bpsProfitFactor perfStatsNext
                            , "expectancy" .= bpsExpectancy perfStatsNext
                            , "lossStreak" .= lossStreakNext
                            , "gateReason" .= perfGateReason args perfStatsNext
                            ]
                    , "adjustments"
                        .= object
                            [ "edgeBuffer" .= argEdgeBuffer argsAdjusted
                            , "minSignalToNoise" .= argMinSignalToNoise argsAdjusted
                            , "kalmanZMin" .= argKalmanZMin argsAdjusted
                            , "trendLookback" .= argTrendLookback argsAdjusted
                            , "edgeBufferAdd" .= baEdgeBufferAdd adjustmentsNext
                            , "minSignalToNoiseAdd" .= baMinSignalToNoiseAdd adjustmentsNext
                            , "kalmanZMinAdd" .= baKalmanZMinAdd adjustmentsNext
                            , "trendLookbackAdd" .= baTrendLookbackAdd adjustmentsNext
                            ]
                    ]
                )
            opsAppendMaybe
                mOps
                (Just (botTenantKey stOut))
                "bot.adjust"
                Nothing
                (Just (argsPublicJson args))
                ( Just
                    ( object
                        [ "symbol" .= botSymbol stOut
                        , "market" .= marketCode (argBinanceMarket args)
                        , "interval" .= argInterval args
                        , "trade" .= tradeToJson tr
                        , "performance"
                            .= object
                                [ "winRate" .= bpsWinRate perfStatsNext
                                , "profitFactor" .= bpsProfitFactor perfStatsNext
                                , "expectancy" .= bpsExpectancy perfStatsNext
                                , "lossStreak" .= lossStreakNext
                                , "gateReason" .= perfGateReason args perfStatsNext
                                ]
                        , "adjustments"
                            .= object
                                [ "edgeBuffer" .= argEdgeBuffer argsAdjusted
                                , "minSignalToNoise" .= argMinSignalToNoise argsAdjusted
                                , "kalmanZMin" .= argKalmanZMin argsAdjusted
                                , "trendLookback" .= argTrendLookback argsAdjusted
                                ]
                        ]
                    )
                )
                (Just eqFinal)
                (activeBotComboUuid stOut)
                (Just (T.pack (botSymbol stOut)))
                Nothing
    opsAppendMaybe
        mOps
        (Just (botTenantKey stOut))
        "bot.bar"
        Nothing
        (Just (argsPublicJson (botArgs stOut)))
        ( Just
            ( object
                [ "symbol" .= botSymbol stOut
                , "market" .= marketCode (argBinanceMarket (botArgs stOut))
                , "interval" .= argInterval (botArgs stOut)
                , "openTime" .= openTimeNew
                , "price" .= priceNew
                , "position" .= posFinal
                ]
            )
        )
        (Just eqFinal)
        (activeBotComboUuid stOut)
        (Just (T.pack (botSymbol stOut)))
        Nothing
    triggerTopCombosBacktestOnCandle topCombosCtx
    pure stOut

placeIfEnabled :: Args -> BotSettings -> LatestSignal -> BinanceEnv -> String -> IO ApiOrderResult
placeIfEnabled args settings sig env sym =
    if not (bsTradeEnabled settings)
        then pure (ApiOrderResult False Nothing Nothing (Just sym) Nothing Nothing Nothing Nothing Nothing Nothing Nothing Nothing Nothing "Paper mode: no order sent.")
        else placeOrderForSignalBot args sym sig env (bsProtectionOrders settings)

placeBotCloseIfEnabled :: Args -> BotSettings -> LatestSignal -> BinanceEnv -> String -> IO ApiOrderResult
placeBotCloseIfEnabled args settings sig env sym =
    if not (bsTradeEnabled settings)
        then pure (ApiOrderResult False Nothing Nothing (Just sym) Nothing Nothing Nothing Nothing Nothing Nothing Nothing Nothing Nothing "Paper mode: no order sent.")
        else placeBotCloseOrder args sym sig env

placeBotCloseOrder :: Args -> String -> LatestSignal -> BinanceEnv -> IO ApiOrderResult
placeBotCloseOrder args sym sig env =
    let args' = args{argPositioning = LongFlat}
        sig' = sig{lsChosenDir = Just (-1)}
     in placeOrderForSignalEx args' sym sig' env Nothing False

runRestApi :: Args -> Maybe Webhook -> IO ()
runRestApi cliArgs mWebhook = do
    -- REST requests should default to mainnet unless callers explicitly set binanceTestnet=true.
    -- This keeps production-safe defaults even if the process was started with --binance-testnet.
    let baseArgs = cliArgs{argBinanceTestnet = False}
    mCommit <- getBuildCommit
    let buildInfo = BuildInfo traderVersion mCommit
    apiToken <- fmap BS.pack <$> lookupEnv "TRADER_API_TOKEN"
    multiUserEnv <- lookupEnv "TRADER_MULTI_USER"
    corsConfig <- resolveCorsConfig apiToken
    timeoutEnv <- lookupEnv "TRADER_API_TIMEOUT_SEC"
    maxAsyncRunningEnv <- lookupEnv "TRADER_API_MAX_ASYNC_RUNNING"
    maxBacktestRunningEnv <- lookupEnv "TRADER_API_MAX_BACKTEST_RUNNING"
    backtestTimeoutEnv <- lookupEnv "TRADER_API_BACKTEST_TIMEOUT_SEC"
    cacheTtlEnv <- lookupEnv "TRADER_API_CACHE_TTL_MS"
    cacheMaxEnv <- lookupEnv "TRADER_API_CACHE_MAX_ENTRIES"
    maxBarsLstmEnv <- lookupEnv "TRADER_API_MAX_BARS_LSTM"
    maxEpochsEnv <- lookupEnv "TRADER_API_MAX_EPOCHS"
    maxHiddenSizeEnv <- lookupEnv "TRADER_API_MAX_HIDDEN_SIZE"
    maxBodyBytesEnv <- lookupEnv "TRADER_API_MAX_BODY_BYTES"
    maxOptimizerOutputBytesEnv <- lookupEnv "TRADER_API_MAX_OPTIMIZER_OUTPUT_BYTES"
    let multiUserEnabled = readEnvBool multiUserEnv False
        timeoutSec =
            case timeoutEnv >>= readMaybe of
                Just n | n >= 0 -> n
                _ -> 1800
        maxAsyncRunning =
            case maxAsyncRunningEnv >>= readMaybe of
                Just n | n >= 1 -> n
                _ -> 1
        maxBacktestRunning =
            case maxBacktestRunningEnv >>= readMaybe of
                Just n | n >= 1 -> n
                _ -> 1
        backtestTimeoutSec =
            case backtestTimeoutEnv >>= readMaybe of
                Just n | n >= 30 -> n
                _ -> 900
        limits =
            ApiComputeLimits
                { aclMaxBarsLstm =
                    case maxBarsLstmEnv >>= readMaybe of
                        Just n | n >= 2 -> n
                        _ -> 1000
                , aclMaxEpochs =
                    case maxEpochsEnv >>= readMaybe of
                        Just n | n >= 1 -> n
                        _ -> 100
                , aclMaxHiddenSize =
                    case maxHiddenSizeEnv >>= readMaybe of
                        Just n | n >= 1 -> n
                        _ -> 32
                }
        cacheTtlMs =
            case cacheTtlEnv >>= readMaybe of
                Just n | n >= 0 -> n
                _ -> 30000 :: Int64
        cacheMaxEntries =
            case cacheMaxEnv >>= readMaybe of
                Just n | n >= 0 -> n
                _ -> 64 :: Int
        maxBodyBytes =
            case (maxBodyBytesEnv >>= readMaybe :: Maybe Int64) of
                Just n | n > 0 -> n
                _ -> defaultApiMaxBodyBytes
        maxOptimizerOutputBytes =
            case (maxOptimizerOutputBytesEnv >>= readMaybe :: Maybe Int) of
                Just n | n > 0 -> n
                _ -> defaultApiMaxOptimizerOutputBytes
        reqLimits =
            ApiRequestLimits
                { arlMaxBodyBytes = maxBodyBytes
                , arlMaxOptimizerOutputBytes = maxOptimizerOutputBytes
                , arlMaxBotStatusTail = defaultApiMaxBotStatusTail
                }
    -- With 1 vCPU (common in small ECS/Fargate tasks), long-running pure compute can starve the
    -- Warp accept loop and make even quick "poll" endpoints appear to hang.
    -- Ensure at least 2 capabilities so the server stays responsive while background work runs.
    caps0 <- getNumCapabilities
    when (caps0 < 2) $ do
        setNumCapabilities 2
        putStrLn "Increased GHC capabilities to 2 (to keep the API responsive during heavy compute)."

    bindHostEnv <- lookupEnv "TRADER_API_BIND_HOST"
    let bindHostStr =
            case trim <$> bindHostEnv of
                Just host | not (null host) -> host
                _ -> "0.0.0.0"
        bindHost = fromString bindHostStr :: Warp.HostPreference
        displayHost = "127.0.0.1" :: String
        port = max 1 (argPort baseArgs)
        settings =
            Warp.setHost bindHost $
                Warp.setTimeout timeoutSec $
                    Warp.setPort port Warp.defaultSettings
    putStrLn (printf "Build: %s%s" (biVersion buildInfo) (maybe "" (\c -> " (" ++ take 12 c ++ ")") (biCommit buildInfo)))
    putStrLn (printf "Starting REST API on http://%s:%d (bind: %s:%d)" displayHost port bindHostStr port)
    putStrLn
        ( printf
            "API limits: maxAsyncRunning=%d, maxBacktestRunning=%d, maxBarsLstm=%d, maxEpochs=%d, maxHiddenSize=%d"
            maxAsyncRunning
            maxBacktestRunning
            (aclMaxBarsLstm limits)
            (aclMaxEpochs limits)
            (aclMaxHiddenSize limits)
        )
    putStrLn
        ( printf
            "API backtest gate: maxRunning=%d timeoutSec=%d"
            maxBacktestRunning
            backtestTimeoutSec
        )
    putStrLn
        ( printf
            "API request limits: maxBodyBytes=%d, maxOptimizerOutputBytes=%d, botStatusTailMax=%d"
            (arlMaxBodyBytes reqLimits)
            (arlMaxOptimizerOutputBytes reqLimits)
            (arlMaxBotStatusTail reqLimits)
        )
    if ccAllowAnyOrigin corsConfig
        then putStrLn "CORS: allowed origin *"
        else case ccAllowedOrigins corsConfig of
            [] ->
                if ccAllowAuthOrigin corsConfig
                    then putStrLn "CORS: implicit read/auth origins allowed (auth-like headers, /health, /version, /optimizer/combos, and tenantKey-scoped GETs)"
                    else putStrLn "CORS: disabled (set TRADER_CORS_ORIGIN to allow a specific origin)"
            origins ->
                putStrLn ("CORS: allowed origins " ++ intercalate ", " (map BS.unpack origins))
    apiCache <- newApiCache cacheMaxEntries cacheTtlMs
    putStrLn
        ( printf
            "API cache: ttlMs=%d maxEntries=%d"
            cacheTtlMs
            cacheMaxEntries
        )
    let multiUserLabel =
            if multiUserEnabled
                then "enabled (tenant-key required for /ops and /ops/performance)"
                else "disabled"
    putStrLn ("Multi-user mode: " ++ multiUserLabel)
    projectRoot <- getCurrentDirectory
    mStateDir <- stateDirFromEnv
    let tmpRoot = projectRoot </> ".tmp"
    createDirectoryIfMissing True tmpRoot
    let optimizerTmp = maybe (tmpRoot </> "optimizer") (</> "optimizer") mStateDir
    createDirectoryIfMissing True optimizerTmp
    topJsonPath <- resolveOptimizerCombosPath optimizerTmp
    topCombosHistoryDir <- resolveOptimizerCombosHistoryDir topJsonPath
    topCombosStore <- newTopCombosStore topJsonPath topCombosHistoryDir
    metrics <- newMetrics
    mJournal <- newJournalFromEnv
    mOpsRaw <- newOpsStoreFromEnv
    mOps <-
        case mOpsRaw of
            Just store -> pure (Just store)
            Nothing ->
                ioError
                    ( userError
                        "Ops persistence is required in --serve mode. Set TRADER_DB_URL (or DATABASE_URL) and ensure the database is reachable."
                    )
    mStateSyncTarget <- newStateSyncTargetFromEnv
    _ <- forkSupervisedWorker "top-combos-sync" (topCombosSyncLoop mOps mStateSyncTarget topCombosStore)
    listenKeyManager <- newListenKeyManager
    mBotStateDir <- resolveBotStateDir
    backtestGate <- newBacktestGate maxBacktestRunning backtestTimeoutSec
    topCombosEnabledEnv <- lookupEnv "TRADER_TOP_COMBOS_BACKTEST_ENABLED"
    let topCombosEnabled = readEnvBool topCombosEnabledEnv True
    topCombosLock <- newMVar ()
    topCombosCandleQueue <- newTBQueueIO 1
    let topCombosCtx =
            TopCombosBacktestCtx
                { tcbcBaseArgs = baseArgs
                , tcbcLimits = limits
                , tcbcGate = backtestGate
                , tcbcOps = mOps
                , tcbcJournal = mJournal
                , tcbcStore = topCombosStore
                , tcbcStateSync = mStateSyncTarget
                , tcbcLock = topCombosLock
                , tcbcCandleQueue = topCombosCandleQueue
                , tcbcEnabled = topCombosEnabled
                }
    let defaultAsyncDir = maybe (tmpRoot </> "async") (</> "async") mStateDir
    asyncDirEnv <- lookupEnv "TRADER_API_ASYNC_DIR"
    let asyncDirTrimmed = trim <$> asyncDirEnv
        mAsyncDir =
            case asyncDirTrimmed of
                Nothing -> Just defaultAsyncDir
                Just dir | null dir -> Nothing
                Just dir -> Just dir
        asyncDirFromEnv =
            case asyncDirTrimmed of
                Nothing -> False
                Just dir -> not (null dir)
        asyncDirFromState = isNothing asyncDirTrimmed && isJust mStateDir
    case mAsyncDir of
        Nothing -> pure ()
        Just dir -> do
            let suffix :: String
                suffix
                    | asyncDirFromEnv = ""
                    | asyncDirFromState = " (from TRADER_STATE_DIR; set TRADER_API_ASYNC_DIR to override)"
                    | otherwise = " (default; set TRADER_API_ASYNC_DIR to override)"
            putStrLn (printf "Async job persistence enabled: %s%s" dir suffix)
    now <- getTimestampMs
    journalWriteMaybe mJournal (object ["type" .= ("server.start" :: String), "atMs" .= now, "port" .= port])
    opsAppendMaybe mOps Nothing "server.start" Nothing Nothing (Just (object ["port" .= port])) Nothing Nothing Nothing Nothing
    autoBotKey <- resolveEnv "BINANCE_API_KEY" (argBinanceApiKey baseArgs)
    autoBotSecret <- resolveEnv "BINANCE_API_SECRET" (argBinanceApiSecret baseArgs)
    let mAutoBotTenant = tenantKeyFromBinanceKeys autoBotKey autoBotSecret
    bot <- newBotController
    case mAutoBotTenant of
        Nothing -> putStrLn "Live bot auto-start skipped: missing BINANCE_API_KEY/BINANCE_API_SECRET (tenant key unavailable)."
        Just tenantKey -> do
            _ <- forkSupervisedWorker "bot-auto-start" (botAutoStartLoop mOps metrics mJournal mWebhook mBotStateDir topCombosStore limits topCombosCtx baseArgs bot tenantKey)
            pure ()
    autoOptimizerEnabledEnv <- lookupEnv "TRADER_OPTIMIZER_ENABLED"
    let autoOptimizerEnabled = readEnvBool autoOptimizerEnabledEnv True
    if autoOptimizerEnabled
        then do
            _ <- forkSupervisedWorker "auto-optimizer" (autoOptimizerLoop baseArgs mStateSyncTarget mOps mJournal optimizerTmp topCombosStore)
            pure ()
        else putStrLn "Auto optimizer background worker disabled (TRADER_OPTIMIZER_ENABLED=false)."
    when topCombosEnabled $ do
        _ <- forkSupervisedWorker "top-combos-candle" (topCombosCandleWorker topCombosCtx)
        _ <- forkSupervisedWorker "top-combos-scheduled-backtest" (autoTopCombosBacktestLoop topCombosCtx)
        pure ()
    asyncSignal <- newJobStore "signal" maxAsyncRunning mAsyncDir
    asyncBacktest <- newJobStore "backtest" maxAsyncRunning mAsyncDir
    asyncTrade <- newJobStore "trade" maxAsyncRunning mAsyncDir
    requestProgressStore <- newRequestProgressStore
    hFlush stdout
    res <-
        ( try
            (Warp.runSettings settings (apiApp buildInfo baseArgs apiToken corsConfig multiUserEnabled bot metrics mJournal mWebhook mOps mStateSyncTarget listenKeyManager requestProgressStore mBotStateDir limits reqLimits apiCache backtestGate topCombosCtx (AsyncStores asyncSignal asyncBacktest asyncTrade) projectRoot topCombosStore optimizerTmp)) ::
            IO (Either IOException ())
        )
    case res of
        Right () -> pure ()
        Left e ->
            ioError
                ( userError
                    ( printf
                        "Failed to start REST API on %s:%d: %s\nTry a different --port (or check permissions / sandbox restrictions)."
                        bindHostStr
                        port
                        (show e)
                    )
                )

lookupHeaderNormalized :: String -> RequestHeaders -> Maybe BS.ByteString
lookupHeaderNormalized wanted hs =
    let wantedNorm = normalizeKey wanted
     in snd <$> find (\(h, _) -> normalizeKey (BS.unpack (CI.original h)) == wantedNorm) hs

newtype RequestProgressStore = RequestProgressStore
    { rpsEntries :: MVar (HM.HashMap String ApiRequestProgress)
    }

requestProgressHeaderName :: String
requestProgressHeaderName = "X-Trader-Request-Id"

requestProgressTtlMs :: Int64
requestProgressTtlMs = 15 * 60 * 1000

newRequestProgressStore :: IO RequestProgressStore
newRequestProgressStore = RequestProgressStore <$> newMVar HM.empty

normalizeRequestProgressId :: String -> Maybe String
normalizeRequestProgressId raw =
    let trimmed = trim raw
     in if null trimmed || length trimmed > 200
            then Nothing
            else Just trimmed

requestProgressIdFromRequest :: Wai.Request -> Maybe String
requestProgressIdFromRequest req =
    normalizeRequestProgressId . BS.unpack
        =<< lookupHeaderNormalized requestProgressHeaderName (Wai.requestHeaders req)

pruneRequestProgressEntries :: Int64 -> HM.HashMap String ApiRequestProgress -> HM.HashMap String ApiRequestProgress
pruneRequestProgressEntries now =
    HM.filter keepEntry
  where
    keepEntry entry =
        let cutoff = fromMaybe (arpUpdatedAtMs entry) (arpCompletedAtMs entry)
         in now - cutoff <= requestProgressTtlMs

requestProgressTracker :: RequestProgressStore -> Wai.Request -> Maybe (RequestProgressStore, String)
requestProgressTracker store req = (store,) <$> requestProgressIdFromRequest req

startRequestProgress :: RequestProgressStore -> String -> String -> String -> Maybe String -> IO ()
startRequestProgress store requestId kind phase detail = do
    now <- getTimestampMs
    let entry =
            ApiRequestProgress
                { arpRequestId = requestId
                , arpKind = kind
                , arpCurrentPhase = phase
                , arpLastCompletedPhase = Nothing
                , arpDetail = detail
                , arpStartedAtMs = now
                , arpUpdatedAtMs = now
                , arpCompletedAtMs = Nothing
                , arpCompletedOk = Nothing
                , arpError = Nothing
                }
    modifyMVar_ (rpsEntries store) $ \entries ->
        pure (HM.insert requestId entry (pruneRequestProgressEntries now entries))

advanceRequestProgress :: RequestProgressStore -> String -> String -> Maybe String -> IO ()
advanceRequestProgress store requestId phase detail = do
    now <- getTimestampMs
    modifyMVar_ (rpsEntries store) $ \entries ->
        let entries' = pruneRequestProgressEntries now entries
            updated =
                HM.adjust
                    ( \entry ->
                        let samePhase = arpCurrentPhase entry == phase
                            lastCompleted =
                                if samePhase
                                    then arpLastCompletedPhase entry
                                    else Just (arpCurrentPhase entry)
                         in entry
                                { arpCurrentPhase = phase
                                , arpLastCompletedPhase = lastCompleted
                                , arpDetail = detail
                                , arpUpdatedAtMs = now
                                , arpError = Nothing
                                }
                    )
                    requestId
                    entries'
         in pure updated

completeRequestProgress :: RequestProgressStore -> String -> Maybe String -> IO ()
completeRequestProgress store requestId detail = do
    now <- getTimestampMs
    modifyMVar_ (rpsEntries store) $ \entries ->
        let entries' = pruneRequestProgressEntries now entries
            updated =
                HM.adjust
                    ( \entry ->
                        entry
                            { arpDetail = detail <|> arpDetail entry
                            , arpUpdatedAtMs = now
                            , arpCompletedAtMs = Just now
                            , arpCompletedOk = Just True
                            , arpError = Nothing
                            }
                    )
                    requestId
                    entries'
         in pure updated

failRequestProgress :: RequestProgressStore -> String -> String -> IO ()
failRequestProgress store requestId errMsg = do
    now <- getTimestampMs
    modifyMVar_ (rpsEntries store) $ \entries ->
        let entries' = pruneRequestProgressEntries now entries
            updated =
                HM.adjust
                    ( \entry ->
                        entry
                            { arpUpdatedAtMs = now
                            , arpCompletedAtMs = Just now
                            , arpCompletedOk = Just False
                            , arpError = Just errMsg
                            }
                    )
                    requestId
                    entries'
         in pure updated

lookupRequestProgress :: RequestProgressStore -> String -> IO (Maybe ApiRequestProgress)
lookupRequestProgress store requestId = do
    now <- getTimestampMs
    modifyMVar (rpsEntries store) $ \entries ->
        let entries' = pruneRequestProgressEntries now entries
         in pure (entries', HM.lookup requestId entries')

startRequestProgressMaybe :: Maybe (RequestProgressStore, String) -> String -> String -> Maybe String -> IO ()
startRequestProgressMaybe Nothing _ _ _ = pure ()
startRequestProgressMaybe (Just (store, requestId)) kind phase detail =
    startRequestProgress store requestId kind phase detail

advanceRequestProgressMaybe :: Maybe (RequestProgressStore, String) -> String -> Maybe String -> IO ()
advanceRequestProgressMaybe Nothing _ _ = pure ()
advanceRequestProgressMaybe (Just (store, requestId)) phase detail =
    advanceRequestProgress store requestId phase detail

completeRequestProgressMaybe :: Maybe (RequestProgressStore, String) -> Maybe String -> IO ()
completeRequestProgressMaybe Nothing _ = pure ()
completeRequestProgressMaybe (Just (store, requestId)) detail =
    completeRequestProgress store requestId detail

failRequestProgressMaybe :: Maybe (RequestProgressStore, String) -> String -> IO ()
failRequestProgressMaybe Nothing _ = pure ()
failRequestProgressMaybe (Just (store, requestId)) errMsg =
    failRequestProgress store requestId errMsg

noCacheHeaders :: ResponseHeaders
noCacheHeaders =
    [ ("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
    , ("Pragma", "no-cache")
    , ("Expires", "0")
    , ("Vary", "Authorization, X-API-Key")
    ]

data CacheEntry a = CacheEntry
    { ceCreatedAtMs :: !Int64
    , ceLastAccessAtMs :: !Int64
    , ceValue :: !a
    }

data ApiCache = ApiCache
    { acTtlMs :: !Int64
    , acMaxEntries :: !Int
    , acSignals :: !(MVar (HM.HashMap Text (CacheEntry LatestSignal)))
    , acBacktests :: !(MVar (HM.HashMap Text (CacheEntry Aeson.Value)))
    , acSignalHits :: !(IORef Int64)
    , acSignalMisses :: !(IORef Int64)
    , acBacktestHits :: !(IORef Int64)
    , acBacktestMisses :: !(IORef Int64)
    }

newApiCache :: Int -> Int64 -> IO ApiCache
newApiCache maxEntries ttlMs = do
    sig <- newMVar HM.empty
    bt <- newMVar HM.empty
    sigHits <- newIORef 0
    sigMiss <- newIORef 0
    btHits <- newIORef 0
    btMiss <- newIORef 0
    pure
        ApiCache
            { acTtlMs = ttlMs
            , acMaxEntries = maxEntries
            , acSignals = sig
            , acBacktests = bt
            , acSignalHits = sigHits
            , acSignalMisses = sigMiss
            , acBacktestHits = btHits
            , acBacktestMisses = btMiss
            }

cacheEnabled :: ApiCache -> Bool
cacheEnabled c = acTtlMs c > 0 && acMaxEntries c > 0

requestWantsNoCache :: Wai.Request -> Bool
requestWantsNoCache req =
    let qs = Wai.queryString req
        nocacheQs =
            case lookup "nocache" qs of
                Nothing -> False
                Just Nothing -> True
                Just (Just raw) ->
                    let s = map toLower (BS.unpack raw)
                     in s == "1" || s == "true" || s == "yes" || s == "on"

        hasNoCacheDirective raw =
            let v = BS.map toLower raw
             in "no-cache" `BS.isInfixOf` v || "no-store" `BS.isInfixOf` v

        hdrs = Wai.requestHeaders req
        cc = lookup hCacheControl hdrs
        pragma = lookup hPragma hdrs
        nocacheHdr =
            maybe False hasNoCacheDirective cc
                || maybe False hasNoCacheDirective pragma
     in nocacheQs || nocacheHdr

barsResolvedForCache :: Args -> Int
barsResolvedForCache args =
    if prefersCsvBars args
        then resolveBarsForCsv args
        else case (argBinanceSymbol args, argData args) of
            (Just _, _) -> resolveBarsForPlatform args
            (_, Just _) -> resolveBarsForCsv args
            _ -> fromMaybe 0 (argBars args)

