                                            ++ hiddenArgs
                                            ++ ["--binary", exePath]
                                            ++ boolArg "--disable-lstm-persistence" disableLstm
                                            ++ boolArg "--no-sweep-threshold" noSweep
                                        )

optimizerCombosFileName :: FilePath
optimizerCombosFileName = "top-combos.json"

s3TopCombosKey :: S3State -> String
s3TopCombosKey st =
    s3KeyFor st ["optimizer", optimizerCombosFileName]

s3TopCombosHistoryKey :: S3State -> Int64 -> String
s3TopCombosHistoryKey st ts =
    s3KeyFor st ["optimizer", "history", printf "top-combos-%d.json" ts]

resolveOptimizerCombosPath :: FilePath -> IO FilePath
resolveOptimizerCombosPath optimizerTmp = do
    mDir <- lookupEnv "TRADER_OPTIMIZER_COMBOS_DIR"
    case trim <$> mDir of
        Just dir | not (null dir) -> pure (dir </> optimizerCombosFileName)
        _ -> do
            mStateDir <- stateSubdirFromEnv "optimizer"
            pure (fromMaybe optimizerTmp mStateDir </> optimizerCombosFileName)

resolveOptimizerCombosHistoryDir :: FilePath -> IO (Maybe FilePath)
resolveOptimizerCombosHistoryDir topJsonPath = do
    mDir <- lookupEnv "TRADER_OPTIMIZER_COMBOS_HISTORY_DIR"
    case trim <$> mDir of
        Nothing -> pure (Just (takeDirectory topJsonPath </> "top-combos-history"))
        Just dir ->
            let lowered = map toLower dir
             in if null dir || lowered `elem` ["0", "false", "off", "no"]
                    then pure Nothing
                    else pure (Just dir)

defaultOptimizerMaxCombos :: Int
defaultOptimizerMaxCombos = 500

optimizerMaxCombosFromEnv :: IO Int
optimizerMaxCombosFromEnv = do
    maxCombosEnv <- lookupEnv "TRADER_OPTIMIZER_MAX_COMBOS"
    pure $
        case maxCombosEnv >>= readMaybe of
            Just n | n >= 1 -> n
            _ -> defaultOptimizerMaxCombos

defaultTopCombosMinPersist :: Int
defaultTopCombosMinPersist = 100

topCombosMinPersistFromEnv :: IO Int
topCombosMinPersistFromEnv = do
    minEnv <- lookupEnv "TRADER_TOP_COMBOS_MIN_PERSIST"
    pure $
        case minEnv >>= readMaybe of
            Just n | n >= 1 -> n
            _ -> defaultTopCombosMinPersist

topCombosComboCount :: Aeson.Value -> Int
topCombosComboCount val =
    case val of
        Aeson.Object o ->
            case KM.lookup (AK.fromString "combos") o of
                Just (Aeson.Array arr) -> V.length arr
                _ -> 0
        _ -> 0

truncateProcessOutput :: Int -> String -> String
truncateProcessOutput maxBytes raw =
    let maxBytes' = max 0 maxBytes
        bs = BS.pack raw
        bsLen = BS.length bs
     in if maxBytes' <= 0
            then ""
            else
                if bsLen <= maxBytes'
                    then raw
                    else
                        let kept = BS.drop (bsLen - maxBytes') bs
                            prefix = printf "... (truncated, showing last %d bytes)\n" maxBytes'
                         in prefix ++ BS.unpack kept

appendCappedBytes :: Int -> BS.ByteString -> BS.ByteString -> BS.ByteString
appendCappedBytes maxBytes chunk acc =
    if maxBytes <= 0
        then BS.empty
        else
            let combined = acc <> chunk
                len = BS.length combined
             in if len <= maxBytes then combined else BS.drop (len - maxBytes) combined

readProcessLimited ::
    CreateProcess ->
    Int ->
    IO (ExitCode, String, String)
readProcessLimited proc' maxBytes = do
    let procLimited =
            proc'
                { std_in = CreatePipe
                , std_out = CreatePipe
                , std_err = CreatePipe
                }
    (mIn, mOut, mErr, ph) <- createProcess procLimited
    maybe (pure ()) (\h -> catchIOError (hClose h) (\_ -> pure ())) mIn
    outRef <- newIORef BS.empty
    errRef <- newIORef BS.empty
    outDone <- newEmptyMVar
    errDone <- newEmptyMVar

    let reader h ref done = do
            hSetBinaryMode h True
            let loop = do
                    chunk <- BS.hGetSome h 8192
                    if BS.null chunk
                        then pure ()
                        else do
                            when (maxBytes > 0) $
                                modifyIORef' ref (appendCappedBytes maxBytes chunk)
                            loop
            catchIOError loop (\_ -> pure ())
            catchIOError (hClose h) (\_ -> pure ())
            putMVar done ()

    case mOut of
        Just h -> void (forkIO (reader h outRef outDone))
        Nothing -> putMVar outDone ()
    case mErr of
        Just h -> void (forkIO (reader h errRef errDone))
        Nothing -> putMVar errDone ()

    exitCode <- waitForProcess ph
    _ <- readMVar outDone
    _ <- readMVar errDone
    out <- readIORef outRef
    err <- readIORef errRef
    pure (exitCode, BS.unpack out, BS.unpack err)

optimizerOutputCapFromEnv :: IO Int
optimizerOutputCapFromEnv = do
    maxOptimizerOutputBytesEnv <- lookupEnv "TRADER_API_MAX_OPTIMIZER_OUTPUT_BYTES"
    pure $
        case (maxOptimizerOutputBytesEnv >>= readMaybe :: Maybe Int) of
            Just n | n > 0 -> n
            _ -> defaultApiMaxOptimizerOutputBytes

resolveOptimizerExecutable :: FilePath -> String -> IO (Either String FilePath)
resolveOptimizerExecutable projectRoot name = do
    exePath <- getExecutablePath
    let localPath = takeDirectory exePath </> name
    localExists <- doesFileExist localPath
    if localExists
        then pure (Right localPath)
        else do
            mPath <- findExecutable name
            case mPath of
                Just p -> pure (Right p)
                Nothing -> do
                    cabalDir <- findCabalDir
                    case cabalDir of
                        Nothing -> pure (Left ("Optimizer executable not found: " ++ name))
                        Just dir -> do
                            let proc' = (proc "cabal" ["list-bin", name]){cwd = Just dir}
                            r <- try (readCreateProcessWithExitCode proc' "") :: IO (Either SomeException (ExitCode, String, String))
                            case r of
                                Left e -> pure (Left ("Failed to discover " ++ name ++ " via cabal: " ++ show e))
                                Right (ExitFailure _, out, err) ->
                                    pure (Left ("Failed to discover " ++ name ++ " via cabal: " ++ trim (if null err then out else err)))
                                Right (ExitSuccess, out, _) ->
                                    let path = trim out
                                     in if null path
                                            then pure (Left ("cabal returned empty binary path for " ++ name))
                                            else do
                                                exists <- doesFileExist path
                                                if exists
                                                    then pure (Right path)
                                                    else pure (Left ("cabal returned non-existent binary path: " ++ path))
  where
    findCabalDir = do
        let candidates = [projectRoot </> "haskell", projectRoot]
        firstExisting candidates
    firstExisting [] = pure Nothing
    firstExisting (dir : rest) = do
        exists <- doesFileExist (dir </> "trader.cabal")
        if exists then pure (Just dir) else firstExisting rest

runOptimizerProcess ::
    FilePath ->
    FilePath ->
    Int ->
    [String] ->
    IO (Either (String, String, String) ApiOptimizerRunResponse)
runOptimizerProcess projectRoot outputPath maxOutputBytes cliArgs = do
    exeResult <- resolveOptimizerExecutable projectRoot "optimize-equity"
    case exeResult of
        Left err -> pure (Left (err, "", ""))
        Right exePath -> do
            let proc' = (proc exePath cliArgs){cwd = Just projectRoot}
            (exitCode, out, err) <- readProcessLimited proc' maxOutputBytes
            case exitCode of
                ExitSuccess -> do
                    recordOrErr <- readLastOptimizerRecord outputPath
                    case recordOrErr of
                        Left msg -> pure (Left (msg, out, err))
                        Right val -> pure (Right (ApiOptimizerRunResponse val out err))
                ExitFailure code -> pure (Left (printf "Optimizer executable failed (exit %d)" code, out, err))

runMergeTopCombos ::
    Maybe StateSyncTarget ->
    FilePath ->
    FilePath ->
    FilePath ->
    Int ->
    IO (Either (String, String, String) ())
runMergeTopCombos mStateSyncTarget projectRoot topJsonPath recordsPath maxItems = do
    dirResult <- try (createDirectoryIfMissing True (takeDirectory topJsonPath)) :: IO (Either SomeException ())
    case dirResult of
        Left e -> pure (Left ("Failed to create top combos directory: " ++ show e, "", ""))
        Right _ -> do
            remoteTempPath <- writeRemoteTopCombosTemp mStateSyncTarget topJsonPath
            historyDir <- resolveOptimizerCombosHistoryDir topJsonPath
            exeResult <- resolveOptimizerExecutable projectRoot "merge-top-combos"
            case exeResult of
                Left err -> pure (Left (err, "", ""))
                Right exePath -> do
                    let baseArgs = ["--top-json", topJsonPath, "--from-jsonl", recordsPath, "--max", show (max 1 maxItems)]
                        remoteArgs = maybe [] (\p -> ["--from-top-json", p]) remoteTempPath
                        historyArgs = maybe [] (\dir -> ["--history-dir", dir]) historyDir
                        args = baseArgs ++ remoteArgs ++ historyArgs
                        proc' = (proc exePath args){cwd = Just projectRoot}
                        cleanup = maybe (pure ()) removeTempTopCombo remoteTempPath
                    (exitCode, out, err) <- readCreateProcessWithExitCode proc' "" `finally` cleanup
                    case exitCode of
                        ExitSuccess -> do
                            persistTopCombosMaybe mStateSyncTarget topJsonPath
                            pure (Right ())
                        ExitFailure code -> pure (Left (printf "Merge executable failed (exit %d)" code, out, err))

writeRemoteTopCombosTemp :: Maybe StateSyncTarget -> FilePath -> IO (Maybe FilePath)
writeRemoteTopCombosTemp mStateSyncTarget topJsonPath = do
    fromSync <- writeStateSyncTopCombosTemp mStateSyncTarget topJsonPath
    case fromSync of
        Just path -> pure (Just path)
        Nothing -> writeS3TopCombosTemp topJsonPath

writeStateSyncTopCombosTemp :: Maybe StateSyncTarget -> FilePath -> IO (Maybe FilePath)
writeStateSyncTopCombosTemp mStateSyncTarget topJsonPath =
    case mStateSyncTarget of
        Nothing -> pure Nothing
        Just target -> do
            payloadOrErr <- fetchStateSyncPayload target
            case payloadOrErr of
                Left _ -> pure Nothing
                Right payload ->
                    case sspTopCombos payload of
                        Just val
                            | isTopCombosPayload val ->
                                writeTopCombosTempFile topJsonPath "top-combos-state-sync.json" (encode val)
                        _ -> pure Nothing

writeS3TopCombosTemp :: FilePath -> IO (Maybe FilePath)
writeS3TopCombosTemp topJsonPath = do
    mS3 <- resolveS3State
    case mS3 of
        Nothing -> pure Nothing
        Just st -> do
            let key = s3TopCombosKey st
            r <- s3GetObject st key
            case r of
                Left _ -> pure Nothing
                Right Nothing -> pure Nothing
                Right (Just contents) ->
                    writeTopCombosTempFile topJsonPath "top-combos-s3.json" contents

writeTopCombosTempFile :: FilePath -> String -> BL.ByteString -> IO (Maybe FilePath)
writeTopCombosTempFile topJsonPath fileName contents = do
    let dir = takeDirectory topJsonPath
    tempResult <- try (openTempFile dir fileName) :: IO (Either SomeException (FilePath, Handle))
    case tempResult of
        Left _ -> pure Nothing
        Right (path, handle) -> do
            writeResult <- try (BL.hPut handle contents) :: IO (Either SomeException ())
            closeResult <- try (hClose handle) :: IO (Either SomeException ())
            case (writeResult, closeResult) of
                (Right _, Right _) -> pure (Just path)
                _ -> do
                    removeTempTopCombo path
                    pure Nothing

removeTempTopCombo :: FilePath -> IO ()
removeTempTopCombo path = do
    _ <- try (removeFile path) :: IO (Either SomeException ())
    pure ()

readLastOptimizerRecord :: FilePath -> IO (Either String Aeson.Value)
readLastOptimizerRecord path = do
    exists <- doesFileExist path
    if not exists
        then pure (Left "Optimizer did not emit any records.")
        else do
            contentsOrErr <- (try (BL.readFile path) :: IO (Either SomeException BL.ByteString))
            case contentsOrErr of
                Left e -> pure (Left ("Failed to read optimizer records: " ++ show e))
                Right contents ->
                    let nonEmpty = filter (not . BS.null) (BS.lines (BL.toStrict contents))
                     in case listToMaybe (reverse nonEmpty) of
                            Nothing -> pure (Left "Optimizer records file was empty.")
                            Just lastLine ->
                                case Aeson.eitherDecodeStrict' lastLine of
                                    Left err -> pure (Left ("Failed to parse optimizer record: " ++ err))
                                    Right val -> pure (Right val)

writeKlinesCsv :: FilePath -> [Kline] -> IO ()
writeKlinesCsv path ks = do
    let header = "openTime,open,high,low,close,volume\n"
        row k =
            intercalate
                ","
                [ show (kOpenTime k)
                , show (kOpen k)
                , show (kHigh k)
                , show (kLow k)
                , show (kClose k)
                , show (kVolume k)
                ]
                ++ "\n"
        body = header ++ concatMap row ks
    writeFile path body

readTopCombosExport :: TopCombosStore -> IO (Either String TopCombosExport)
readTopCombosExport store = do
    valOrErr <- readTopCombosValue (tcsPath store)
    case valOrErr of
        Left err -> pure (Left err)
        Right val ->
            case Aeson.fromJSON val of
                Aeson.Error err -> pure (Left ("Failed to parse top combos JSON: " ++ err))
                Aeson.Success out -> pure (Right out)

readTopCombosExportWithDbFallback :: Maybe OpsStore -> TopCombosStore -> IO (Either String TopCombosExport)
readTopCombosExportWithDbFallback mOps store = do
    valOrErr <- readTopCombosValueWithDbFallback mOps store
    case valOrErr of
        Left err -> pure (Left err)
        Right val ->
            case Aeson.fromJSON val of
                Aeson.Error err -> pure (Left ("Failed to parse top combos JSON: " ++ err))
                Aeson.Success out -> pure (Right out)

persistTopCombosMaybe :: Maybe StateSyncTarget -> FilePath -> IO ()
persistTopCombosMaybe mSync path = do
    mS3 <- resolveS3State
    let needsRead = isJust mS3 || isJust mSync
    if not needsRead
        then pure ()
        else do
            contentsOrErr <- (try (BL.readFile path) :: IO (Either SomeException BL.ByteString))
            case contentsOrErr of
                Left _ -> pure ()
                Right contents -> do
                    case mS3 of
                        Nothing -> pure ()
                        Just st -> do
                            _ <- s3PutObject st (s3TopCombosKey st) contents
                            persistTopCombosHistoryMaybe path st contents
                            pure ()
                    syncTopCombosMaybe mSync contents

persistTopCombosTargets :: [String] -> Maybe StateSyncTarget -> FilePath -> IO [String]
persistTopCombosTargets targets mSync path =
    if null targets
        then pure []
        else do
            contentsOrErr <- (try (BL.readFile path) :: IO (Either SomeException BL.ByteString))
            case contentsOrErr of
                Left _ -> pure []
                Right contents -> do
                    s3Persisted <-
                        if "s3" `elem` targets
                            then do
                                mS3 <- resolveS3State
                                case mS3 of
                                    Nothing -> pure []
                                    Just st -> do
                                        result <- s3PutObject st (s3TopCombosKey st) contents
                                        case result of
                                            Left _ -> pure []
                                            Right _ -> do
                                                persistTopCombosHistoryMaybe path st contents
                                                pure ["s3"]
                            else pure []
                    stateSyncPersisted <-
                        if "state-sync" `elem` targets
                            then do
                                syncTopCombosMaybe mSync contents
                                lastErr <-
                                    case mSync of
                                        Nothing -> pure (Just "missing state sync target")
                                        Just target -> readIORef (sstLastError target)
                                pure ["state-sync" | isNothing lastErr]
                            else pure []
                    pure (s3Persisted ++ stateSyncPersisted)

strategyCodeFromMethod :: Maybe String -> Text
strategyCodeFromMethod mMethod =
    let toStrategyCode method =
            T.pack $
                case method of
                    MethodKalmanOnly -> "kalman"
                    MethodLstmOnly -> "lstm"
                    MethodBoth -> "both"
                    _ -> methodCode method
        parseStrategyCode raw =
            case parseMethod raw of
                Right method -> Just (toStrategyCode method)
                Left _ -> Nothing
        parseStrategyCodeNormalized raw =
            case parseMethod (normalizeKey raw) of
                Right method -> Just (toStrategyCode method)
                Left _ -> Nothing
     in fromMaybe "unknown" $
            mMethod >>= \raw ->
                parseStrategyCode raw
                    <|> parseStrategyCodeNormalized raw

persistTopCombosDbMaybe :: Maybe OpsStore -> TopCombosStore -> IO ()
persistTopCombosDbMaybe mOps store =
    withTopCombosLock store (persistTopCombosDbMaybeUnlocked mOps store)

persistTopCombosDbMaybeUnlocked :: Maybe OpsStore -> TopCombosStore -> IO ()
persistTopCombosDbMaybeUnlocked mOps store =
    case mOps of
        Nothing -> pure ()
        Just opsStore -> do
            combosOrErr <- readTopCombosExport store
            case combosOrErr of
                Left err -> hPutStrLn stderr ("WARN: failed to persist top combos to DB (" ++ err ++ ")")
                Right export -> do
                    _ <- try (withMVar (osLock opsStore) (\_ -> persistTopCombosToDb (osConn opsStore) export)) :: IO (Either SomeException ())
                    pure ()

persistTopCombosToDb :: Connection -> TopCombosExport -> IO ()
persistTopCombosToDb conn export =
    withTransaction conn $ do
        strategyRows <- query_ conn "SELECT id, code FROM strategies" :: IO [(Int, Text)]
        let strategyMap = HM.fromList [(code, sid) | (sid, code) <- strategyRows]
        now <- getTimestampMs
        forM_ (tceCombos export) $ \combo -> do
            case uuidFromText (topComboUuid combo) of
                Nothing -> pure ()
                Just comboUuid -> do
                    let mStrategyId = HM.lookup (strategyCodeFromMethod (topComboParamString "method" combo)) strategyMap
                        mSymbol = T.pack <$> topComboSymbol combo
                        mInterval = T.pack <$> topComboParamString "interval" combo
                        mObjective = T.pack <$> tcObjectiveLabel combo
                        mSource = T.pack <$> normalizedTopComboSource (tcSource combo)
                        mAnnualized = topComboMetricDouble "annualizedReturn" combo
                        paramsJson = encodeJsonTextMaybe (Just (Aeson.Object (tcParams combo)))
                        metricsJson = encodeJsonTextMaybe (Aeson.Object <$> tcMetrics combo)
                    opRows <- query conn "SELECT COUNT(*) FROM ops WHERE combo_uuid = ?" (Only comboUuid) :: IO [Only Int64]
                    let opCount =
                            case opRows of
                                (Only v : _) -> fromIntegral v
                                _ -> 0 :: Int
                    void $
                        execute
                            conn
                            ( "INSERT INTO combos (combo_uuid, strategy_id, symbol, interval, objective, source, final_equity, annualized_return, score, open_threshold, close_threshold, params_json, metrics_json, operation_count, created_at_ms, updated_at_ms) "
                                <> "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?::jsonb, ?::jsonb, ?, ?, ?) "
                                <> "ON CONFLICT (combo_uuid) DO UPDATE "
                                <> "SET strategy_id = EXCLUDED.strategy_id, "
                                <> "symbol = EXCLUDED.symbol, "
                                <> "interval = EXCLUDED.interval, "
                                <> "objective = EXCLUDED.objective, "
                                <> "source = EXCLUDED.source, "
                                <> "final_equity = EXCLUDED.final_equity, "
                                <> "annualized_return = EXCLUDED.annualized_return, "
                                <> "score = EXCLUDED.score, "
                                <> "open_threshold = EXCLUDED.open_threshold, "
                                <> "close_threshold = EXCLUDED.close_threshold, "
                                <> "params_json = EXCLUDED.params_json, "
                                <> "metrics_json = EXCLUDED.metrics_json, "
                                <> "operation_count = EXCLUDED.operation_count, "
                                <> "updated_at_ms = EXCLUDED.updated_at_ms"
                            )
                            ( comboUuid
                            , mStrategyId
                            , mSymbol
                            , mInterval
                            , mObjective
                            , mSource
                            , tcFinalEquity combo
                            , mAnnualized
                            , tcScore combo
                            , tcOpenThreshold combo
                            , tcCloseThreshold combo
                            , paramsJson
                            , metricsJson
                            , opCount
                            , now
                            , now
                            )
                    persistComboParameters conn comboUuid mStrategyId (tcParams combo)

persistComboParameters :: Connection -> UUID.UUID -> Maybe Int -> Aeson.Object -> IO ()
persistComboParameters conn comboUuid mStrategyId params = do
    void $ execute conn "DELETE FROM combo_parameters WHERE combo_uuid = ?" (Only comboUuid)
    forM_ (KM.toList params) $ \(k, v) ->
        void $
            execute
                conn
                "INSERT INTO combo_parameters (combo_uuid, name, value_json, strategy_id) VALUES (?, ?, ?::jsonb, ?)"
                (comboUuid, AK.toText k, encodeJsonTextMaybe (Just v), mStrategyId)

persistTopCombosHistoryMaybe :: FilePath -> S3State -> BL.ByteString -> IO ()
persistTopCombosHistoryMaybe topJsonPath st contents = do
    historyDir <- resolveOptimizerCombosHistoryDir topJsonPath
    case historyDir of
        Nothing -> pure ()
        Just _ -> do
            ts <- getTimestampMs
            let key = s3TopCombosHistoryKey st ts
            _ <- s3PutObject st key contents
            pure ()

readTopCombosValueFromDbRaw :: OpsStore -> IO (Either String Aeson.Value)
readTopCombosValueFromDbRaw store = do
    result <- try readDb :: IO (Either SomeException (Either String Aeson.Value))
    case result of
        Left e -> pure (Left ("Failed to read top combos from the database: " ++ show e))
        Right out -> pure out
  where
    readDb = do
        maxCombos <- optimizerMaxCombosFromEnv
        let limitSafe = max 1 maxCombos
        rows <-
            withMVar (osLock store) $ \_ ->
                query
                    (osConn store)
                    ( "SELECT combo_uuid, final_equity, annualized_return, objective, source, score, open_threshold, close_threshold, "
                        <> "params_json::text, metrics_json::text, created_at_ms, updated_at_ms "
                        <> "FROM combos "
                        <> "ORDER BY annualized_return DESC NULLS LAST, score DESC NULLS LAST, final_equity DESC NULLS LAST, updated_at_ms DESC NULLS LAST "
                        <> "LIMIT ?"
                    )
                    (Only limitSafe) ::
                    IO [PersistedComboRow]
        let combos = mapMaybe persistedComboToValue (filterPersistedComboRows rows)
        if null combos
            then pure (Left "No persisted combos found in the database.")
            else do
                now <- getTimestampMs
                let combosRanked = zipWith addRank [1 ..] (sortOn comboPerformanceKey combos)
                    payload =
                        object
                            [ "generatedAtMs" .= now
                            , "source" .= ("db" :: String)
                            , "combos" .= combosRanked
                            ]
                pure (Right payload)

    addRank :: Int -> Aeson.Value -> Aeson.Value
    addRank rank val =
        case val of
            Aeson.Object o -> Aeson.Object (KM.insert (AK.fromString "rank") (toJSON rank) o)
            other -> other

readTopCombosValueFromDb :: OpsStore -> IO (Either String Aeson.Value)
readTopCombosValueFromDb store =
    fmap normalizeTopCombosPayload <$> readTopCombosValueFromDbRaw store

readTopCombosValueWithDbFallback :: Maybe OpsStore -> TopCombosStore -> IO (Either String Aeson.Value)
readTopCombosValueWithDbFallback mOps store =
    withTopCombosLock store (readTopCombosValueWithDbFallbackUnlocked mOps store)

readTopCombosValueWithDbFallbackRaw :: Maybe OpsStore -> TopCombosStore -> IO (Either String Aeson.Value)
readTopCombosValueWithDbFallbackRaw mOps store =
    withTopCombosLock store (readTopCombosValueWithDbFallbackRawUnlocked mOps store)

readTopCombosValueWithDbFallbackUnlocked :: Maybe OpsStore -> TopCombosStore -> IO (Either String Aeson.Value)
readTopCombosValueWithDbFallbackUnlocked mOps store = do
    let path = tcsPath store
    localResult <- readTopCombosValue path
    case localResult of
        Right val -> pure (Right val)
        Left localErr ->
            case mOps of
                Nothing -> pure (Left localErr)
                Just opsStore -> do
                    dbResult <- readTopCombosValueFromDb opsStore
                    case dbResult of
                        Left dbErr -> pure (Left (localErr ++ " " ++ dbErr))
                        Right val -> pure (Right val)

readTopCombosValueWithDbFallbackRawUnlocked :: Maybe OpsStore -> TopCombosStore -> IO (Either String Aeson.Value)
readTopCombosValueWithDbFallbackRawUnlocked mOps store = do
    let path = tcsPath store
    localResult <- readTopCombosValueRaw path
    case localResult of
        Right val -> pure (Right val)
        Left localErr ->
            case mOps of
                Nothing -> pure (Left localErr)
                Just opsStore -> do
                    dbResult <- readTopCombosValueFromDbRaw opsStore
                    case dbResult of
                        Left dbErr -> pure (Left (localErr ++ " " ++ dbErr))
                        Right val -> pure (Right val)

readTopCombosValueRaw :: FilePath -> IO (Either String Aeson.Value)
readTopCombosValueRaw path = do
    localResult <- readTopCombosValueLocal path
    case localResult of
        Right val -> pure (Right val)
        Left localErr -> do
            mS3 <- resolveS3State
            case mS3 of
                Nothing -> pure (Left localErr)
                Just st -> do
                    let key = s3TopCombosKey st
                    r <- s3GetObject st key
                    case r of
                        Left e -> pure (Left ("Failed to read top combos from S3: " ++ e))
                        Right Nothing -> pure (Left localErr)
                        Right (Just contents) ->
                            case Aeson.eitherDecode' contents of
                                Left err -> pure (Left ("Failed to parse top combos JSON from S3: " ++ err))
                                Right val -> pure (Right val)

readTopCombosValue :: FilePath -> IO (Either String Aeson.Value)
readTopCombosValue path =
    fmap normalizeTopCombosPayload <$> readTopCombosValueRaw path

extractBacktestMetrics :: Aeson.Value -> Maybe Aeson.Value
extractBacktestMetrics val =
    case val of
        Aeson.Object o -> KM.lookup (AK.fromString "metrics") o
        _ -> Nothing

extractBacktestOperations :: Aeson.Value -> Maybe Aeson.Value
extractBacktestOperations val =
    case val of
        Aeson.Object o ->
            case KM.lookup (AK.fromString "trades") o of
                Just (Aeson.Array trades) ->
                    let ops = mapMaybe tradeToOp (V.toList trades)
                     in if null ops then Nothing else Just (Aeson.Array (V.fromList ops))
                _ -> Nothing
        _ -> Nothing
  where
    tradeToOp :: Aeson.Value -> Maybe Aeson.Value
    tradeToOp tradeVal =
        case tradeVal of
            Aeson.Object trade -> do
                entryIdx <- (KM.lookup (AK.fromString "entryIndex") trade >>= AT.parseMaybe parseJSON :: Maybe Int)
                exitIdx <- (KM.lookup (AK.fromString "exitIndex") trade >>= AT.parseMaybe parseJSON :: Maybe Int)
                let entryEq = KM.lookup (AK.fromString "entryEquity") trade >>= AT.parseMaybe parseJSON :: Maybe Double
                    exitEq = KM.lookup (AK.fromString "exitEquity") trade >>= AT.parseMaybe parseJSON :: Maybe Double
                    retVal = KM.lookup (AK.fromString "return") trade >>= AT.parseMaybe parseJSON :: Maybe Double
                    holding = KM.lookup (AK.fromString "holdingPeriods") trade >>= AT.parseMaybe parseJSON :: Maybe Int
                    exitReason = KM.lookup (AK.fromString "exitReason") trade >>= AT.parseMaybe parseJSON :: Maybe String
                    base =
                        [ "entryIndex" .= entryIdx
                        , "exitIndex" .= exitIdx
                        ]
                    extras =
                        catMaybes
                            [ fmap ("entryEquity" .=) entryEq
                            , fmap ("exitEquity" .=) exitEq
                            , fmap ("return" .=) retVal
                            , fmap ("holdingPeriods" .=) holding
                            , fmap ("exitReason" .=) exitReason
                            ]
                pure (object (base ++ extras))
            _ -> Nothing

objectiveScoreFromMetrics :: Args -> String -> Aeson.Value -> Maybe Double
objectiveScoreFromMetrics args objective metricsVal =
    case metricsVal of
        Aeson.Object metrics ->
            let rawScore =
                    objectiveScore
                        metrics
                        objective
                        (argTunePenaltyMaxDrawdown args)
                        (argTunePenaltyTurnover args)
             in if isNaN rawScore || isInfinite rawScore
                    then Nothing
                    else Just rawScore
        _ -> Nothing

topComboParamString :: String -> TopCombo -> Maybe String
topComboParamString key combo =
    KM.lookup (AK.fromString key) (tcParams combo) >>= AT.parseMaybe parseJSON

topComboParamInt :: String -> TopCombo -> Maybe Int
topComboParamInt key combo =
    KM.lookup (AK.fromString key) (tcParams combo) >>= AT.parseMaybe parseJSON

topComboMetricInt :: String -> TopCombo -> Maybe Int
topComboMetricInt key combo = do
    metrics <- tcMetrics combo
    KM.lookup (AK.fromString key) metrics >>= AT.parseMaybe parseJSON

topComboMetricDouble :: String -> TopCombo -> Maybe Double
topComboMetricDouble key combo = do
    metrics <- tcMetrics combo
    KM.lookup (AK.fromString key) metrics >>= AT.parseMaybe parseJSON

topComboTradeCount :: TopCombo -> Int
topComboTradeCount combo = fromMaybe 0 (topComboMetricInt "tradeCount" combo)

topComboAnnualizedReturn :: TopCombo -> Double
topComboAnnualizedReturn combo =
    let ann = fromMaybe (negate (1 / 0)) (topComboMetricDouble "annualizedReturn" combo)
     in if isNaN ann || isInfinite ann then negate (1 / 0) else ann

topComboRankKey :: TopCombo -> (Double, Double, Double, Int)
topComboRankKey combo =
    let rank = fromMaybe (maxBound :: Int) (tcRank combo)
        score = fromMaybe (negate (1 / 0)) (tcScore combo)
        eq = fromMaybe 0 (tcFinalEquity combo)
        score' = if isNaN score || isInfinite score then negate (1 / 0) else score
        eq' = if isNaN eq || isInfinite eq then 0 else eq
     in (negate (topComboAnnualizedReturn combo), negate score', negate eq', rank)

topComboTradePriorityKey :: TopCombo -> (Double, Int, Double, Double, Int)
topComboTradePriorityKey combo =
    let trades = negate (topComboTradeCount combo)
        (ann, score, eq, rank) = topComboRankKey combo
     in (ann, trades, score, eq, rank)

topComboMatchesSymbol :: String -> Maybe String -> TopCombo -> Bool
topComboMatchesSymbol symRaw mInterval combo =
    let sym = normalizeSymbol symRaw
        comboSym = topComboSymbol combo
        symOk = maybe False (\s -> normalizeSymbol s == sym) comboSym
        intervalOk =
            case mInterval of
                Nothing -> True
                Just interval ->
                    case topComboParamString "interval" combo of
                        Nothing -> True
                        Just v -> v == interval
     in symOk && intervalOk

bestTopComboFromList :: [TopCombo] -> Maybe TopCombo
bestTopComboFromList combos =
    case sortOn topComboTradePriorityKey combos of
        [] -> Nothing
        (c : _) -> Just c

bestTopCombo :: TopCombosExport -> Maybe TopCombo
bestTopCombo export = bestTopComboFromList (tceCombos export)

bestTopComboForSymbol :: String -> Maybe String -> TopCombosExport -> Maybe TopCombo
bestTopComboForSymbol symRaw mInterval export =
    bestTopComboFromList (filter (topComboMatchesSymbol symRaw mInterval) (tceCombos export))

applyTopComboForStart :: Args -> TopCombo -> Either String Args
applyTopComboForStart base combo = do
    args0 <- parseTopComboToArgs base combo
    let mInterval = topComboParamString "interval" combo
        mBars = topComboParamInt "bars" combo
        intervalOk =
            case mInterval of
                Nothing -> Nothing
                Just v | isPlatformInterval (argPlatform args0) v -> Just v
                _ -> Nothing
        barsOk =
            case mBars of
                Nothing -> Nothing
                Just n -> Just (max 0 n)
        args1 =
            case intervalOk of
                Nothing -> args0
                Just v -> args0{argInterval = v}
        args2 =
            case barsOk of
                Nothing -> args1
                Just n -> args1{argBars = Just n}
    pure args2

applyTopComboForStartWithUuid :: Args -> TopCombo -> Either String (Args, Maybe Text)
applyTopComboForStartWithUuid base combo = do
    args0 <- applyTopComboForStart base combo
    pure (args0, Just (topComboUuid combo))

handleOptimizerRun ::
    ApiRequestLimits ->
    Maybe OpsStore ->
    Maybe StateSyncTarget ->
    FilePath ->
    TopCombosStore ->
    FilePath ->
    Wai.Request ->
    (Wai.Response -> IO Wai.ResponseReceived) ->
    IO Wai.ResponseReceived
handleOptimizerRun reqLimits mOps mStateSyncTarget projectRoot topCombosStore optimizerTmp req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid optimizer payload: "
    case payloadOrErr of
        Left resp -> respond resp
        Right payload -> do
            ts <- fmap (floor . (* 1000)) getPOSIXTime
            randId <- randomIO :: IO Word64
            let topJsonPath = tcsPath topCombosStore
            let recordsPath = optimizerTmp </> printf "optimizer-%d-%016x.jsonl" (ts :: Integer) randId
                maxOutputBytes = arlMaxOptimizerOutputBytes reqLimits
                truncateOut = truncateProcessOutput maxOutputBytes
            argsOrErr <- prepareOptimizerArgs recordsPath payload
            case argsOrErr of
                Left msg -> respond (jsonError status400 msg)
                Right args -> do
                    runResult <- runOptimizerProcess projectRoot recordsPath maxOutputBytes args
                    case runResult of
                        Left (msg, out, err) ->
                            respond
                                ( jsonValue
                                    status500
                                    (object ["error" .= msg, "stdout" .= truncateOut out, "stderr" .= truncateOut err])
                                )
                        Right resp -> do
                            let resp' =
                                    resp
                                        { arrStdout = truncateOut (arrStdout resp)
                                        , arrStderr = truncateOut (arrStderr resp)
                                        }
                            maxCombos <- optimizerMaxCombosFromEnv
                            mergeResult <- withTopCombosLock topCombosStore (runMergeTopCombos mStateSyncTarget projectRoot topJsonPath recordsPath maxCombos)
                            case mergeResult of
                                Left (msg, out, err) ->
                                    respond
                                        ( jsonValue
                                            status500
                                            (object ["error" .= msg, "stdout" .= truncateOut out, "stderr" .= truncateOut err])
                                        )
                                Right _ -> do
                                    persistTopCombosDbMaybe mOps topCombosStore
                                    respond (jsonValue status200 resp')

handleOptimizerCombos ::
    Maybe OpsStore ->
    Maybe StateSyncTarget ->
    FilePath ->
    TopCombosStore ->
    FilePath ->
    (Wai.Response -> IO Wai.ResponseReceived) ->
    IO Wai.ResponseReceived
handleOptimizerCombos mOps mStateSyncTarget projectRoot topCombosStore optimizerTmp respond = do
    let topJsonPath = tcsPath topCombosStore
    let tmpPath = optimizerTmp </> optimizerCombosFileName
        fallbackPath = projectRoot </> "web" </> "public" </> optimizerCombosFileName
    topVal0 <- readTopCombosValueWithDbFallback mOps topCombosStore
    topVal <-
        case topVal0 of
            Right v -> pure (Right v)
            Left err -> do
                recovered <- withTopCombosLock topCombosStore (recoverTopCombosFromHistory topJsonPath)
                pure $
                    case recovered of
                        Just val -> Right val
                        Nothing -> Left err
    topValBackfilled <-
        case (mOps, topVal) of
            (Just opsStore, Right val) -> do
                dbVal <- readTopCombosValueFromDb opsStore
                let currentCount = topCombosComboCount val
                    dbCount =
                        case dbVal of
                            Right dbVal' -> topCombosComboCount dbVal'
                            Left _ -> 0
                when (currentCount > dbCount) $
                    withTopCombosLock topCombosStore (persistTopCombosDbMaybeUnlocked mOps topCombosStore)
                pure (Right val)
            _ -> pure topVal
    minPersist <- topCombosMinPersistFromEnv
    maxCombos <- optimizerMaxCombosFromEnv
    _ <-
        case (mOps, topValBackfilled) of
            (Just opsStore, Right val) -> do
                let currentCount = topCombosComboCount val
                if currentCount >= minPersist
                    then pure (Right val)
                    else do
                        dbVal <- readTopCombosValueFromDb opsStore
                        case dbVal of
                            Left _ -> pure (Right val)
                            Right dbVal' -> do
                                now <- getTimestampMs
                                let mergedVal = mergeTopCombosPayloads (max minPersist maxCombos) now [val, dbVal']
                                    mergedCount = topCombosComboCount mergedVal
                                if mergedCount <= currentCount
                                    then pure (Right val)
                                    else do
                                        withTopCombosLock topCombosStore $ do
                                            _ <- writeTopCombosValue topJsonPath mergedVal
                                            persistTopCombosMaybe mStateSyncTarget topJsonPath
                                            persistTopCombosDbMaybeUnlocked mOps topCombosStore
                                        pure (Right mergedVal)
            _ -> pure topValBackfilled
    let sanitizeVal = fmap (fst . sanitizeTopCombosValue)
    tmpVal <-
        if tmpPath /= topJsonPath
            then sanitizeVal <$> readTopCombosValueLocal tmpPath
            else pure (Left "missing")
    fallbackVal <-
        if fallbackPath /= topJsonPath && fallbackPath /= tmpPath
            then sanitizeVal <$> readTopCombosValueLocal fallbackPath
            else pure (Left "missing")
    let seedVal = listToMaybe (rights [tmpVal, fallbackVal])
    case (topValBackfilled, seedVal) of
        (Left _, Just seed) ->
            withTopCombosLock topCombosStore $ do
                existsNow <- doesFileExist topJsonPath
                unless existsNow $ do
                    _ <- writeTopCombosValue topJsonPath seed
                    persistTopCombosMaybe mStateSyncTarget topJsonPath
        _ -> pure ()
    topResponseVal <- readTopCombosValueWithDbFallbackRaw mOps topCombosStore
    tmpResponseVal <-
        if tmpPath /= topJsonPath
            then readTopCombosValueLocal tmpPath
            else pure (Left "missing")
    fallbackResponseVal <-
        if fallbackPath /= topJsonPath && fallbackPath /= tmpPath
            then readTopCombosValueLocal fallbackPath
            else pure (Left "missing")
    let responseVals = rights [topResponseVal, tmpResponseVal, fallbackResponseVal]
    now <- getTimestampMs
    let maxResponseCombos = max minPersist maxCombos
        (mergedVal, TopCombosMergeStats{tcmsRawCount = rawCount, tcmsDroppedCount = droppedCount, tcmsDedupedCount = dedupedCount}) =
            mergeTopCombosPayloadsWithStats maxResponseCombos now responseVals
        combos = extractCombos mergedVal
        payloadSources =
            concatMap
                ( \val ->
                    let sanitized = fst (sanitizeTopCombosValue val)
                     in if null (extractCombos sanitized)
                            then []
                            else maybeToList (extractPayloadSource sanitized)
                )
                responseVals
        payloadSource = listToMaybe payloadSources
    if null combos
        then respond (jsonError status404 "Optimizer combos not available yet.")
        else do
            let out =
                    object
                        [ "generatedAtMs" .= now
                        , "source" .= ("optimizer/combos" :: String)
                        , "payloadSource" .= payloadSource
                        , "payloadSources" .= payloadSources
                        , "rawCount" .= rawCount
                        , "droppedCount" .= droppedCount
                        , "dedupedCount" .= dedupedCount
                        , "combos" .= combos
                        ]
            respond (jsonValue status200 out)
  where
    extractCombos :: Aeson.Value -> [Aeson.Value]
    extractCombos val =
        case val of
            Aeson.Object o ->
                let generatedAtMs = KM.lookup "generatedAtMs" o >>= AT.parseMaybe parseJSON
                    applyCreatedAt = applyComboCreatedAt generatedAtMs
                 in case KM.lookup "combos" o of
                        Just (Aeson.Array arr) -> map applyCreatedAt (V.toList arr)
                        _ -> []
            _ -> []

    applyComboCreatedAt :: Maybe Int64 -> Aeson.Value -> Aeson.Value
    applyComboCreatedAt createdAtMs val =
        case (createdAtMs, val) of
            (Just ts, Aeson.Object o) ->
                case KM.lookup "createdAtMs" o of
                    Just Aeson.Null -> Aeson.Object (KM.insert "createdAtMs" (toJSON ts) o)
                    Just _ -> val
                    Nothing -> Aeson.Object (KM.insert "createdAtMs" (toJSON ts) o)
            _ -> val

    extractPayloadSource :: Aeson.Value -> Maybe String
    extractPayloadSource val =
        case val of
            Aeson.Object o -> KM.lookup "source" o >>= AT.parseMaybe parseJSON >>= cleanPayloadSource
            _ -> Nothing

    cleanPayloadSource :: String -> Maybe String
    cleanPayloadSource raw =
        let s = trim raw
         in if null s then Nothing else Just s

    recoverTopCombosFromHistory :: FilePath -> IO (Maybe Aeson.Value)
    recoverTopCombosFromHistory topPath =
        case tcsHistoryDir topCombosStore of
            Nothing -> pure Nothing
            Just histDir -> do
                exists <- doesDirectoryExist histDir
                if not exists
                    then pure Nothing
                    else do
                        entries <- listDirectory histDir
                        let candidates =
                                sortOn Data.Ord.Down ([histDir </> f | f <- entries, "top-combos-" `isPrefixOf` f, ".json" `isSuffixOf` f])
                        restoreFirst candidates
      where
        restoreFirst [] = pure Nothing
        restoreFirst (p : ps) = do
            valOrErr <- readTopCombosValueLocal p
            case valOrErr of
                Right val -> do
                    _ <- writeTopCombosValue topPath val
                    persistTopCombosMaybe mStateSyncTarget topPath
                    pure (Just val)
                Left _ -> restoreFirst ps

handleStateSyncExport ::
    Maybe OpsStore ->
    Maybe FilePath ->
    TopCombosStore ->
    Wai.Request ->
    (Wai.Response -> IO Wai.ResponseReceived) ->
    IO Wai.ResponseReceived
handleStateSyncExport mOps mBotStateDir topCombosStore req respond =
    case requireTenantKey "state/sync" (tenantKeyFromRequest req) of
        Left e -> respond (jsonError status400 e)
        Right tenantKey -> do
            now <- getTimestampMs
            snaps <- readBotStatusSnapshotsMaybe mBotStateDir tenantKey
            topVal <- readTopCombosValueWithDbFallback mOps topCombosStore
            let payload =
                    StateSyncPayload
                        { sspGeneratedAtMs = Just now
                        , sspBotSnapshots = if null snaps then Nothing else Just snaps
                        , sspTopCombos =
                            case topVal of
                                Right val -> Just val
                                Left _ -> Nothing
                        }
            respond (jsonValue status200 payload)

handleStateSyncImport ::
    ApiRequestLimits ->
    Maybe OpsStore ->
    Maybe StateSyncTarget ->
    Maybe FilePath ->
    TopCombosStore ->
    Wai.Request ->
    (Wai.Response -> IO Wai.ResponseReceived) ->
    IO Wai.ResponseReceived
handleStateSyncImport reqLimits mOps mStateSyncTarget mBotStateDir topCombosStore req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid state sync payload: "
    case payloadOrErr of
        Left resp -> respond resp
        Right payload ->
            case requireTenantKey "state/sync" (tenantKeyFromRequest req) of
                Left e -> respond (jsonError status400 e)
                Right tenantKey -> do
                    now <- getTimestampMs
                    let incomingSnaps = fromMaybe [] (sspBotSnapshots payload)
                    existingSnaps <- readBotStatusSnapshotsMaybe mBotStateDir tenantKey
                    let mergedSnaps = mergeBotSnapshots (existingSnaps ++ incomingSnaps)
                        snapsWithSymbol =
                            mapMaybe
                                (\snap -> (,) <$> botSnapshotSymbol snap <*> pure snap)
                                mergedSnaps
                        writtenCount = length snapsWithSymbol
                        skippedCount = length mergedSnaps - writtenCount
                        snapStats =
                            object
                                [ "incoming" .= length incomingSnaps
                                , "existing" .= length existingSnaps
                                , "merged" .= length mergedSnaps
                                , "written" .= writtenCount
                                , "skipped" .= skippedCount
                                ]
                    forM_ snapsWithSymbol $ uncurry (writeBotStatusSnapshotMaybe mBotStateDir tenantKey)

                    let topJsonPath = tcsPath topCombosStore
                        mkTopStats :: String -> Maybe Int64 -> Maybe Int64 -> Aeson.Value
                        mkTopStats action incoming local =
                            object
                                ( ["action" .= (action :: String)]
                                    ++ maybe [] (\v -> ["incomingGeneratedAtMs" .= v]) incoming
                                    ++ maybe [] (\v -> ["localGeneratedAtMs" .= v]) local
                                )

                    topStatsOrErr <-
                        case sspTopCombos payload of
                            Nothing -> do
                                localTopValResult <- readTopCombosValueWithDbFallback mOps topCombosStore
                                let localGeneratedAt =
                                        case localTopValResult of
                                            Right val -> topCombosGeneratedAtMs val
                                            Left _ -> Nothing
                                pure (Right (mkTopStats "skipped" Nothing localGeneratedAt))
                            Just raw ->
                                if not (isTopCombosPayload raw)
                                    then pure (Left (jsonError status400 "Invalid topCombos payload (expected object with combos array)."))
                                    else withTopCombosLock topCombosStore $ do
                                        localTopValResult <- readTopCombosValueWithDbFallbackUnlocked mOps topCombosStore
                                        minPersist <- topCombosMinPersistFromEnv
                                        let localTopVal =
                                                case localTopValResult of
                                                    Right val -> Just val
                                                    Left _ -> Nothing
                                            localGeneratedAt = localTopVal >>= topCombosGeneratedAtMs
                                            localCount = maybe 0 topCombosComboCount localTopVal
                                            (incomingSanitized, _) = sanitizeTopCombosValue raw
                                            incomingGeneratedAt = topCombosGeneratedAtMs incomingSanitized
                                            incomingCount = topCombosComboCount incomingSanitized
                                            needsBackfill = localCount < minPersist && incomingCount > localCount
                                            shouldReplace =
                                                needsBackfill
                                                    || case (incomingGeneratedAt, localGeneratedAt) of
                                                        (Just incomingTs, Just localTs) -> incomingTs >= localTs
                                                        (Just _, Nothing) -> True
                                                        (Nothing, Nothing) -> True
                                                        (Nothing, Just _) -> False
                                        if shouldReplace
                                            then do
                                                maxCombos <- optimizerMaxCombosFromEnv
                                                let mergedVal =
                                                        case localTopVal of
                                                            Just localVal -> mergeTopCombosPayloads maxCombos now [localVal, incomingSanitized]
                                                            Nothing -> mergeTopCombosPayloads maxCombos now [incomingSanitized]
                                                    action =
                                                        case localTopVal of
                                                            Just _ -> "merged"
                                                            Nothing -> "replaced"
                                                writeResult <- writeTopCombosValue topJsonPath mergedVal
                                                case writeResult of
                                                    Left err ->
                                                        pure (Left (jsonError status500 ("Failed to write top combos: " ++ err)))
                                                    Right _ -> do
                                                        persistTopCombosMaybe mStateSyncTarget topJsonPath
                                                        persistTopCombosDbMaybeUnlocked mOps topCombosStore
                                                        pure (Right (mkTopStats action incomingGeneratedAt localGeneratedAt))
                                            else pure (Right (mkTopStats "kept" incomingGeneratedAt localGeneratedAt))

                    case topStatsOrErr of
                        Left resp -> respond resp
                        Right topStats ->
                            respond
                                ( jsonValue
                                    status200
                                    (object ["ok" .= True, "atMs" .= now, "botSnapshots" .= snapStats, "topCombos" .= topStats])
                                )

handleMetrics :: Metrics -> BotController -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleMetrics metrics botCtrl respond = do
    states <- botGetStatesAll botCtrl
    body <- renderMetricsText metrics (not (null states))
    respond (textValue status200 body)

handleOps :: Bool -> Maybe OpsStore -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleOps multiUserEnabled mOps req respond =
    case mOps of
        Nothing ->
            respond
                ( jsonValue
                    status200
                    ( object
                        [ "enabled" .= False
                        , "hint" .= ("Set TRADER_DB_URL (or DATABASE_URL) to enable ops persistence (PostgreSQL)." :: String)
                        , "ops" .= ([] :: [PersistedOperation])
                        ]
                    )
                )
        Just store -> do
            let tenantResult =
                    if multiUserEnabled
                        then Just <$> requireTenantKey "ops" (tenantKeyFromRequest req)
                        else Right (tenantKeyFromRequest req)
            case tenantResult of
                Left e -> respond (jsonError status400 e)
                Right mTenantKey -> do
                    let q = Wai.queryString req
                        lookupParam name =
                            case lookup (BS.pack name) q of
                                Just (Just raw) -> Just raw
                                _ -> Nothing
                        readIntParam name =
                            lookupParam name >>= (readMaybe . BS.unpack)
                        readBoolParam name =
                            case fmap (map toLower . BS.unpack) (lookupParam name) of
                                Just "1" -> Just True
                                Just "true" -> Just True
                                Just "yes" -> Just True
                                Just "y" -> Just True
                                Just "only" -> Just True
                                Just "0" -> Just False
                                Just "false" -> Just False
                                Just "no" -> Just False
                                Just "n" -> Just False
                                _ -> Nothing
                        limit = fromMaybe 200 (readIntParam "limit")
                        sinceId = readIntParam "since"
                        kind = T.pack . BS.unpack <$> lookupParam "kind"
                        symbol = T.pack . BS.unpack <$> lookupParam "symbol"
                        comboUuid = T.pack . BS.unpack <$> lookupParam "comboUuid"
                        orderId = T.pack . BS.unpack <$> lookupParam "orderId"
                        fromMs = readIntParam "fromMs"
                        toMs = readIntParam "toMs"
                        botOnly = readBoolParam "bot"
                    ops <- opsList store mTenantKey sinceId limit kind symbol comboUuid orderId fromMs toMs botOnly
                    latestId <- readIORef (osLatestId store)
                    respond (jsonValue status200 (object ["enabled" .= True, "latestId" .= latestId, "ops" .= ops]))

handleOpsPerformance :: Bool -> Maybe OpsStore -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleOpsPerformance multiUserEnabled mOps req respond =
    case mOps of
        Nothing ->
            respond
                ( jsonValue
                    status200
                    ( OpsPerformanceResponse
                        { oprEnabled = False
                        , oprReady = False
                        , oprCommitsReady = False
                        , oprCombosReady = False
                        , oprHint = Just "Set TRADER_DB_URL (or DATABASE_URL) to enable ops persistence."
                        , oprUpdatedAtMs = Nothing
                        , oprCommits = []
                        , oprCombos = []
                        }
                    )
                )
        Just store -> do
            let tenantResult =
                    if multiUserEnabled
                        then Just <$> requireTenantKey "ops/performance" (tenantKeyFromRequest req)
                        else Right (tenantKeyFromRequest req)
            case tenantResult of
                Left e -> respond (jsonError status400 e)
                Right mTenantKey -> do
                    let q = Wai.queryString req
                        lookupParam name =
                            case lookup (BS.pack name) q of
                                Just (Just raw) -> Just raw
                                _ -> Nothing
                        readIntParam name =
                            lookupParam name >>= (readMaybe . BS.unpack)
                        readTextParam name =
                            T.pack . BS.unpack <$> lookupParam name
                        limitParam name def =
                            case readIntParam name of
                                Nothing -> def
                                Just n -> max 0 (min 200 n)
                        commitLimit = limitParam "commitLimit" 40
                        comboLimit = limitParam "comboLimit" 40
                        comboScope = fromMaybe "latest" (readTextParam "comboScope")
                        comboOrder = fromMaybe "delta" (readTextParam "comboOrder")
                    now <- getTimestampMs
                    ready <- opsPerformanceReady store
                    let commitsReady = oprCommitsReadyFlag ready
                        combosReady = oprCombosReadyFlag ready
                        baseHint =
                            if commitsReady
                                then
                                    if combosReady
                                        then Nothing
                                        else Just "Combo deltas are unavailable; rerun rollup_performance.sh to create the views."
                                else Just "Performance rollups are unavailable; run haskell/scripts/rollup_performance.sh to build them."
                    commits <- if commitsReady then opsPerformanceCommits store mTenantKey commitLimit else pure []
                    combos <- if combosReady then opsPerformanceCombos store mTenantKey comboLimit comboScope comboOrder else pure []
                    respond
                        ( jsonValue
                            status200
                            ( OpsPerformanceResponse
                                { oprEnabled = True
                                , oprReady = commitsReady
                                , oprCommitsReady = commitsReady
                                , oprCombosReady = combosReady
                                , oprHint = baseHint
                                , oprUpdatedAtMs = Just now
                                , oprCommits = commits
                                , oprCombos = combos
                                }
                            )
                        )

handleOutbox :: Bool -> Maybe OpsStore -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleOutbox multiUserEnabled mOps req respond =
    case mOps of
        Nothing ->
            respond
                ( jsonValue
                    status200
                    ( object
                        [ "enabled" .= False
                        , "hint" .= ("Set TRADER_DB_URL (or DATABASE_URL) to enable outbox persistence." :: String)
                        ]
                    )
                )
        Just store -> do
            let q = Wai.queryString req
                lookupParam name =
                    case lookup (BS.pack name) q of
                        Just (Just raw) -> Just raw
                        _ -> Nothing
                statusParam = T.toLower . T.strip . T.pack . BS.unpack <$> lookupParam "status"
                statusFilter =
                    case statusParam of
                        Just "pending" -> Just "pending"
                        Just "publishing" -> Just "publishing"
                        Just "published" -> Just "published"
                        Just "failed" -> Just "failed"
                        Just _ -> Nothing
                        Nothing -> Nothing
                tenantResult =
                    if multiUserEnabled
                        then Just <$> requireTenantKey "outbox" (tenantKeyFromRequest req)
                        else Right (tenantKeyFromRequest req)
            case (statusParam, statusFilter) of
                (Just _, Nothing) -> respond (jsonError status400 "Invalid outbox status (expected pending|publishing|published|failed).")
                _ ->
                    case tenantResult of
                        Left e -> respond (jsonError status400 e)
                        Right mTenantKey -> do
                            payload <- outboxStatusValue store mTenantKey statusFilter
                            respond (jsonValue status200 payload)

handleSignal :: ApiRequestLimits -> ApiCache -> Maybe OpsStore -> ApiComputeLimits -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleSignal reqLimits apiCache mOps limits baseArgs req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            let tenantHint = apTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
             in case argsFromApi baseArgs params of
                    Left e -> respond (jsonError status400 e)
                    Right args0 ->
                        case resolveTenantKeyFromApiParamsWithHint tenantHint args0 params of
                            Left e -> respond (jsonError status400 e)
                            Right mReqTenant -> do
                                let args =
                                        args0
                                            { argTradeOnly = True
                                            , argBinanceTrade = False
                                            , argSweepThreshold = False
                                            , argOptimizeOperations = False
                                            }
                                case validateArgs args of
                                    Left e -> respond (jsonError status400 e)
                                    Right args1 -> do
                                        case validateApiComputeLimits limits args1 of
                                            Left e -> respond (jsonError status400 e)
                                            Right argsOk -> do
                                                let noCache = requestWantsNoCache req
                                                r <-
                                                    try
                                                        ( if noCache
                                                            then computeLatestSignalFromArgsWithLimits limits mOps argsOk
                                                            else computeLatestSignalFromArgsCached apiCache limits mOps argsOk
                                                        ) ::
                                                        IO (Either SomeException LatestSignal)
                                                case r of
                                                    Left ex ->
                                                        let (st, msg) = exceptionToHttp ex
                                                         in respond (jsonError st msg)
                                                    Right sig -> do
                                                        opsAppendMaybe
                                                            mOps
                                                            mReqTenant
                                                            "signal"
                                                            (Just (toJSON (sanitizeApiParams params)))
                                                            (Just (argsPublicJson argsOk))
                                                            (Just (toJSON sig))
                                                            Nothing
                                                            Nothing
                                                            (T.pack <$> argBinanceSymbol argsOk)
                                                            Nothing
                                                        outboxEnqueueMaybe
                                                            mOps
                                                            mReqTenant
                                                            "trader.v1.signals.generated"
                                                            (Just (ownerKeyFromArgs mReqTenant argsOk))
                                                            ( object
                                                                [ "ownerKey" .= ownerKeyFromArgs mReqTenant argsOk
                                                                , "signal" .= sig
                                                                ]
                                                            )
                                                        respond (jsonValue status200 sig)

handleSignalAsync :: ApiRequestLimits -> ApiCache -> Maybe OpsStore -> ApiComputeLimits -> JobStore LatestSignal -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleSignalAsync reqLimits apiCache mOps limits store baseArgs req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            let tenantHint = apTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
             in case argsFromApi baseArgs params of
                    Left e -> respond (jsonError status400 e)
                    Right args0 ->
                        case resolveTenantKeyFromApiParamsWithHint tenantHint args0 params of
                            Left e -> respond (jsonError status400 e)
                            Right mReqTenant -> do
                                let args =
                                        args0
                                            { argTradeOnly = True
                                            , argBinanceTrade = False
                                            , argSweepThreshold = False
                                            , argOptimizeOperations = False
                                            }
                                case validateArgs args of
                                    Left e -> respond (jsonError status400 e)
                                    Right args1 -> do
                                        case validateApiComputeLimits limits args1 of
                                            Left e -> respond (jsonError status400 e)
                                            Right argsOk -> do
                                                let paramsJson = Just (toJSON (sanitizeApiParams params))
                                                    argsJson = Just (argsPublicJson argsOk)
                                                    noCache = requestWantsNoCache req
                                                r <-
                                                    startJob mOps store $ do
                                                        sig <-
                                                            if noCache
                                                                then computeLatestSignalFromArgsWithLimits limits mOps argsOk
                                                                else computeLatestSignalFromArgsCached apiCache limits mOps argsOk
                                                        opsAppendMaybe mOps mReqTenant "signal" paramsJson argsJson (Just (toJSON sig)) Nothing Nothing (T.pack <$> argBinanceSymbol argsOk) Nothing
                                                        outboxEnqueueMaybe
                                                            mOps
                                                            mReqTenant
                                                            "trader.v1.signals.generated"
                                                            (Just (ownerKeyFromArgs mReqTenant argsOk))
                                                            ( object
                                                                [ "ownerKey" .= ownerKeyFromArgs mReqTenant argsOk
                                                                , "signal" .= sig
                                                                ]
                                                            )
                                                        pure sig
                                                case r of
                                                    Left e -> respond (jsonError status429 e)
                                                    Right jobId -> do
                                                        outboxEnqueueMaybe
                                                            mOps
                                                            mReqTenant
                                                            "trader.v1.jobs.requested"
                                                            (Just jobId)
                                                            (object ["jobId" .= jobId, "jobType" .= ("signal" :: String), "status" .= ("running" :: String)])
                                                        respond (jsonValue status202 (object ["jobId" .= jobId]))

handleTrade :: ApiRequestLimits -> Maybe OpsStore -> ApiComputeLimits -> Metrics -> Maybe Journal -> Maybe Webhook -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleTrade reqLimits mOps limits metrics mJournal mWebhook baseArgs req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            let tenantHint = apTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
                originIp = requestOriginIp req
             in case argsFromApi baseArgs params of
                    Left e -> respond (jsonError status400 e)
                    Right args0 ->
                        case resolveTenantKeyFromApiParamsWithHint tenantHint args0 params of
                            Left e -> respond (jsonError status400 e)
                            Right mReqTenant -> do
                                let args1 =
                                        args0
                                            { argTradeOnly = True
                                            , argBinanceTrade = True
                                            , argSweepThreshold = False
                                            , argOptimizeOperations = False
                                            }
                                case validateArgs args1 of
                                    Left e -> respond (jsonError status400 e)
                                    Right args ->
                                        case validateApiComputeLimits limits args of
                                            Left e -> respond (jsonError status400 e)
                                            Right argsOk -> do
                                                mServerTenant <- serverTenantKeyForPlatform (argPlatform argsOk)
                                                let ownerMatch =
                                                        case (mReqTenant, mServerTenant) of
                                                            (Just reqTenant, Just serverTenant) -> reqTenant == serverTenant
                                                            _ -> False
                                                    useServerKeys =
                                                        case mServerTenant of
                                                            Nothing -> False
                                                            Just _ ->
                                                                case mReqTenant of
                                                                    Nothing -> True
                                                                    Just _ -> ownerMatch
                                                    mOpsTenant =
                                                        if useServerKeys
                                                            then mServerTenant
                                                            else mReqTenant
                                                    needsUserKeys =
                                                        shouldRequireUserTradeKeys
                                                            (argPlatform argsOk)
                                                            mReqTenant
                                                            useServerKeys
                                                            (argDryRun argsOk)
                                                    hasUserKeys =
                                                        case argPlatform argsOk of
                                                            PlatformBinance -> hasBinanceKeys argsOk
                                                            PlatformCoinbase -> hasCoinbaseKeys argsOk
                                                            _ -> True
                                                if needsUserKeys && not hasUserKeys
                                                    then
                                                        respond
                                                            ( jsonError
                                                                status400
                                                                ( case argPlatform argsOk of
                                                                    PlatformBinance -> "binanceApiKey and binanceApiSecret are required for non-owner trades."
                                                                    PlatformCoinbase -> "coinbaseApiKey, coinbaseApiSecret, and coinbaseApiPassphrase are required for non-owner trades."
                                                                    _ -> "API keys are required for this trade."
                                                                )
                                                            )
                                                    else do
                                                        let argsFinal =
                                                                if useServerKeys
                                                                    then sanitizeArgsKeys argsOk
                                                                    else argsOk
                                                            mIdemKey = normalizeMaybeText (T.pack . trim <$> argIdempotencyKey argsFinal)
                                                            idemReqHash = requestHashFromApiParams params
                                                        idemCheck <-
                                                            case (mOps, mIdemKey) of
                                                                (Just opsStore, Just idemKey) ->
                                                                    resolveTradeIdempotency opsStore mOpsTenant idemKey idemReqHash
                                                                _ -> pure TradeIdemAcquire
                                                        case idemCheck of
                                                            TradeIdemConflict msg -> respond (jsonError status409 msg)
                                                            TradeIdemBusy msg -> respond (jsonError status409 msg)
                                                            TradeIdemCached cachedValue -> respond (jsonValue status200 cachedValue)
                                                            TradeIdemAcquire -> do
                                                                r <- try (computeTradeFromArgsWithLimits limits mOps argsFinal) :: IO (Either SomeException ApiTradeResponse)
                                                                case r of
                                                                    Left ex -> do
                                                                        case (mOps, mIdemKey) of
                                                                            (Just opsStore, Just idemKey) ->
                                                                                completeTradeIdempotencyError opsStore mOpsTenant idemKey idemReqHash (snd (exceptionToHttp ex))
                                                                            _ -> pure ()
                                                                        let (st, msg) = exceptionToHttp ex
                                                                         in respond (jsonError st msg)
                                                                    Right out -> do
                                                                        case (mOps, mIdemKey) of
                                                                            (Just opsStore, Just idemKey) ->
                                                                                completeTradeIdempotencySuccess opsStore mOpsTenant idemKey idemReqHash (toJSON out)
                                                                            _ -> pure ()
                                                                        metricsRecordOrder metrics (atrOrder out)
                                                                        now <- getTimestampMs
                                                                        journalWriteMaybe
                                                                            mJournal
                                                                            ( object
                                                                                [ "type" .= ("trade.order" :: String)
                                                                                , "atMs" .= now
                                                                                , "symbol" .= argBinanceSymbol argsFinal
                                                                                , "market" .= marketCode (argBinanceMarket argsFinal)
                                                                                , "action" .= lsAction (atrSignal out)
                                                                                , "order" .= atrOrder out
                                                                                , "originIp" .= originIp
                                                                                ]
                                                                            )
                                                                        let outJson =
                                                                                case toJSON out of
                                                                                    Aeson.Object o ->
                                                                                        Aeson.Object
                                                                                            (KM.insert (AK.fromString "originIp") (toJSON originIp) o)
                                                                                    v -> v
                                                                        opsAppendMaybe
                                                                            mOps
                                                                            mOpsTenant
                                                                            "trade.order"
                                                                            (Just (toJSON (sanitizeApiParams params)))
                                                                            (Just (argsPublicJson argsFinal))
                                                                            (Just outJson)
                                                                            Nothing
                                                                            Nothing
                                                                            (T.pack <$> argBinanceSymbol argsFinal)
                                                                            (orderIdFromOrderResult (atrOrder out))
                                                                        outboxEnqueueMaybe
                                                                            mOps
                                                                            mOpsTenant
                                                                            "trader.v1.orders.submitted"
                                                                            (Just (ownerKeyFromArgs mOpsTenant argsFinal))
                                                                            ( object
                                                                                [ "ownerKey" .= ownerKeyFromArgs mOpsTenant argsFinal
                                                                                , "trade" .= out
                                                                                ]
                                                                            )
                                                                        webhookNotifyMaybe mWebhook (webhookEventTradeOrder argsFinal (atrSignal out) (atrOrder out))
                                                                        respond (jsonValue status200 out)

handleTradeAsync :: ApiRequestLimits -> Maybe OpsStore -> ApiComputeLimits -> JobStore ApiTradeResponse -> Metrics -> Maybe Journal -> Maybe Webhook -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleTradeAsync reqLimits mOps limits store metrics mJournal mWebhook baseArgs req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            let tenantHint = apTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
                originIp = requestOriginIp req
             in case argsFromApi baseArgs params of
                    Left e -> respond (jsonError status400 e)
                    Right args0 ->
                        case resolveTenantKeyFromApiParamsWithHint tenantHint args0 params of
                            Left e -> respond (jsonError status400 e)
                            Right mReqTenant -> do
                                let args1 =
                                        args0
                                            { argTradeOnly = True
                                            , argBinanceTrade = True
                                            , argSweepThreshold = False
                                            , argOptimizeOperations = False
                                            }
                                case validateArgs args1 of
                                    Left e -> respond (jsonError status400 e)
                                    Right args ->
                                        case validateApiComputeLimits limits args of
                                            Left e -> respond (jsonError status400 e)
                                            Right argsOk -> do
                                                mServerTenant <- serverTenantKeyForPlatform (argPlatform argsOk)
                                                let ownerMatch =
                                                        case (mReqTenant, mServerTenant) of
                                                            (Just reqTenant, Just serverTenant) -> reqTenant == serverTenant
                                                            _ -> False
                                                    useServerKeys =
                                                        case mServerTenant of
                                                            Nothing -> False
                                                            Just _ ->
                                                                case mReqTenant of
                                                                    Nothing -> True
                                                                    Just _ -> ownerMatch
                                                    mOpsTenant =
                                                        if useServerKeys
                                                            then mServerTenant
                                                            else mReqTenant
                                                    needsUserKeys =
                                                        shouldRequireUserTradeKeys
                                                            (argPlatform argsOk)
                                                            mReqTenant
                                                            useServerKeys
                                                            (argDryRun argsOk)
                                                    hasUserKeys =
                                                        case argPlatform argsOk of
                                                            PlatformBinance -> hasBinanceKeys argsOk
                                                            PlatformCoinbase -> hasCoinbaseKeys argsOk
                                                            _ -> True
                                                if needsUserKeys && not hasUserKeys
                                                    then
                                                        respond
                                                            ( jsonError
                                                                status400
                                                                ( case argPlatform argsOk of
                                                                    PlatformBinance -> "binanceApiKey and binanceApiSecret are required for non-owner trades."
                                                                    PlatformCoinbase -> "coinbaseApiKey, coinbaseApiSecret, and coinbaseApiPassphrase are required for non-owner trades."
                                                                    _ -> "API keys are required for this trade."
                                                                )
                                                            )
                                                    else do
                                                        let argsFinal =
                                                                if useServerKeys
                                                                    then sanitizeArgsKeys argsOk
                                                                    else argsOk
                                                            paramsJson = Just (toJSON (sanitizeApiParams params))
                                                            argsJson = Just (argsPublicJson argsFinal)
                                                            mIdemKey = normalizeMaybeText (T.pack . trim <$> argIdempotencyKey argsFinal)
                                                            idemReqHash = requestHashFromApiParams params
                                                        idemCheck <-
                                                            case (mOps, mIdemKey) of
                                                                (Just opsStore, Just idemKey) ->
                                                                    resolveTradeIdempotency opsStore mOpsTenant idemKey idemReqHash
                                                                _ -> pure TradeIdemAcquire
                                                        case idemCheck of
                                                            TradeIdemConflict msg -> respond (jsonError status409 msg)
                                                            TradeIdemBusy msg -> respond (jsonError status409 msg)
                                                            TradeIdemCached cachedValue -> do
                                                                outboxEnqueueMaybe
                                                                    mOps
                                                                    mOpsTenant
                                                                    "trader.v1.jobs.requested"
                                                                    Nothing
                                                                    (object ["jobType" .= ("trade" :: String), "status" .= ("cached" :: String)])
                                                                respond (jsonValue status200 (object ["status" .= ("done" :: String), "result" .= cachedValue]))
                                                            TradeIdemAcquire -> do
                                                                r <-
                                                                    startJob mOps store $ do
                                                                        outResult <- try (computeTradeFromArgsWithLimits limits mOps argsFinal) :: IO (Either SomeException ApiTradeResponse)
                                                                        out <-
                                                                            case outResult of
                                                                                Left ex -> do
                                                                                    case (mOps, mIdemKey) of
                                                                                        (Just opsStore, Just idemKey) ->
                                                                                            completeTradeIdempotencyError opsStore mOpsTenant idemKey idemReqHash (snd (exceptionToHttp ex))
                                                                                        _ -> pure ()
                                                                                    throwIO ex
                                                                                Right out' -> do
                                                                                    case (mOps, mIdemKey) of
                                                                                        (Just opsStore, Just idemKey) ->
                                                                                            completeTradeIdempotencySuccess opsStore mOpsTenant idemKey idemReqHash (toJSON out')
                                                                                        _ -> pure ()
                                                                                    pure out'
                                                                        metricsRecordOrder metrics (atrOrder out)
                                                                        now <- getTimestampMs
                                                                        journalWriteMaybe
                                                                            mJournal
                                                                            ( object
                                                                                [ "type" .= ("trade.order" :: String)
                                                                                , "atMs" .= now
                                                                                , "symbol" .= argBinanceSymbol argsFinal
                                                                                , "market" .= marketCode (argBinanceMarket argsFinal)
                                                                                , "action" .= lsAction (atrSignal out)
                                                                                , "order" .= atrOrder out
                                                                                , "originIp" .= originIp
                                                                                ]
                                                                            )
                                                                        let outJson =
                                                                                case toJSON out of
                                                                                    Aeson.Object o ->
                                                                                        Aeson.Object
                                                                                            (KM.insert (AK.fromString "originIp") (toJSON originIp) o)
                                                                                    v -> v
                                                                        opsAppendMaybe
                                                                            mOps
                                                                            mOpsTenant
                                                                            "trade.order"
                                                                            paramsJson
                                                                            argsJson
                                                                            (Just outJson)
                                                                            Nothing
                                                                            Nothing
                                                                            (T.pack <$> argBinanceSymbol argsFinal)
                                                                            (orderIdFromOrderResult (atrOrder out))
                                                                        outboxEnqueueMaybe
                                                                            mOps
                                                                            mOpsTenant
                                                                            "trader.v1.orders.submitted"
                                                                            (Just (ownerKeyFromArgs mOpsTenant argsFinal))
                                                                            ( object
                                                                                [ "ownerKey" .= ownerKeyFromArgs mOpsTenant argsFinal
                                                                                , "trade" .= out
                                                                                ]
                                                                            )
                                                                        webhookNotifyMaybe mWebhook (webhookEventTradeOrder argsFinal (atrSignal out) (atrOrder out))
                                                                        pure out
                                                                case r of
                                                                    Left e -> do
                                                                        case (mOps, mIdemKey) of
                                                                            (Just opsStore, Just idemKey) ->
                                                                                completeTradeIdempotencyError opsStore mOpsTenant idemKey idemReqHash e
                                                                            _ -> pure ()
                                                                        respond (jsonError status429 e)
                                                                    Right jobId -> do
                                                                        outboxEnqueueMaybe
                                                                            mOps
                                                                            mReqTenant
                                                                            "trader.v1.jobs.requested"
                                                                            (Just jobId)
                                                                            (object ["jobId" .= jobId, "jobType" .= ("trade" :: String), "status" .= ("running" :: String)])
                                                                        respond (jsonValue status202 (object ["jobId" .= jobId]))

extractBacktestFinalEquity :: Aeson.Value -> Maybe Double
extractBacktestFinalEquity =
    AT.parseMaybe $
        Aeson.withObject "Backtest" $ \o -> do
            m <- o AT..: "metrics"
            m AT..: "finalEquity"

handleBacktest :: ApiRequestLimits -> ApiCache -> Maybe OpsStore -> ApiComputeLimits -> BacktestGate -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBacktest reqLimits apiCache mOps limits backtestGate baseArgs req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            let tenantHint = apTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
             in case argsFromApi baseArgs params of
                    Left e -> respond (jsonError status400 e)
                    Right args0 ->
                        case resolveTenantKeyFromApiParamsWithHint tenantHint args0 params of
                            Left e -> respond (jsonError status400 e)
                            Right mReqTenant -> do
                                let args =
                                        args0
                                            { argTradeOnly = False
                                            , argBinanceTrade = False
                                            , argOptimizeOperations = fromMaybe (argOptimizeOperations args0) (apOptimizeOperations params)
                                            , argSweepThreshold = fromMaybe (argSweepThreshold args0) (apSweepThreshold params)
                                            , argBacktestRatio = fromMaybe (argBacktestRatio args0) (apBacktestRatio params)
                                            }
                                case validateApiComputeLimits limits args of
                                    Left e -> respond (jsonError status400 e)
                                    Right argsOk -> do
                                        let noCache = requestWantsNoCache req
                                            computeAction =
                                                if noCache
                                                    then computeBacktestFromArgsWithLimits limits mOps argsOk
                                                    else computeBacktestFromArgsCached apiCache limits mOps argsOk
                                        r <- runBacktestWithGateWait backtestGate computeAction
                                        case r of
                                            Left failure ->
                                                let (st, msg) = backtestFailureToHttp backtestGate failure
                                                 in respond (jsonError st msg)
                                            Right out -> do
                                                opsAppendMaybe
                                                    mOps
                                                    mReqTenant
                                                    "backtest"
                                                    (Just (toJSON (sanitizeApiParams params)))
                                                    (Just (argsPublicJson argsOk))
                                                    (Just out)
                                                    (extractBacktestFinalEquity out)
                                                    Nothing
                                                    (T.pack <$> argBinanceSymbol argsOk)
                                                    Nothing
                                                outboxEnqueueMaybe
                                                    mOps
                                                    mReqTenant
                                                    "trader.v1.backtests.completed"
                                                    (Just (ownerKeyFromArgs mReqTenant argsOk))
                                                    (object ["ownerKey" .= ownerKeyFromArgs mReqTenant argsOk, "result" .= out])
                                                respond (jsonValue status200 out)

handleBacktestAsync :: ApiRequestLimits -> ApiCache -> Maybe OpsStore -> ApiComputeLimits -> BacktestGate -> JobStore Aeson.Value -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBacktestAsync reqLimits apiCache mOps limits backtestGate store baseArgs req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            let tenantHint = apTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
             in case argsFromApi baseArgs params of
                    Left e -> respond (jsonError status400 e)
                    Right args0 ->
                        case resolveTenantKeyFromApiParamsWithHint tenantHint args0 params of
                            Left e -> respond (jsonError status400 e)
                            Right mReqTenant -> do
                                let args =
                                        args0
                                            { argTradeOnly = False
                                            , argBinanceTrade = False
                                            , argOptimizeOperations = fromMaybe (argOptimizeOperations args0) (apOptimizeOperations params)
                                            , argSweepThreshold = fromMaybe (argSweepThreshold args0) (apSweepThreshold params)
                                            , argBacktestRatio = fromMaybe (argBacktestRatio args0) (apBacktestRatio params)
                                            }
                                case validateApiComputeLimits limits args of
                                    Left e -> respond (jsonError status400 e)
                                    Right argsOk -> do
                                        let paramsJson = Just (toJSON (sanitizeApiParams params))
                                            argsJson = Just (argsPublicJson argsOk)
                                            noCache = requestWantsNoCache req
                                        r <-
                                            startJob mOps store $ do
                                                let computeAction =
                                                        if noCache
                                                            then computeBacktestFromArgsWithLimits limits mOps argsOk
                                                            else computeBacktestFromArgsCached apiCache limits mOps argsOk
                                                gateResult <- runBacktestWithGateWait backtestGate computeAction
                                                case gateResult of
                                                    Left failure -> throwIO (userError (backtestFailureMessage backtestGate failure))
                                                    Right out -> do
                                                        opsAppendMaybe
                                                            mOps
                                                            mReqTenant
                                                            "backtest"
                                                            paramsJson
                                                            argsJson
                                                            (Just out)
                                                            (extractBacktestFinalEquity out)
                                                            Nothing
                                                            (T.pack <$> argBinanceSymbol argsOk)
                                                            Nothing
                                                        outboxEnqueueMaybe
                                                            mOps
                                                            mReqTenant
                                                            "trader.v1.backtests.completed"
                                                            (Just (ownerKeyFromArgs mReqTenant argsOk))
                                                            (object ["ownerKey" .= ownerKeyFromArgs mReqTenant argsOk, "result" .= out])
                                                        pure out
                                        case r of
                                            Left e -> respond (jsonError status429 e)
                                            Right jobId -> do
                                                outboxEnqueueMaybe
                                                    mOps
                                                    mReqTenant
                                                    "trader.v1.jobs.requested"
                                                    (Just jobId)
                                                    (object ["jobId" .= jobId, "jobType" .= ("backtest" :: String), "status" .= ("running" :: String)])
                                                respond (jsonValue status202 (object ["jobId" .= jobId]))

handleAsyncPoll :: (ToJSON a) => Maybe OpsStore -> JobStore a -> Text -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleAsyncPoll mOps store jobId respond = do
    now <- getTimestampMs
    pruneJobStore store now
    mEntry <- withMVar (jsJobs store) (pure . HM.lookup jobId)
    case mEntry of
        Nothing -> do
            mDisk <- readJobFile store jobId
            case mDisk of
                Just v -> respond (jsonValue status200 v)
                Nothing -> do
                    mDb <-
                        case mOps of
                            Nothing -> pure Nothing
                            Just opsStore -> readAsyncJobDb opsStore jobId
                    case mDb of
                        Just v -> respond (jsonValue status200 v)
                        Nothing -> respond (jsonValue status200 (object ["status" .= ("error" :: String), "error" .= ("Not found" :: String)]))
        Just entry -> do
            r <- tryReadMVar (jeResult entry)
            case r of
                Nothing ->
                    respond
                        ( jsonValue
                            status200
                            (object ["status" .= ("running" :: String), "createdAtMs" .= jeCreatedAtMs entry])
                        )
                Just (Left err) ->
                    respond
                        ( jsonValue
                            status200
                            (object ["status" .= ("error" :: String), "createdAtMs" .= jeCreatedAtMs entry, "error" .= err])
                        )
                Just (Right v) ->
                    respond
                        ( jsonValue
                            status200
                            (object ["status" .= ("done" :: String), "createdAtMs" .= jeCreatedAtMs entry, "result" .= v])
                        )

handleAsyncCancel :: (ToJSON a) => Maybe OpsStore -> JobStore a -> Text -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleAsyncCancel mOps store jobId respond = do
    now <- getTimestampMs
    pruneJobStore store now
    mEntry <- withMVar (jsJobs store) (pure . HM.lookup jobId)
    case mEntry of
        Nothing -> respond (jsonValue status200 (object ["status" .= ("error" :: String), "error" .= ("Not found" :: String)]))
        Just entry -> do
            r <- tryReadMVar (jeResult entry)
            case r of
                Just (Right _) ->
                    respond
                        ( jsonValue
                            status200
                            (object ["status" .= ("done" :: String), "createdAtMs" .= jeCreatedAtMs entry])
                        )
                Just (Left err) ->
                    respond
                        ( jsonValue
                            status200
                            (object ["status" .= ("error" :: String), "createdAtMs" .= jeCreatedAtMs entry, "error" .= err])
                        )
                Nothing -> do
                    canceledAt <- getTimestampMs
                    let msg = "Canceled" :: String
                    persistAsyncJobState
                        mOps
                        store
                        jobId
                        (object ["status" .= ("error" :: String), "createdAtMs" .= jeCreatedAtMs entry, "completedAtMs" .= canceledAt, "error" .= msg])
                    _ <- tryPutMVar (jeResult entry) (Left msg)
                    killThread (jeThreadId entry)
                    respond
                        ( jsonValue
                            status200
                            (object ["status" .= ("canceled" :: String), "createdAtMs" .= jeCreatedAtMs entry, "canceledAtMs" .= canceledAt])
                        )

handleRequestProgress :: RequestProgressStore -> Text -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleRequestProgress store rawRequestId respond =
    case normalizeRequestProgressId (T.unpack rawRequestId) of
        Nothing -> respond (jsonError status400 "requestId is required")
        Just requestId -> do
            mProgress <- lookupRequestProgress store requestId
            case mProgress of
                Nothing -> respond (jsonError status404 "Request progress not found")
                Just progress -> respond (jsonValue status200 progress)

handleBinanceKeys :: RequestProgressStore -> ApiRequestLimits -> Maybe OpsStore -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinanceKeys requestProgressStore reqLimits mOps baseArgs req respond = do
    let mTracker = requestProgressTracker requestProgressStore req
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            case argsFromApi baseArgs params of
                Left e -> respond (jsonError status400 e)
                Right args0 ->
                    case resolveTenantKeyFromApiParams args0 params of
                        Left e -> respond (jsonError status400 e)
                        Right _ ->
                            if argPlatform args0 /= PlatformBinance
                                then respond (jsonError status400 ("Binance keys require platform=binance (got " ++ platformCode (argPlatform args0) ++ ")."))
                                else do
                                    startRequestProgressMaybe mTracker "binance/keys" "egress IP" Nothing
                                    r <- try (computeBinanceKeysStatusFromArgs mOps mTracker args0) :: IO (Either SomeException ApiBinanceKeysStatus)
                                    case r of
                                        Left ex ->
                                            let (st, msg) = exceptionToHttp ex
                                             in do
                                                    failRequestProgressMaybe mTracker msg
                                                    respond (jsonError st msg)
                                        Right out -> do
                                            completeRequestProgressMaybe mTracker (Just "response ready")
                                            respond (jsonValue status200 out)

handleBinanceProxyHealth :: (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinanceProxyHealth respond = do
    health <- binanceProxyHealth
    respond (jsonValue status200 health)

handleCoinbaseKeys :: ApiRequestLimits -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleCoinbaseKeys reqLimits baseArgs req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            case argsFromApi baseArgs params of
                Left e -> respond (jsonError status400 e)
                Right args0 ->
                    case resolveTenantKeyFromApiParams args0 params of
                        Left e -> respond (jsonError status400 e)
                        Right _ ->
                            if argPlatform args0 /= PlatformCoinbase
                                then respond (jsonError status400 ("Coinbase keys require platform=coinbase (got " ++ platformCode (argPlatform args0) ++ ")."))
                                else do
                                    r <- try (computeCoinbaseKeysStatusFromArgs args0) :: IO (Either SomeException ApiCoinbaseKeysStatus)
                                    case r of
                                        Left ex ->
                                            let (st, msg) = exceptionToHttp ex
                                             in respond (jsonError st msg)
                                        Right out -> respond (jsonValue status200 out)

parseMarketForListenKey :: Args -> Maybe String -> Either String BinanceMarket
parseMarketForListenKey baseArgs raw =
    case raw of
        Nothing -> Right (argBinanceMarket baseArgs)
        Just r ->
            case normalizeKey r of
                "spot" -> Right MarketSpot
                "margin" -> Right MarketMargin
                "futures" -> Right MarketFutures
                other -> Left ("Invalid market: " ++ show other ++ " (expected spot|margin|futures)")

resolveTestnetForListenKey :: Args -> Maybe Bool -> Bool
resolveTestnetForListenKey baseArgs = fromMaybe (argBinanceTestnet baseArgs)

binanceUserStreamWsBase :: BinanceMarket -> Bool -> String
binanceUserStreamWsBase market testnet =
    case market of
        MarketFutures ->
            if testnet
                then "wss://stream.binancefuture.com/ws"
                else "wss://fstream.binance.com/ws"
        _ ->
            if testnet
                then "wss://testnet.binance.vision/ws"
                else "wss://stream.binance.com:9443/ws"

binanceUserStreamWsUrl :: BinanceMarket -> Bool -> String -> String
binanceUserStreamWsUrl market testnet listenKey =
    binanceUserStreamWsBase market testnet ++ "/" ++ listenKey

data ListenKeyStreamEvent
    = ListenKeyStreamStatus !BS.ByteString
    | ListenKeyStreamKeepAlive !Int64
    | ListenKeyStreamBinance !BS.ByteString
    | ListenKeyStreamError !BS.ByteString
    | ListenKeyStreamStop

data ListenKeyStreamState = ListenKeyStreamState
    { lksEnv :: !BinanceEnv
    , lksTenantKey :: !TenantKey
    , lksMarket :: !BinanceMarket
    , lksTestnet :: !Bool
    , lksListenKey :: !String
    , lksWsUrl :: !String
    , lksKeepAliveMs :: !Int
    , lksChan :: !(Chan ListenKeyStreamEvent)
    , lksStopSignal :: !(MVar ())
    , lksStatusRef :: !(IORef (Maybe BS.ByteString))
    , lksKeepAliveAtRef :: !(IORef (Maybe Int64))
    , lksLastEventRef :: !(IORef (Maybe BS.ByteString))
    }

data ListenKeyStream = ListenKeyStream
    { lksState :: !ListenKeyStreamState
    , lksWsThread :: !ThreadId
    , lksKeepAliveThread :: !ThreadId
    }

newtype ListenKeyManager = ListenKeyManager {lkmState :: MVar (HM.HashMap TenantKey ListenKeyStream)}

newListenKeyManager :: IO ListenKeyManager
newListenKeyManager = ListenKeyManager <$> newMVar HM.empty

listenKeyStreamHeaders :: ResponseHeaders
listenKeyStreamHeaders =
    [ ("Content-Type", "text/event-stream")
    , ("Cache-Control", "no-cache")
    , ("Connection", "keep-alive")
    , ("X-Accel-Buffering", "no")
    , ("Vary", "Authorization, X-API-Key")
    ]

listenKeyKeepAliveIntervalMs :: Int -> Int
listenKeyKeepAliveIntervalMs keepAliveMs =
    max 60000 (floor (fromIntegral keepAliveMs * (0.9 :: Double)))

listenKeyWsPingIntervalSec :: Int
listenKeyWsPingIntervalSec = 180

listenKeyWsReconnectDelayMs :: Int
listenKeyWsReconnectDelayMs = 5000

listenKeyStreamHeartbeatMs :: Int
listenKeyStreamHeartbeatMs = 15000

maxListenKeyEventBytes :: Int
maxListenKeyEventBytes = 20000

formatTenantKeyShort :: TenantKey -> String
formatTenantKeyShort key =
    let raw = T.unpack key
        len = length raw
     in if len <= 12
            then raw
            else take 6 raw ++ "..." ++ drop (len - 4) raw

listenKeyLogPrefix :: ListenKeyStreamState -> String
listenKeyLogPrefix st =
    "ListenKey[tenant="
        ++ formatTenantKeyShort (lksTenantKey st)
        ++ ", market="
        ++ show (lksMarket st)
        ++ ", testnet="
        ++ show (lksTestnet st)
        ++ "]"

logListenKey :: ListenKeyStreamState -> String -> IO ()
logListenKey st msg = putStrLn (listenKeyLogPrefix st ++ " " ++ msg)

mkSseEvent :: BS.ByteString -> BS.ByteString -> BS.ByteString
mkSseEvent eventName payload =
    let payloadLines =
            if BS.null payload
                then [""]
                else BS.split '\n' payload
        dataLines = map ("data: " <>) payloadLines
     in BS.intercalate "\n" (("event: " <> eventName) : dataLines) <> "\n\n"

listenKeyStatusPayload :: String -> Maybe String -> Int64 -> BS.ByteString
listenKeyStatusPayload status message atMs =
    BL.toStrict $
        encode $
            object
                ( ["status" .= status, "atMs" .= atMs]
                    ++ maybe [] (\msg -> ["message" .= msg]) message
                )

listenKeyErrorPayload :: String -> Int64 -> BS.ByteString
listenKeyErrorPayload message atMs =
    BL.toStrict $
        encode $
            object
                [ "message" .= message
                , "atMs" .= atMs
                ]

listenKeyKeepAlivePayload :: Int64 -> BS.ByteString
listenKeyKeepAlivePayload atMs =
    BL.toStrict $
        encode $
            object
                [ "atMs" .= atMs
                ]

listenKeyEventToSse :: ListenKeyStreamEvent -> Maybe BS.ByteString
listenKeyEventToSse evt =
    case evt of
        ListenKeyStreamStatus payload -> Just (mkSseEvent "status" payload)
        ListenKeyStreamKeepAlive atMs -> Just (mkSseEvent "keepalive" (listenKeyKeepAlivePayload atMs))
        ListenKeyStreamBinance payload -> Just (mkSseEvent "binance" payload)
        ListenKeyStreamError payload -> Just (mkSseEvent "error" payload)
        ListenKeyStreamStop -> Nothing

emitListenKeyStatus :: ListenKeyStreamState -> String -> Maybe String -> IO ()
emitListenKeyStatus st status message = do
    now <- getTimestampMs
    let payload = listenKeyStatusPayload status message now
    logListenKey st ("status=" ++ status ++ maybe "" (" msg=" ++) message)
    writeIORef (lksStatusRef st) (Just payload)
    writeChan (lksChan st) (ListenKeyStreamStatus payload)

emitListenKeyKeepAlive :: ListenKeyStreamState -> Int64 -> IO ()
emitListenKeyKeepAlive st atMs = do
    writeIORef (lksKeepAliveAtRef st) (Just atMs)
    writeChan (lksChan st) (ListenKeyStreamKeepAlive atMs)

emitListenKeyBinance :: ListenKeyStreamState -> BS.ByteString -> IO ()
emitListenKeyBinance st payload = do
    let trimmed =
            if BS.length payload > maxListenKeyEventBytes
                then BS.take maxListenKeyEventBytes payload
                else payload
    writeIORef (lksLastEventRef st) (Just trimmed)
    writeChan (lksChan st) (ListenKeyStreamBinance trimmed)

emitListenKeyError :: ListenKeyStreamState -> String -> IO ()
emitListenKeyError st message = do
    now <- getTimestampMs
    let payload = listenKeyErrorPayload message now
    logListenKey st ("error=" ++ message)
    writeChan (lksChan st) (ListenKeyStreamError payload)

isListenKeyMissingError :: String -> Bool
isListenKeyMissingError msg =
    let msgLower = map toLower msg
     in "-1125" `isInfixOf` msgLower || "listenkey does not exist" `isInfixOf` msgLower

isListenKeyRetryableError :: String -> Bool
isListenKeyRetryableError msg =
    let msgLower = map toLower msg
        markers =
            [ "timeout"
            , "timed out"
            , "connection reset"
            , "connection closed"
            , "connection refused"
            , "econnreset"
            , "econnrefused"
            , "temporary"
            , "temporarily"
            , "network"
            ]
     in any (`isInfixOf` msgLower) markers

retryListenKey :: String -> IO a -> IO (Either SomeException a)
retryListenKey label action = go 0 500000
  where
    maxRetries = 3 :: Int
    go n delayUs = do
        result <- try action
        case result of
            Right v -> pure (Right v)
            Left ex ->
                let msg = displayException ex
                 in if n < maxRetries && isListenKeyRetryableError msg
                        then do
                            putStrLn (printf "ListenKey %s failed (attempt %d/%d): %s; retrying..." label (n + 1) maxRetries msg)
                            threadDelay delayUs
                            go (n + 1) (min (delayUs * 2) 5000000)
                        else pure (Left ex)

listenKeyStreamStopped :: ListenKeyStreamState -> IO Bool
listenKeyStreamStopped st = isJust <$> tryReadMVar (lksStopSignal st)

stopListenKeyStreamInternal :: ListenKeyStream -> IO ()
stopListenKeyStreamInternal stream = do
    let st = lksState stream
    _ <- tryPutMVar (lksStopSignal st) ()
    emitListenKeyStatus st "stopped" Nothing
    writeChan (lksChan st) ListenKeyStreamStop
    killThread (lksWsThread stream)
    killThread (lksKeepAliveThread stream)
    _ <- try (closeListenKey (lksEnv st) (lksListenKey st)) :: IO (Either SomeException ())
    pure ()

stopListenKeyStream :: ListenKeyManager -> TenantKey -> IO ()
stopListenKeyStream manager tenantKey =
    modifyMVar_ (lkmState manager) $ \streams -> do
        case HM.lookup tenantKey streams of
            Nothing -> pure streams
            Just stream -> do
                stopListenKeyStreamInternal stream
                pure (HM.delete tenantKey streams)

stopListenKeyStreamMatching :: ListenKeyManager -> TenantKey -> String -> IO Bool
stopListenKeyStreamMatching manager tenantKey listenKey =
    modifyMVar (lkmState manager) $ \streams ->
        case HM.lookup tenantKey streams of
            Just stream | lksListenKey (lksState stream) == listenKey -> do
                stopListenKeyStreamInternal stream
                pure (HM.delete tenantKey streams, True)
            _ -> pure (streams, False)

startListenKeyStream :: ListenKeyManager -> TenantKey -> BinanceEnv -> BinanceMarket -> Bool -> String -> Int -> IO ListenKeyStream
startListenKeyStream manager tenantKey env market testnet listenKey keepAliveMs =
    modifyMVar (lkmState manager) $ \streams -> do
        Data.Foldable.for_
            (HM.lookup tenantKey streams)
            stopListenKeyStreamInternal
        chan <- newChan
        stopSignal <- newEmptyMVar
        statusRef <- newIORef Nothing
        keepAliveRef <- newIORef Nothing
        lastEventRef <- newIORef Nothing
        let wsUrl = binanceUserStreamWsUrl market testnet listenKey
            state =
                ListenKeyStreamState
                    { lksEnv = env
                    , lksTenantKey = tenantKey
                    , lksMarket = market
                    , lksTestnet = testnet
                    , lksListenKey = listenKey
                    , lksWsUrl = wsUrl
                    , lksKeepAliveMs = keepAliveMs
                    , lksChan = chan
                    , lksStopSignal = stopSignal
                    , lksStatusRef = statusRef
                    , lksKeepAliveAtRef = keepAliveRef
                    , lksLastEventRef = lastEventRef
                    }
        emitListenKeyStatus state "connecting" Nothing
        wsThread <- forkIO (listenKeyWsWorker state)
        keepAliveThread <- forkIO (listenKeyKeepAliveWorker manager tenantKey state)
        let stream =
                ListenKeyStream
                    { lksState = state
                    , lksWsThread = wsThread
                    , lksKeepAliveThread = keepAliveThread
                    }
        pure (HM.insert tenantKey stream streams, stream)

parseListenKeyWsUrl :: String -> Either String (Bool, String, Int, String)
parseListenKeyWsUrl raw = do
    (secure, rest, defaultPort) <-
        case stripPrefix "wss://" raw of
            Just r -> Right (True, r, 443)
            Nothing ->
                case stripPrefix "ws://" raw of
                    Just r -> Right (False, r, 80)
                    Nothing -> Left ("Invalid WebSocket URL: " ++ raw)
    let (hostPort, pathRaw) = break (== '/') rest
    if null hostPort
        then Left ("Invalid WebSocket URL: " ++ raw)
        else do
            (host, port) <-
                case break (== ':') hostPort of
                    (h, ':' : p) ->
                        case readMaybe p of
                            Just n -> Right (h, n)
                            Nothing -> Left ("Invalid WebSocket port: " ++ p)
                    (h, _) -> Right (h, defaultPort)
            let path = if null pathRaw then "/" else pathRaw
            Right (secure, host, port, path)

listenKeyWsWorker :: ListenKeyStreamState -> IO ()
listenKeyWsWorker st =
    case parseListenKeyWsUrl (lksWsUrl st) of
        Left err -> do
            emitListenKeyStatus st "disconnected" (Just err)
            emitListenKeyError st err
        Right (secure, host, port, path) -> do
            let portNumber = fromIntegral port
                runner =
                    if secure
                        then Wuss.runSecureClient host portNumber path
                        else WS.runClient host port path
                connectOnce =
                    runner $ \conn -> do
                        emitListenKeyStatus st "connected" Nothing
                        WS.withPingThread conn listenKeyWsPingIntervalSec (pure ()) $
                            forever $ do
                                msg <- WS.receiveData conn
                                emitListenKeyBinance st msg
                handleDisconnect mErr = do
                    stopped <- listenKeyStreamStopped st
                    unless stopped $ do
                        case mErr of
                            Just ex -> do
                                emitListenKeyStatus st "disconnected" (Just "WebSocket closed")
                                emitListenKeyError st (displayException ex)
                            Nothing -> emitListenKeyStatus st "disconnected" Nothing
                        threadDelay (listenKeyWsReconnectDelayMs * 1000)
                        stopped' <- listenKeyStreamStopped st
                        unless stopped' $ do
                            emitListenKeyStatus st "connecting" Nothing
                            loop
                loop = do
                    result <- try connectOnce :: IO (Either SomeException ())
                    case result of
                        Left ex -> handleDisconnect (Just ex)
                        Right _ -> handleDisconnect Nothing
            loop

listenKeyKeepAliveWorker :: ListenKeyManager -> TenantKey -> ListenKeyStreamState -> IO ()
listenKeyKeepAliveWorker manager tenantKey st = do
    let intervalMs = listenKeyKeepAliveIntervalMs (lksKeepAliveMs st)
        intervalUs = intervalMs * 1000
        loop = do
            stopped <- listenKeyStreamStopped st
            unless stopped $ do
                result <- retryListenKey "keepAlive" (keepAliveListenKey (lksEnv st) (lksListenKey st))
                case result of
                    Left ex -> do
                        stopped' <- listenKeyStreamStopped st
                        unless stopped' $ do
                            let msg = displayException ex
                            if isListenKeyMissingError msg
                                then do
                                    emitListenKeyStatus st "expired" (Just "listenKey expired; restart stream.")
                                    _ <- stopListenKeyStreamMatching manager tenantKey (lksListenKey st)
                                    pure ()
                                else emitListenKeyError st ("Keep-alive failed: " ++ msg)
                    Right _ -> do
                        now <- getTimestampMs
                        emitListenKeyKeepAlive st now
                threadDelay intervalUs
                loop
    loop

handleBinanceListenKeyStream :: ListenKeyManager -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinanceListenKeyStream manager req respond =
    case requireTenantKey "binance/listenKey/stream" (tenantKeyFromRequest req) of
        Left e -> respond (jsonError status400 e)
        Right tenantKey -> do
            streams <- readMVar (lkmState manager)
            case HM.lookup tenantKey streams of
                Nothing -> respond (jsonError status404 "Listen key stream not running.")
                Just stream -> do
                    let st = lksState stream
                    logListenKey st "SSE client connected"
                    respond $
                        Wai.responseStream status200 listenKeyStreamHeaders $ \write flush -> do
                            chan <- dupChan (lksChan st)
                            let handleSendError :: IOException -> IO Bool
                                handleSendError ex = do
                                    logListenKey st ("SSE send failed: " ++ displayException ex)
                                    pure False
                                send payload =
                                    (write (byteString payload) >> flush >> pure True)
                                        `catch` handleSendError
                                sendMaybeEvent eventName payload =
                                    case payload of
                                        Nothing -> pure True
                                        Just raw -> send (mkSseEvent eventName raw)
                            statusPayload <- readIORef (lksStatusRef st)
                            okStatus <- sendMaybeEvent "status" statusPayload
                            when okStatus $ do
                                keepAliveAt <- readIORef (lksKeepAliveAtRef st)
                                let keepAlivePayload = fmap listenKeyKeepAlivePayload keepAliveAt
                                okKeepAlive <- sendMaybeEvent "keepalive" keepAlivePayload
                                when okKeepAlive $ do
                                    lastEvent <- readIORef (lksLastEventRef st)
                                    okLast <- sendMaybeEvent "binance" lastEvent
                                    when okLast $ do
                                        let heartbeatUs = listenKeyStreamHeartbeatMs * 1000
                                            heartbeatPayload = ":\n\n"
                                            loop = do
                                                evtOrTimeout <- timeout heartbeatUs (readChan chan)
                                                case evtOrTimeout of
                                                    Nothing -> do
                                                        ok <- send heartbeatPayload
                                                        when ok loop
                                                    Just evt ->
                                                        case listenKeyEventToSse evt of
                                                            Nothing -> logListenKey st "SSE stream stopped"
                                                            Just payload -> do
                                                                ok <- send payload
                                                                when ok loop
                                        loop

handleBinanceListenKey :: ApiRequestLimits -> Maybe OpsStore -> ListenKeyManager -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinanceListenKey reqLimits mOps listenKeyManager baseArgs req respond = do
    if argPlatform baseArgs /= PlatformBinance
        then respond (jsonError status400 ("Binance listenKey requires platform=binance (got " ++ platformCode (argPlatform baseArgs) ++ ")."))
        else do
            payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
            case payloadOrErr of
                Left resp -> respond resp
                Right params -> do
                    let tenantHint = alsTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
                    case resolveTenantKeyFromParams tenantHint (alsBinanceApiKey params) (alsBinanceApiSecret params) Nothing Nothing Nothing of
                        Left e -> respond (jsonError status400 e)
                        Right mTenant ->
                            case requireTenantKey "binance/listenKey" mTenant of
                                Left e -> respond (jsonError status400 e)
                                Right tenantKey -> do
                                    let testnet = resolveTestnetForListenKey baseArgs (alsBinanceTestnet params)
                                    case parseMarketForListenKey baseArgs (alsMarket params) of
                                        Left e -> respond (jsonError status400 e)
                                        Right market -> do
                                            if market == MarketMargin && testnet
                                                then respond (jsonError status400 "binanceTestnet is not supported for margin operations")
                                                else do
                                                    apiKey <- resolveEnv "BINANCE_API_KEY" (alsBinanceApiKey params <|> argBinanceApiKey baseArgs)
                                                    apiSecret <- resolveEnv "BINANCE_API_SECRET" (alsBinanceApiSecret params <|> argBinanceApiSecret baseArgs)
                                                    urls <- resolveBinanceBaseUrls
                                                    let baseUrl = selectBinanceBaseUrl urls testnet market
                                                    env <- newBinanceEnvWithOps mOps market baseUrl (BS.pack <$> apiKey) (BS.pack <$> apiSecret)
                                                    r <- retryListenKey "create" (createListenKey env)
                                                    case r of
                                                        Left ex ->
                                                            let (st, msg) = exceptionToHttp ex
                                                             in respond (jsonError st msg)
                                                        Right lk -> do
                                                            let keepAliveMs = 25 * 60 * 1000
                                                            _ <- startListenKeyStream listenKeyManager tenantKey env market testnet lk keepAliveMs
                                                            let resp =
                                                                    ApiListenKeyResponse
                                                                        { alrListenKey = lk
                                                                        , alrMarket = marketCode market
                                                                        , alrTestnet = testnet
                                                                        , alrWsUrl = binanceUserStreamWsUrl market testnet lk
                                                                        , alrKeepAliveMs = keepAliveMs
                                                                        }
                                                            respond (jsonValue status200 resp)

handleBinanceListenKeyKeepAlive :: ApiRequestLimits -> Maybe OpsStore -> ListenKeyManager -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinanceListenKeyKeepAlive reqLimits mOps listenKeyManager baseArgs req respond = do
    if argPlatform baseArgs /= PlatformBinance
        then respond (jsonError status400 ("Binance listenKey keepAlive requires platform=binance (got " ++ platformCode (argPlatform baseArgs) ++ ")."))
        else do
            payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
            case payloadOrErr of
                Left resp -> respond resp
                Right params -> do
                    let tenantHint = alaTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
                    case resolveTenantKeyFromParams tenantHint (alaBinanceApiKey params) (alaBinanceApiSecret params) Nothing Nothing Nothing of
                        Left e -> respond (jsonError status400 e)
                        Right mTenant ->
                            case requireTenantKey "binance/listenKey/keepAlive" mTenant of
                                Left e -> respond (jsonError status400 e)
                                Right tenantKey -> do
                                    let testnet = resolveTestnetForListenKey baseArgs (alaBinanceTestnet params)
                                    case parseMarketForListenKey baseArgs (alaMarket params) of
                                        Left e -> respond (jsonError status400 e)
                                        Right market -> do
                                            if market == MarketMargin && testnet
                                                then respond (jsonError status400 "binanceTestnet is not supported for margin operations")
                                                else do
                                                    let listenKey = alaListenKey params
                                                    streams <- readMVar (lkmState listenKeyManager)
                                                    case HM.lookup tenantKey streams of
                                                        Just stream | lksListenKey (lksState stream) == listenKey -> do
                                                            let st = lksState stream
                                                            r <- retryListenKey "keepAlive" (keepAliveListenKey (lksEnv st) listenKey)
                                                            case r of
                                                                Left ex -> do
                                                                    let msg = displayException ex
                                                                    emitListenKeyError st msg
                                                                    when (isListenKeyMissingError msg) $ do
                                                                        _ <- stopListenKeyStreamMatching listenKeyManager tenantKey listenKey
                                                                        pure ()
                                                                    let (respSt, respMsg) = exceptionToHttp ex
                                                                     in respond (jsonError respSt respMsg)
                                                                Right _ -> do
                                                                    now <- getTimestampMs
                                                                    emitListenKeyKeepAlive st now
                                                                    respond (jsonValue status200 (object ["ok" .= True, "atMs" .= now]))
                                                        _ -> do
                                                            apiKey <- resolveEnv "BINANCE_API_KEY" (alaBinanceApiKey params <|> argBinanceApiKey baseArgs)
                                                            apiSecret <- resolveEnv "BINANCE_API_SECRET" (alaBinanceApiSecret params <|> argBinanceApiSecret baseArgs)
                                                            urls <- resolveBinanceBaseUrls
                                                            let baseUrl = selectBinanceBaseUrl urls testnet market
                                                            env <- newBinanceEnvWithOps mOps market baseUrl (BS.pack <$> apiKey) (BS.pack <$> apiSecret)
                                                            r <- retryListenKey "keepAlive" (keepAliveListenKey env listenKey)
                                                            case r of
                                                                Left ex -> do
                                                                    let msg = displayException ex
                                                                    when (isListenKeyMissingError msg) $ do
                                                                        _ <- stopListenKeyStreamMatching listenKeyManager tenantKey listenKey
                                                                        pure ()
                                                                    let (st, respMsg) = exceptionToHttp ex
                                                                     in respond (jsonError st respMsg)
                                                                Right _ -> do
                                                                    now <- getTimestampMs
                                                                    respond (jsonValue status200 (object ["ok" .= True, "atMs" .= now]))

handleBinanceListenKeyClose :: ApiRequestLimits -> Maybe OpsStore -> ListenKeyManager -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinanceListenKeyClose reqLimits mOps listenKeyManager baseArgs req respond = do
    if argPlatform baseArgs /= PlatformBinance
        then respond (jsonError status400 ("Binance listenKey close requires platform=binance (got " ++ platformCode (argPlatform baseArgs) ++ ")."))
        else do
            payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
            case payloadOrErr of
                Left resp -> respond resp
                Right params -> do
                    let tenantHint = alaTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
                    case resolveTenantKeyFromParams tenantHint (alaBinanceApiKey params) (alaBinanceApiSecret params) Nothing Nothing Nothing of
                        Left e -> respond (jsonError status400 e)
                        Right mTenant ->
                            case requireTenantKey "binance/listenKey/close" mTenant of
