                                                                Right _ -> do
                                                                    now <- getTimestampMs
                                                                    respond (jsonValue status200 (object ["ok" .= True, "atMs" .= now]))

handleBinanceTrades :: ApiRequestLimits -> Maybe OpsStore -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinanceTrades reqLimits mOps baseArgs req respond = do
    if argPlatform baseArgs /= PlatformBinance
        then respond (jsonError status400 ("Binance trades require platform=binance (got " ++ platformCode (argPlatform baseArgs) ++ ")."))
        else do
            payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
            case payloadOrErr of
                Left resp -> respond resp
                Right params -> do
                    case resolveTenantKeyFromBinanceTradesRequest params of
                        Left e -> respond (jsonError status400 e)
                        Right mReqTenant -> do
                            let testnet = resolveTestnetForListenKey baseArgs (abrBinanceTestnet params)
                            case parseMarketForListenKey baseArgs (abrMarket params) of
                                Left e -> respond (jsonError status400 e)
                                Right market -> do
                                    if market == MarketMargin && testnet
                                        then respond (jsonError status400 "binanceTestnet is not supported for margin operations")
                                        else do
                                            apiKey <- resolveEnv "BINANCE_API_KEY" (abrBinanceApiKey params <|> argBinanceApiKey baseArgs)
                                            apiSecret <- resolveEnv "BINANCE_API_SECRET" (abrBinanceApiSecret params <|> argBinanceApiSecret baseArgs)
                                            urls <- resolveBinanceBaseUrls
                                            let baseUrl = selectBinanceBaseUrl urls testnet market
                                                mOpsTenant = mReqTenant <|> tenantKeyFromBinanceKeys apiKey apiSecret
                                            env <- newBinanceEnvWithOps mOps market baseUrl (BS.pack <$> apiKey) (BS.pack <$> apiSecret)
                                            let symbolsRaw =
                                                    case abrSymbols params of
                                                        Just xs -> map trim xs
                                                        Nothing ->
                                                            case fmap trim (abrSymbol params) of
                                                                Just s | not (null s) -> [s]
                                                                _ -> []
                                                symbols = filter (not . null) (dedupeStable (map normalizeSymbol symbolsRaw))
                                                allSymbols = null symbols
                                                limit = abrLimit params
                                                startTime = abrStartTimeMs params
                                                endTime = abrEndTimeMs params
                                                fromId = abrFromId params
                                            if allSymbols && market /= MarketFutures
                                                then respond (jsonError status400 "binance trades require symbol for spot/margin markets")
                                                else do
                                                    result <- try $ do
                                                        trades <-
                                                            if allSymbols
                                                                then fetchAccountTrades env Nothing limit startTime endTime fromId
                                                                else
                                                                    concat
                                                                        <$> mapM
                                                                            (\sym -> fetchAccountTrades env (Just sym) limit startTime endTime fromId)
                                                                            symbols
                                                        let tradesSorted = sortOn (negate . btTime) trades
                                                        tradesWithIps <-
                                                            case (mOps, mOpsTenant) of
                                                                (Just store, Just tenantKey) ->
                                                                    attachBinanceTradeOriginIps store tenantKey tradesSorted
                                                                _ -> pure tradesSorted
                                                        now <- getTimestampMs
                                                        pure
                                                            ApiBinanceTradesResponse
                                                                { abtrMarket = marketCode market
                                                                , abtrTestnet = testnet
                                                                , abtrSymbols = symbols
                                                                , abtrAllSymbols = allSymbols
                                                                , abtrTrades = tradesWithIps
                                                                , abtrFetchedAtMs = now
                                                                }
                                                    case result of
                                                        Left ex ->
                                                            let (st, msg) = exceptionToHttp ex
                                                             in respond (jsonError st msg)
                                                        Right payload ->
                                                            respond (jsonValue status200 payload)

computeBinancePositionsResponse :: Maybe (RequestProgressStore, String) -> Maybe OpsStore -> Args -> BinanceMarket -> Bool -> ApiBinancePositionsRequest -> IO ApiBinancePositionsResponse
computeBinancePositionsResponse mTracker mOps baseArgs market testnet params = do
    apiKey <- resolveEnv "BINANCE_API_KEY" (abpBinanceApiKey params <|> argBinanceApiKey baseArgs)
    apiSecret <- resolveEnv "BINANCE_API_SECRET" (abpBinanceApiSecret params <|> argBinanceApiSecret baseArgs)
    urls <- resolveBinanceBaseUrls
    let baseUrl = selectBinanceBaseUrl urls testnet market
    env <- newBinanceEnvWithOps mOps market baseUrl (BS.pack <$> apiKey) (BS.pack <$> apiSecret)
    r <- try (fetchFuturesPositionRisks env) :: IO (Either SomeException [FuturesPositionRisk])
    advanceRequestProgressMaybe mTracker "account UID" Nothing
    accountUidResult <- try (fetchFuturesAccountUid env) :: IO (Either SomeException (Maybe Int64))
    let accountUid =
            case accountUidResult of
                Right v -> v
                Left _ -> Nothing
    case r of
        Left ex -> throwIO ex
        Right positions -> do
            let interval = fromMaybe (argInterval baseArgs) (abpInterval params)
                limitRaw = fromMaybe 120 (abpLimit params)
                limitSafe = max 10 (min 1000 limitRaw)
                openPositions = filter (\p -> abs (fprPositionAmt p) > 1e-12) positions
                totalOpenPositions = length openPositions
                toApiPosition p =
                    ApiBinancePosition
                        { abpSymbol = fprSymbol p
                        , abpPositionAmt = fprPositionAmt p
                        , abpEntryPrice = fprEntryPrice p
                        , abpMarkPrice = fprMarkPrice p
                        , abpUnrealizedPnl = fprUnrealizedProfit p
                        , abpLiquidationPrice = fprLiquidationPrice p
                        , abpBreakEvenPrice = fprBreakEvenPrice p
                        , abpLeverage = fprLeverage p
                        , abpMarginType = fprMarginType p
                        , abpPositionSide = fprPositionSide p
                        }
                formatKlineDetail idx sym =
                    sym ++ " (" ++ show idx ++ "/" ++ show totalOpenPositions ++ ")"
            persistBinancePositionsMaybe mOps market openPositions
            chartsRaw <-
                forM (zip [1 ..] openPositions) $ \(idx, pos) -> do
                    let sym = fprSymbol pos
                    advanceRequestProgressMaybe mTracker "klines" (Just (formatKlineDetail idx sym))
                    kr <- try (fetchKlines env sym interval limitSafe) :: IO (Either SomeException [Kline])
                    pure $
                        case kr of
                            Left _ -> Nothing
                            Right ks ->
                                Just
                                    ApiBinancePositionChart
                                        { abpcSymbol = sym
                                        , abpcOpenTimes = map kOpenTime ks
                                        , abpcPrices = map kClose ks
                                        }
            now <- getTimestampMs
            pure
                ApiBinancePositionsResponse
                    { abprMarket = marketCode market
                    , abprTestnet = testnet
                    , abprInterval = interval
                    , abprLimit = limitSafe
                    , abprPositions = map toApiPosition openPositions
                    , abprCharts = catMaybes chartsRaw
                    , abprFetchedAtMs = now
                    , abprAccountUid = accountUid
                    }

handleBinancePositions :: RequestProgressStore -> ApiRequestLimits -> Maybe OpsStore -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinancePositions requestProgressStore reqLimits mOps baseArgs req respond = do
    let mTracker = requestProgressTracker requestProgressStore req
    if argPlatform baseArgs /= PlatformBinance
        then respond (jsonError status400 ("Binance positions require platform=binance (got " ++ platformCode (argPlatform baseArgs) ++ ")."))
        else do
            payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
            case payloadOrErr of
                Left resp -> respond resp
                Right params -> do
                    case resolveTenantKeyFromBinancePositionsRequest params of
                        Left e -> respond (jsonError status400 e)
                        Right _ -> do
                            let testnet = resolveTestnetForListenKey baseArgs (abpBinanceTestnet params)
                            case parseMarketForListenKey baseArgs (abpMarket params) of
                                Left e -> respond (jsonError status400 e)
                                Right market -> do
                                    if market /= MarketFutures
                                        then respond (jsonError status400 "binance positions require market=futures")
                                        else do
                                            startRequestProgressMaybe mTracker "binance/positions" "positions" Nothing
                                            result <- try (computeBinancePositionsResponse mTracker mOps baseArgs market testnet params) :: IO (Either SomeException ApiBinancePositionsResponse)
                                            case result of
                                                Left ex ->
                                                    let (st, msg) = exceptionToHttp ex
                                                     in do
                                                            failRequestProgressMaybe mTracker msg
                                                            respond (jsonError st msg)
                                                Right out -> do
                                                    completeRequestProgressMaybe mTracker (Just "response ready")
                                                    respond (jsonValue status200 out)

handleBinancePositionsGet :: RequestProgressStore -> ApiRequestLimits -> Maybe OpsStore -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinancePositionsGet requestProgressStore _reqLimits mOps baseArgs req respond = do
    let mTracker = requestProgressTracker requestProgressStore req
    -- Reuse POST handler with defaults derived from base args.
    let params =
            ApiBinancePositionsRequest
                { abpBinanceTestnet = Nothing
                , abpMarket = Just (marketCode (argBinanceMarket baseArgs))
                , abpInterval = Just (argInterval baseArgs)
                , abpLimit = Nothing
                , abpBinanceApiKey = Nothing
                , abpBinanceApiSecret = Nothing
                , abpTenantKey = Nothing
                }
    -- Inline the core of handleBinancePositions with the provided params.
    if argPlatform baseArgs /= PlatformBinance
        then respond (jsonError status400 ("Binance positions require platform=binance (got " ++ platformCode (argPlatform baseArgs) ++ ")."))
        else do
            case resolveTenantKeyFromBinancePositionsRequest params of
                Left e -> respond (jsonError status400 e)
                Right _ -> do
                    let testnet = resolveTestnetForListenKey baseArgs (abpBinanceTestnet params)
                    case parseMarketForListenKey baseArgs (abpMarket params) of
                        Left e -> respond (jsonError status400 e)
                        Right market -> do
                            if market /= MarketFutures
                                then respond (jsonError status400 "binance positions require market=futures")
                                else do
                                    startRequestProgressMaybe mTracker "binance/positions" "positions" Nothing
                                    result <- try (computeBinancePositionsResponse mTracker mOps baseArgs market testnet params) :: IO (Either SomeException ApiBinancePositionsResponse)
                                    case result of
                                        Left ex ->
                                            let (st, msg) = exceptionToHttp ex
                                             in do
                                                    failRequestProgressMaybe mTracker msg
                                                    respond (jsonError st msg)
                                        Right out -> do
                                            completeRequestProgressMaybe mTracker (Just "response ready")
                                            respond (jsonValue status200 out)

handleBinanceClosePosition :: ApiRequestLimits -> Maybe OpsStore -> Args -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBinanceClosePosition reqLimits mOps baseArgs req respond = do
    let originIp = requestOriginIp req
    if argPlatform baseArgs /= PlatformBinance
        then respond (jsonError status400 ("Binance close position requires platform=binance (got " ++ platformCode (argPlatform baseArgs) ++ ")."))
        else do
            payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
            case payloadOrErr of
                Left resp -> respond resp
                Right params -> do
                    case resolveTenantKeyFromBinanceClosePositionRequest params of
                        Left e -> respond (jsonError status400 e)
                        Right mReqTenant -> do
                            let testnet = resolveTestnetForListenKey baseArgs (abcpBinanceTestnet params)
                            case parseMarketForListenKey baseArgs (abcpMarket params) of
                                Left e -> respond (jsonError status400 e)
                                Right market -> do
                                    if market /= MarketFutures
                                        then respond (jsonError status400 "binance close position requires market=futures")
                                        else do
                                            let live = fromMaybe (argBinanceLive baseArgs) (abcpBinanceLive params)
                                            if not live
                                                then respond (jsonError status400 "binanceLive must be enabled to close positions")
                                                else do
                                                    let symbolRaw = trim (abcpSymbol params)
                                                    if null symbolRaw
                                                        then respond (jsonError status400 "symbol is required")
                                                        else do
                                                            apiKey <- resolveEnv "BINANCE_API_KEY" (abcpBinanceApiKey params <|> argBinanceApiKey baseArgs)
                                                            apiSecret <- resolveEnv "BINANCE_API_SECRET" (abcpBinanceApiSecret params <|> argBinanceApiSecret baseArgs)
                                                            urls <- resolveBinanceBaseUrls
                                                            let baseUrl = selectBinanceBaseUrl urls testnet market
                                                                mOpsTenant = mReqTenant <|> tenantKeyFromBinanceKeys apiKey apiSecret
                                                            env <- newBinanceEnvWithOps mOps market baseUrl (BS.pack <$> apiKey) (BS.pack <$> apiSecret)
                                                            r <- try (fetchFuturesPositionRisks env) :: IO (Either SomeException [FuturesPositionRisk])
                                                            case r of
                                                                Left ex ->
                                                                    let (st, msg) = exceptionToHttp ex
                                                                     in respond (jsonError st msg)
                                                                Right positions -> do
                                                                    let sym = normalizeSymbol symbolRaw
                                                                        reqSideRaw = normalizePositionSideText (abcpPositionSide params)
                                                                        reqSide =
                                                                            case reqSideRaw of
                                                                                Just "BOTH" -> Nothing
                                                                                _ -> reqSideRaw
                                                                        posSideNorm p = normalizePositionSideText (fprPositionSide p)
                                                                        matchesSym p = normalizeSymbol (fprSymbol p) == sym
                                                                        matchesSide p =
                                                                            case reqSide of
                                                                                Nothing -> True
                                                                                Just reqSideLabel ->
                                                                                    case posSideNorm p of
                                                                                        Just posSideLabel | posSideLabel /= "BOTH" -> posSideLabel == reqSideLabel
                                                                                        _ -> True
                                                                        openPositions =
                                                                            filter (\p -> abs (fprPositionAmt p) > 1e-12) (filter matchesSym positions)
                                                                        openMatches = filter matchesSide openPositions
                                                                        sideSet = dedupeStable (map posSideNorm openPositions)
                                                                        sideSetNonBoth = filter (/= Just "BOTH") sideSet

                                                                        baseResult sideLabel qty =
                                                                            ApiOrderResult
                                                                                { aorSent = False
                                                                                , aorMode = Just "live"
                                                                                , aorSide = Just sideLabel
                                                                                , aorSymbol = Just sym
                                                                                , aorQuantity = Just qty
                                                                                , aorQuoteQuantity = Nothing
                                                                                , aorOrderId = Nothing
                                                                                , aorClientOrderId = Nothing
                                                                                , aorStatus = Nothing
                                                                                , aorExecutedQty = Nothing
                                                                                , aorCummulativeQuoteQty = Nothing
                                                                                , aorTxHash = Nothing
                                                                                , aorResponse = Nothing
                                                                                , aorMessage = ""
                                                                                }

                                                                        noPosition msg =
                                                                            let base = baseResult "CLOSE" 0
                                                                             in respond $
                                                                                    jsonValue
                                                                                        status200
                                                                                        ( base
                                                                                            { aorMessage = msg
                                                                                            }
                                                                                        )

                                                                        closeSide posAmt =
                                                                            if posAmt > 0 then ("SELL", Sell) else ("BUY", Buy)

                                                                        shortErr ex = take 240 (show ex)

                                                                    let fallbackAmt = abcpPositionAmt params
                                                                        tryPlace posAmt posSideForOrder = do
                                                                            let qty = abs posAmt
                                                                                (sideLabel, side) = closeSide posAmt
                                                                                posSideParam =
                                                                                    case reqSide of
                                                                                        Just s -> Just s
                                                                                        Nothing ->
                                                                                            case posSideForOrder of
                                                                                                Just s | s /= "BOTH" -> Just s
                                                                                                _ -> Nothing
                                                                                baseOut = baseResult sideLabel qty
                                                                            r2 <- try (placeFuturesMarketOrderWithPositionSide env OrderLive sym side qty (Just True) Nothing posSideParam) :: IO (Either SomeException BL.ByteString)
                                                                            case r2 of
                                                                                Left ex ->
                                                                                    respond (jsonValue status200 baseOut{aorMessage = "Order failed: " ++ shortErr ex})
                                                                                Right body -> do
                                                                                    let out0 =
                                                                                            baseOut
                                                                                                { aorSent = True
                                                                                                , aorResponse = Just (shortResp body)
                                                                                                , aorMessage = "Close order sent."
                                                                                                }
                                                                                        out = maybe out0 (`applyOrderInfo` out0) (decodeOrderInfo body)
                                                                                        outJson =
                                                                                            case toJSON out of
                                                                                                Aeson.Object o ->
                                                                                                    Aeson.Object
                                                                                                        (KM.insert (AK.fromString "originIp") (toJSON originIp) o)
                                                                                                v -> v
                                                                                        paramsJson =
                                                                                            Just
                                                                                                ( object
                                                                                                    [ "symbol" .= sym
                                                                                                    , "market" .= marketCode market
                                                                                                    , "positionSide" .= posSideParam
                                                                                                    , "reduceOnly" .= True
                                                                                                    , "quantity" .= qty
                                                                                                    ]
                                                                                                )
                                                                                    opsAppendMaybe
                                                                                        mOps
                                                                                        mOpsTenant
                                                                                        "trade.order"
                                                                                        paramsJson
                                                                                        Nothing
                                                                                        (Just outJson)
                                                                                        Nothing
                                                                                        Nothing
                                                                                        (Just (T.pack sym))
                                                                                        (orderIdFromOrderResult out)
                                                                                    respond (jsonValue status200 out)

                                                                    case openPositions of
                                                                        [] ->
                                                                            case fallbackAmt of
                                                                                Just amt
                                                                                    | abs amt > 1e-12 -> tryPlace amt Nothing
                                                                                _ -> noPosition ("No open position found for " ++ sym ++ ".")
                                                                        _ ->
                                                                            if isNothing reqSide && length sideSetNonBoth > 1
                                                                                then respond (jsonError status400 "Multiple hedge positions are open; provide positionSide (LONG/SHORT).")
                                                                                else case openMatches of
                                                                                    [] ->
                                                                                        case fallbackAmt of
                                                                                            Just amt
                                                                                                | abs amt > 1e-12 ->
                                                                                                    tryPlace amt reqSide
                                                                                            _ -> noPosition ("No open position found for " ++ sym ++ " (matching positionSide).")
                                                                                    (pos : _) -> do
                                                                                        let posAmt = fprPositionAmt pos
                                                                                        tryPlace posAmt (posSideNorm pos)
  where
    normalizePositionSideText raw =
        case fmap (map toUpper . trim) raw of
            Nothing -> Nothing
            Just "" -> Nothing
            Just v -> Just v

handleBotStart :: ApiRequestLimits -> Maybe OpsStore -> ApiComputeLimits -> TopCombosBacktestCtx -> Metrics -> Maybe Journal -> Maybe Webhook -> Maybe FilePath -> TopCombosStore -> Args -> BotController -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBotStart reqLimits mOps limits topCombosCtx metrics mJournal mWebhook mBotStateDir topCombosStore baseArgs botCtrl req respond = do
    payloadOrErr <- decodeRequestBodyLimited reqLimits req "Invalid JSON: "
    case payloadOrErr of
        Left resp -> respond resp
        Right params ->
            let tenantHint = apTenantKey params <|> fmap T.unpack (tenantKeyFromRequest req)
                originIp = requestOriginIp req
             in case argsFromApi baseArgs params of
                    Left e -> respond (jsonError status400 e)
                    Right args0 ->
                        case resolveTenantKeyFromApiParamsWithHint tenantHint args0 params of
                            Left e -> respond (jsonError status400 e)
                            Right mTenant ->
                                case requireTenantKey "bot/start" mTenant of
                                    Left e -> respond (jsonError status400 e)
                                    Right tenantKey -> do
                                        let argsBase = args0{argTradeOnly = True}
                                            tradeEnabled = botTradeEnabledFromApi (apBotTrade params)
                                        symbolsOrErr <- resolveBotSymbols argsBase params
                                        let requestedSymbols =
                                                case symbolsOrErr of
                                                    Left _ -> []
                                                    Right syms -> syms
                                        orphanSymbols <-
                                            if tradeEnabled && platformSupportsLiveBot (argPlatform argsBase)
                                                then resolveOrphanOpenPositionSymbols mOps limits argsBase requestedSymbols
                                                else pure []
                                        let symbols = dedupeStable (requestedSymbols ++ orphanSymbols)
                                            errorMsg =
                                                case symbolsOrErr of
                                                    Left e -> e
                                                    Right _ -> "bot/start requires binanceSymbol or botSymbols"
                                        if null symbols
                                            then respond (jsonError status400 errorMsg)
                                            else do
                                                let allowExistingBase = length requestedSymbols > 1
                                                    orphanNorm = map normalizeSymbol orphanSymbols
                                                    allowExistingFor sym = allowExistingBase || normalizeSymbol sym `elem` orphanNorm
                                                    noAdoptRequirement = AdoptRequirement False False
                                                results <- forM symbols $ \sym -> do
                                                    let argsSym = argsBase{argBinanceSymbol = Just sym}
                                                        allowExisting = allowExistingFor sym
                                                        adoptable = tradeEnabled && platformSupportsLiveBot (argPlatform argsSym)
                                                    adoptReqOrErr <-
                                                        if adoptable
                                                            then resolveAdoptionRequirement mOps argsSym sym
                                                            else pure (Right noAdoptRequirement)
                                                    case adoptReqOrErr of
                                                        Left err -> pure (sym, Left err)
                                                        Right adoptReq -> do
                                                            (argsCombo, mComboUuid) <-
                                                                if arActive adoptReq
                                                                    then applyOriginComboForAdoptionMaybe mOps topCombosStore limits tenantKey argsSym adoptReq sym
                                                                    else do
                                                                        when (shouldClearPositionOriginOnStart adoptable (arActive adoptReq)) $
                                                                            clearPositionOriginIfFlatMaybe mOps tenantKey argsSym sym
                                                                        applyLatestTopCombo mOps topCombosStore limits sym argsSym adoptReq
                                                            case validateApiComputeLimits limits argsCombo of
                                                                Left err -> pure (sym, Left err)
                                                                Right argsOk -> do
                                                                    r <- botStartSymbol allowExisting mOps metrics mJournal mWebhook mBotStateDir topCombosStore limits topCombosCtx adoptReq botCtrl tenantKey argsOk mComboUuid originIp params sym
                                                                    pure (sym, r)

                                                let errors =
                                                        [ object ["symbol" .= sym, "error" .= err]
                                                        | (sym, Left err) <- results
                                                        ]
                                                statuses <- forM [outcome | (_, Right outcome) <- results] $ \outcome ->
                                                    case bsoState outcome of
                                                        BotStarting rt -> pure (botStartingJson rt)
                                                        BotRunning rt -> do
                                                            st <- readMVar (brStateVar rt)
                                                            pure (botStatusJson st)

                                                now <- getTimestampMs
                                                forM_ [outcome | (_, Right outcome) <- results, bsoStarted outcome] $ \outcome ->
                                                    case bsoState outcome of
                                                        BotStarting rt -> do
                                                            let settings = bsrSettings rt
                                                            journalWriteMaybe
                                                                mJournal
                                                                ( object
                                                                    [ "type" .= ("bot.start" :: String)
                                                                    , "atMs" .= now
                                                                    , "symbol" .= bsrSymbol rt
                                                                    , "market" .= marketCode (argBinanceMarket (bsrArgs rt))
                                                                    , "interval" .= argInterval (bsrArgs rt)
                                                                    , "tradeEnabled" .= bsTradeEnabled (bsrSettings rt)
                                                                    , "protectionOrders" .= bsProtectionOrders (bsrSettings rt)
                                                                    ]
                                                                )
                                                            opsAppendMaybe
                                                                mOps
                                                                (Just tenantKey)
                                                                "bot.start"
                                                                (Just (toJSON (sanitizeApiParams params)))
                                                                (Just (argsPublicJson (bsrArgs rt)))
                                                                ( Just
                                                                    ( object
                                                                        [ "symbol" .= bsrSymbol rt
                                                                        , "market" .= marketCode (argBinanceMarket (bsrArgs rt))
                                                                        , "interval" .= argInterval (bsrArgs rt)
                                                                        , "tradeEnabled" .= bsTradeEnabled settings
                                                                        , "protectionOrders" .= bsProtectionOrders settings
                                                                        , "botAdoptExistingPosition" .= bsAdoptExistingPosition settings
                                                                        , "botPollSeconds" .= bsPollSeconds settings
                                                                        , "botOnlineEpochs" .= bsOnlineEpochs settings
                                                                        , "botTrainBars" .= bsTrainBars settings
                                                                        , "botMaxPoints" .= bsMaxPoints settings
                                                                        ]
                                                                    )
                                                                )
                                                                Nothing
                                                                Nothing
                                                                (Just (T.pack (bsrSymbol rt)))
                                                                Nothing
                                                        _ -> pure ()

                                                case (symbols, errors, statuses) of
                                                    ([_], [], [status]) -> respond (jsonValue status202 status)
                                                    _ ->
                                                        if null statuses
                                                            then case errors of
                                                                [] -> respond (jsonError status400 "Failed to start bot.")
                                                                errs -> do
                                                                    let errorMsgFromValue err =
                                                                            case err of
                                                                                Aeson.Object o ->
                                                                                    case KM.lookup "error" o of
                                                                                        Just (Aeson.String t) -> Just (T.unpack t)
                                                                                        _ -> Nothing
                                                                                _ -> Nothing
                                                                        msg =
                                                                            case errs of
                                                                                [err] -> fromMaybe "Failed to start bot." (errorMsgFromValue err)
                                                                                _ -> "Failed to start bot."
                                                                        payload = object ["error" .= msg, "errors" .= errs]
                                                                    respond (jsonValue status400 payload)
                                                            else do
                                                                let base = botStatusJsonMulti statuses
                                                                    payload =
                                                                        case base of
                                                                            Aeson.Object o ->
                                                                                let o' =
                                                                                        if null errors
                                                                                            then o
                                                                                            else KM.insert "errors" (toJSON errors) o
                                                                                 in Aeson.Object o'
                                                                            _ -> base
                                                                respond (jsonValue status202 payload)

handleBotStop :: Maybe OpsStore -> Maybe Journal -> Maybe Webhook -> Maybe FilePath -> BotController -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBotStop mOps mJournal mWebhook mBotStateDir botCtrl req respond = do
    let mSymbol =
            case lookup (BS.pack "symbol") (Wai.queryString req) of
                Just (Just raw) -> Just (BS.unpack raw)
                _ -> Nothing
    case requireTenantKey "bot/stop" (tenantKeyFromRequest req) of
        Left e -> respond (jsonError status400 e)
        Right tenantKey -> do
            stopped <- botStop botCtrl tenantKey mSymbol
            now <- getTimestampMs
            let stoppedSymbols = map botSymbol stopped
                mStopSymbol =
                    case stoppedSymbols of
                        [sym] -> Just (T.pack sym)
                        _ -> Nothing
            journalWriteMaybe mJournal (object ["type" .= ("bot.stop" :: String), "atMs" .= now, "symbols" .= stoppedSymbols])
            opsAppendMaybe mOps (Just tenantKey) "bot.stop" Nothing Nothing (Just (object ["symbols" .= stoppedSymbols])) Nothing Nothing mStopSymbol Nothing
            forM_ stopped (botStatusLogMaybe mOps False)
            webhookNotifyMaybe mWebhook (webhookEventBotStop stoppedSymbols)

            let snaps =
                    [ BotStatusSnapshot
                        { bssSavedAtMs = now
                        , bssStatus = botStatusJson st
                        }
                    | st <- stopped
                    ]
            forM_ stopped $ \st -> do
                let snap =
                        BotStatusSnapshot
                            { bssSavedAtMs = now
                            , bssStatus = botStatusJson st
                            }
                writeBotStatusSnapshotMaybe mBotStateDir tenantKey (botSymbol st) snap

            case snaps of
                [] -> do
                    case mSymbol of
                        Nothing -> respond (jsonValue status200 botStoppedJson)
                        Just sym -> do
                            mSnap <- readBotStatusSnapshotMaybe mBotStateDir tenantKey sym
                            case mSnap of
                                Nothing -> respond (jsonValue status200 botStoppedJson)
                                Just snap -> respond (jsonValue status200 (botStoppedSnapshotJson snap))
                [snap] -> respond (jsonValue status200 (botStoppedSnapshotJson snap))
                _ -> respond (jsonValue status200 (botStoppedMultiJson snaps))

handleBotStatus :: ApiRequestLimits -> BotController -> Maybe FilePath -> Wai.Request -> (Wai.Response -> IO Wai.ResponseReceived) -> IO Wai.ResponseReceived
handleBotStatus reqLimits botCtrl mBotStateDir req respond = do
    let q = Wai.queryString req
        maxTail = arlMaxBotStatusTail reqLimits
        tailN =
            case lookup (BS.pack "tail") q of
                Just (Just raw) -> readMaybe (BS.unpack raw) >>= \n -> if n > 0 then Just (min n maxTail) else Nothing
                _ -> Nothing
        mSymbol =
            case lookup (BS.pack "symbol") q of
                Just (Just raw) -> Just (BS.unpack raw)
                _ -> Nothing

    case requireTenantKey "bot/status" (tenantKeyFromRequest req) of
        Left e -> respond (jsonError status400 e)
        Right tenantKey ->
            case mSymbol of
                Just sym -> do
                    mSt <- botGetStateFor botCtrl tenantKey sym
                    case mSt of
                        Just st -> do
                            let st' = maybe st (`botStateTail` st) tailN
                            respond (jsonValue status200 (botStatusJson st'))
                        Nothing -> do
                            mSnap <- readBotStatusSnapshotMaybe mBotStateDir tenantKey sym
                            case mSnap of
                                Nothing -> respond (jsonValue status200 botStoppedJson)
                                Just snap -> respond (jsonValue status200 (botStoppedSnapshotJson snap))
                Nothing -> do
                    mrt <- readMVar (bcRuntime botCtrl)
                    let tenantMap = fromMaybe HM.empty (HM.lookup tenantKey mrt)
                    if HM.null tenantMap
                        then do
                            snaps <- readBotStatusSnapshotsMaybe mBotStateDir tenantKey
                            case snaps of
                                [] -> respond (jsonValue status200 botStoppedJson)
                                [snap] -> respond (jsonValue status200 (botStoppedSnapshotJson snap))
                                _ -> respond (jsonValue status200 (botStoppedMultiJson snaps))
                        else do
                            let entries = sortOn fst (HM.toList tenantMap)
                            case entries of
                                [(_sym, state)] ->
                                    case state of
                                        BotStarting rt -> respond (jsonValue status200 (botStartingJson rt))
                                        BotRunning rt -> do
                                            st <- readMVar (brStateVar rt)
                                            let st' = maybe st (`botStateTail` st) tailN
                                            respond (jsonValue status200 (botStatusJson st'))
                                _ -> do
                                    statuses <-
                                        forM entries $ \(_sym, state) ->
                                            case state of
                                                BotStarting rt -> pure (botStartingJson rt)
                                                BotRunning rt -> do
                                                    st <- readMVar (brStateVar rt)
                                                    let st' = maybe st (`botStateTail` st) tailN
                                                    pure (botStatusJson st')
                                    respond (jsonValue status200 (botStatusJsonMulti statuses))

argsFromApi :: Args -> ApiParams -> Either String Args
argsFromApi baseArgs p = do
    platform <-
        case apPlatform p of
            Nothing -> Right (argPlatform baseArgs)
            Just raw -> parsePlatform raw
    method <-
        case apMethod p of
            Nothing -> Right (argMethod baseArgs)
            Just raw -> parseMethod raw

    positioning <-
        case apPositioning p of
            Nothing -> Right (argPositioning baseArgs)
            Just raw -> parsePositioning raw

    intrabarFill <-
        case apIntrabarFill p of
            Nothing -> Right (argIntrabarFill baseArgs)
            Just raw -> parseIntrabarFill raw

    noTradeWindows <-
        case apNoTradeWindows p of
            Nothing -> Right (argNoTradeWindows baseArgs)
            Just raws ->
                case traverse parseTimeWindow raws of
                    Left err -> Left ("Invalid noTradeWindows: " ++ err)
                    Right windows -> Right windows

    norm <-
        case apNormalization p of
            Nothing -> Right (argNormalization baseArgs)
            Just raw ->
                case parseNormType raw of
                    Just n -> Right n
                    Nothing -> Left ("Invalid normalization: " ++ show raw ++ " (expected none|minmax|standard|log)")

    tuneObjective <-
        case apTuneObjective p of
            Nothing -> Right (argTuneObjective baseArgs)
            Just raw -> parseTuneObjective raw

    predictors <-
        case apPredictors p of
            Nothing -> Right (argPredictors baseArgs)
            Just raw -> predictorSetFromString raw

    (futuresFlag, marginFlag) <-
        case apMarket p of
            Nothing -> Right (argBinanceFutures baseArgs, argBinanceMargin baseArgs)
            Just raw ->
                case map toLower (trim raw) of
                    "spot" -> Right (False, False)
                    "margin" -> Right (False, True)
                    "futures" -> Right (True, False)
                    other -> Left ("Invalid market: " ++ show other ++ " (expected spot|margin|futures)")

    let pick :: Maybe a -> a -> a
        pick v def = fromMaybe def v

        pickMaybe :: Maybe a -> Maybe a -> Maybe a
        pickMaybe v def =
            case v of
                Just _ -> v
                Nothing -> def

        openThr =
            pick
                (apOpenThreshold p <|> apThreshold p)
                (argOpenThreshold baseArgs)
        closeThr =
            case apCloseThreshold p <|> apThreshold p of
                Just v -> v
                Nothing ->
                    case apOpenThreshold p of
                        Just _ -> openThr
                        Nothing -> argCloseThreshold baseArgs
        botSymbolsFirst =
            case apBotSymbols p of
                Nothing -> Nothing
                Just xs -> find (not . null) (map trim xs)
        binanceSymbolRaw = pickMaybe (apBinanceSymbol p <|> botSymbolsFirst) (argBinanceSymbol baseArgs)
        binanceSymbolSanitized = binanceSymbolRaw >>= sanitizeComboSymbolForPlatform (Just (platformCode platform))
        binanceSymbol = binanceSymbolSanitized <|> binanceSymbolRaw

        args =
            baseArgs
                { argData = pickMaybe (apData p) (argData baseArgs)
                , argPriceCol = pick (apPriceColumn p) (argPriceCol baseArgs)
                , argHighCol = pickMaybe (apHighColumn p) (argHighCol baseArgs)
                , argLowCol = pickMaybe (apLowColumn p) (argLowCol baseArgs)
                , argBinanceSymbol = binanceSymbol
                , argPlatform = platform
                , argBinanceFutures = futuresFlag
                , argBinanceMargin = marginFlag
                , argInterval = pick (apInterval p) (argInterval baseArgs)
                , argBars = pickMaybe (apBars p) (argBars baseArgs)
                , argLookbackWindow = pick (apLookbackWindow p) (argLookbackWindow baseArgs)
                , argLookbackBars = pickMaybe (apLookbackBars p) (argLookbackBars baseArgs)
                , argBinanceTestnet = pick (apBinanceTestnet p) (argBinanceTestnet baseArgs)
                , argBinanceApiKey = pickMaybe (apBinanceApiKey p) (argBinanceApiKey baseArgs)
                , argBinanceApiSecret = pickMaybe (apBinanceApiSecret p) (argBinanceApiSecret baseArgs)
                , argCoinbaseApiKey = pickMaybe (apCoinbaseApiKey p) (argCoinbaseApiKey baseArgs)
                , argCoinbaseApiSecret = pickMaybe (apCoinbaseApiSecret p) (argCoinbaseApiSecret baseArgs)
                , argCoinbaseApiPassphrase = pickMaybe (apCoinbaseApiPassphrase p) (argCoinbaseApiPassphrase baseArgs)
                , argNormalization = norm
                , argHiddenSize = pick (apHiddenSize p) (argHiddenSize baseArgs)
                , argEpochs = pick (apEpochs p) (argEpochs baseArgs)
                , argLr = pick (apLr p) (argLr baseArgs)
                , argValRatio = pick (apValRatio p) (argValRatio baseArgs)
                , argBacktestRatio = pick (apBacktestRatio p) (argBacktestRatio baseArgs)
                , argBacktestFrom = pickMaybe (apFrom p) (argBacktestFrom baseArgs)
                , argBacktestTo = pickMaybe (apTo p) (argBacktestTo baseArgs)
