dirLabel :: Maybe Int -> Maybe String
dirLabel d =
    case d of
        Just 1 -> Just "UP"
        Just (-1) -> Just "DOWN"
        _ -> Nothing

computeLatestSignalFromArgs :: Maybe OpsStore -> Args -> IO LatestSignal
computeLatestSignalFromArgs mOps args = do
    (series, mBinanceEnv) <- loadPrices mOps args
    computeLatestSignalFromSeries args series mBinanceEnv

computeLatestSignalFromArgsWithLimits :: ApiComputeLimits -> Maybe OpsStore -> Args -> IO LatestSignal
computeLatestSignalFromArgsWithLimits limits mOps args = do
    (series, mBinanceEnv) <- loadPrices mOps args
    case validateApiComputeLimitsAfterLoad limits args series of
        Left msg -> throwIO (userError msg)
        Right () -> pure ()
    computeLatestSignalFromSeries args series mBinanceEnv

computeLatestSignalFromSeries :: Args -> PriceSeries -> Maybe BinanceEnv -> IO LatestSignal
computeLatestSignalFromSeries args series mBinanceEnv = do
    let prices = psClose series
    ensureMinPriceRows args 2 prices
    let lookback = argLookback args
    ensureLookbackRows args lookback prices
    computeTradeOnlySignal args lookback series mBinanceEnv

computeTradeFromArgs :: Maybe OpsStore -> Args -> IO ApiTradeResponse
computeTradeFromArgs mOps args = do
    (series, mBinanceEnv) <- loadPrices mOps args
    computeTradeFromSeries args series mBinanceEnv

computeTradeFromArgsWithLimits :: ApiComputeLimits -> Maybe OpsStore -> Args -> IO ApiTradeResponse
computeTradeFromArgsWithLimits limits mOps args = do
    (series, mBinanceEnv) <- loadPrices mOps args
    case validateApiComputeLimitsAfterLoad limits args series of
        Left msg -> throwIO (userError msg)
        Right () -> pure ()
    computeTradeFromSeries args series mBinanceEnv

noOrderResult :: String -> ApiOrderResult
noOrderResult msg =
    ApiOrderResult
        { aorSent = False
        , aorMode = Nothing
        , aorSide = Nothing
        , aorSymbol = Nothing
        , aorQuantity = Nothing
        , aorQuoteQuantity = Nothing
        , aorOrderId = Nothing
        , aorClientOrderId = Nothing
        , aorStatus = Nothing
        , aorExecutedQty = Nothing
        , aorCummulativeQuoteQty = Nothing
        , aorTxHash = Nothing
        , aorResponse = Nothing
        , aorMessage = msg
        }

ensureRuntimeConfig :: Args -> IO ()
ensureRuntimeConfig args = do
    runtimeValidation <- validateRuntimeConfig args
    case runtimeValidation of
        Left msg -> throwIO (userError msg)
        Right () -> pure ()

dryRunOrderResult :: Args -> LatestSignal -> ApiOrderResult
dryRunOrderResult args sig =
    let chosen = lsChosenDir sig
        message =
            case chosen of
                Nothing -> "Dry run: neutral signal; no order would be sent."
                Just _ -> "Dry run: order execution disabled; no exchange or DEX request was sent."
        side =
            case chosen of
                Just 1 -> Just "BUY"
                Just (-1) -> Just "SELL"
                _ -> Nothing
        qty =
            case argOrderQuantity args of
                Just q | q > 0 -> Just q
                _ -> Nothing
        quoteQty =
            case argOrderQuote args of
                Just q | q > 0 -> Just q
                _ -> Nothing
        dexSymbol =
            case (argDexBaseToken args, argDexQuoteToken args) of
                (Just baseRaw, Just quoteRaw) ->
                    let base = trim baseRaw
                        quote = trim quoteRaw
                     in if null base || null quote then argBinanceSymbol args else Just (base ++ "/" ++ quote)
                _ -> argBinanceSymbol args
        symbol =
            case argPlatform args of
                PlatformUniswap -> dexSymbol
                PlatformCurve -> dexSymbol
                PlatformSushiswap -> dexSymbol
                PlatformBalancer -> dexSymbol
                PlatformPancakeswap -> dexSymbol
                PlatformOneInch -> dexSymbol
                _ -> argBinanceSymbol args
     in ApiOrderResult
            { aorSent = False
            , aorMode = Just "dry-run"
            , aorSide = side
            , aorSymbol = symbol
            , aorQuantity = qty
            , aorQuoteQuantity = quoteQty
            , aorOrderId = Nothing
            , aorClientOrderId = trim <$> argIdempotencyKey args
            , aorStatus = Just "not_sent"
            , aorExecutedQty = Nothing
            , aorCummulativeQuoteQty = Nothing
            , aorTxHash = Nothing
            , aorResponse = Nothing
            , aorMessage = message
            }

placeOrderForSignalPlatform :: Args -> LatestSignal -> Maybe BinanceEnv -> IO ApiOrderResult
placeOrderForSignalPlatform args sig mBinanceEnv =
    if argDryRun args
        then pure (dryRunOrderResult args sig)
        else case argPlatform args of
            PlatformBinance ->
                case (argBinanceSymbol args, mBinanceEnv) of
                    (Nothing, _) -> pure (noOrderResult "No order: missing binanceSymbol.")
                    (_, Nothing) -> pure (noOrderResult "No order: missing Binance environment (use binanceSymbol data source).")
                    (Just sym, Just env) -> placeOrderForSignal args sym sig env
            PlatformCoinbase ->
                case argBinanceSymbol args of
                    Nothing -> pure (noOrderResult "No order: missing symbol.")
                    Just sym -> do
                        envOrErr <- try (makeCoinbaseEnv args) :: IO (Either SomeException CoinbaseEnv)
                        case envOrErr of
                            Left ex -> pure (noOrderResult ("No order: " ++ take 240 (show ex)))
                            Right env -> placeCoinbaseOrderForSignal args sym sig env
            PlatformUniswap -> placeDexOrderForSignal args sig
            PlatformCurve -> placeDexOrderForSignal args sig
            PlatformSushiswap -> placeDexOrderForSignal args sig
            PlatformBalancer -> placeDexOrderForSignal args sig
            PlatformPancakeswap -> placeDexOrderForSignal args sig
            PlatformOneInch -> placeDexOrderForSignal args sig
            _ -> pure (noOrderResult "No order: trading is supported on Binance, Coinbase, and supported DEX platforms only.")

placeDexOrderForSignal :: Args -> LatestSignal -> IO ApiOrderResult
placeDexOrderForSignal args sig = do
    let baseResult =
            ApiOrderResult
                { aorSent = False
                , aorMode = Just "dex"
                , aorSide = Nothing
                , aorSymbol = argBinanceSymbol args
                , aorQuantity = Nothing
                , aorQuoteQuantity = Nothing
                , aorOrderId = Nothing
                , aorClientOrderId = Nothing
                , aorStatus = Nothing
                , aorExecutedQty = Nothing
                , aorCummulativeQuoteQty = Nothing
                , aorTxHash = Nothing
                , aorResponse = Nothing
                , aorMessage = ""
                }
        noOrder msg = pure baseResult{aorMessage = msg}
        neutralMsg =
            case lsMethod sig of
                MethodBoth -> "No order: directions disagree or neutral (direction gate)."
                MethodKalmanOnly -> "No order: Kalman neutral (within threshold)."
                MethodKalmanPhysicsError -> "No order: Kalman neutral (within threshold)."
                MethodLstmOnly -> "No order: LSTM neutral (within threshold)."
                MethodBlend -> "No order: Blend neutral (within threshold)."
                MethodConfBlend -> "No order: Conf blend neutral (within threshold)."
                MethodConfPick -> "No order: Conf pick neutral (within threshold)."
                MethodConformalClip -> "No order: Conformal clip neutral (within threshold)."
                MethodCostPick -> "No order: Cost pick neutral (within threshold)."
                MethodHarmonicBlend -> "No order: Harmonic blend neutral (within threshold)."
                MethodDisagreementGuard -> "No order: Disagreement guard neutral (within threshold)."
                MethodMedianBlend -> "No order: Median blend neutral (within threshold)."
                MethodNeutralGuard -> "No order: Neutral guard neutral (within threshold)."
                MethodRiskParityBlend -> "No order: Risk parity blend neutral (within threshold)."
                MethodConsensusBoost -> "No order: Consensus boost neutral (within threshold)."
                MethodAnchorBlend -> "No order: Anchor blend neutral (within threshold)."
                MethodTensionGate -> "No order: Tension gate neutral (within threshold)."
                MethodEntropyBlend -> "No order: Entropy blend neutral (within threshold)."
                MethodCoherenceGate -> "No order: Coherence gate neutral (within threshold)."
                MethodDivergenceGate -> "No order: Divergence gate neutral (within threshold)."
                MethodFractalBlend -> "No order: Fractal blend neutral (within threshold)."
                MethodPhaseCancel -> "No order: Phase cancel neutral (within threshold)."
                MethodSoftmaxBlend -> "No order: Softmax blend neutral (within threshold)."
                MethodSmoothSoftmaxBlend -> "No order: Smooth softmax blend neutral (within threshold)."
                MethodHedgeBlend -> "No order: Hedge blend neutral (within threshold)."
                MethodNetSoftmaxBlend -> "No order: Net softmax blend neutral (within threshold)."
                MethodEdgeBlend -> "No order: Edge blend neutral (within threshold)."
                MethodEdgePick -> "No order: Edge pick neutral (within threshold)."
                MethodGeoBlend -> "No order: Geo blend neutral (within threshold)."
                MethodRegimeSwitch -> "No order: Regime switch neutral (within threshold)."
                MethodRouter -> "No order: Router neutral (score/threshold)."
                MethodBanditRouter -> "No order: Bandit router neutral (score/threshold)."
        currentPrice = lsCurrentPrice sig
        entryScale = entryScaleForSignal args MarketSpot sig
        exitScale = maybe 1 clamp01 (lsExitSize sig)
    case argOrderQuoteFraction args of
        Just f | f > 0 -> noOrder "No order: orderQuoteFraction is not supported for DEX trades."
        _ ->
            case lsChosenDir sig of
                Nothing -> noOrder neutralMsg
                Just dir -> do
                    envOrErr <- resolveDexEnv (argDexChainId args) (Just (argDexAutoApprove args))
                    case envOrErr of
                        Left err -> noOrder ("No order: " ++ err)
                        Right env -> do
                            let protocols = argDexProtocols args <|> deProtocols env
                            case resolveDexTokenInputs args of
                                Left err -> noOrder ("No order: " ++ err)
                                Right (baseRaw, quoteRaw) -> do
                                    tokensOrErr <- resolveDexTokens env baseRaw quoteRaw (argDexBaseDecimals args) (argDexQuoteDecimals args)
                                    case tokensOrErr of
                                        Left err -> noOrder ("No order: " ++ err)
                                        Right (baseTok, quoteTok) -> do
                                            let symbolLabel = buildDexSymbolLabel baseTok quoteTok
                                                baseOut = baseResult{aorSymbol = Just symbolLabel}
                                            case resolveDexAmount dir (Just currentPrice) entryScale exitScale args of
                                                Left err -> pure baseOut{aorMessage = "No order: " ++ err}
                                                Right (amountInRaw, sideLabel, inputIsQuote) -> do
                                                    let (tokenIn, tokenOut) =
                                                            if inputIsQuote then (quoteTok, baseTok) else (baseTok, quoteTok)
                                                    case tokenAmountToInteger amountInRaw (dtDecimals tokenIn) of
                                                        Left err -> pure baseOut{aorMessage = "No order: " ++ err}
                                                        Right amountInInt -> do
                                                            swapOrErr <- swapDexExactIn env tokenIn tokenOut amountInInt (argSlippage args) protocols
                                                            case swapOrErr of
                                                                Left err -> pure baseOut{aorMessage = "Order failed: " ++ take 240 err}
                                                                Right swap -> do
                                                                    let amountInHuman = amountInRaw
                                                                        outAmountHuman =
                                                                            case dsToAmount swap of
                                                                                Nothing -> Nothing
                                                                                Just n -> Just (integerToTokenAmount n (dtDecimals tokenOut))
                                                                        (qtyOut, quoteOut) =
                                                                            if inputIsQuote
                                                                                then (outAmountHuman, Just amountInHuman)
                                                                                else (Just amountInHuman, outAmountHuman)
                                                                    pure
                                                                        baseOut
                                                                            { aorSent = True
                                                                            , aorSide = Just sideLabel
                                                                            , aorQuantity = qtyOut
                                                                            , aorQuoteQuantity = quoteOut
                                                                            , aorTxHash = Just (dsTxHash swap)
                                                                            , aorResponse = Just (dsResponseBody swap)
                                                                            , aorMessage = "Order sent."
                                                                            }

resolveDexTokenInputs :: Args -> Either String (String, String)
resolveDexTokenInputs args =
    case (argDexBaseToken args, argDexQuoteToken args) of
        (Just base, Just quote) -> Right (trim base, trim quote)
        _ ->
            case argBinanceSymbol args >>= splitDexSymbol of
                Just (base, quote) -> Right (base, quote)
                Nothing -> Left "DEX trades require dexBaseToken/dexQuoteToken or a symbol in BASE/QUOTE form."

splitDexSymbol :: String -> Maybe (String, String)
splitDexSymbol raw =
    let s = trim raw
        splitOn delim =
            case break (== delim) s of
                (a, _ : b) | not (null a) && not (null b) -> Just (a, b)
                _ -> Nothing
     in splitOn '/' <|> splitOn '-'

buildDexSymbolLabel :: DexToken -> DexToken -> String
buildDexSymbolLabel baseTok quoteTok =
    let base = if null (dtSymbol baseTok) then dtAddress baseTok else dtSymbol baseTok
        quote = if null (dtSymbol quoteTok) then dtAddress quoteTok else dtSymbol quoteTok
     in base ++ "/" ++ quote

resolveDexAmount :: Int -> Maybe Double -> Double -> Double -> Args -> Either String (Double, String, Bool)
resolveDexAmount dir mPrice entryScale exitScale args =
    let quoteArg = argOrderQuote args
        qtyArg = argOrderQuantity args
        price = fromMaybe 0 mPrice
        wantPrice = price > 0
        scaled val scale = max 0 (val * scale)
     in case dir of
            1 ->
                let baseQuote =
                        case quoteArg of
                            Just q | q > 0 -> Right q
                            _ ->
                                case qtyArg of
                                    Just q
                                        | q > 0 ->
                                            if wantPrice then Right (q * price) else Left "Missing price to convert orderQuantity to quote amount."
                                    _ -> Left "Provide orderQuote (or orderQuantity) for BUY."
                 in do
                        q <- baseQuote
                        let qScaled = scaled q entryScale
                        if qScaled <= 0 then Left "Quote amount must be > 0." else Right (qScaled, "BUY", True)
            (-1) ->
                let baseQty =
                        case qtyArg of
                            Just q | q > 0 -> Right q
                            _ ->
                                case quoteArg of
                                    Just q
                                        | q > 0 ->
                                            if wantPrice then Right (q / price) else Left "Missing price to convert orderQuote to base amount."
                                    _ -> Left "Provide orderQuantity (or orderQuote) for SELL."
                 in do
                        q <- baseQty
                        let qScaled = scaled q exitScale
                        if qScaled <= 0 then Left "Base amount must be > 0." else Right (qScaled, "SELL", False)
            _ -> Left "No order: neutral direction."

computeTradeFromSeries :: Args -> PriceSeries -> Maybe BinanceEnv -> IO ApiTradeResponse
computeTradeFromSeries args series mBinanceEnv = do
    ensureRuntimeConfig args
    let prices = psClose series
    ensureMinPriceRows args 2 prices
    let lookback = argLookback args
    ensureLookbackRows args lookback prices
    sig <- computeTradeOnlySignal args lookback series mBinanceEnv
    order <- placeOrderForSignalPlatform args sig mBinanceEnv
    pure ApiTradeResponse{atrSignal = sig, atrOrder = order}

truncateString :: Int -> String -> String
truncateString n s =
    if length s <= n then s else take n s ++ "..."

extractHttpStatusCode :: String -> Maybe Int
extractHttpStatusCode msg =
    let go [] = Nothing
        go ('H' : 'T' : 'T' : 'P' : ' ' : rest) =
            let digits = takeWhile isDigit rest
             in readMaybe digits
        go (_ : xs) = go xs
     in go msg

extractJsonObject :: String -> Maybe String
extractJsonObject msg =
    case dropWhile (/= '{') msg of
        [] -> Nothing
        s0 -> go 0 False False [] s0
  where
    go _ _ _ _ [] = Nothing
    go depth inString escaped acc (c : cs)
        | inString =
            let acc' = c : acc
             in if escaped
                    then go depth True False acc' cs
                    else case c of
                        '\\' -> go depth True True acc' cs
                        '"' -> go depth False False acc' cs
                        _ -> go depth True False acc' cs
        | otherwise =
            let acc' = c : acc
             in case c of
                    '"' -> go depth True False acc' cs
                    '{' -> go (depth + 1) False False acc' cs
                    '}'
                        | depth <= 0 -> Nothing
                        | depth == 1 -> Just (reverse acc')
                        | otherwise -> go (depth - 1) False False acc' cs
                    _ -> go depth False False acc' cs

parseCoinbaseError :: String -> (Maybe Int, Maybe String, String)
parseCoinbaseError raw =
    let raw' = truncateString 240 raw
        httpCode = extractHttpStatusCode raw'
        decoded =
            case extractJsonObject raw' of
                Nothing -> Nothing
                Just json ->
                    case eitherDecode (BL.fromStrict (BS.pack json)) :: Either String Aeson.Value of
                        Right (Aeson.Object o) ->
                            case KM.lookup "message" o of
                                Just (Aeson.String t) -> Just (T.unpack t)
                                _ -> Nothing
                        _ -> Nothing
        summary = fromMaybe raw' decoded
     in (httpCode, decoded, summary)

probeBinance :: String -> IO a -> IO ApiBinanceProbe
probeBinance step action = do
    r <- try action
    case r of
        Right _ -> pure (ApiBinanceProbe True False step Nothing Nothing "OK")
        Left ex -> do
            let msg =
                    case (fromException ex :: Maybe IOError) of
                        Just io | isUserError io -> ioeGetErrorString io
                        _ -> show ex
                err = parseBinanceError msg
                code = beiCode err
                m = beiMsg err
                summary = beiSummary err
                isMinNotional = code == Just (-4164) && "order/test" `isInfixOf` step
            pure $
                if isMinNotional
                    then ApiBinanceProbe False True step Nothing Nothing "Trade test skipped: order notional below minNotional (increase order size)."
                    else ApiBinanceProbe False False step code m summary

probeCoinbase :: String -> IO a -> IO ApiBinanceProbe
probeCoinbase step action = do
    r <- try action
    case r of
        Right _ -> pure (ApiBinanceProbe True False step Nothing Nothing "OK")
        Left ex -> do
            let msg =
                    case (fromException ex :: Maybe IOError) of
                        Just io | isUserError io -> ioeGetErrorString io
                        _ -> show ex
                (code, m, summary) = parseCoinbaseError msg
            pure (ApiBinanceProbe False False step code m summary)

binanceEgressIpProbeTimeoutMicros :: Int
binanceEgressIpProbeTimeoutMicros = 1500000

binanceEgressIpProbeUrls :: [String]
binanceEgressIpProbeUrls =
    [ "https://checkip.amazonaws.com"
    , "https://api64.ipify.org"
    , "https://api.ipify.org"
    ]

resolveBinanceEgressIp :: IO (Maybe String)
resolveBinanceEgressIp = do
    mOverride <- lookupEnv "TRADER_BINANCE_EGRESS_IP"
    case mOverride >>= extractPublicIpCandidate of
        Just ip -> pure (Just ip)
        Nothing -> do
            manager <- newManager tlsManagerSettings
            probeUrls manager binanceEgressIpProbeUrls
  where
    probeUrls _ [] = pure Nothing
    probeUrls manager (url : rest) = do
        r <- try (fetchPublicIpFromUrl manager url) :: IO (Either SomeException (Maybe String))
        case r of
            Right (Just ip) -> pure (Just ip)
            _ -> probeUrls manager rest

fetchPublicIpFromUrl :: Manager -> String -> IO (Maybe String)
fetchPublicIpFromUrl manager url = do
    req0 <- parseRequest url
    let req =
            req0
                { method = "GET"
                , requestHeaders = ("Accept", "text/plain") : requestHeaders req0
                , responseTimeout = responseTimeoutMicro binanceEgressIpProbeTimeoutMicros
                }
    resp <- httpLbs req manager
    let code = statusCode (responseStatus resp)
    if code < 200 || code >= 300
        then pure Nothing
        else pure (extractPublicIpCandidate (BS.unpack (BL.toStrict (responseBody resp))))

extractPublicIpCandidate :: String -> Maybe String
extractPublicIpCandidate raw = go (trimString raw)
  where
    go [] = Nothing
    go s@(c : cs)
        | isIpChar c =
            let candidate = takeWhile isIpChar s
             in if looksLikePublicIp candidate then Just candidate else go cs
        | otherwise = go cs

    isIpChar c = isHexDigit c || c == '.' || c == ':'

    looksLikePublicIp candidate =
        not (null candidate)
            && length candidate <= 64
            && any isDigit candidate
            && ('.' `elem` candidate || ':' `elem` candidate)

computeBinanceKeysStatusFromArgs :: Maybe OpsStore -> Maybe (RequestProgressStore, String) -> Args -> IO ApiBinanceKeysStatus
computeBinanceKeysStatusFromArgs mOps mTracker args = do
    apiKey <- resolveEnv "BINANCE_API_KEY" (argBinanceApiKey args)
    apiSecret <- resolveEnv "BINANCE_API_SECRET" (argBinanceApiSecret args)
    egressIp <- resolveBinanceEgressIp

    let hasApiKey = maybe False (not . null . trim) apiKey
        hasApiSecret = maybe False (not . null . trim) apiSecret
        market = argBinanceMarket args
        sym = argBinanceSymbol args
        mSym = normalizeBinanceSymbolForKeys sym
        tenantKey = fmap T.unpack (tenantKeyFromBinanceKeys apiKey apiSecret)
        baseStatus =
            ApiBinanceKeysStatus
                { abkMarket = marketCode market
                , abkTestnet = argBinanceTestnet args
                , abkSymbol = sym
                , abkHasApiKey = hasApiKey
                , abkHasApiSecret = hasApiSecret
                , abkEgressIp = egressIp
                , abkTenantKey = tenantKey
                , abkSigned = Nothing
                , abkTradeTest = Nothing
                }

    if not hasApiKey || not hasApiSecret
        then pure baseStatus
        else do
            env <- makeBinanceEnv mOps args
            advanceRequestProgressMaybe
                mTracker
                "signed probe"
                ( Just
                    ( case market of
                        MarketFutures -> "futures available balance"
                        MarketSpot -> "spot free balance"
                        MarketMargin -> "margin free balance"
                    )
                )
            signedProbe <-
                probeBinance "signed" $ do
                    case market of
                        MarketFutures -> do
                            let quoteAsset = maybe "USDT" (snd . splitSymbol) mSym
                            _ <- fetchFuturesAvailableBalance env quoteAsset
                            pure ()
                        _ -> do
                            sym' <- maybe (throwIO (userError "binanceSymbol is required.")) pure mSym
                            let (baseAsset, _) = splitSymbol sym'
                            _ <- fetchFreeBalance env baseAsset
                            pure ()

            tradeProbe <-
                case market of
                    MarketMargin -> pure Nothing
                    MarketSpot -> do
                        advanceRequestProgressMaybe mTracker "order/test" (Just "order/test")
                        case mSym of
                            Nothing -> pure (Just (mkSkippedProbe "order/test" missingSymbolMsg))
                            Just sym'' -> do
                                let qty =
                                        case argOrderQuantity args of
                                            Just q | q > 0 -> Just q
                                            _ -> Nothing
                                    qqArg =
                                        case argOrderQuote args of
                                            Just q | q > 0 -> Just q
                                            _ -> Nothing
                                qq <-
                                    case (qty, qqArg, argOrderQuoteFraction args) of
                                        (Nothing, Nothing, Just f) | f > 0 -> do
                                            let (_baseAsset, quoteAsset) = splitSymbol sym''
                                            quoteBal <- fetchFreeBalance env quoteAsset
                                            let q0 = quoteBal * f
                                                q0Scaled = q0
                                                q1 =
                                                    let mCap =
                                                            case argMaxOrderQuote args of
                                                                Just q | q > 0 -> Just q
                                                                _ -> Nothing
                                                     in maybe q0Scaled (`min` q0Scaled) mCap
                                            pure (if q1 > 0 then Just q1 else Nothing)
                                        _ -> pure qqArg
                                if isNothing qty && isNothing qq
                                    then pure (Just (mkSkippedProbe "order/test" missingSizingMsg))
                                    else do
                                        (mFilters, mFiltersErr) <- fetchFilters env sym''
                                        case mFilters of
                                            Nothing -> pure (Just (mkSkippedProbe "order/test" (missingFiltersMsgWith mFiltersErr)))
                                            Just _ ->
                                                case qty of
                                                    Nothing ->
                                                        case qq of
                                                            Nothing -> pure (Just (mkSkippedProbe "order/test" missingSizingMsg))
                                                            Just qq0 ->
                                                                case validateProbeQuote mFilters qq0 of
                                                                    Left e -> pure (Just (mkSkippedProbe "order/test" e))
                                                                    Right qq1 -> do
                                                                        let ctx =
                                                                                formatProbeContext
                                                                                    [ ("symbol", Just sym'')
                                                                                    , ("side", Just "BUY")
                                                                                    , ("quote", Just (fmtProbeDouble qq1))
                                                                                    , ("quoteRaw", fmtRawIfDifferent qq0 qq1)
                                                                                    , ("step", fmtStepText (effectiveStep =<< mFilters))
                                                                                    , ("minQty", fmtMaybeProbeDouble (effectiveMinQty =<< mFilters))
                                                                                    , ("minNotional", fmtMaybeProbeDouble (sfMinNotional =<< mFilters))
                                                                                    ]
                                                                        Just . appendProbeContext ctx
                                                                            <$> probeBinance "order/test" (void (placeMarketOrder env OrderTest sym'' Buy qty (Just qq1) Nothing (trim <$> argIdempotencyKey args)))
                                                    Just qRaw -> do
                                                        mPrice <- fetchPriceIfNeeded env sym'' mFilters
                                                        case normalizeProbeQty mFilters mPrice qRaw of
                                                            Left e -> pure (Just (mkSkippedProbe "order/test" e))
                                                            Right q -> do
                                                                let ctx =
                                                                        formatProbeContext
                                                                            [ ("symbol", Just sym'')
                                                                            , ("side", Just "BUY")
                                                                            , ("qty", Just (fmtProbeDouble q))
                                                                            , ("qtyRaw", fmtRawIfDifferent qRaw q)
                                                                            , ("price", fmtMaybeProbeDouble mPrice)
                                                                            , ("step", fmtStepText (effectiveStep =<< mFilters))
                                                                            , ("minQty", fmtMaybeProbeDouble (effectiveMinQty =<< mFilters))
                                                                            , ("minNotional", fmtMaybeProbeDouble (sfMinNotional =<< mFilters))
                                                                            ]
                                                                Just . appendProbeContext ctx
                                                                    <$> probeBinance "order/test" (void (placeMarketOrder env OrderTest sym'' Buy (Just q) qq Nothing (trim <$> argIdempotencyKey args)))
                    MarketFutures -> do
                        advanceRequestProgressMaybe mTracker "order/test" (Just "futures/order/test")
                        case mSym of
                            Nothing -> pure (Just (mkSkippedProbe "futures/order/test" missingSymbolMsg))
                            Just sym'' -> do
                                let qtyFromArgs =
                                        case argOrderQuantity args of
                                            Just q | q > 0 -> Just q
                                            _ -> Nothing
                                case qtyFromArgs of
                                    Just qRaw -> do
                                        (mFilters, mFiltersErr) <- fetchFilters env sym''
                                        case mFilters of
                                            Nothing -> pure (Just (mkSkippedProbe "futures/order/test" (missingFiltersMsgWith mFiltersErr)))
                                            Just _ -> do
                                                mPrice <- fetchPriceIfNeeded env sym'' mFilters
                                                case normalizeProbeQty mFilters mPrice qRaw of
                                                    Left e -> pure (Just (mkSkippedProbe "futures/order/test" e))
                                                    Right q -> do
                                                        let ctx =
                                                                formatProbeContext
                                                                    [ ("symbol", Just sym'')
                                                                    , ("side", Just "BUY")
                                                                    , ("qty", Just (fmtProbeDouble q))
                                                                    , ("qtyRaw", fmtRawIfDifferent qRaw q)
                                                                    , ("price", fmtMaybeProbeDouble mPrice)
                                                                    , ("step", fmtStepText (effectiveStep =<< mFilters))
                                                                    , ("minQty", fmtMaybeProbeDouble (effectiveMinQty =<< mFilters))
                                                                    , ("minNotional", fmtMaybeProbeDouble (sfMinNotional =<< mFilters))
                                                                    ]
                                                        Just . appendProbeContext ctx
                                                            <$> probeBinance "futures/order/test" (void (placeMarketOrder env OrderTest sym'' Buy (Just q) Nothing Nothing (trim <$> argIdempotencyKey args)))
                                    Nothing -> do
                                        qq <-
                                            case argOrderQuote args of
                                                Just qq | qq > 0 -> pure (Just qq)
                                                _ ->
                                                    case argOrderQuoteFraction args of
                                                        Just f | f > 0 -> do
                                                            let (_baseAsset, quoteAsset) = splitSymbol sym''
                                                            bal <- fetchFuturesAvailableBalance env quoteAsset
                                                            let q0 = bal * f
                                                                q0Scaled = q0
                                                                q1 =
                                                                    let mCap =
                                                                            case argMaxOrderQuote args of
                                                                                Just q | q > 0 -> Just q
                                                                                _ -> Nothing
                                                                     in maybe q0Scaled (`min` q0Scaled) mCap
                                                            pure (if q1 > 0 then Just q1 else Nothing)
                                                        _ -> pure Nothing
                                        case qq of
                                            Nothing -> pure (Just (mkSkippedProbe "futures/order/test" missingSizingMsg))
                                            Just qq0 -> do
                                                (mFilters, mFiltersErr) <- fetchFilters env sym''
                                                case mFilters of
                                                    Nothing -> pure (Just (mkSkippedProbe "futures/order/test" (missingFiltersMsgWith mFiltersErr)))
                                                    Just _ ->
                                                        case validateProbeQuote mFilters qq0 of
                                                            Left e -> pure (Just (mkSkippedProbe "futures/order/test" e))
                                                            Right qq1 -> do
                                                                mPrice <- fetchPriceMaybe env sym''
                                                                case mPrice of
                                                                    Nothing -> pure (Just (mkSkippedProbe "futures/order/test" "Price unavailable for quote sizing."))
                                                                    Just price -> do
                                                                        let qRaw = qq1 / price
                                                                        case normalizeProbeQty mFilters (Just price) qRaw of
                                                                            Left e -> pure (Just (mkSkippedProbe "futures/order/test" e))
                                                                            Right q -> do
                                                                                let ctx =
                                                                                        formatProbeContext
                                                                                            [ ("symbol", Just sym'')
                                                                                            , ("side", Just "BUY")
                                                                                            , ("qty", Just (fmtProbeDouble q))
                                                                                            , ("qtyRaw", fmtRawIfDifferent qRaw q)
                                                                                            , ("quote", Just (fmtProbeDouble qq1))
                                                                                            , ("quoteRaw", fmtRawIfDifferent qq0 qq1)
                                                                                            , ("price", fmtMaybeProbeDouble (Just price))
                                                                                            , ("step", fmtStepText (effectiveStep =<< mFilters))
                                                                                            , ("minQty", fmtMaybeProbeDouble (effectiveMinQty =<< mFilters))
                                                                                            , ("minNotional", fmtMaybeProbeDouble (sfMinNotional =<< mFilters))
                                                                                            ]
                                                                                Just . appendProbeContext ctx
                                                                                    <$> probeBinance "futures/order/test" (void (placeMarketOrder env OrderTest sym'' Buy (Just q) Nothing Nothing (trim <$> argIdempotencyKey args)))

            let normalizeTradeProbe p
                    | abpOk p || abpSkipped p || not (abpOk signedProbe) = p
                    | binanceTradeTestConfirmsAuth (abpCode p) (abpSummary p) =
                        p{abpOk = True, abpSummary = "Auth OK, but order rejected: " ++ abpSummary p}
                    | otherwise = p
            pure baseStatus{abkSigned = Just signedProbe, abkTradeTest = normalizeTradeProbe <$> tradeProbe}
  where
    missingSizingMsg =
        if isJust (argOrderQuoteFraction args)
            then "Provide orderQuantity/orderQuote, or set orderQuoteFraction with sufficient quote balance."
            else "Provide orderQuantity or orderQuote."
    missingSymbolMsg = "Provide binanceSymbol for the trade test."
    missingFiltersMsg = "Exchange info unavailable (cannot validate precision)."
    missingFiltersMsgWith mDetail =
        case mDetail >>= nonEmptyTrim of
            Nothing -> missingFiltersMsg
            Just detail -> missingFiltersMsg ++ ": " ++ detail

    normalizeBinanceSymbolForKeys raw =
        let sanitized = raw >>= sanitizeComboSymbolForPlatform (Just "binance")
         in case sanitized of
                Just _ -> sanitized
                Nothing ->
                    case fmap trim raw of
                        Nothing -> Nothing
                        Just s ->
                            let s' = map toUpper (filter isAlphaNum s)
                             in if length s' < 3 || length s' > 30 then Nothing else Just s'

    mkSkippedProbe step reason =
        ApiBinanceProbe False True step Nothing Nothing ("Trade test skipped: " ++ reason)

    fetchFilters env sym = do
        r <- try (fetchSymbolFilters env sym) :: IO (Either SomeException SymbolFilters)
        pure $
            case r of
                Right sf -> (Just sf, Nothing)
                Left ex -> (Nothing, Just (summarizeExchangeInfoError ex))

    summarizeExchangeInfoError ex =
        let msg =
                case (fromException ex :: Maybe IOError) of
                    Just io | isUserError io -> ioeGetErrorString io
                    _ -> show ex
            summary = beiSummary (parseBinanceError msg)
            flattened = map (\c -> if c == '\n' || c == '\r' then ' ' else c) summary
         in truncateString 240 (trim flattened)

    fetchPriceMaybe env sym = do
        let attempt action = do
                r <- try action :: IO (Either SomeException Double)
                pure $
                    case r of
                        Right price | price > 0 -> Just price
                        _ -> Nothing
            attemptKlineClose = do
                r <- try (fetchKlines env sym "1m" 1) :: IO (Either SomeException [Kline])
                pure $
                    case r of
                        Right (k : _) | kClose k > 0 -> Just (kClose k)
                        _ -> Nothing
        primary <- attempt (fetchTickerPrice env sym)
        case primary of
            Just _ -> pure primary
            Nothing -> do
                markPrice <-
                    case beMarket env of
                        MarketFutures -> attempt (fetchFuturesMarkPrice env sym)
                        _ -> pure Nothing
                case markPrice of
                    Just _ -> pure markPrice
                    Nothing -> do
                        last24h <- attempt (fetchTicker24hPrice env sym)
                        case last24h of
                            Just _ -> pure last24h
                            Nothing -> attemptKlineClose

    fetchPriceIfNeeded env sym mSf =
        case mSf >>= sfMinNotional of
            Nothing -> pure Nothing
            Just _ -> fetchPriceMaybe env sym

    effectiveStep sf = sfMarketStepSize sf <|> sfLotStepSize sf
    effectiveMinQty sf = sfMarketMinQty sf <|> sfLotMinQty sf
    effectiveMaxQty sf = sfMarketMaxQty sf <|> sfLotMaxQty sf

    fmtProbeDouble :: Double -> String
    fmtProbeDouble = trimTrailingZeros . printf "%.8f"

    fmtMaybeProbeDouble :: Maybe Double -> Maybe String
    fmtMaybeProbeDouble = fmap fmtProbeDouble

    fmtStepText :: Maybe Step -> Maybe String
    fmtStepText = fmap (T.unpack . stepText)

    fmtRawIfDifferent :: Double -> Double -> Maybe String
    fmtRawIfDifferent raw used =
        if abs (raw - used) > 1e-9 then Just (fmtProbeDouble raw) else Nothing

    formatProbeContext :: [(String, Maybe String)] -> Maybe String
    formatProbeContext fields =
        let parts = [k ++ "=" ++ v | (k, Just v) <- fields, not (null v)]
         in if null parts then Nothing else Just ("order: " ++ intercalate ", " parts)

    appendProbeContext :: Maybe String -> ApiBinanceProbe -> ApiBinanceProbe
    appendProbeContext Nothing p = p
    appendProbeContext (Just ctx) p
        | abpOk p || abpSkipped p = p
        | otherwise =
            p{abpSummary = truncateString 360 (abpSummary p ++ " (" ++ ctx ++ ")")}

    trimTrailingZeros :: String -> String
    trimTrailingZeros s =
        case break (== '.') s of
            (a, "") -> a
            (a, '.' : b) ->
                let b' = reverse (dropWhile (== '0') (reverse b))
                 in if null b' then a else a ++ "." ++ b'
            _ -> s

    quantizeUp :: Step -> Double -> Double
    quantizeUp st x
        | x <= 0 = 0
        | otherwise =
            let scaleD = fromIntegral (stepScale st) :: Double
                scaled = ceiling (x * scaleD - 1e-9) :: Integer
                stepI = stepInt st
                q = ((scaled + stepI - 1) `div` stepI) * stepI
             in fromIntegral q / scaleD

    validateProbeQuote mSf qq =
        if qq <= 0
            then Left "Quote is 0."
            else case mSf >>= sfMinNotional of
                Just mn | qq < mn -> Right mn
                _ -> Right qq

    normalizeProbeQty mSf mPrice qtyRaw =
        case mSf of
            Nothing ->
                if qtyRaw > 0
                    then Right qtyRaw
                    else Left "Quantity is 0."
            Just sf ->
                let qty0 = max 0 qtyRaw
                    qty1 = maybe qty0 (`quantizeDown` qty0) (effectiveStep sf)
                    qty2 =
                        case (mPrice, sfMinNotional sf) of
                            (Just price, Just mn)
                                | price > 0 && qty1 * price < mn ->
                                    let minQ = mn / price
                                     in maybe minQ (`quantizeUp` minQ) (effectiveStep sf)
                            _ -> qty1
                 in if qty2 <= 0
                        then Left "Quantity rounds to 0."
                        else case effectiveMinQty sf of
                            Just minQ | qty2 < minQ -> Left ("Quantity below minQty (" ++ show minQ ++ ").")
                            _ ->
                                case effectiveMaxQty sf of
                                    Just maxQ | qty2 > maxQ -> Left ("Quantity above maxQty (" ++ show maxQ ++ ").")
                                    _ ->
                                        case (mPrice, sfMinNotional sf) of
                                            (Just price, Just mn) | price > 0 && qty2 * price < mn -> Left ("Notional below minNotional (" ++ show mn ++ ").")
                                            _ -> Right qty2

computeCoinbaseKeysStatusFromArgs :: Args -> IO ApiCoinbaseKeysStatus
computeCoinbaseKeysStatusFromArgs args = do
    apiKeyRaw <- resolveEnv "COINBASE_API_KEY" (argCoinbaseApiKey args)
    apiSecretRaw <- resolveEnv "COINBASE_API_SECRET" (argCoinbaseApiSecret args)
    apiPassphraseRaw <- resolveEnv "COINBASE_API_PASSPHRASE" (argCoinbaseApiPassphrase args)

    let cleanKey v =
            case fmap trim v of
                Just "" -> Nothing
                other -> other
        apiKey = cleanKey apiKeyRaw
        apiSecret = cleanKey apiSecretRaw
        apiPassphrase = cleanKey apiPassphraseRaw
        hasApiKey = isJust apiKey
        hasApiSecret = isJust apiSecret
        hasApiPassphrase = isJust apiPassphrase
        tenantKey = fmap T.unpack (tenantKeyFromCoinbaseKeys apiKey apiSecret apiPassphrase)
        baseStatus =
            ApiCoinbaseKeysStatus
                { ackHasApiKey = hasApiKey
                , ackHasApiSecret = hasApiSecret
                , ackHasApiPassphrase = hasApiPassphrase
                , ackTenantKey = tenantKey
                , ackSigned = Nothing
                }

    if not (hasApiKey && hasApiSecret && hasApiPassphrase)
        then pure baseStatus
        else do
            env <- newCoinbaseEnv (BS.pack <$> apiKey) (BS.pack <$> apiSecret) (BS.pack <$> apiPassphrase)
            signedProbe <- probeCoinbase "signed" (void (fetchCoinbaseAccounts env))
            pure baseStatus{ackSigned = Just signedProbe}

data BinanceOrderInfo = BinanceOrderInfo
    { boiOrderId :: !(Maybe Int64)
    , boiClientOrderId :: !(Maybe String)
    , boiStatus :: !(Maybe String)
    , boiExecutedQty :: !(Maybe Double)
    , boiCummulativeQuoteQty :: !(Maybe Double)
    }
    deriving (Eq, Show)

instance FromJSON BinanceOrderInfo where
    parseJSON =
        Aeson.withObject "BinanceOrderInfo" $ \o -> do
            oid <- o Aeson..:? "orderId"
            cid <- o Aeson..:? "clientOrderId"
            st <- o Aeson..:? "status"
            exec <- parseMaybeDoubleField o "executedQty"
            cum <-
                parseMaybeDoubleField o "cummulativeQuoteQty"
                    <|> parseMaybeDoubleField o "cumQuote"
                    <|> parseMaybeDoubleField o "cumQuoteQty"
            pure BinanceOrderInfo{boiOrderId = oid, boiClientOrderId = cid, boiStatus = st, boiExecutedQty = exec, boiCummulativeQuoteQty = cum}
      where
        parseMaybeDoubleField o k = do
            mv <- o Aeson..:? k :: AT.Parser (Maybe Aeson.Value)
            case mv of
                Nothing -> pure Nothing
                Just v -> Just <$> parseJsonDouble v

        parseJsonDouble v =
            case v of
                Aeson.String t ->
                    case readMaybe (T.unpack t) of
                        Just d -> pure d
                        Nothing -> fail ("Failed to parse double: " ++ T.unpack t)
                Aeson.Number n -> pure (realToFrac n)
                _ -> fail "Expected number or string"

decodeOrderInfo :: BL.ByteString -> Maybe BinanceOrderInfo
decodeOrderInfo raw =
    case Aeson.decode raw of
        Nothing -> Nothing
        Just v -> AT.parseMaybe parseJSON v

applyOrderInfo :: BinanceOrderInfo -> ApiOrderResult -> ApiOrderResult
applyOrderInfo info r =
    r
        { aorOrderId = boiOrderId info <|> aorOrderId r
        , aorClientOrderId = boiClientOrderId info <|> aorClientOrderId r
        , aorStatus = boiStatus info <|> aorStatus r
        , aorExecutedQty = boiExecutedQty info <|> aorExecutedQty r
        , aorCummulativeQuoteQty = boiCummulativeQuoteQty info <|> aorCummulativeQuoteQty r
        }

lstmConfidenceScore :: Args -> LatestSignal -> Maybe Double
lstmConfidenceScore args sig = do
    next <- lsSizingNext sig
    let cur = lsCurrentPrice sig
        sizeRef = max 1e-6 (max 0 (fromMaybe (argMaxPositionSize args) (lsPositionSize sig)))
        volPerBar = volPerBarFromSignal args sig
        perSideCost = estimatedPerSideCost args sizeRef volPerBar
        minEdgeBase = max 0 (argMinEdge args)
        minEdge =
            if argCostAwareEdge args
                then max minEdgeBase (breakEvenThresholdFromPerSideCost perSideCost + max 0 (argEdgeBuffer args))
                else minEdgeBase
        thr = max 1e-12 (max (max 0 (argOpenThreshold args)) minEdge)
        bad x = isNaN x || isInfinite x
    if cur <= 0 || bad cur || bad next
        then Nothing
        else
            let edge = abs (next / cur - 1)
                raw = edge / (2 * thr)
             in if bad edge || bad raw
                    then Nothing
                    else Just (max 0 (min 1 raw))

lstmConfidenceSizing :: Args -> LatestSignal -> (Double, Maybe String)
lstmConfidenceSizing args sig =
    if argVolConfGate args /= VolConfGateDisabled || not (argConfidenceSizing args)
        then (1, Nothing)
        else
            let hard0 = clamp01 (argLstmConfidenceHard args)
                soft0 = clamp01 (argLstmConfidenceSoft args)
                hard = hard0
                soft = min soft0 hard
                denom = max 1e-12 (hard - soft)
             in if hard <= 0
                    then (1, Nothing)
                    else case lstmConfidenceScore args sig of
                        Nothing -> (1, Nothing)
                        Just score ->
                            let scaleRaw
                                    | score <= soft = 0
                                    | score >= hard = 1
                                    | otherwise = (score - soft) / denom
                                scale = clamp01 scaleRaw
                             in if scale <= 0
                                    then
                                        ( 0
                                        , Just (printf "No order: LSTM confidence %.1f%% (<%.1f%%)." (score * 100) (soft * 100))
                                        )
                                    else (scale, Nothing)

scale01 :: Double -> Double -> Double -> Double
scale01 lo hi x =
    let lo' = min lo hi
        hi' = max lo hi
     in if hi' <= lo' + 1e-12
            then if x >= hi' then 1 else 0
            else clamp01 ((x - lo') / (hi' - lo'))

lstmConfidenceScoreFromPred :: Double -> Double -> Double -> Maybe Double
lstmConfidenceScoreFromPred openThr prev next =
    let bad x = isNaN x || isInfinite x
        thr = max 1e-12 openThr
     in if prev <= 0 || bad prev || bad next
            then Nothing
            else
                let edge = abs (next / prev - 1)
                    raw = edge / (2 * thr)
                 in if bad edge || bad raw
                        then Nothing
                        else Just (clamp01 raw)

kalmanZFromMeta :: StepMeta -> Maybe Double
kalmanZFromMeta m =
    let v = max 0 (smKalmanVar m)
        s = sqrt v
        z = if s <= 0 then 0 else abs (smKalmanMean m) / s
     in if isNaN z || isInfinite z then Nothing else Just z

confidenceBlendWeightFromPreds ::
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Maybe Double ->
    Double
confidenceBlendWeightFromPreds fallbackWeight zMin zMax openThr prev kalPred lstmPred mKalZ =
    let wFallback = clamp01 fallbackWeight
        kalScore =
            case mKalZ of
                Just z | not (isNaN z || isInfinite z) -> scale01 zMin zMax z
                _ -> fromMaybe 0 (lstmConfidenceScoreFromPred openThr prev kalPred)
        lstmScore = fromMaybe 0 (lstmConfidenceScoreFromPred openThr prev lstmPred)
        denom = kalScore + lstmScore
     in if denom <= 1e-12
            then wFallback
            else clamp01 (kalScore / denom)

confidenceBlendPredFromPreds ::
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Maybe Double ->
    Double
confidenceBlendPredFromPreds fallbackWeight zMin zMax openThr prev kalPred lstmPred mKalZ =
    let bad x = isNaN x || isInfinite x
        wFallback = clamp01 fallbackWeight
     in case (bad kalPred, bad lstmPred) of
            (False, False) ->
                let w = confidenceBlendWeightFromPreds fallbackWeight zMin zMax openThr prev kalPred lstmPred mKalZ
                 in w * kalPred + (1 - w) * lstmPred
            (False, True) -> kalPred
            (True, False) -> lstmPred
            (True, True) -> finiteBlendOrNeutral wFallback prev kalPred lstmPred

confidenceBlendPredictionsV ::
    Double ->
    Double ->
    Double ->
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    Maybe (V.Vector StepMeta) ->
    V.Vector Double
confidenceBlendPredictionsV fallbackWeight zMin zMax openThr pricesV kalPredV lstmPredV mMetaV =
    let stepCount = minimum [V.length pricesV - 1, V.length kalPredV, V.length lstmPredV]
        kalZAt t =
            case mMetaV of
                Just metaV
                    | t >= 0 && t < V.length metaV ->
                        kalmanZFromMeta (metaV V.! t)
                _ -> Nothing
        pick t =
            let prev = pricesV V.! t
                kalPred = kalPredV V.! t
                lstmPred = lstmPredV V.! t
             in confidenceBlendPredFromPreds fallbackWeight zMin zMax openThr prev kalPred lstmPred (kalZAt t)
     in V.generate (max 0 stepCount) pick

confidencePickPredFromPreds ::
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Maybe Double ->
    Double
confidencePickPredFromPreds fallbackWeight zMin zMax openThr prev kalPred lstmPred mKalZ =
    let bad x = isNaN x || isInfinite x
     in case (bad kalPred, bad lstmPred) of
            (False, False) ->
                let w = confidenceBlendWeightFromPreds fallbackWeight zMin zMax openThr prev kalPred lstmPred mKalZ
                 in if w >= 0.5 then kalPred else lstmPred
            (False, True) -> kalPred
            (True, False) -> lstmPred
            (True, True) ->
                let wFallback = clamp01 fallbackWeight
                 in finiteBlendOrNeutral wFallback prev kalPred lstmPred

