        pick t =
            let prev = pricesV V.! t
                kalPred = kalPredV V.! t
                lstmPred = lstmPredV V.! t
             in geometricBlendPredFromPreds fallbackWeight prev kalPred lstmPred
     in V.generate (max 0 stepCount) pick

regimeSwitchPredFromPreds ::
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Double ->
    Maybe StepMeta ->
    Double
regimeSwitchPredFromPreds fallbackWeight highVolCutoff kalZCutoff prev kalPred lstmPred mMeta =
    let bad x = isNaN x || isInfinite x
        blend = blendPredFromPreds fallbackWeight prev kalPred lstmPred
        kalZMeta = mMeta >>= kalmanZFromMeta
        hvMeta = mMeta >>= smHighVolProb
     in case (bad kalPred, bad lstmPred) of
            (False, False) ->
                case (kalZMeta, hvMeta) of
                    (Just _, Just hv) | hv >= highVolCutoff -> blend
                    (Just z, _) | z >= kalZCutoff -> kalPred
                    _ -> lstmPred
            (False, True) -> kalPred
            (True, False) -> lstmPred
            (True, True) -> blend

regimeSwitchPredictionsV ::
    Double ->
    Double ->
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    Maybe (V.Vector StepMeta) ->
    V.Vector Double
regimeSwitchPredictionsV fallbackWeight highVolCutoff kalZCutoff pricesV kalPredV lstmPredV mMetaV =
    let stepCount = minimum [V.length pricesV - 1, V.length kalPredV, V.length lstmPredV]
        metaAt t =
            case mMetaV of
                Just metaV
                    | t >= 0 && t < V.length metaV -> Just (metaV V.! t)
                _ -> Nothing
        pick t =
            let prev = pricesV V.! t
                kalPred = kalPredV V.! t
                lstmPred = lstmPredV V.! t
             in regimeSwitchPredFromPreds fallbackWeight highVolCutoff kalZCutoff prev kalPred lstmPred (metaAt t)
     in V.generate (max 0 stepCount) pick

conformalClipBoundsFromMeta :: StepMeta -> Maybe (Double, Double)
conformalClipBoundsFromMeta m =
    let bad x = isNaN x || isInfinite x
     in case (smConformalLo m, smConformalHi m) of
            (Just lo, Just hi) | not (bad lo || bad hi) -> Just (lo, hi)
            _ ->
                case (smQuantile10 m, smQuantile90 m) of
                    (Just lo, Just hi) | not (bad lo || bad hi) -> Just (lo, hi)
                    _ -> Nothing

conformalClipPredFromPreds ::
    Double ->
    Double ->
    Double ->
    Double ->
    Maybe (Double, Double) ->
    Double
conformalClipPredFromPreds fallbackWeight prev kalPred lstmPred mBounds =
    let bad x = isNaN x || isInfinite x
        w = clamp01 fallbackWeight
        cand0 =
            case (bad kalPred, bad lstmPred) of
                (False, False) ->
                    let v = w * kalPred + (1 - w) * lstmPred
                     in if bad v then kalPred else v
                (False, True) -> kalPred
                (True, False) -> lstmPred
                (True, True) -> prev
        cand = if bad cand0 then prev else cand0
     in if prev <= 0 || bad prev || bad cand
            then cand
            else
                let rCand = cand / prev - 1
                 in case mBounds of
                        Just (lo0, hi0) ->
                            let rClipped = clampRange lo0 hi0 rCand
                                rSafe = max (-0.999999) rClipped
                                pred = prev * (1 + rSafe)
                             in if bad pred then cand else pred
                        Nothing -> cand

conformalClipPredictionsV ::
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    Maybe (V.Vector StepMeta) ->
    V.Vector Double
conformalClipPredictionsV fallbackWeight pricesV kalPredV lstmPredV mMetaV =
    let stepCount = minimum [V.length pricesV - 1, V.length kalPredV, V.length lstmPredV]
        boundsAt t =
            case mMetaV of
                Just metaV
                    | t >= 0 && t < V.length metaV ->
                        conformalClipBoundsFromMeta (metaV V.! t)
                _ -> Nothing
        pick t =
            let prev = pricesV V.! t
                kalPred = kalPredV V.! t
                lstmPred = lstmPredV V.! t
             in conformalClipPredFromPreds fallbackWeight prev kalPred lstmPred (boundsAt t)
     in V.generate (max 0 stepCount) pick

hedgeBlendPredictionsV ::
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double
hedgeBlendPredictionsV initWeight pricesV kalPredV lstmPredV =
    let stepCount = minimum [V.length pricesV - 1, V.length kalPredV, V.length lstmPredV]
        bad x = isNaN x || isInfinite x
        w0Raw = clamp01 initWeight
        epsW = 1e-6
        w0 = max epsW (min (1 - epsW) (if bad w0Raw then 0.5 else w0Raw))
        logit p = log (p / (1 - p))
        sigmoid z
            | z >= 30 = 1
            | z <= (-30) = 0
            | otherwise = 1 / (1 + exp (negate z))
        eta = 6.0
        maxErr = 0.1
        safePred w prev kalPred lstmPred =
            case (bad kalPred, bad lstmPred) of
                (False, False) ->
                    let v = w * kalPred + (1 - w) * lstmPred
                        fallback = finiteBlendOrNeutral w0 prev kalPred lstmPred
                     in if bad v then fallback else v
                (False, True) -> kalPred
                (True, False) -> lstmPred
                (True, True) ->
                    neutralPredFromPrev prev
        ret prev x =
            if prev <= 0 || bad prev || bad x
                then Nothing
                else
                    let r = x / prev - 1
                     in if bad r then Nothing else Just r
        lossFromR rPred rReal =
            let e = abs (rPred - rReal)
                e' = min maxErr (max 0 e)
             in if bad e' then maxErr else e'
        updateZ z prev actual kalPred lstmPred =
            case ret prev actual of
                Nothing -> z
                Just rReal ->
                    let mRKal = ret prev kalPred
                        mRLstm = ret prev lstmPred
                        lKal = maybe maxErr (`lossFromR` rReal) mRKal
                        lLstm = maybe maxErr (`lossFromR` rReal) mRLstm
                        z' = z - eta * (lKal - lLstm)
                     in if bad z' then z else z'
        step (t, z) =
            if t >= stepCount
                then Nothing
                else
                    let prev = pricesV V.! t
                        actual = pricesV V.! (t + 1)
                        kalPred = kalPredV V.! t
                        lstmPred = lstmPredV V.! t
                        w = sigmoid z
                        pred = safePred w prev kalPred lstmPred
                        z' = updateZ z prev actual kalPred lstmPred
                     in Just (pred, (t + 1, z'))
     in V.unfoldrN (max 0 stepCount) step (0, logit w0)

clampRange :: Double -> Double -> Double -> Double
clampRange lo hi x =
    let lo' = min lo hi
        hi' = max lo hi
     in max lo' (min hi' x)

intervalWidth :: Interval -> Double
intervalWidth i = iHi i - iLo i

quantileWidth :: Quantiles -> Double
quantileWidth q = q90 q - q10 q

confirmConformal :: Args -> Double -> Maybe Interval -> Int -> Bool
confirmConformal args thr mI dir =
    (not (argConfirmConformal args) || not (predictorEnabled (argPredictors args) SensorConformal))
        || ( case (mI, dir) of
                (Just i, 1) -> iLo i > thr
                (Just i, -1) -> iHi i < negate thr
                _ -> False
           )

confirmQuantiles :: Args -> Double -> Maybe Quantiles -> Int -> Bool
confirmQuantiles args thr mQ dir =
    (not (argConfirmQuantiles args) || not (predictorEnabled (argPredictors args) SensorQuantile))
        || ( case (mQ, dir) of
                (Just q, 1) -> q10 q > thr
                (Just q, -1) -> q90 q < negate thr
                _ -> False
           )

gateKalmanDir ::
    Args ->
    Bool ->
    Double ->
    Double ->
    Maybe RegimeProbs ->
    Maybe Interval ->
    Maybe Quantiles ->
    Double ->
    Maybe Int ->
    (Maybe Int, Maybe String)
gateKalmanDir args useSizing thr kalZ mReg mI mQ confScore dirRaw =
    case dirRaw of
        Nothing -> (Nothing, Nothing)
        Just dir ->
            let effectiveUseSizing = useSizing && argVolConfGate args == VolConfGateDisabled
                zMin = max 0 (argKalmanZMin args)
                hvOk =
                    ( not (predictorEnabled (argPredictors args) SensorHMM)
                        || ( case (argMaxHighVolProb args, mReg) of
                                (Just maxHv, Just r) -> rpHighVol r <= maxHv
                                (Just _, Nothing) -> False
                                _ -> True
                           )
                    )
                confWidthOk =
                    ( not (predictorEnabled (argPredictors args) SensorConformal)
                        || ( case (argMaxConformalWidth args, mI) of
                                (Just maxW, Just i) -> intervalWidth i <= maxW
                                (Just _, Nothing) -> False
                                _ -> True
                           )
                    )
                qWidthOk =
                    ( not (predictorEnabled (argPredictors args) SensorQuantile)
                        || ( case (argMaxQuantileWidth args, mQ) of
                                (Just maxW, Just q) -> quantileWidth q <= maxW
                                (Just _, Nothing) -> False
                                _ -> True
                           )
                    )
             in if kalZ < zMin
                    then (Nothing, Just "KALMAN_Z")
                    else
                        if not hvOk
                            then (Nothing, Just "HMM_HIGH_VOL")
                            else
                                if not confWidthOk
                                    then (Nothing, Just "CONFORMAL_WIDTH")
                                    else
                                        if not qWidthOk
                                            then (Nothing, Just "QUANTILE_WIDTH")
                                            else
                                                if not (confirmConformal args thr mI dir)
                                                    then (Nothing, Just "CONFORMAL_CONFIRM")
                                                    else
                                                        if not (confirmQuantiles args thr mQ dir)
                                                            then (Nothing, Just "QUANTILE_CONFIRM")
                                                            else
                                                                if effectiveUseSizing && confScore < argMinPositionSize args
                                                                    then (Nothing, Just "MIN_SIZE")
                                                                    else (Just dir, Nothing)

confidenceScoreKalman :: Args -> Double -> Maybe RegimeProbs -> Maybe Interval -> Maybe Quantiles -> Double
confidenceScoreKalman args kalZ mReg mI mQ =
    let zMin = max 0 (argKalmanZMin args)
        zMax = max zMin (argKalmanZMax args)
        zScore = scale01 zMin zMax kalZ
        hvScore =
            case (argMaxHighVolProb args, mReg) of
                (Just maxHv, Just r) -> clamp01 ((maxHv - rpHighVol r) / max 1e-12 maxHv)
                _ -> 1
        confScore =
            case (argMaxConformalWidth args, mI) of
                (Just maxW, Just i) -> clamp01 ((maxW - intervalWidth i) / max 1e-12 maxW)
                _ -> 1
        qScore =
            case (argMaxQuantileWidth args, mQ) of
                (Just maxW, Just q) -> clamp01 ((maxW - quantileWidth q) / max 1e-12 maxW)
                _ -> 1
     in zScore * hvScore * confScore * qScore

computeThresholdFactorsFromHistory ::
    Args ->
    Method ->
    Double ->
    Double ->
    Double ->
    Int ->
    Double ->
    V.Vector Double ->
    PredHistory ->
    (Double, Double)
computeThresholdFactorsFromHistory args method openThrBase closeThrBase minEdge lookback roundTripCost pricesV hist =
    if not (argThresholdFactorEnabled args)
        then (1, 1)
        else
            let factorAlpha = clamp01 (argThresholdFactorAlpha args)
                factorMinRaw = argThresholdFactorMin args
                factorMaxRaw = argThresholdFactorMax args
                factorMin = max 1e-6 (min factorMinRaw factorMaxRaw)
                factorMax = max factorMin (max factorMinRaw factorMaxRaw)
                factorFloor = max 0 (argThresholdFactorFloor args)
                openThrBase' = normalizeSignalThreshold openThrBase
                closeThrBase' = normalizeSignalThreshold closeThrBase
                factorWEdgeKal = argThresholdFactorEdgeKalWeight args
                factorWEdgeLstm = argThresholdFactorEdgeLstmWeight args
                factorWKalmanZ = argThresholdFactorKalmanZWeight args
                factorWHighVol = argThresholdFactorHighVolWeight args
                factorWConformal = argThresholdFactorConformalWeight args
                factorWQuantile = argThresholdFactorQuantileWeight args
                factorWLstmConf = argThresholdFactorLstmConfWeight args
                factorWLstmHealth = argThresholdFactorLstmHealthWeight args
                lstmHealthScore =
                    case phLstmHealth hist of
                        Just v | not (isNaN v || isInfinite v) -> clamp01 v
                        _ -> 0.5
                kalPred0 = phKalman hist
                lstmPred0 = phLstm hist
                blendWeight = clamp01 (argBlendWeight args)
                blendPred0 = blendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                harmonicBlendPred0 = harmonicBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                disagreementGuardPred0 = disagreementGuardPredictionsV blendWeight pricesV kalPred0 lstmPred0
                medianBlendPred0 = medianBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                neutralGuardPred0 = neutralGuardPredictionsV blendWeight pricesV kalPred0 lstmPred0
                riskParityBlendPred0 = riskParityBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                consensusBoostPred0 = consensusBoostPredictionsV blendWeight pricesV kalPred0 lstmPred0
                anchorBlendPred0 = anchorBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                tensionGatePred0 = tensionGatePredictionsV blendWeight pricesV kalPred0 lstmPred0
                entropyBlendPred0 = entropyBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                coherenceGatePred0 = coherenceGatePredictionsV blendWeight pricesV kalPred0 lstmPred0
                fractalBlendPred0 = fractalBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                phaseCancelPred0 = phaseCancelPredictionsV blendWeight pricesV kalPred0 lstmPred0
                softmaxBlendPred0 = softmaxBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                smoothSoftmaxBlendPred0 = smoothSoftmaxBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                netSoftmaxBlendPred0 = netSoftmaxBlendPredictionsV blendWeight roundTripCost pricesV kalPred0 lstmPred0
                edgeBlendPred0 = edgeBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                edgePickPred0 = edgePickPredictionsV blendWeight pricesV kalPred0 lstmPred0
                costPickPred0 = costPickPredictionsV blendWeight roundTripCost pricesV kalPred0 lstmPred0
                geoBlendPred0 = geometricBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                confBlendOpenThr = max openThrBase' minEdge
                divergenceGatePred0 = divergenceGatePredictionsV blendWeight confBlendOpenThr pricesV kalPred0 lstmPred0
                confBlendPred0 =
                    confidenceBlendPredictionsV
                        blendWeight
                        (max 0 (argKalmanZMin args))
                        (max (max 0 (argKalmanZMin args)) (argKalmanZMax args))
                        confBlendOpenThr
                        pricesV
                        kalPred0
                        lstmPred0
                        (phMeta hist)
                confPickPred0 =
                    confidencePickPredictionsV
                        blendWeight
                        (max 0 (argKalmanZMin args))
                        (max (max 0 (argKalmanZMin args)) (argKalmanZMax args))
                        confBlendOpenThr
                        pricesV
                        kalPred0
                        lstmPred0
                        (phMeta hist)
                conformalClipPred0 =
                    conformalClipPredictionsV
                        blendWeight
                        pricesV
                        kalPred0
                        lstmPred0
                        (phMeta hist)
                regimeSwitchPred0 =
                    regimeSwitchPredictionsV
                        blendWeight
                        0.6
                        1.0
                        pricesV
                        kalPred0
                        lstmPred0
                        (phMeta hist)
                hedgeBlendPred0 = hedgeBlendPredictionsV blendWeight pricesV kalPred0 lstmPred0
                routerPred =
                    if method == MethodRouter || method == MethodBanditRouter
                        then
                            let runRouter f =
                                    let (predV, _models) =
                                            f
                                                openThrBase
                                                roundTripCost
                                                (argRouterScorePnlWeight args)
                                                (argRouterLookback args)
                                                (argRouterMinScore args)
                                                pricesV
                                                kalPred0
                                                lstmPred0
                                                blendPred0
                                                costPickPred0
                                                regimeSwitchPred0
                                                edgeBlendPred0
                                                (phMeta hist)
                                     in predV
                             in case method of
                                    MethodBanditRouter -> runRouter banditPredictionsWithModelsV
                                    _ -> runRouter routerPredictionsWithModelsV
                        else blendPred0
                (kalPred1, lstmPred1) =
                    case method of
                        MethodBlend -> (blendPred0, blendPred0)
                        MethodConfBlend -> (confBlendPred0, confBlendPred0)
                        MethodConfPick -> (confPickPred0, confPickPred0)
                        MethodConformalClip -> (conformalClipPred0, conformalClipPred0)
                        MethodCostPick -> (costPickPred0, costPickPred0)
                        MethodHarmonicBlend -> (harmonicBlendPred0, harmonicBlendPred0)
                        MethodDisagreementGuard -> (disagreementGuardPred0, disagreementGuardPred0)
                        MethodMedianBlend -> (medianBlendPred0, medianBlendPred0)
                        MethodNeutralGuard -> (neutralGuardPred0, neutralGuardPred0)
                        MethodRiskParityBlend -> (riskParityBlendPred0, riskParityBlendPred0)
                        MethodConsensusBoost -> (consensusBoostPred0, consensusBoostPred0)
                        MethodAnchorBlend -> (anchorBlendPred0, anchorBlendPred0)
                        MethodTensionGate -> (tensionGatePred0, tensionGatePred0)
                        MethodEntropyBlend -> (entropyBlendPred0, entropyBlendPred0)
                        MethodCoherenceGate -> (coherenceGatePred0, coherenceGatePred0)
                        MethodDivergenceGate -> (divergenceGatePred0, divergenceGatePred0)
                        MethodFractalBlend -> (fractalBlendPred0, fractalBlendPred0)
                        MethodPhaseCancel -> (phaseCancelPred0, phaseCancelPred0)
                        MethodSoftmaxBlend -> (softmaxBlendPred0, softmaxBlendPred0)
                        MethodSmoothSoftmaxBlend -> (smoothSoftmaxBlendPred0, smoothSoftmaxBlendPred0)
                        MethodHedgeBlend -> (hedgeBlendPred0, hedgeBlendPred0)
                        MethodNetSoftmaxBlend -> (netSoftmaxBlendPred0, netSoftmaxBlendPred0)
                        MethodEdgeBlend -> (edgeBlendPred0, edgeBlendPred0)
                        MethodEdgePick -> (edgePickPred0, edgePickPred0)
                        MethodGeoBlend -> (geoBlendPred0, geoBlendPred0)
                        MethodRegimeSwitch -> (regimeSwitchPred0, regimeSwitchPred0)
                        MethodKalmanOnly -> (kalPred0, kalPred0)
                        MethodKalmanPhysicsError -> (kalPred0, kalPred0)
                        MethodLstmOnly -> (lstmPred0, lstmPred0)
                        MethodRouter -> (routerPred, routerPred)
                        MethodBanditRouter -> (routerPred, routerPred)
                        MethodBoth -> (kalPred0, lstmPred0)
                stepCount = minimum [V.length pricesV - 1, V.length kalPred1, V.length lstmPred1]
                alignVec len v
                    | V.length v == len = v
                    | V.length v > len = V.drop (V.length v - len) v
                    | otherwise = v
                pricesUsed
                    | V.length pricesV == stepCount + 1 = pricesV
                    | V.length pricesV > stepCount + 1 = V.drop (V.length pricesV - (stepCount + 1)) pricesV
                    | otherwise = pricesV
                kalPred = alignVec stepCount kalPred1
                lstmPred = alignVec stepCount lstmPred1
                metaUsed =
                    case phMeta hist of
                        Just metaV
                            | V.length metaV >= stepCount ->
                                Just (V.drop (V.length metaV - stepCount) metaV)
                        _ -> Nothing
                startT = max 0 (lookback - 1)
                bad x = isNaN x || isInfinite x
                clampFrac x = min 0.999999 (max 0 x)
                signedScore s = 2 * clamp01 s - 1
                scoreOrNeutral mv =
                    case mv of
                        Just v | not (bad v) -> clamp01 v
                        _ -> 0.5
                edgeScore thr edge =
                    let denom = max 1e-12 (abs thr)
                        raw = edge / (2 * denom)
                     in if bad raw then 0.5 else clamp01 raw
                metaAt t =
                    case metaUsed of
                        Just v | t >= 0 && t < V.length v -> Just (v V.! t)
                        _ -> Nothing
                metaReg m = RegimeProbs 0 0 <$> smHighVolProb m
                metaQuantiles m =
                    case (smQuantile10 m, smQuantile90 m) of
                        (Just lo, Just hi) -> Just (Quantiles lo ((lo + hi) / 2) hi)
                        _ -> Nothing
                metaInterval m =
                    case (smConformalLo m, smConformalHi m) of
                        (Just lo, Just hi) -> Just (Interval lo hi)
                        _ -> Nothing
                direction thr prev next =
                    let thr' = normalizeSignalThreshold thr
                     in if prev <= 0 || bad prev || bad next
                            then Nothing
                            else
                                let up = prev * (1 + thr')
                                    down = prev * (1 - thr')
                                 in if next > up
                                        then Just (1 :: Int)
                                        else if next < down then Just (-1) else Nothing
                updateFactor prev target =
                    if factorAlpha <= 0
                        then prev
                        else
                            let next = (1 - factorAlpha) * prev + factorAlpha * target
                             in if bad next then prev else clampRange factorMin factorMax next
                step (fOpenPrev, fClosePrev, posSide) t =
                    let fOpenBase = clampRange factorMin factorMax fOpenPrev
                        fCloseBase = clampRange factorMin factorMax fClosePrev
                        minEdgeAdj = max factorFloor (minEdge * fOpenBase)
                        openThrAdj =
                            normalizeSignalThreshold
                                (max minEdgeAdj (max factorFloor (openThrBase' * fOpenBase)))
                        prev = pricesUsed V.! t
                        kalNext = kalPred V.! t
                        lstmNext = lstmPred V.! t
                        edgePred p =
                            if prev <= 0 || bad prev || bad p
                                then 0
                                else
                                    let edge = abs (p / prev - 1)
                                     in if bad edge then 0 else edge
                        edgeKal = edgePred kalNext
                        edgeLstm = edgePred lstmNext
                        (mReg, mQ, mI, kalZ) =
                            case metaAt t of
                                Nothing -> (Nothing, Nothing, Nothing, 0)
                                Just m ->
                                    let z = fromMaybe 0 (kalmanZFromMeta m)
                                     in (metaReg m, metaQuantiles m, metaInterval m, z)
                        confScore = confidenceScoreKalman args kalZ mReg mI mQ
                        kalDirRaw = direction openThrAdj prev kalNext
                        lstmDir = direction openThrAdj prev lstmNext
                        (kalDir, _) = gateKalmanDir args (argConfidenceSizing args) openThrAdj kalZ mReg mI mQ confScore kalDirRaw
                        agreeOk =
                            case (kalDir, lstmDir) of
                                (Just a, Just b) -> a == b
                                _ -> False
                        posSide' =
                            case (kalDir, lstmDir) of
                                (Just a, Just b) | a == b -> a
                                _ -> 0
                        pendingUpdate = posSide /= 0 || agreeOk
                        zScoreMaybe =
                            if isNothing (metaAt t)
                                then Nothing
                                else
                                    let zMin = max 0 (argKalmanZMin args)
                                        zMax = max zMin (argKalmanZMax args)
                                     in Just (scale01 zMin zMax kalZ)
                        hvScoreMaybe =
                            case mReg of
                                Nothing -> Nothing
                                Just r ->
                                    let score =
                                            case argMaxHighVolProb args of
                                                Just maxHv | maxHv > 0 -> clamp01 ((maxHv - rpHighVol r) / max 1e-12 maxHv)
                                                _ -> clamp01 (1 - rpHighVol r)
                                     in Just score
                        confScoreMaybe =
                            case mI of
                                Nothing -> Nothing
                                Just i ->
                                    case argMaxConformalWidth args of
                                        Just maxW | maxW > 0 -> Just (clamp01 ((maxW - intervalWidth i) / max 1e-12 maxW))
                                        _ -> Nothing
                        qScoreMaybe =
                            case mQ of
                                Nothing -> Nothing
                                Just q ->
                                    case argMaxQuantileWidth args of
                                        Just maxW | maxW > 0 -> Just (clamp01 ((maxW - quantileWidth q) / max 1e-12 maxW))
                                        _ -> Nothing
                        lstmScore = scoreOrNeutral (lstmConfidenceScoreFromPred openThrBase' prev lstmNext)
                        healthScore = lstmHealthScore
                        factorTarget thr =
                            let edgeKalScore = edgeScore thr edgeKal
                                edgeLstmScore = edgeScore thr edgeLstm
                                raw =
                                    1
                                        + factorWEdgeKal * signedScore edgeKalScore
                                        + factorWEdgeLstm * signedScore edgeLstmScore
                                        + factorWKalmanZ * signedScore (scoreOrNeutral zScoreMaybe)
                                        + factorWHighVol * signedScore (scoreOrNeutral hvScoreMaybe)
                                        + factorWConformal * signedScore (scoreOrNeutral confScoreMaybe)
                                        + factorWQuantile * signedScore (scoreOrNeutral qScoreMaybe)
                                        + factorWLstmConf * signedScore lstmScore
                                        + factorWLstmHealth * signedScore healthScore
                             in if bad raw then 1 else clampFrac raw
                        fOpenNext =
                            if pendingUpdate
                                then updateFactor fOpenBase (factorTarget openThrBase')
                                else fOpenBase
                        fCloseNext =
                            if pendingUpdate
                                then updateFactor fCloseBase (factorTarget closeThrBase')
                                else fCloseBase
                     in (fOpenNext, fCloseNext, posSide')
             in if stepCount <= 0 || startT > stepCount - 1
                    then (1, 1)
                    else
                        let (fOpenFinal, fCloseFinal, _posFinal) =
                                foldl' step (1, 1, 0) [startT .. stepCount - 1]
                         in (fOpenFinal, fCloseFinal)

orderSizeMultiplier :: Double
orderSizeMultiplier = 1

scaleOrderSize :: Double -> Double
scaleOrderSize x = x * orderSizeMultiplier
entryScaleForSignal :: Args -> BinanceMarket -> LatestSignal -> Double
entryScaleForSignal args market sig =
    let s0 = fromMaybe 1 (lsPositionSize sig)
        s1 = max 0 s0
        s2 = min s1 (max 0 (argMaxPositionSize args))
        (lstmScale, _) = lstmConfidenceSizing args sig
        s3 =
            case market of
                MarketFutures -> s2
                _ -> min 1 s2
     in scaleOrderSize (max 0 (s3 * lstmScale))

placeOrderForSignal :: Args -> String -> LatestSignal -> BinanceEnv -> IO ApiOrderResult
placeOrderForSignal args sym sig env =
    placeOrderForSignalEx args sym sig env Nothing True

placeOrderForSignalBot :: Args -> String -> LatestSignal -> BinanceEnv -> Bool -> IO ApiOrderResult
placeOrderForSignalBot args sym sig env = placeOrderForSignalEx args sym sig env Nothing

placeOrderForSignalEx :: Args -> String -> LatestSignal -> BinanceEnv -> Maybe String -> Bool -> IO ApiOrderResult
placeOrderForSignalEx args sym sig env mClientOrderIdOverride enableProtectionOrders = do
    case (beApiKey env, beApiSecret env) of
        (Nothing, _) -> noOrder "No order: missing Binance API key."
        (_, Nothing) -> noOrder "No order: missing Binance API secret."
        (Just _, Just _) ->
            case chosenDir of
                Nothing -> noOrder neutralMsg
                Just dir -> do
                    mFilters <- tryFetchFilters
                    case mFilters of
                        Nothing -> noOrder "No order: exchangeInfo unavailable (cannot validate precision)."
                        Just _ -> do
                            let (baseAsset, quoteAsset) = splitSymbol sym
                            r <- try (place mFilters baseAsset quoteAsset dir) :: IO (Either SomeException ApiOrderResult)
                            case r of
                                Left ex -> noOrder ("Order failed: " ++ shortErr ex)
                                Right out -> pure out
  where
    method = lsMethod sig
    chosenDir = lsChosenDir sig
    currentPrice = lsCurrentPrice sig

    entryScale :: Double
    entryScale = entryScaleForSignal args (beMarket env) sig

    exitScale :: Double
    exitScale =
        maybe 1 clamp01 (lsExitSize sig)

    clientOrderId :: Maybe String
    clientOrderId = trim <$> (mClientOrderIdOverride <|> argIdempotencyKey args)

    baseResult :: ApiOrderResult
    baseResult =
        ApiOrderResult
            { aorSent = False
            , aorMode = Just (modeLabel mode)
            , aorSide = Nothing
            , aorSymbol = Just sym
            , aorQuantity = Nothing
            , aorQuoteQuantity = Nothing
            , aorOrderId = Nothing
            , aorClientOrderId = clientOrderId
            , aorStatus = Nothing
            , aorExecutedQty = Nothing
            , aorCummulativeQuoteQty = Nothing
            , aorTxHash = Nothing
            , aorResponse = Nothing
            , aorMessage = ""
            }

    noOrder :: String -> IO ApiOrderResult
    noOrder msg = pure baseResult{aorMessage = msg}

    neutralMsg =
        case method of
            MethodBoth -> "No order: directions disagree or neutral (direction gate)."
            MethodKalmanOnly -> "No order: Kalman neutral (within threshold)."
            MethodKalmanPhysicsError -> "No order: Kalman neutral (within threshold)."
            MethodLstmOnly -> "No order: LSTM neutral (within threshold)."
            MethodBlend -> "No order: Blend neutral (within threshold)."
            MethodConfBlend -> "No order: Conf blend neutral (within threshold)."
            MethodConfPick -> "No order: Conf pick neutral (within threshold)."
            MethodConformalClip -> "No order: Conformal clip neutral (within threshold)."
            MethodCostPick -> "No order: Cost pick neutral (within threshold)."
            MethodHarmonicBlend -> "No order: Harmonic blend neutral (within threshold)."
            MethodDisagreementGuard -> "No order: Disagreement guard neutral (within threshold)."
            MethodMedianBlend -> "No order: Median blend neutral (within threshold)."
            MethodNeutralGuard -> "No order: Neutral guard neutral (within threshold)."
            MethodRiskParityBlend -> "No order: Risk parity blend neutral (within threshold)."
            MethodConsensusBoost -> "No order: Consensus boost neutral (within threshold)."
            MethodAnchorBlend -> "No order: Anchor blend neutral (within threshold)."
            MethodTensionGate -> "No order: Tension gate neutral (within threshold)."
            MethodEntropyBlend -> "No order: Entropy blend neutral (within threshold)."
            MethodCoherenceGate -> "No order: Coherence gate neutral (within threshold)."
            MethodDivergenceGate -> "No order: Divergence gate neutral (within threshold)."
            MethodFractalBlend -> "No order: Fractal blend neutral (within threshold)."
            MethodPhaseCancel -> "No order: Phase cancel neutral (within threshold)."
            MethodSoftmaxBlend -> "No order: Softmax blend neutral (within threshold)."
            MethodSmoothSoftmaxBlend -> "No order: Smooth softmax blend neutral (within threshold)."
            MethodHedgeBlend -> "No order: Hedge blend neutral (within threshold)."
            MethodNetSoftmaxBlend -> "No order: Net softmax blend neutral (within threshold)."
            MethodEdgeBlend -> "No order: Edge blend neutral (within threshold)."
            MethodEdgePick -> "No order: Edge pick neutral (within threshold)."
            MethodGeoBlend -> "No order: Geo blend neutral (within threshold)."
            MethodRegimeSwitch -> "No order: Regime switch neutral (within threshold)."
            MethodRouter -> "No order: Router neutral (score/threshold)."
            MethodBanditRouter -> "No order: Bandit router neutral (score/threshold)."

    shortErr :: SomeException -> String
    shortErr ex = take 240 (show ex)

    mode = if argBinanceLive args then OrderLive else OrderTest

    lstmBlockMsg :: Maybe String
    lstmBlockMsg = snd (lstmConfidenceSizing args sig)

    protectionMinConfidence :: Double
    protectionMinConfidence = clamp01 (argProtectionMinConfidence args)

    protectionConfidence :: Maybe Double
    protectionConfidence =
        let raw = lsConfidence sig <|> lstmConfidenceScore args sig
            clean x =
                if isNaN x || isInfinite x
                    then Nothing
                    else Just (clamp01 x)
         in raw >>= clean

    makerWaitEnabled :: Bool
    makerWaitEnabled = argExecutionMakerFirst args && mode == OrderLive

    makerOffsetFrac :: Double
    makerOffsetFrac = max 0 (argExecutionMakerOffsetBps args) / 10000

    makerTimeoutUs :: Int
    makerTimeoutUs = max 0 (floor (max 0 (argExecutionMakerTimeoutSec args) * 1000000))

    makerPollUs :: Int
    makerPollUs = max 1000 (argExecutionMakerPollMs args * 1000)

    waitForMakerEntry :: OrderSide -> IO (Either String ())
    waitForMakerEntry side =
        if not makerWaitEnabled || makerOffsetFrac <= 0
            then pure (Right ())
            else do
                let targetPx =
                        case side of
                            Buy -> currentPrice * (1 - makerOffsetFrac)
                            Sell -> currentPrice * (1 + makerOffsetFrac)
                    isReady px =
                        case side of
                            Buy -> px <= targetPx
                            Sell -> px >= targetPx
                    timeoutMsg = "No order: maker-first timeout (market fallback disabled)."
                if makerTimeoutUs <= 0
                    then
                        if argExecutionMakerFallbackMarket args
                            then pure (Right ())
                            else pure (Left timeoutMsg)
                    else do
                        start <- getPOSIXTime
                        let elapsedUs now = floor ((now - start) * 1000000)
                            loop = do
                                pxOrErr <- try (fetchTickerPrice env sym) :: IO (Either SomeException Double)
                                case pxOrErr of
                                    Right px | not (isNaN px || isInfinite px) && isReady px -> pure (Right ())
                                    _ -> do
                                        now <- getPOSIXTime
                                        if elapsedUs now >= makerTimeoutUs
                                            then
                                                if argExecutionMakerFallbackMarket args
                                                    then pure (Right ())
                                                    else pure (Left timeoutMsg)
                                            else do
                                                threadDelay makerPollUs
                                                loop
                        loop

    tryFetchFilters :: IO (Maybe SymbolFilters)
    tryFetchFilters = do
        r <- try (fetchSymbolFilters env sym) :: IO (Either SomeException SymbolFilters)
        case r of
            Left _ -> pure Nothing
            Right sf -> pure (Just sf)

    effectiveStep sf = sfMarketStepSize sf <|> sfLotStepSize sf
    effectiveMinQty sf = sfMarketMinQty sf <|> sfLotMinQty sf
    effectiveMaxQty sf = sfMarketMaxQty sf <|> sfLotMaxQty sf

    stepValue :: Step -> Double
    stepValue st = fromIntegral (stepInt st) / fromIntegral (stepScale st)

    quantizeUp :: Step -> Double -> Double
    quantizeUp st x
        | x <= 0 = 0
        | otherwise =
            let scaleD = fromIntegral (stepScale st) :: Double
                scaled = ceiling (x * scaleD - 1e-9) :: Integer
                stepI = stepInt st
                q = ((scaled + stepI - 1) `div` stepI) * stepI
             in fromIntegral q / scaleD

    minTradeQty :: SymbolFilters -> Double -> Maybe Double
    minTradeQty sf price =
        let minQ = fromMaybe 0 (effectiveMinQty sf)
            stepQ = maybe 0 stepValue (effectiveStep sf)
            notionalQ =
                case sfMinNotional sf of
                    Just mn | price > 0 -> mn / price
                    _ -> 0
            minRaw = max minQ (max stepQ notionalQ)
            minAdj =
                case effectiveStep sf of
                    Just st -> quantizeUp st minRaw
                    Nothing -> minRaw
         in if minAdj > 0 then Just minAdj else Nothing

    minTradeQtyMaybe :: Maybe SymbolFilters -> Double -> Maybe Double
    minTradeQtyMaybe mSf price = mSf >>= \sf -> minTradeQty sf price

    isLongSpot :: Maybe SymbolFilters -> Double -> Double -> Bool
    isLongSpot mSf price baseBal =
        case minTradeQtyMaybe mSf price of
            Just minQ -> baseBal >= minQ
            Nothing -> baseBal > 0

    isTooSmallQtyError :: String -> Bool
    isTooSmallQtyError msg =
        msg == "Quantity rounds to 0."
            || "Quantity below minQty" `isPrefixOf` msg
            || "Notional below minNotional" `isPrefixOf` msg

    normalizeQty :: SymbolFilters -> Double -> Double -> Either String Double
    normalizeQty sf price qtyRaw =
        let qty0 = max 0 qtyRaw
            qty1 = maybe qty0 (`quantizeDown` qty0) (effectiveStep sf)
         in if qty1 <= 0
                then Left "Quantity rounds to 0."
                else case effectiveMinQty sf of
                    Just minQ | qty1 < minQ -> Left ("Quantity below minQty (" ++ show minQ ++ ").")
                    _ ->
                        case effectiveMaxQty sf of
                            Just maxQ | qty1 > maxQ -> Left ("Quantity above maxQty (" ++ show maxQ ++ ").")
                            _ ->
                                case sfMinNotional sf of
                                    Just mn | price > 0 && qty1 * price < mn -> Left ("Notional below minNotional (" ++ show mn ++ ").")
                                    _ -> Right qty1

    normalizeEntryQty :: SymbolFilters -> Double -> Double -> Either String (Double, Bool)
    normalizeEntryQty sf price qtyRaw =
        case normalizeQty sf price qtyRaw of
            Right q -> Right (q, False)
            Left err ->
                if not (isTooSmallQtyError err)
                    then Left err
                    else case minTradeQty sf price of
                        Nothing -> Left err
                        Just minQ ->
                            case normalizeQty sf price minQ of
                                Right qMin -> Right (qMin, qMin > qtyRaw + 1e-9)
                                Left _ -> Left err

    sendMarketOrderWithMaker :: Bool -> String -> OrderSide -> Maybe Double -> Maybe Double -> Maybe Bool -> IO ApiOrderResult
    sendMarketOrderWithMaker isEntry sideLabel side mQty mQuote mReduceOnly =
        if not isEntry
            then sendMarketOrder sideLabel side mQty mQuote mReduceOnly
            else do
                waitRes <- waitForMakerEntry side
                case waitRes of
                    Left msg ->
                        pure
                            baseResult
                                { aorSide = Just sideLabel
                                , aorQuantity = mQty
                                , aorQuoteQuantity = mQuote
                                , aorMessage = msg
                                }
                    Right () -> sendMarketOrder sideLabel side mQty mQuote mReduceOnly

    sendMarketOrder :: String -> OrderSide -> Maybe Double -> Maybe Double -> Maybe Bool -> IO ApiOrderResult
    sendMarketOrder sideLabel side mQty mQuote mReduceOnly = do
        let baseOut =
                baseResult
                    { aorSide = Just sideLabel
                    , aorQuantity = mQty
                    , aorQuoteQuantity = mQuote
                    }

        let tryReconcile ex =
                case (mode, clientOrderId) of
                    (OrderLive, Just cid) -> do
                        r2 <- try (fetchOrderByClientId env sym cid) :: IO (Either SomeException BL.ByteString)
                        case r2 of
                            Left _ -> pure baseOut{aorMessage = "Order failed: " ++ shortErr ex}
                            Right body ->
                                let out0 =
                                        baseOut
                                            { aorSent = True
                                            , aorResponse = Just (shortResp body)
                                            , aorMessage = "Order reconciled by clientOrderId after error: " ++ shortErr ex
                                            }
                                 in pure (maybe out0 (`applyOrderInfo` out0) (decodeOrderInfo body))
                    _ -> pure baseOut{aorMessage = "Order failed: " ++ shortErr ex}

        r <- try (placeMarketOrder env mode sym side mQty mQuote mReduceOnly clientOrderId) :: IO (Either SomeException BL.ByteString)
        case r of
            Left ex -> tryReconcile ex
            Right body ->
                let out0 =
                        baseOut
                            { aorSent = True
                            , aorResponse = Just (shortResp body)
                            , aorMessage = "Order sent."
                            }
                 in pure (maybe out0 (`applyOrderInfo` out0) (decodeOrderInfo body))

    place :: Maybe SymbolFilters -> String -> String -> Int -> IO ApiOrderResult
    place mSf baseAsset quoteAsset dir =
        case beMarket env of
            MarketSpot -> placeSpotOrMargin mSf baseAsset quoteAsset dir
            MarketMargin ->
                if mode == OrderTest
                    then pure baseResult{aorMessage = "No order: margin trading requires binanceLive (no test endpoint)."}
                    else placeSpotOrMargin mSf baseAsset quoteAsset dir
            MarketFutures -> placeFutures mSf quoteAsset dir

    placeSpotOrMargin :: Maybe SymbolFilters -> String -> String -> Int -> IO ApiOrderResult
    placeSpotOrMargin mSf baseAsset quoteAsset dir = do
        baseBal <- fetchFreeBalance env baseAsset
        let alreadyLong = isLongSpot mSf currentPrice baseBal
            qtyArg = case argOrderQuantity args of Just q | q > 0 -> Just q; _ -> Nothing
            quoteArg = case argOrderQuote args of Just q | q > 0 -> Just q; _ -> Nothing
            quoteFracArg = case argOrderQuoteFraction args of Just f | f > 0 -> Just f; _ -> Nothing
            maxOrderQuoteArg = case argMaxOrderQuote args of Just q | q > 0 -> Just q; _ -> Nothing

        case dir of
            1 ->
                if alreadyLong
                    then pure baseResult{aorMessage = "No order: already long."}
                    else case lstmBlockMsg of
                        Just msg -> pure baseResult{aorMessage = msg}
                        Nothing -> do
                            let qtyArgBuy = fmap (* entryScale) qtyArg
                                quoteArgBuy = fmap (* entryScale) quoteArg
                                quoteFracArgBuy = fmap (* entryScale) quoteFracArg
                            quoteBal <- fetchFreeBalance env quoteAsset
                            let quoteFromFraction =
                                    case (qtyArgBuy, quoteArgBuy, quoteFracArgBuy) of
                                        (Nothing, Nothing, Just f) ->
                                            let q0 = quoteBal * f
                                                q1 = maybe q0 (`min` q0) maxOrderQuoteArg
                                             in Just q1
                                        _ -> Nothing
                                quoteEffective = quoteArgBuy <|> quoteFromFraction

                            case (qtyArgBuy, quoteEffective) of
                                (Nothing, Nothing) ->
                                    case quoteFracArgBuy of
                                        Nothing -> pure baseResult{aorMessage = "No order: provide orderQuantity or orderQuote."}
                                        Just _ -> pure baseResult{aorMessage = "No order: computed quote is 0 (check quote balance / orderQuoteFraction / maxOrderQuote)."}
                                (Just qRaw, _) ->
                                    case mSf of
                                        Nothing ->
                                            if qRaw * currentPrice > quoteBal
                                                then pure baseResult{aorMessage = "No order: insufficient quote balance."}
                                                else sendMarketOrderWithMaker True "BUY" Buy (Just qRaw) Nothing Nothing
                                        Just sf ->
                                            case normalizeEntryQty sf currentPrice qRaw of
                                                Left e -> pure baseResult{aorMessage = "No order: " ++ e}
                                                Right (q, bumped) ->
                                                    if q * currentPrice > quoteBal
                                                        then
                                                            pure
                                                                baseResult
                                                                    { aorMessage =
                                                                        if bumped
                                                                            then "No order: insufficient quote balance for min order size."
                                                                            else "No order: insufficient quote balance."
                                                                    }
                                                        else do
                                                            out <- sendMarketOrderWithMaker True "BUY" Buy (Just q) Nothing Nothing
                                                            pure $
                                                                if bumped && aorSent out
                                                                    then out{aorMessage = aorMessage out ++ " (min size applied)."}
                                                                    else out
                                (Nothing, Just qq0) ->
                                    let qq = max 0 qq0
                                        minQuote =
                                            case minTradeQtyMaybe mSf currentPrice of
                                                Just minQ -> minQ * currentPrice
                                                Nothing -> 0
                                     in if qq <= 0
                                            then pure baseResult{aorMessage = "No order: quote is 0."}
                                            else
                                                if minQuote > 0 && qq < minQuote
                                                    then pure baseResult{aorMessage = "No order: quote below exchange minimums."}
                                                    else
                                                        if qq > quoteBal
                                                            then pure baseResult{aorMessage = "No order: insufficient quote balance."}
                                                            else sendMarketOrderWithMaker True "BUY" Buy Nothing (Just qq) Nothing
            (-1) ->
                if not alreadyLong
                    then pure baseResult{aorMessage = "No order: already flat."}
                    else do
                        let qtyArgSell = qtyArg
                            qRaw0 =
                                case qtyArgSell of
                                    Just q -> min q baseBal
                                    Nothing -> baseBal
                            qRaw = qRaw0 * exitScale
                        case mSf of
                            Nothing ->
                                if qRaw <= 0
                                    then pure baseResult{aorMessage = "No order: quantity is 0."}
                                    else sendMarketOrder "SELL" Sell (Just qRaw) Nothing Nothing
                            Just sf ->
                                let minQty = minTradeQty sf currentPrice
                                    baseBelowMin = maybe False (baseBal <) minQty
                                    reqBelowMin =
                                        isJust qtyArg
                                            && maybe False (\minQ -> qRaw < minQ && baseBal >= minQ) minQty
                                 in case normalizeQty sf currentPrice qRaw of
                                        Left e
                                            | baseBelowMin ->
                                                pure baseResult{aorMessage = "No order: position below exchange minimums (dust)."}
                                            | reqBelowMin ->
                                                pure baseResult{aorMessage = "No order: orderQuantity below exchange minimums."}
                                            | otherwise -> pure baseResult{aorMessage = "No order: " ++ e}
                                        Right q ->
                                            if q > baseBal
                                                then pure baseResult{aorMessage = "No order: insufficient base balance."}
                                                else sendMarketOrder "SELL" Sell (Just q) Nothing Nothing
            _ -> pure baseResult{aorMessage = neutralMsg}

    placeFutures :: Maybe SymbolFilters -> String -> Int -> IO ApiOrderResult
    placeFutures mSf quoteAsset dir = do
        summary <- fetchFuturesPositionSummary env sym
        if fpsHasLong summary && fpsHasShort summary
            then
                pure $
                    baseResult
                        { aorMessage = "No order: both long and short futures positions are open; flatten one side first."
                        }
            else do
                let posAmt = fpsNetAmt summary
                    protectPrefix = "trader_prot_"
                    isBad x = isNaN x || isInfinite x
                    leverageRaw = fromMaybe 1 (fpsLeverage summary)
                    leverage =
                        if leverageRaw > 0 && not (isBad leverageRaw)
                            then leverageRaw
                            else 1
                    marginRequired qty =
                        let qty' = max 0 qty
                            px = max 0 currentPrice
                         in if qty' <= 0 || px <= 0 || isBad qty' || isBad px
                                then 0
                                else qty' * px / leverage
                    ensureFuturesFunds dir qty =
                        if qty <= 0
                            then pure (Right ())
                            else do
                                avail <- fetchFuturesAvailableBalance env quoteAsset
                                let freed =
                                        if posAmt * fromIntegral dir < 0
                                            then marginRequired (abs posAmt)
                                            else 0
                                    available = max 0 (avail + freed)
                                    needed = marginRequired qty
                                    asset = map toUpper quoteAsset
                                pure $
                                    if needed <= available + 1e-9
                                        then Right ()
                                        else
                                            Left
                                                ( printf
                                                    "No order: insufficient futures balance (need %.4f %s, available %.4f, leverage %.1fx)."
                                                    needed
                                                    asset
                                                    available
                                                    leverage
                                                )
                    volPerBar =
                        case lsVolatility sig of
                            Just vol ->
                                let perBar = vol / sqrt (max 1e-12 (periodsPerYear args))
                                 in if isNaN perBar || isInfinite perBar || perBar <= 0 then Nothing else Just perBar
                            _ -> Nothing
                    stopFromVol mult =
                        if mult <= 0
                            then Nothing
                            else case volPerBar of
                                Just v ->
                                    let frac = mult * v
                                        fracClamped = min 0.999999 (max 0 frac)
                                     in if isNaN fracClamped || isInfinite fracClamped || fracClamped <= 0
                                            then Nothing
                                            else Just fracClamped
                                _ -> Nothing
                    stopLoss0 =
                        case stopFromVol (argStopLossVolMult args) of
                            Just v -> Just v
                            Nothing ->
                                case argStopLoss args of
                                    Just v | v > 0 -> Just v
                                    _ -> Nothing
                    takeProfit0 =
                        case stopFromVol (argTakeProfitVolMult args) of
                            Just v -> Just v
                            Nothing ->
                                case argTakeProfit args of
                                    Just v | v > 0 -> Just v
                                    _ -> Nothing
                    protectionManaged = enableProtectionOrders && mode == OrderLive
                    protectionWanted = protectionManaged && (isJust stopLoss0 || isJust takeProfit0)
                    protectionConfidenceOk =
                        protectionMinConfidence <= 0
                            || case protectionConfidence of
                                Just c -> c >= protectionMinConfidence
                                Nothing -> False
                    protectionBlockMsg =
                        if protectionMinConfidence <= 0
                            then Nothing
                            else case protectionConfidence of
                                Nothing ->
                                    Just
                                        ( printf
                                            "Protection orders skipped: confidence unavailable (<%.1f%%)."
                                            (protectionMinConfidence * 100)
                                        )
                                Just c
                                    | c < protectionMinConfidence ->
                                        Just
                                            ( printf
                                                "Protection orders skipped: confidence %.1f%% (<%.1f%%)."
                                                (c * 100)
                                                (protectionMinConfidence * 100)
                                            )
                                _ -> Nothing
                    protectionBlocked = protectionWanted && not protectionConfidenceOk
                    protectionEnabled = protectionWanted && protectionConfidenceOk

                    appendProtectionNote :: ApiOrderResult -> ApiOrderResult
                    appendProtectionNote out =
                        if protectionBlocked
                            then case protectionBlockMsg of
                                Nothing -> out
                                Just msg ->
                                    let baseMsg = aorMessage out
                                        sep = if null baseMsg then "" else " "
                                     in out{aorMessage = baseMsg ++ sep ++ msg}
                            else out
                    normalizeStopPrice px =
                        case mSf >>= sfTickSize of
                            Nothing -> px
                            Just st -> quantizeDown st (max 0 px)

                    cancelProtectionOrders :: IO ()
                    cancelProtectionOrders =
                        if not protectionManaged
                            then pure ()
                            else do
                                _ <- try (cancelFuturesOpenOrdersByClientPrefix env sym protectPrefix) :: IO (Either SomeException Int)
                                pure ()

                    placeProtectionOrders :: Int -> Double -> IO (Either String ())
                    placeProtectionOrders protectDir entryPrice
                        | not protectionEnabled = pure (Right ())
                        | otherwise = do
                            ts <- getTimestampMs
                            let requiresAlgo msg =
                                    "-4120" `isInfixOf` msg
                                        || "Algo Order" `isInfixOf` msg
                                        || "algo order" `isInfixOf` msg
                                isExistingProtection msg =
                                    let msgLower = map toLower msg
                                     in "-4130" `isInfixOf` msgLower
                                            || "open stop or take profit order" `isInfixOf` msgLower
                                            || "closeposition in the direction is existing" `isInfixOf` msgLower
                                mkCid suffix =
                                    let raw = protectPrefix ++ show ts ++ "_" ++ suffix
                                     in if length raw <= 36 then raw else take 36 raw

                                place1 :: OrderSide -> String -> Double -> String -> IO (Either String ())
                                place1 side orderType px suffix = do
                                    let cid = mkCid suffix
                                        px1 = normalizeStopPrice px
                                    r <- try (placeFuturesTriggerMarketOrder env mode sym side orderType px1 (Just cid)) :: IO (Either SomeException BL.ByteString)
                                    case r of
                                        Right _ -> pure (Right ())
                                        Left ex -> do
                                            let msg = take 240 (show ex)
                                            if isExistingProtection msg
                                                then pure (Right ())
                                                else
                                                    if requiresAlgo msg
                                                        then do
                                                            let hedgeSide =
                                                                    if protectDir < 0
                                                                        then Just "SHORT"
                                                                        else Just "LONG"
                                                                shouldRetryWithSide errMsg =
                                                                    "positionSide" `isInfixOf` errMsg || "Position side" `isInfixOf` errMsg
                                                            rAlgo <- try (placeFuturesAlgoTriggerMarketOrder env mode sym side orderType px1 (Just cid) Nothing) :: IO (Either SomeException BL.ByteString)
                                                            case rAlgo of
                                                                Right _ -> pure (Right ())
                                                                Left exAlgo -> do
                                                                    let msgAlgo = take 240 (show exAlgo)
                                                                    if isExistingProtection msgAlgo
                                                                        then pure (Right ())
                                                                        else
                                                                            if shouldRetryWithSide msgAlgo
                                                                                then do
                                                                                    rAlgo2 <- try (placeFuturesAlgoTriggerMarketOrder env mode sym side orderType px1 (Just cid) hedgeSide) :: IO (Either SomeException BL.ByteString)
                                                                                    pure $
                                                                                        case rAlgo2 of
                                                                                            Left exAlgo2 ->
                                                                                                let msgAlgo2 = take 240 (show exAlgo2)
                                                                                                 in if isExistingProtection msgAlgo2 then Right () else Left msgAlgo2
                                                                                            Right _ -> Right ()
                                                                                else pure (Left msgAlgo)
                                                        else pure (Left msg)

                                (slSide, mSlPx, tpSide, mTpPx) =
                                    if protectDir < 0
                                        then
                                            ( Buy
                                            , (\sl -> entryPrice * (1 + sl)) <$> stopLoss0
                                            , Buy
                                            , (\tp -> entryPrice * (1 - tp)) <$> takeProfit0
                                            )
                                        else
                                            ( Sell
                                            , (\sl -> entryPrice * (1 - sl)) <$> stopLoss0
                                            , Sell
                                            , (\tp -> entryPrice * (1 + tp)) <$> takeProfit0
                                            )

                            rSl <-
                                case mSlPx of
                                    Nothing -> pure (Right ())
                                    Just px -> place1 slSide "STOP_MARKET" px "sl"
                            rTp <-
                                case mTpPx of
                                    Nothing -> pure (Right ())
                                    Just px -> place1 tpSide "TAKE_PROFIT_MARKET" px "tp"
                            pure $
                                case (rSl, rTp) of
                                    (Left e, _) -> Left ("Protection order failed: " ++ e)
                                    (_, Left e) -> Left ("Protection order failed: " ++ e)
                                    _ -> Right ()

                mQuoteFromFraction <-
                    case (argOrderQuantity args, argOrderQuote args, argOrderQuoteFraction args) of
                        (Nothing, Nothing, Just f) | f > 0 -> do
                            bal <- fetchFuturesAvailableBalance env quoteAsset
                            let q0 = bal * f * entryScale
                                q1 =
                                    let mCap =
                                            case argMaxOrderQuote args of
                                                Just q | q > 0 -> Just q
                                                _ -> Nothing
                                     in maybe q0 (`min` q0) mCap
                            pure (Just q1)
                        _ -> pure Nothing
                let mDesiredQtyRaw =
                        case argOrderQuantity args of
                            Just q | q > 0 -> Just (q * entryScale)
                            Just _ -> Nothing
                            Nothing ->
                                case fmap (* entryScale) (argOrderQuote args) <|> mQuoteFromFraction of
                                    Just qq | qq > 0 && currentPrice > 0 -> Just (qq / currentPrice)
                                    _ -> Nothing

                    normalizeFuturesQty qRaw =
                        case mSf of
                            Nothing -> Right qRaw
                            Just sf -> normalizeQty sf currentPrice qRaw

                    normalizeFuturesEntryQty qRaw =
                        case mSf of
                            Nothing -> Right (qRaw, False)
                            Just sf -> normalizeEntryQty sf currentPrice qRaw

                    closeOrder sideLabel side qtyRaw =
                        case normalizeFuturesQty qtyRaw of
                            Left e ->
                                case minTradeQtyMaybe mSf currentPrice of
                                    Just minQ | qtyRaw < minQ -> pure baseResult{aorMessage = "No order: position below exchange minimums (dust)."}
                                    _ -> pure baseResult{aorMessage = "No order: " ++ e}
                            Right q ->
                                if q <= 0
                                    then pure baseResult{aorMessage = "No order: quantity is 0."}
                                    else do
                                        out <- sendMarketOrder sideLabel side (Just q) Nothing (Just True)
                                        if not (aorSent out) || mode /= OrderLive
                                            then pure out
                                            else do
                                                let isLongClose = side == Sell
                                                    wantSide = if isLongClose then Just "LONG" else Just "SHORT"
                                                    normalizeSide = fmap normalizeKey
                                                    matchesSide ps =
                                                        case (normalizeSide ps, normalizeSide wantSide) of
                                                            (Just "long", Just "long") -> True
                                                            (Just "short", Just "short") -> True
                                                            _ -> False
                                                    isBotAlgo cid = "trader_prot_" `isPrefixOf` cid
                                                let waitMax = 12 :: Int
                                                    waitDelayUs = 500000
                                                    waitLoop n = do
                                                        amt <- fetchFuturesPositionAmt env sym
                                                        if abs amt <= 1e-12 || n <= 0
                                                            then pure ()
                                                            else threadDelay waitDelayUs >> waitLoop (n - 1)
                                                waitLoop waitMax
                                                algoOrdersOrErr <- try (fetchFuturesOpenAlgoOrders env sym) :: IO (Either SomeException [FuturesAlgoOpenOrder])
                                                case algoOrdersOrErr of
                                                    Left _ -> pure out
                                                    Right orders -> do
                                                        let filtered =
                                                                [ o
                                                                | o <- orders
                                                                , let symOk = normalizeKey (faoSymbol o) == normalizeKey sym
                                                                , symOk
                                                                , let mCid = faoClientAlgoId o
                                                                , maybe False isBotAlgo mCid
                                                                , let ps = faoPositionSide o
                                                                , case normalizeSide ps of
                                                                    Just "long" -> matchesSide ps
                                                                    Just "short" -> matchesSide ps
                                                                    _ -> True
                                                                ]
                                                        forM_ filtered $ \o ->
                                                            case faoClientAlgoId o of
                                                                Nothing -> pure ()
                                                                Just cid -> do
                                                                    _ <- try (cancelFuturesAlgoOrderByClientId env cid) :: IO (Either SomeException BL.ByteString)
                                                                    pure ()
                                                        pure out

                    noFuturesSizingMsg =
                        if maybe False (> 0) (argOrderQuoteFraction args)
                            then "No order: computed quote is 0 (check futures balance / orderQuoteFraction / maxOrderQuote)."
                            else "No order: futures requires orderQuantity or orderQuote."

                case dir of
                    1 ->
                        if posAmt > 0
                            then
                                if protectionEnabled
                                    then do
                                        cancelProtectionOrders
                                        r <- placeProtectionOrders 1 currentPrice
                                        pure $
                                            case r of
                                                Left e -> baseResult{aorMessage = "No market order: already long. " ++ e}
                                                Right () -> baseResult{aorMessage = "No market order: already long. Protection orders refreshed."}
                                    else
                                        let baseMsg =
                                                if protectionBlocked
                                                    then "No market order: already long."
                                                    else "No order: already long."
                                         in pure (appendProtectionNote baseResult{aorMessage = baseMsg})
                            else case lstmBlockMsg of
                                Just msg | posAmt == 0 -> pure baseResult{aorMessage = msg}
                                _ ->
                                    case mDesiredQtyRaw of
                                        Nothing -> pure baseResult{aorMessage = noFuturesSizingMsg}
                                        Just q0 -> do
                                            case normalizeFuturesEntryQty q0 of
                                                Left e -> pure baseResult{aorMessage = "No order: " ++ e}
                                                Right (qDesired, bumped) -> do
                                                    fundsCheck <- ensureFuturesFunds 1 qDesired
                                                    case fundsCheck of
                                                        Left msg -> pure baseResult{aorMessage = msg}
                                                        Right () -> do
                                                            cancelProtectionOrders
                                                            let qtyToBuyRaw = if posAmt < 0 then abs posAmt + qDesired else qDesired
                                                            case normalizeFuturesQty qtyToBuyRaw of
                                                                Left e -> pure baseResult{aorMessage = "No order: " ++ e}
                                                                Right q ->
                                                                    if q <= 0
                                                                        then pure baseResult{aorMessage = "No order: quantity is 0."}
                                                                        else do
                                                                            out0 <- sendMarketOrderWithMaker True "BUY" Buy (Just q) Nothing Nothing
                                                                            let out =
                                                                                    if bumped && aorSent out0
                                                                                        then out0{aorMessage = aorMessage out0 ++ " (min size applied)."}
                                                                                        else out0
                                                                            if aorSent out
                                                                                then
                                                                                    if protectionEnabled
                                                                                        then do
                                                                                            let fillPx =
                                                                                                    case (aorExecutedQty out, aorCummulativeQuoteQty out) of
                                                                                                        (Just eq, Just qq) | eq > 0 && qq > 0 -> qq / eq
                                                                                                        _ -> currentPrice
                                                                                            r <- placeProtectionOrders 1 fillPx
                                                                                            pure $
                                                                                                case r of
                                                                                                    Left e -> out{aorMessage = aorMessage out ++ " " ++ e}
                                                                                                    Right () -> out{aorMessage = aorMessage out ++ " Protection orders placed."}
                                                                                        else pure (appendProtectionNote out)
                                                                                else pure out
                    (-1) ->
                        case argPositioning args of
                            LongShort ->
                                if posAmt < 0
                                    then
                                        if protectionEnabled
                                            then do
                                                cancelProtectionOrders
                                                r <- placeProtectionOrders (-1) currentPrice
                                                pure $
                                                    case r of
                                                        Left e -> baseResult{aorMessage = "No market order: already short. " ++ e}
                                                        Right () -> baseResult{aorMessage = "No market order: already short. Protection orders refreshed."}
                                            else
                                                let baseMsg =
                                                        if protectionBlocked
                                                            then "No market order: already short."
                                                            else "No order: already short."
                                                 in pure (appendProtectionNote baseResult{aorMessage = baseMsg})
                                    else case lstmBlockMsg of
                                        Just msg | posAmt == 0 -> pure baseResult{aorMessage = msg}
                                        _ ->
                                            case mDesiredQtyRaw of
                                                Nothing -> pure baseResult{aorMessage = noFuturesSizingMsg}
                                                Just q0 -> do
                                                    case normalizeFuturesEntryQty q0 of
                                                        Left e -> pure baseResult{aorMessage = "No order: " ++ e}
                                                        Right (qDesired, bumped) -> do
                                                            fundsCheck <- ensureFuturesFunds (-1) qDesired
                                                            case fundsCheck of
                                                                Left msg -> pure baseResult{aorMessage = msg}
                                                                Right () -> do
                                                                    cancelProtectionOrders
                                                                    let qtyToSellRaw = if posAmt > 0 then posAmt + qDesired else qDesired
                                                                    case normalizeFuturesQty qtyToSellRaw of
                                                                        Left e -> pure baseResult{aorMessage = "No order: " ++ e}
                                                                        Right q ->
                                                                            if q <= 0
                                                                                then pure baseResult{aorMessage = "No order: quantity is 0."}
                                                                                else do
                                                                                    out0 <- sendMarketOrderWithMaker True "SELL" Sell (Just q) Nothing Nothing
                                                                                    let out =
                                                                                            if bumped && aorSent out0
                                                                                                then out0{aorMessage = aorMessage out0 ++ " (min size applied)."}
                                                                                                else out0
                                                                                    if aorSent out
                                                                                        then
                                                                                            if protectionEnabled
                                                                                                then do
                                                                                                    let fillPx =
                                                                                                            case (aorExecutedQty out, aorCummulativeQuoteQty out) of
                                                                                                                (Just eq, Just qq) | eq > 0 && qq > 0 -> qq / eq
                                                                                                                _ -> currentPrice
                                                                                                    r <- placeProtectionOrders (-1) fillPx
                                                                                                    pure $
                                                                                                        case r of
                                                                                                            Left e -> out{aorMessage = aorMessage out ++ " " ++ e}
                                                                                                            Right () -> out{aorMessage = aorMessage out ++ " Protection orders placed."}
                                                                                                else pure (appendProtectionNote out)
                                                                                        else pure out
                            LongFlat ->
                                if posAmt == 0
                                    then do
                                        cancelProtectionOrders
                                        pure baseResult{aorMessage = "No order: already flat."}
                                    else
                                        if posAmt > 0
                                            then do
                                                cancelProtectionOrders
                                                closeOrder "SELL" Sell (abs posAmt * exitScale)
                                            else do
                                                cancelProtectionOrders
                                                closeOrder "BUY" Buy (abs posAmt * exitScale)
                    _ -> pure baseResult{aorMessage = neutralMsg}

    modeLabel m =
        case m of
            OrderLive -> "live"
            OrderTest -> "test"

placeCoinbaseOrderForSignal :: Args -> String -> LatestSignal -> CoinbaseEnv -> IO ApiOrderResult
placeCoinbaseOrderForSignal args symRaw sig env = do
    case (ceApiKey env, ceApiSecret env, ceApiPassphrase env) of
        (Nothing, _, _) -> noOrder "No order: missing Coinbase API key."
        (_, Nothing, _) -> noOrder "No order: missing Coinbase API secret."
        (_, _, Nothing) -> noOrder "No order: missing Coinbase API passphrase."
        _ ->
            if not (argBinanceLive args)
                then noOrder "No order: Coinbase does not support test orders; enable Live orders to send trades."
                else case splitCoinbaseSymbol sym of
                    Left err -> noOrder ("No order: " ++ err)
                    Right (baseAsset, quoteAsset) ->
                        if argPositioning args == LongShort
                            then noOrder "No order: Coinbase supports spot only (positioning=long-flat)."
                            else do
                                baseBal <- fetchCoinbaseAvailableBalance env baseAsset
                                quoteBal <- fetchCoinbaseAvailableBalance env quoteAsset
                                mBaseMinQty <- do
                                    r <- try (fetchCoinbaseBaseMinSize env sym) :: IO (Either SomeException (Maybe Double))
                                    pure (fromRight Nothing r)
                                case chosenDir of
                                    Nothing -> noOrder neutralMsg
                                    Just dir ->
                                        case dir of
                                            1 -> placeBuy baseBal quoteBal mBaseMinQty baseAsset quoteAsset
                                            (-1) -> placeSell baseBal mBaseMinQty baseAsset
                                            _ -> noOrder neutralMsg
  where
    sym = normalizeSymbol symRaw
    method = lsMethod sig
    chosenDir = lsChosenDir sig
    currentPrice = lsCurrentPrice sig

    entryScale :: Double
    entryScale = entryScaleForSignal args MarketSpot sig

    exitScale :: Double
    exitScale =
        maybe 1 clamp01 (lsExitSize sig)

    clientOrderId :: Maybe String
    clientOrderId = trim <$> argIdempotencyKey args

    baseResult :: ApiOrderResult
    baseResult =
        ApiOrderResult
            { aorSent = False
            , aorMode = Just (if argBinanceLive args then "live" else "paper")
            , aorSide = Nothing
            , aorSymbol = Just sym
            , aorQuantity = Nothing
            , aorQuoteQuantity = Nothing
            , aorOrderId = Nothing
            , aorClientOrderId = clientOrderId
            , aorStatus = Nothing
            , aorExecutedQty = Nothing
            , aorCummulativeQuoteQty = Nothing
            , aorTxHash = Nothing
            , aorResponse = Nothing
            , aorMessage = ""
            }

    noOrder :: String -> IO ApiOrderResult
    noOrder msg = pure baseResult{aorMessage = msg}

    neutralMsg =
        case method of
            MethodBoth -> "No order: directions disagree or neutral (direction gate)."
            MethodKalmanOnly -> "No order: Kalman neutral (within threshold)."
            MethodKalmanPhysicsError -> "No order: Kalman neutral (within threshold)."
            MethodLstmOnly -> "No order: LSTM neutral (within threshold)."
            MethodBlend -> "No order: Blend neutral (within threshold)."
            MethodConfBlend -> "No order: Conf blend neutral (within threshold)."
            MethodConfPick -> "No order: Conf pick neutral (within threshold)."
            MethodConformalClip -> "No order: Conformal clip neutral (within threshold)."
            MethodCostPick -> "No order: Cost pick neutral (within threshold)."
            MethodHarmonicBlend -> "No order: Harmonic blend neutral (within threshold)."
            MethodDisagreementGuard -> "No order: Disagreement guard neutral (within threshold)."
            MethodMedianBlend -> "No order: Median blend neutral (within threshold)."
            MethodNeutralGuard -> "No order: Neutral guard neutral (within threshold)."
            MethodRiskParityBlend -> "No order: Risk parity blend neutral (within threshold)."
            MethodConsensusBoost -> "No order: Consensus boost neutral (within threshold)."
            MethodAnchorBlend -> "No order: Anchor blend neutral (within threshold)."
            MethodTensionGate -> "No order: Tension gate neutral (within threshold)."
            MethodEntropyBlend -> "No order: Entropy blend neutral (within threshold)."
            MethodCoherenceGate -> "No order: Coherence gate neutral (within threshold)."
            MethodDivergenceGate -> "No order: Divergence gate neutral (within threshold)."
            MethodFractalBlend -> "No order: Fractal blend neutral (within threshold)."
            MethodPhaseCancel -> "No order: Phase cancel neutral (within threshold)."
            MethodSoftmaxBlend -> "No order: Softmax blend neutral (within threshold)."
            MethodSmoothSoftmaxBlend -> "No order: Smooth softmax blend neutral (within threshold)."
            MethodHedgeBlend -> "No order: Hedge blend neutral (within threshold)."
            MethodNetSoftmaxBlend -> "No order: Net softmax blend neutral (within threshold)."
            MethodEdgeBlend -> "No order: Edge blend neutral (within threshold)."
            MethodEdgePick -> "No order: Edge pick neutral (within threshold)."
            MethodGeoBlend -> "No order: Geo blend neutral (within threshold)."
            MethodRegimeSwitch -> "No order: Regime switch neutral (within threshold)."
            MethodRouter -> "No order: Router neutral (score/threshold)."
            MethodBanditRouter -> "No order: Bandit router neutral (score/threshold)."

    lstmBlockMsg :: Maybe String
    lstmBlockMsg = snd (lstmConfidenceSizing args sig)

    isLongCoinbaseSpot :: Maybe Double -> Double -> Bool
    isLongCoinbaseSpot mMinQty baseBal =
        case mMinQty of
            Just minQty | minQty > 0 -> baseBal >= minQty
            _ -> baseBal > 0

    splitCoinbaseSymbol s =
        case break (== '-') s of
            (base, '-' : quote)
                | not (null base) && not (null quote) ->
                    Right (map toUpper base, map toUpper quote)
            _ -> Left "Coinbase symbols must be BASE-QUOTE (e.g., BTC-USD)."

    sendOrder :: String -> Maybe Double -> Maybe Double -> IO ApiOrderResult
    sendOrder sideLabel mQty mFunds = do
        let baseOut =
                baseResult
                    { aorSide = Just sideLabel
                    , aorQuantity = mQty
                    , aorQuoteQuantity = mFunds
                    }
        r <- try (placeCoinbaseMarketOrder env sym sideLabel mQty mFunds clientOrderId) :: IO (Either SomeException BL.ByteString)
        case r of
            Left ex -> pure baseOut{aorMessage = "Order failed: " ++ take 240 (show ex)}
            Right body ->
                pure
                    baseOut
                        { aorSent = True
                        , aorResponse = Just (shortResp body)
                        , aorMessage = "Order sent."
                        }

    placeBuy baseBal quoteBal mBaseMinQty _baseAsset quoteAsset =
        if isLongCoinbaseSpot mBaseMinQty baseBal
            then noOrder "No order: already long."
            else case lstmBlockMsg of
                Just msg -> noOrder msg
                Nothing -> do
                    let qtyArg =
                            case argOrderQuantity args of
                                Just q | q > 0 -> Just (q * entryScale)
                                _ -> Nothing
                        quoteArg =
                            case argOrderQuote args of
                                Just q | q > 0 -> Just (q * entryScale)
                                _ -> Nothing
                        quoteFracArg =
                            case argOrderQuoteFraction args of
                                Just f | f > 0 -> Just (f * entryScale)
                                _ -> Nothing
                        maxOrderQuoteArg =
                            case argMaxOrderQuote args of
                                Just q | q > 0 -> Just q
                                _ -> Nothing
                        quoteFromFraction =
                            case (qtyArg, quoteArg, quoteFracArg) of
                                (Nothing, Nothing, Just f) ->
                                    let q0 = quoteBal * f
                                        q1 = maybe q0 (`min` q0) maxOrderQuoteArg
                                     in Just q1
                                _ -> Nothing
                        quoteEffective = quoteArg <|> quoteFromFraction

                    case (qtyArg, quoteEffective) of
                        (Nothing, Nothing) ->
                            case quoteFracArg of
                                Nothing -> noOrder "No order: provide orderQuantity or orderQuote."
                                Just _ -> noOrder "No order: computed quote is 0 (check quote balance / orderQuoteFraction / maxOrderQuote)."
                        (Just qRaw, _) ->
                            if currentPrice > 0 && qRaw * currentPrice > quoteBal
                                then noOrder ("No order: insufficient " ++ quoteAsset ++ " balance.")
                                else sendOrder "BUY" (Just qRaw) Nothing
                        (Nothing, Just qq0) ->
                            let qq = max 0 qq0
                             in if qq <= 0
                                    then noOrder "No order: quote is 0."
                                    else
                                        if qq > quoteBal
                                            then noOrder ("No order: insufficient " ++ quoteAsset ++ " balance.")
                                            else sendOrder "BUY" Nothing (Just qq)

    placeSell baseBal mBaseMinQty _baseAsset =
        if not (isLongCoinbaseSpot mBaseMinQty baseBal)
            then noOrder "No order: already flat."
            else do
                let qtyArg =
                        case argOrderQuantity args of
                            Just q | q > 0 -> Just q
                            _ -> Nothing
                    qtyArgSell = qtyArg
                    qRaw0 =
                        case qtyArgSell of
                            Just q -> min q baseBal
                            Nothing -> baseBal
                    qRaw = qRaw0 * exitScale
                case mBaseMinQty of
                    Just minQty | baseBal < minQty -> noOrder "No order: position below exchange minimums (dust)."
                    Just minQty
                        | qRaw > 0 && qRaw < minQty ->
                            noOrder $
                                if isJust qtyArgSell
                                    then "No order: orderQuantity below exchange minimums."
                                    else "No order: exit size below exchange minimums."
                    _ ->
                        if qRaw <= 0
                            then noOrder "No order: quantity is 0."
                            else sendOrder "SELL" (Just qRaw) Nothing

computeBacktestFromArgs :: Maybe OpsStore -> Args -> IO Aeson.Value
computeBacktestFromArgs mOps args = do
    (series, mBinanceEnv) <- loadPrices mOps args
    computeBacktestFromSeries args series mBinanceEnv

computeBacktestFromArgsWithLimits :: ApiComputeLimits -> Maybe OpsStore -> Args -> IO Aeson.Value
computeBacktestFromArgsWithLimits limits mOps args = do
    (series, mBinanceEnv) <- loadPrices mOps args
    seriesForLimits <-
        case applyBacktestTimeWindow args series of
            Left msg -> throwIO (userError msg)
            Right s -> pure s
    case validateApiComputeLimitsAfterLoad limits args seriesForLimits of
        Left msg -> throwIO (userError msg)
        Right () -> pure ()
    computeBacktestFromSeries args series mBinanceEnv

backtestTimeBoundsMs :: Args -> Either String (Maybe Int64, Maybe Int64)
backtestTimeBoundsMs args =
    let parseBound flag raw =
            case raw of
                Nothing -> Right Nothing
                Just s ->
                    case parseTimestampMs s of
                        Just t -> Right (Just t)
                        Nothing ->
                            Left
                                ( flag
                                    ++ " must be epoch seconds/ms or ISO-8601 (e.g. 1704067200, 1704067200000, 2025-01-01, 2025-01-01T00:00:00Z)"
                                )
     in do
            fromMs <- parseBound "--from" (argBacktestFrom args)
            toMs <- parseBound "--to" (argBacktestTo args)
            Right (fromMs, toMs)

applyBacktestTimeWindow :: Args -> PriceSeries -> Either String PriceSeries
applyBacktestTimeWindow args series = do
    (mFromMs, mToMs) <- backtestTimeBoundsMs args
    case (mFromMs, mToMs) of
        (Nothing, Nothing) -> Right series
        _ ->
            let prices = psClose series
                n = length prices
                inRange t = maybe True (<= t) mFromMs && maybe True (t <=) mToMs
                sliceContiguous i0 len xs = take len (drop i0 xs)
                keepMaybe xs =
                    case xs of
                        Just vals | length vals == n -> Just vals
                        _ -> Nothing
             in case psOpenTimes series of
                    Just openTimes
                        | length openTimes == n ->
                            let matching = [i | (i, t) <- zip [0 :: Int ..] openTimes, inRange t]
                             in case matching of
                                    [] ->
                                        Left
                                            ( "Backtest window is empty for the selected bounds. Adjust --from/--to. "
                                                ++ "(source: "
                                                ++ priceSourceLabel args
                                                ++ ")"
                                            )
                                    i0 : rest ->
                                        let i1 = foldl' (\_ i -> i) i0 rest
                                            len = i1 - i0 + 1
                                            opens = fmap (sliceContiguous i0 len) (keepMaybe (psOpen series))
                                            highs = fmap (sliceContiguous i0 len) (keepMaybe (psHigh series))
                                            lows = fmap (sliceContiguous i0 len) (keepMaybe (psLow series))
                                            volumes = fmap (sliceContiguous i0 len) (keepMaybe (psVolume series))
                                            openTimes' = Just (sliceContiguous i0 len openTimes)
                                            closes = sliceContiguous i0 len prices
                                         in Right (PriceSeries closes opens highs lows volumes openTimes')
                    _ ->
                        Left
                            "--from/--to require timestamped bars (CSV with a time column or exchange klines)."

scaleBacktestMetrics :: Double -> BacktestMetrics -> BacktestMetrics
scaleBacktestMetrics factor m =
    m
        { bmFinalEquity = bmFinalEquity m * factor
        , bmGrossProfit = bmGrossProfit m * factor
        , bmGrossLoss = bmGrossLoss m * factor
        }

scaleTradeEquity :: Double -> Trade -> Trade
scaleTradeEquity factor tr =
    tr
        { trEntryEquity = trEntryEquity tr * factor
        , trExitEquity = trExitEquity tr * factor
        }

scaleWalkForwardReport :: Double -> WalkForwardReport -> WalkForwardReport
scaleWalkForwardReport factor report =
    let scaleFold fold0 =
            fold0{wffMetrics = scaleBacktestMetrics factor (wffMetrics fold0)}
        scaleSummary summary =
            summary
                { wfsFinalEquityMean = wfsFinalEquityMean summary * factor
                , wfsFinalEquityStd = wfsFinalEquityStd summary * factor
                }
     in report
            { wfrFolds = map scaleFold (wfrFolds report)
            , wfrSummary = scaleSummary (wfrSummary report)
            }

scaleBaselineMetrics :: Double -> Baseline -> Baseline
scaleBaselineMetrics factor baseline =
    baseline{blMetrics = scaleBacktestMetrics factor (blMetrics baseline)}

computeBacktestFromSeries :: Args -> PriceSeries -> Maybe BinanceEnv -> IO Aeson.Value
computeBacktestFromSeries args series mBinanceEnv = do
    let lookback = argLookback args
    summary <- computeBacktestSummary args lookback series mBinanceEnv
    pure (backtestSummaryJson summary)

backtestSummaryJson :: BacktestSummary -> Aeson.Value
backtestSummaryJson summary =
    let metrics = bsMetrics summary
        tuneStatsJson =
            case bsTuneStats summary of
                Nothing -> Nothing
                Just st ->
                    Just
                        ( object
                            [ "folds" .= tsFoldCount st
                            , "scores" .= tsFoldScores st
                            , "meanScore" .= tsMeanScore st
                            , "stdScore" .= tsStdScore st
                            ]
                        )
        tuneMetricsJson =
            case bsTuneMetrics summary of
                Nothing -> Nothing
                Just m -> Just (metricsToJson m)
        tuningJson =
            object
                [ "objective" .= tuneObjectiveCode (bsTuneObjective summary)
                , "penaltyMaxDrawdown" .= bsTunePenaltyMaxDrawdown summary
                , "penaltyTurnover" .= bsTunePenaltyTurnover summary
                , "stressVolMult" .= bsTuneStressVolMult summary
                , "stressShock" .= bsTuneStressShock summary
                , "stressWeight" .= bsTuneStressWeight summary
                , "minRoundTrips" .= bsMinRoundTrips summary
                , "walkForwardFolds" .= bsWalkForwardFolds summary
                , "walkForwardEmbargoBars" .= bsWalkForwardEmbargoBars summary
                , "tuneStats" .= tuneStatsJson
                , "tuneMetrics" .= tuneMetricsJson
                ]
        costsJson =
            object
                [ "fee" .= bsFee summary
                , "slippage" .= bsSlippage summary
                , "spread" .= bsSpread summary
                , "feeFixed" .= bsFeeFixed summary
                , "feeMin" .= bsFeeMin summary
                , "slippageVolMult" .= bsSlippageVolMult summary
                , "slippageImpact" .= bsSlippageImpact summary
                , "slippageImpactPower" .= bsSlippageImpactPower summary
                , "spreadVolMult" .= bsSpreadVolMult summary
                , "perSideCost" .= bsEstimatedPerSideCost summary
                , "roundTripCost" .= bsEstimatedRoundTripCost summary
                , "breakEvenThreshold" .= breakEvenThresholdFromPerSideCost (bsEstimatedPerSideCost summary)
                ]
        walkForwardJson =
            case bsWalkForward summary of
                Nothing -> Nothing
                Just wf ->
                    let foldJson f =
                            object
                                [ "startIndex" .= wffStartIndex f
                                , "endIndex" .= wffEndIndex f
                                , "metrics" .= metricsToJson (wffMetrics f)
                                ]
                        s = wfrSummary wf
                        summaryJson =
                            object
                                [ "finalEquityMean" .= wfsFinalEquityMean s
                                , "finalEquityStd" .= wfsFinalEquityStd s
                                , "annualizedReturnMean" .= wfsAnnualizedReturnMean s
                                , "annualizedReturnStd" .= wfsAnnualizedReturnStd s
                                , "sharpeMean" .= wfsSharpeMean s
                                , "sharpeStd" .= wfsSharpeStd s
                                , "maxDrawdownMean" .= wfsMaxDrawdownMean s
                                , "maxDrawdownStd" .= wfsMaxDrawdownStd s
                                , "turnoverMean" .= wfsTurnoverMean s
                                , "turnoverStd" .= wfsTurnoverStd s
                                ]
                     in Just (object ["foldCount" .= wfrFoldCount wf, "folds" .= map foldJson (wfrFolds wf), "summary" .= summaryJson])
     in object
            [ "split"
                .= object
                    [ "train" .= bsTrainSize summary
                    , "fit" .= bsFitSize summary
                    , "tune" .= bsTuneSize summary
                    , "tuneRatio" .= bsTuneRatio summary
                    , "tuneStartIndex" .= bsFitSize summary
                    , "backtest" .= bsBacktestSize summary
                    , "backtestRatio" .= bsBacktestRatio summary
                    , "from" .= bsBacktestFromMs summary
                    , "to" .= bsBacktestToMs summary
                    , "backtestStartIndex" .= bsTrainEnd summary
                    ]
            , "initialBalance" .= bsInitialBalance summary
            , "method" .= methodCode (bsMethodUsed summary)
            , "volConfGate" .= volConfGateCode (bsVolConfGate summary)
            , "vol_conf_gate" .= volConfGateCode (bsVolConfGate summary)
            , "threshold" .= bsBestOpenThreshold summary
            , "openThreshold" .= bsBestOpenThreshold summary
            , "closeThreshold" .= bsBestCloseThreshold summary
            , "minHoldBars" .= bsMinHoldBars summary
            , "cooldownBars" .= bsCooldownBars summary
            , "maxHoldBars" .= bsMaxHoldBars summary
            , "stopLossVolMult" .= bsStopLossVolMult summary
            , "takeProfitVolMult" .= bsTakeProfitVolMult summary
            , "trailingStopVolMult" .= bsTrailingStopVolMult summary
            , "maxPositionSize" .= bsMaxPositionSize summary
            , "minEdge" .= bsMinEdge summary
            , "minSignalToNoise" .= bsMinSignalToNoise summary
            , "costAwareEdge" .= bsCostAwareEdge summary
            , "edgeBuffer" .= bsEdgeBuffer summary
            , "trendLookback" .= bsTrendLookback summary
            , "volTarget" .= bsVolTarget summary
            , "volLookback" .= bsVolLookback summary
            , "volEwmaAlpha" .= bsVolEwmaAlpha summary
            , "volFloor" .= bsVolFloor summary
            , "volScaleMax" .= bsVolScaleMax summary
            , "maxVolatility" .= bsMaxVolatility summary
            , "rebalanceBars" .= bsRebalanceBars summary
            , "rebalanceThreshold" .= bsRebalanceThreshold summary
            , "rebalanceCostMult" .= bsRebalanceCostMult summary
            , "rebalanceGlobal" .= bsRebalanceGlobal summary
            , "fundingRate" .= bsFundingRate summary
            , "fundingBySide" .= bsFundingBySide summary
            , "rebalanceResetOnSignal" .= bsRebalanceResetOnSignal summary
            , "fundingOnOpen" .= bsFundingOnOpen summary
            , "blendWeight" .= bsBlendWeight summary
            , "triLayer" .= bsTriLayer summary
            , "triLayerFastMult" .= bsTriLayerFastMult summary
            , "triLayerSlowMult" .= bsTriLayerSlowMult summary
            , "triLayerCloudPadding" .= bsTriLayerCloudPadding summary
            , "triLayerCloudSlope" .= bsTriLayerCloudSlope summary
            , "triLayerCloudWidth" .= bsTriLayerCloudWidth summary
            , "triLayerTouchLookback" .= bsTriLayerTouchLookback summary
            , "triLayerPriceAction" .= bsTriLayerPriceAction summary
            , "triLayerPriceActionBody" .= bsTriLayerPriceActionBody summary
            , "triLayerExitOnSlow" .= bsTriLayerExitOnSlow summary
            , "kalmanBandLookback" .= bsKalmanBandLookback summary
            , "kalmanBandStdMult" .= bsKalmanBandStdMult summary
            , "lstmExitFlipStrong" .= bsLstmExitFlipStrong summary
            , "lstmExitFlipBars" .= bsLstmExitFlipBars summary
            , "lstmExitFlipGraceBars" .= bsLstmExitFlipGraceBars summary
            , "lstmConfidenceSoft" .= bsLstmConfidenceSoft summary
            , "lstmConfidenceHard" .= bsLstmConfidenceHard summary
            , "tuning" .= tuningJson
            , "costs" .= costsJson
            , "walkForward" .= walkForwardJson
            , "metrics" .= metricsToJson metrics
            , "sharpe" .= bmSharpe metrics
            , "max_drawdown" .= bmMaxDrawdown metrics
            , "avg_trade" .= bmAvgTradeReturn metrics
            , "closed_trades" .= bmRoundTrips metrics
            , "baselines" .= map baselineToJson (bsBaselines summary)
            , "latestSignal" .= bsLatestSignal summary
            , "equityCurve" .= bsEquityCurve summary
            , "prices" .= bsBacktestPrices summary
            , "openTimes" .= bsOpenTimes summary
            , "kalmanPredNext" .= bsKalmanPredNext summary
            , "lstmPredNext" .= bsLstmPredNext summary
            , "positions" .= bsPositions summary
            , "agreementOk" .= bsAgreementOk summary
            , "trades" .= map tradeToJson (bsTrades summary)
            ]

tradeToJson :: Trade -> Aeson.Value
tradeToJson tr =
    object
        [ "entryIndex" .= trEntryIndex tr
        , "exitIndex" .= trExitIndex tr
        , "entryEquity" .= trEntryEquity tr
        , "exitEquity" .= trExitEquity tr
        , "return" .= trReturn tr
        , "holdingPeriods" .= trHoldingPeriods tr
        , "entryHighVolProb" .= trEntryHighVolProb tr
        , "exitReason" .= trExitReason tr
        , "entryIp" .= trEntryIp tr
        , "exitIp" .= trExitIp tr
        ]

baselineToJson :: Baseline -> Aeson.Value
baselineToJson b =
    object
        [ "name" .= blName b
        , "metrics" .= metricsToJson (blMetrics b)
        ]

metricsToJson :: BacktestMetrics -> Aeson.Value
metricsToJson m =
    object
        [ "finalEquity" .= bmFinalEquity m
        , "totalReturn" .= bmTotalReturn m
        , "annualizedReturn" .= bmAnnualizedReturn m
        , "annualizedVolatility" .= bmAnnualizedVolatility m
        , "sharpe" .= bmSharpe m
        , "sortino" .= bmSortino m
        , "calmar" .= bmCalmar m
        , "downsideVolatility" .= bmDownsideVolatility m
        , "var95" .= bmVaR95 m
        , "cvar95" .= bmCVaR95 m
        , "maxDrawdown" .= bmMaxDrawdown m
        , "tradeCount" .= bmTradeCount m
        , "positionChanges" .= bmPositionChanges m
        , "roundTrips" .= bmRoundTrips m
        , "closedTrades" .= bmRoundTrips m
        , "closed_trades" .= bmRoundTrips m
        , "winRate" .= bmWinRate m
        , "grossProfit" .= bmGrossProfit m
        , "grossLoss" .= bmGrossLoss m
        , "profitFactor" .= bmProfitFactor m
        , "avgTradeReturn" .= bmAvgTradeReturn m
        , "avgTrade" .= bmAvgTradeReturn m
        , "avg_trade" .= bmAvgTradeReturn m
        , "avgHoldingPeriods" .= bmAvgHoldingPeriods m
        , "exposure" .= bmExposure m
        , "agreementRate" .= bmAgreementRate m
        , "turnover" .= bmTurnover m
        , "max_drawdown" .= bmMaxDrawdown m
        ]

runTradeOnly :: Maybe Webhook -> Args -> Int -> PriceSeries -> Maybe BinanceEnv -> IO ()
runTradeOnly mWebhook args lookback series mBinanceEnv = do
    ensureRuntimeConfig args
    signal <- computeTradeOnlySignal args lookback series mBinanceEnv
    if argJson args
        then
            if argBinanceTrade args
                then do
                    order <- placeOrderForSignalPlatform args signal mBinanceEnv
                    webhookNotifyMaybeSync mWebhook (webhookEventTradeOrder args signal order)
                    printJsonStdout (object ["mode" .= ("trade" :: String), "trade" .= ApiTradeResponse signal order])
                else printJsonStdout (object ["mode" .= ("signal" :: String), "signal" .= signal])
        else do
            printLatestSignalSummary signal
            let sizeRef = max 1e-6 (max 0 (fromMaybe (argMaxPositionSize args) (lsPositionSize signal)))
                volPerBar = volPerBarFromSignal args signal
                perSide = estimatedPerSideCost args sizeRef volPerBar
                roundTrip = estimatedRoundTripCost args sizeRef volPerBar
                minEdgeBase = max 0 (argMinEdge args)
                minEdge =
                    if argCostAwareEdge args
                        then max minEdgeBase (breakEvenThresholdFromPerSideCost perSide + max 0 (argEdgeBuffer args))
                        else minEdgeBase
                openThr = max (argOpenThreshold args) minEdge
            printCostGuidance openThr (argCloseThreshold args) perSide roundTrip
            maybeSendOrder mWebhook args mBinanceEnv signal

runBacktestPipeline :: Maybe Webhook -> Args -> Int -> PriceSeries -> Maybe BinanceEnv -> IO ()
runBacktestPipeline mWebhook args lookback series mBinanceEnv = do
    ensureRuntimeConfig args
    summary <- computeBacktestSummary args lookback series mBinanceEnv
    if argJson args
        then do
            let base = backtestSummaryJson summary
            if argBinanceTrade args
                then do
                    order <- placeOrderForSignalPlatform args (bsLatestSignal summary) mBinanceEnv
                    webhookNotifyMaybeSync mWebhook (webhookEventTradeOrder args (bsLatestSignal summary) order)
                    printJsonStdout (object ["mode" .= ("backtest" :: String), "backtest" .= base, "trade" .= ApiTradeResponse (bsLatestSignal summary) order])
                else printJsonStdout (object ["mode" .= ("backtest" :: String), "backtest" .= base])
        else do
            let n = bsTrainSize summary + bsBacktestSize summary
                trainEndRaw = bsTrainEndRaw summary
                trainEnd = bsTrainEnd summary
                backtestRatio = bsBacktestRatio summary

            when (trainEndRaw /= trainEnd) $
                putStrLn
                    ( printf
                        "Split adjusted for lookback: requested train=%d backtest=%d -> using train=%d backtest=%d"
                        trainEndRaw
                        (n - trainEndRaw)
                        trainEnd
                        (n - trainEnd)
                    )

            if bsTuneSize summary > 0
                then
                    putStrLn
                        ( printf
                            "\nSplit: fit=%d tune=%d backtest=%d (tune-ratio=%.3f, backtest-ratio=%.3f)"
                            (bsFitSize summary)
                            (bsTuneSize summary)
                            (bsBacktestSize summary)
                            (bsTuneRatio summary)
                            backtestRatio
                        )
                else
                    putStrLn
                        ( printf
                            "\nSplit: train=%d backtest=%d (backtest-ratio=%.3f)"
                            (bsTrainSize summary)
                            (bsBacktestSize summary)
                            backtestRatio
                        )

            if argOptimizeOperations args
                then
                    putStrLn
                        ( printf
                            "Optimized on tune split (objective=%s): method=%s open=%.6f (%.3f%%) close=%.6f (%.3f%%)"
                            (tuneObjectiveCode (bsTuneObjective summary))
                            (methodCode (bsMethodUsed summary))
                            (bsBestOpenThreshold summary)
                            (bsBestOpenThreshold summary * 100)
                            (bsBestCloseThreshold summary)
                            (bsBestCloseThreshold summary * 100)
                        )
                else
                    when (argSweepThreshold args) $
                        putStrLn
                            ( printf
                                "Best thresholds on tune split (objective=%s): open=%.6f (%.3f%%) close=%.6f (%.3f%%)"
                                (tuneObjectiveCode (bsTuneObjective summary))
                                (bsBestOpenThreshold summary)
                                (bsBestOpenThreshold summary * 100)
                                (bsBestCloseThreshold summary)
                                (bsBestCloseThreshold summary * 100)
                            )

            case (bsBacktestFromMs summary, bsBacktestToMs summary) of
                (Nothing, Nothing) -> pure ()
                (mFrom, mTo) ->
                    putStrLn
                        ( printf
                            "Backtest window: from=%s to=%s"
                            (maybe "start" show mFrom)
                            (maybe "end" show mTo)
                        )

            case bsTuneStats summary of
                Nothing -> pure ()
                Just st ->
                    when (bsTuneSize summary > 0) $
                        putStrLn
                            ( printf
                                "Tune objective stats: folds=%d mean=%.6f std=%.6f (ddPenalty=%.3f, turnoverPenalty=%.3f)"
                                (tsFoldCount st)
                                (tsMeanScore st)
                                (tsStdScore st)
                                (bsTunePenaltyMaxDrawdown summary)
                                (bsTunePenaltyTurnover summary)
                            )

            when (argOptimizeOperations args || argSweepThreshold args) $
                when (bsTuneObjective summary /= TuneAnnualizedEquity) $
                    putStrLn "Tip: To optimize annualized equity, rerun with --tune-objective annualized-equity (alias: annualized-return)."

            printCostGuidance
                (max (bsBestOpenThreshold summary) (bsMinEdge summary))
                (bsBestCloseThreshold summary)
                (bsEstimatedPerSideCost summary)
                (bsEstimatedRoundTripCost summary)
            printFundingGuidance (argFundingRate args) (argFundingBySide args)
            putStrLn (printf "Vol/conf gate: %s" (volConfGateCode (bsVolConfGate summary)))

            putStrLn $
                case bsMethodUsed summary of
                    MethodBoth -> "Backtest (Kalman fusion + LSTM direction-agreement gated) complete."
                    MethodKalmanOnly -> "Backtest (Kalman fusion only) complete."
                    MethodKalmanPhysicsError -> "Backtest (Kalman physics-error model) complete."
                    MethodLstmOnly -> "Backtest (LSTM only) complete."
                    MethodBlend -> "Backtest (Kalman + LSTM blend) complete."
                    MethodConfBlend -> "Backtest (confidence-weighted Kalman/LSTM blend) complete."
                    MethodConfPick -> "Backtest (confidence winner-take-all Kalman/LSTM pick) complete."
                    MethodConformalClip -> "Backtest (conformal-clipped Kalman/LSTM blend) complete."
                    MethodCostPick -> "Backtest (cost-aware Kalman/LSTM pick) complete."
                    MethodHarmonicBlend -> "Backtest (harmonic-return Kalman/LSTM blend) complete."
                    MethodDisagreementGuard -> "Backtest (disagreement-aware Kalman/LSTM pick) complete."
                    MethodMedianBlend -> "Backtest (median-robust Kalman/LSTM blend) complete."
                    MethodNeutralGuard -> "Backtest (neutral-on-disagreement Kalman/LSTM guard) complete."
                    MethodRiskParityBlend -> "Backtest (risk-parity Kalman/LSTM blend) complete."
                    MethodConsensusBoost -> "Backtest (consensus-boost Kalman/LSTM guard) complete."
                    MethodAnchorBlend -> "Backtest (anchor-to-price Kalman/LSTM blend) complete."
                    MethodTensionGate -> "Backtest (tension-gated Kalman/LSTM guard) complete."
                    MethodEntropyBlend -> "Backtest (entropy-aware Kalman/LSTM blend) complete."
                    MethodCoherenceGate -> "Backtest (coherence-gated Kalman/LSTM guard) complete."
                    MethodDivergenceGate -> "Backtest (divergence-gated Kalman/LSTM blend) complete."
                    MethodFractalBlend -> "Backtest (fractal-space Kalman/LSTM blend) complete."
                    MethodPhaseCancel -> "Backtest (phase-cancel Kalman/LSTM guard) complete."
                    MethodSoftmaxBlend -> "Backtest (softmax-edge Kalman/LSTM blend) complete."
                    MethodSmoothSoftmaxBlend -> "Backtest (EMA-smoothed softmax-edge Kalman/LSTM blend) complete."
                    MethodHedgeBlend -> "Backtest (hedge-weighted Kalman/LSTM blend) complete."
                    MethodNetSoftmaxBlend -> "Backtest (post-cost softmax Kalman/LSTM blend) complete."
                    MethodEdgeBlend -> "Backtest (edge-weighted Kalman/LSTM blend) complete."
                    MethodEdgePick -> "Backtest (edge winner-take-all Kalman/LSTM pick) complete."
                    MethodGeoBlend -> "Backtest (geometric Kalman/LSTM blend) complete."
                    MethodRegimeSwitch -> "Backtest (regime-switched Kalman/LSTM) complete."
                    MethodRouter -> "Backtest (adaptive router: Kalman/LSTM/blend) complete."
                    MethodBanditRouter -> "Backtest (bandit router: Kalman/LSTM/blend) complete."

            Data.Foldable.for_ (bsLstmHistory summary) printLstmSummary

            printMetrics (bsMethodUsed summary) (bsInitialBalance summary) (bsMetrics summary)

            case bsWalkForward summary of
                Nothing -> pure ()
                Just wf -> do
                    let s = wfrSummary wf
                        initialBalance = bsInitialBalance summary
                    putStrLn ""
                    putStrLn "**Walk-forward backtest**"
                    if abs (initialBalance - 1) <= 1e-12
                        then
                            putStrLn
                                ( printf
                                    "Folds=%d finalEq=%.4fx±%.4fx sharpe=%.3f±%.3f maxDD=%.2f%%±%.2f%% turnover=%.4f±%.4f"
                                    (wfrFoldCount wf)
                                    (wfsFinalEquityMean s)
                                    (wfsFinalEquityStd s)
                                    (wfsSharpeMean s)
                                    (wfsSharpeStd s)
                                    (wfsMaxDrawdownMean s * 100)
                                    (wfsMaxDrawdownStd s * 100)
                                    (wfsTurnoverMean s)
                                    (wfsTurnoverStd s)
                                )
                        else
                            putStrLn
                                ( printf
                                    "Folds=%d finalEq=%.4f±%.4f (initial=%.4f) sharpe=%.3f±%.3f maxDD=%.2f%%±%.2f%% turnover=%.4f±%.4f"
                                    (wfrFoldCount wf)
                                    (wfsFinalEquityMean s)
                                    (wfsFinalEquityStd s)
                                    initialBalance
                                    (wfsSharpeMean s)
                                    (wfsSharpeStd s)
                                    (wfsMaxDrawdownMean s * 100)
                                    (wfsMaxDrawdownStd s * 100)
                                    (wfsTurnoverMean s)
                                    (wfsTurnoverStd s)
                                )

            printLatestSignalSummary (bsLatestSignal summary)
            maybeSendOrder mWebhook args mBinanceEnv (bsLatestSignal summary)

printJsonStdout :: (ToJSON a) => a -> IO ()
printJsonStdout v = BS.putStrLn (BL.toStrict (encode v))

computeTradeOnlySignal :: Args -> Int -> PriceSeries -> Maybe BinanceEnv -> IO LatestSignal
computeTradeOnlySignal args lookback series mBinanceEnv = do
    when
        (argSweepThreshold args)
        (throwIO (userError "Cannot use --sweep-threshold with --trade-only (sweep requires a backtest split)."))
    when
        (argOptimizeOperations args)
        (throwIO (userError "Cannot use --optimize-operations with --trade-only (optimization requires a backtest split)."))

    let prices = psClose series
        featureInputs = featureInputsFromSeries series
        method = runtimeMethod (argMethod args)
        pricesV = fiClose featureInputs
        n = V.length pricesV
        stepCount = max 0 (n - 1)
        needsHistory = argThresholdFactorEnabled args || method == MethodRouter || method == MethodBanditRouter
    when
        (n <= lookback)
        ( throwIO
            ( userError
                ( printf
                    "Not enough data for lookback=%d (need >= %d prices, got %d). Reduce --lookback-bars/--lookback-window or increase --bars."
                    lookback
                    (lookback + 1)
                    n
                )
            )
        )

    mMarketModel <-
        case (method, mBinanceEnv, argBinanceSymbol args) of
            (MethodLstmOnly, _, _) -> pure Nothing
            (_, Just env, Just sym)
                | platformSupportsMarketContext (argPlatform args) -> do
                    r <- try (buildMarketModel args env sym n pricesV) :: IO (Either SomeException (Maybe MarketModel))
                    case r of
                        Right model -> pure model
                        Left ex -> do
                            hPutStrLn stderr ("WARN: failed to build market context model (trade-only) for " ++ sym ++ ": " ++ displayException ex)
                            pure Nothing
            _ -> pure Nothing

    (mLstmCtx, mLstmPredHistory, mLstmHealth) <-
        case method of
            MethodKalmanOnly -> pure (Nothing, Nothing, Nothing)
            _ -> do
                let normState = fitNorm (argNormalization args) prices
                    obsAll = forwardSeries normState prices
                    lstmCfg =
                        LSTMConfig
                            { lcLookback = lookback
                            , lcHiddenSize = argHiddenSize args
                            , lcEpochs = argEpochs args
                            , lcLearningRate = argLr args
                            , lcValRatio = argValRatio args
                            , lcPatience = argPatience args
                            , lcGradClip = argGradClip args
                            , lcSeed = argSeed args
                            }
                (lstmModel, lstmHistory) <- trainLstmWithPersistence args lookback lstmCfg obsAll
                let lstmPredHistory =
                        if needsHistory
                            then
                                let obsV = V.fromList obsAll
                                 in Just $
                                        V.generate stepCount $ \i ->
                                            if i < lookback - 1
                                                then pricesV V.! i
                                                else
                                                    let window = V.toList (V.slice (i - lookback + 1) lookback obsV)
                                                        predObs = predictNext lstmModel window
                                                     in inverseNorm normState predObs
                            else Nothing
                    lstmHealth = lstmHealthScore lstmHistory
                pure (Just (normState, obsAll, lstmModel), lstmPredHistory, lstmHealth)

    (mKalmanCtx, mKalPredHistory, mMetaHistory) <-
        case method of
            MethodLstmOnly -> pure (Nothing, Nothing, Nothing)
            _ | needsHistory -> do
                let predictors = trainPredictorsWithInputsWithMarket (argPredictors args) lookback mMarketModel featureInputs
                    hmm0 = initHMMFilter predictors []
                    kal0 =
                        initKalman1
                            0
                            (max 1e-12 (argKalmanMeasurementVar args))
                            (max 0 (argKalmanProcessVar args) * max 0 (argKalmanDt args))
                    sv0 = emptySensorVar
                    (kalPrev, hmmPrev, svPrev, kalPredRev, metaRev) =
                        foldl'
                            (backtestStepKalmanOnly args featureInputs predictors 0 mMarketModel)
                            (kal0, hmm0, sv0, [], [])
                            [0 .. stepCount - 1]
                    kalPredV = V.fromList (reverse kalPredRev)
                    metaV = V.fromList (reverse metaRev)
                pure (Just (predictors, kalPrev, hmmPrev, svPrev), Just kalPredV, Just metaV)
            _ -> do
                let predictors = trainPredictorsWithInputsWithMarket (argPredictors args) lookback mMarketModel featureInputs
                    hmm0 = initHMMFilter predictors []
                    kal0 =
                        initKalman1
                            0
                            (max 1e-12 (argKalmanMeasurementVar args))
                            (max 0 (argKalmanProcessVar args) * max 0 (argKalmanDt args))
                    sv0 = emptySensorVar

                    step (kal, hmm, sv) t =
                        let priceT = pricesV V.! t
                            nextP = pricesV V.! (t + 1)
                            realizedR = if priceT == 0 then 0 else nextP / priceT - 1
                            (sensorOuts, predState) = predictSensorsWithInputs predictors featureInputs hmm t
                            meas = mapMaybe (toMeasurement args sv) sensorOuts ++ maybeToList (mMarketModel >>= (`marketMeasurementAt` t))
                            kal' = stepMulti meas kal
                            sv' =
                                foldl'
                                    (\acc (sid, out) -> updateResidual sid (realizedR - soMu out) acc)
                                    sv
                                    sensorOuts
                            hmm' = updateHMM predictors predState realizedR
                         in (kal', hmm', sv')

                    (kalPrev, hmmPrev, svPrev) = foldl' step (kal0, hmm0, sv0) [0 .. n - 2]
                pure (Just (predictors, kalPrev, hmmPrev, svPrev), Nothing, Nothing)

    let mPredHistory =
            if not needsHistory
                then Nothing
                else case (mKalPredHistory, mLstmPredHistory) of
                    (Just kalHist, Just lstmHist) ->
                        Just
                            PredHistory
                                { phKalman = kalHist
                                , phLstm = lstmHist
                                , phMeta = mMetaHistory
                                , phLstmHealth = mLstmHealth
                                }
                    (Just kalHist, Nothing) ->
                        Just
                            PredHistory
                                { phKalman = kalHist
                                , phLstm = kalHist
                                , phMeta = mMetaHistory
                                , phLstmHealth = mLstmHealth
                                }
                    (Nothing, Just lstmHist) ->
                        Just
                            PredHistory
                                { phKalman = lstmHist
                                , phLstm = lstmHist
                                , phMeta = Nothing
                                , phLstmHealth = mLstmHealth
                                }
                    _ -> Nothing

    case computeLatestSignal args lookback featureInputs mLstmCtx mKalmanCtx mMarketModel mPredHistory of
        Left err -> throwIO (userError err)
        Right sig -> pure sig

-- LSTM weight persistence (for incremental training across backtests)

data PersistedLstmModel = PersistedLstmModel
    { plmVersion :: !Int
    , plmHiddenSize :: !Int
    , plmTrainBars :: !Int
    , plmParams :: ![Double]
    }
    deriving (Eq, Show, Generic)

instance FromJSON PersistedLstmModel where
    parseJSON = Aeson.genericParseJSON (jsonOptions 3)

instance ToJSON PersistedLstmModel where
    toJSON = Aeson.genericToJSON (jsonOptions 3)

defaultLstmWeightsDir :: FilePath
defaultLstmWeightsDir = ".tmp/lstm"

resolveLstmWeightsDir :: IO (Maybe FilePath)
resolveLstmWeightsDir = do
    mDir <- lookupEnv "TRADER_LSTM_WEIGHTS_DIR"
    case trim <$> mDir of
        Just dir | null dir -> pure Nothing
        Just dir -> pure (Just dir)
        Nothing -> do
            mStateDir <- stateSubdirFromEnv "lstm"
            pure (Just (fromMaybe defaultLstmWeightsDir mStateDir))

hashBytesHex :: BL.ByteString -> String
hashBytesHex bs =
    let digest :: Digest SHA256
        digest = hash (BL.toStrict bs)
     in BS.unpack (B16.encode (convert digest))

lstmWeightsPath :: Args -> Int -> IO (Maybe FilePath)
lstmWeightsPath args lookback = do
    mDir <- resolveLstmWeightsDir
    case mDir of
        Nothing -> pure Nothing
        Just dir -> do
            key <- lstmModelKey args lookback
            let file = "lstm-" ++ hashKeyHex key ++ ".json"
            pure (Just (dir </> file))

loadPersistedLstmModel :: FilePath -> Int -> Int -> IO (Maybe LSTMModel)
loadPersistedLstmModel path hidden trainBars = do
    exists <- doesFileExist path
    if not exists
        then pure Nothing
        else do
            eBs <- try (BL.readFile path) :: IO (Either SomeException BL.ByteString)
            case eBs of
                Left _ -> pure Nothing
                Right bs ->
                    case eitherDecode bs of
                        Left _ -> pure Nothing
                        Right plm ->
                            let ok =
                                    plmVersion plm == 2
                                        && plmHiddenSize plm == hidden
                                        && plmTrainBars plm <= max 0 trainBars
                                        && length (plmParams plm) == paramCount hidden
                             in if ok
                                    then pure (Just (LSTMModel (plmHiddenSize plm) (plmParams plm)))
                                    else pure Nothing

savePersistedLstmModelMaybe :: Maybe FilePath -> Int -> LSTMModel -> IO ()
savePersistedLstmModelMaybe mPath trainBars model =
    case mPath of
        Nothing -> pure ()
        Just path -> do
            _ <-
                try
                    ( do
                        createDirectoryIfMissing True (takeDirectory path)
                        let plm =
                                PersistedLstmModel
                                    { plmVersion = 2
                                    , plmHiddenSize = lmHiddenSize model
                                    , plmTrainBars = max 0 trainBars
                                    , plmParams = lmParams model
                                    }
                        randId <- randomIO :: IO Word64
                        let tmpPath = path ++ ".tmp-" ++ show randId
                        BL.writeFile tmpPath (encode plm)
                        -- Atomic on POSIX when within the same filesystem; on Windows, fall back to replace.
                        r1 <- try (renameFile tmpPath path) :: IO (Either SomeException ())
                        case r1 of
                            Right _ -> pure ()
                            Left _ -> do
                                _ <- try (removeFile path) :: IO (Either SomeException ())
                                _ <- try (renameFile tmpPath path) :: IO (Either SomeException ())
                                pure ()
                    ) ::
                    IO (Either SomeException ())
            pure ()

trainLstmWithPersistence :: Args -> Int -> LSTMConfig -> [Double] -> IO (LSTMModel, [EpochStats])
trainLstmWithPersistence args lookback cfg series = do
    let trainBars = length series
    when (trainBars <= lookback) $
        throwIO
            ( userError
                ( printf
                    "Not enough data for lookback=%d (got %d bars). Increase --bars/--lookback-window or reduce --lookback-bars."
                    lookback
                    trainBars
                )
            )
    mPath <- lstmWeightsPath args lookback
    mSeed <-
        case mPath of
            Nothing -> pure Nothing
            Just path -> loadPersistedLstmModel path (lcHiddenSize cfg) trainBars
    let (model, hist) =
            case mSeed of
                Just seedModel -> fineTuneLSTM cfg seedModel series
                Nothing -> trainLSTM cfg series
    savePersistedLstmModelMaybe mPath trainBars model
    pure (model, hist)

computeBacktestSummary :: Args -> Int -> PriceSeries -> Maybe BinanceEnv -> IO BacktestSummary
computeBacktestSummary args lookback series mBinanceEnv = do
    seriesWindow <-
        case applyBacktestTimeWindow args series of
            Left msg -> throwIO (userError msg)
            Right s -> pure s
    (backtestFromMs, backtestToMs) <-
        case backtestTimeBoundsMs args of
            Left msg -> throwIO (userError msg)
            Right bounds -> pure bounds
    let methodRequestedRaw = argMethod args
        methodRequested = runtimeMethod methodRequestedRaw
        useKalmanPhysics = methodRequestedRaw == MethodKalmanPhysicsError
        methodRequestedForReporting =
            if useKalmanPhysics
                then MethodKalmanPhysicsError
                else methodRequested
        trimForMethod xs =
            if useKalmanPhysics
                then takeLast 1000 xs
                else xs
        pricesRaw = psClose seriesWindow
        nRaw = length pricesRaw
        prices = trimForMethod pricesRaw
        n = length prices
        matchLengthAndTrim mVals =
            case mVals of
                Just vals | length vals == nRaw -> Just (trimForMethod vals)
                _ -> Nothing
    ensureMinPriceRows args 2 prices
    ensureLookbackRows args lookback prices
    when useKalmanPhysics $ do
        when (argOptimizeOperations args || argSweepThreshold args) $
            throwIO (userError "Method kalman_physics_error does not support --optimize-operations/--sweep-threshold.")
        when (n < 1000) $
            throwIO
                ( userError
                    ( "Method kalman_physics_error requires 1000 bars (got "
                        ++ show n
                        ++ "). Increase --bars and ensure data source has enough rows."
                    )
                )
    let initialBalance = argInitialBalance args
        backtestRatio =
            if useKalmanPhysics
                then 0.3
                else argBacktestRatio args
    split <-
        case splitTrainBacktest lookback backtestRatio prices of
            Left err -> throwIO (userError err)
            Right s -> pure s
    let trainEndRaw = splitTrainEndRaw split
        trainEnd = splitTrainEnd split
        trainPrices = splitTrain split
        backtestPrices = splitBacktest split
        trainSize = length trainPrices
        tuningEnabled = not useKalmanPhysics && (argOptimizeOperations args || argSweepThreshold args)
        tuneRatio = max 0 (min 0.999999 (argTuneRatio args))
        tuneRatioUsed = if tuningEnabled then tuneRatio else 0
        tuneSize =
            if tuningEnabled
                then max 0 (min trainSize (floor (fromIntegral trainSize * tuneRatioUsed)))
                else 0
        fitSize = max 0 (trainSize - tuneSize)

    when (tuningEnabled && tuneSize < 2) $
        throwIO
            ( userError
                ( printf
                    "Tune window too small (%d). Increase --tune-ratio, reduce --backtest-ratio, or increase the number of bars."
                    tuneSize
                )
            )
    when (tuningEnabled && fitSize < lookback + 1) $
        throwIO
            ( userError
                ( printf
                    "Fit window too small for lookback=%d (fit=%d, tune=%d). Decrease --tune-ratio, reduce --lookback-bars/--lookback-window, or increase the number of bars."
                    lookback
                    fitSize
                    tuneSize
                )
            )

    let opensAll = matchLengthAndTrim (psOpen seriesWindow)
        opensAllForBars =
            fromMaybe
                ( case prices of
                    [] -> []
                    p0 : _ -> p0 : init prices
                )
                opensAll
        (highsAll, lowsAll) =
            case (matchLengthAndTrim (psHigh seriesWindow), matchLengthAndTrim (psLow seriesWindow)) of
                (Just hs, Just ls)
                    | length hs == n && length ls == n -> (hs, ls)
                _ -> (prices, prices)
        volumesAll = fromMaybe (replicate n 1) (matchLengthAndTrim (psVolume seriesWindow))
        openTimesAll = matchLengthAndTrim (psOpenTimes seriesWindow)

        predStart = if tuningEnabled then fitSize else trainEnd
        stepCount = n - predStart - 1
        fitPrices = take predStart prices

        tunePrices = drop fitSize trainPrices
        tuneOpens = fmap (take tuneSize . drop fitSize) opensAll
        tuneHighs = take tuneSize (drop fitSize highsAll)
        tuneLows = take tuneSize (drop fitSize lowsAll)
        tuneOpenTimes = fmap (take tuneSize . drop fitSize) openTimesAll

        backtestOpens = fmap (drop trainEnd) opensAll
        backtestHighs = drop trainEnd highsAll
        backtestLows = drop trainEnd lowsAll
        backtestOpenTimes = fmap (drop trainEnd) openTimesAll
        methodForComputation
            | useKalmanPhysics = MethodKalmanPhysicsError
            | argOptimizeOperations args = MethodBoth
            | otherwise =
                case methodRequested of
                    MethodBlend -> MethodBoth
                    MethodConfBlend -> MethodBoth
                    MethodConfPick -> MethodBoth
                    MethodConformalClip -> MethodBoth
                    MethodCostPick -> MethodBoth
                    MethodHarmonicBlend -> MethodBoth
                    MethodDisagreementGuard -> MethodBoth
                    MethodMedianBlend -> MethodBoth
                    MethodNeutralGuard -> MethodBoth
                    MethodRiskParityBlend -> MethodBoth
                    MethodConsensusBoost -> MethodBoth
                    MethodAnchorBlend -> MethodBoth
                    MethodTensionGate -> MethodBoth
                    MethodEntropyBlend -> MethodBoth
                    MethodCoherenceGate -> MethodBoth
                    MethodDivergenceGate -> MethodBoth
                    MethodFractalBlend -> MethodBoth
                    MethodPhaseCancel -> MethodBoth
                    MethodSoftmaxBlend -> MethodBoth
                    MethodSmoothSoftmaxBlend -> MethodBoth
                    MethodHedgeBlend -> MethodBoth
                    MethodNetSoftmaxBlend -> MethodBoth
                    MethodEdgeBlend -> MethodBoth
                    MethodEdgePick -> MethodBoth
                    MethodGeoBlend -> MethodBoth
                    MethodRegimeSwitch -> MethodBoth
                    MethodRouter -> MethodBoth
                    MethodBanditRouter -> MethodBoth
                    _ -> methodRequested
        pricesV = V.fromList prices
        allFeatureInputs =
            featureInputsFromLists
                prices
                opensAll
                (Just highsAll)
                (Just lowsAll)
                (Just volumesAll)
        fitFeatureInputs =
            featureInputsFromLists
                fitPrices
                (take predStart <$> opensAll)
                (Just (take predStart highsAll))
                (Just (take predStart lowsAll))
                (Just (take predStart volumesAll))
        highsV = V.fromList highsAll
        lowsV = V.fromList lowsAll

        lstmCfg =
            LSTMConfig
                { lcLookback = lookback
                , lcHiddenSize = argHiddenSize args
                , lcEpochs = argEpochs args
                , lcLearningRate = argLr args
                , lcValRatio = argValRatio args
                , lcPatience = argPatience args
                , lcGradClip = argGradClip args
                , lcSeed = argSeed args
                }

    mMarketModel <-
        case (methodForComputation, mBinanceEnv, argBinanceSymbol args) of
            (MethodLstmOnly, _, _) -> pure Nothing
            (_, Just env, Just sym) -> do
                r <- try (buildMarketModel args env sym predStart pricesV) :: IO (Either SomeException (Maybe MarketModel))
                case r of
                    Right model -> pure model
                    Left ex -> do
                        hPutStrLn stderr ("WARN: failed to build market context model (backtest) for " ++ sym ++ ": " ++ displayException ex)
                        pure Nothing
            _ -> pure Nothing

    let runDualPredictorBacktest = do
            let normState = fitNorm (argNormalization args) fitPrices
                obsAll = forwardSeries normState prices
                obsTrain = take predStart obsAll
            (lstmModel, history) <- trainLstmWithPersistence args lookback lstmCfg obsTrain
            let predictors = trainPredictorsWithInputsWithMarket (argPredictors args) lookback mMarketModel fitFeatureInputs
                hmmInitReturns = forwardReturns (take (predStart + 1) prices)
                hmm0 = initHMMFilter predictors hmmInitReturns
                kal0 =
                    initKalman1
                        0
                        (max 1e-12 (argKalmanMeasurementVar args))
                        (max 0 (argKalmanProcessVar args) * max 0 (argKalmanDt args))
                sv0 = emptySensorVar
                (kalFinal, hmmFinal, svFinal, kalPredRev, lstmPredRev, metaRev) =
                    foldl'
                        (backtestStep args lookback normState obsAll allFeatureInputs lstmModel predictors predStart mMarketModel)
                        (kal0, hmm0, sv0, [], [], [])
                        [0 .. stepCount - 1]
                kalPred = reverse kalPredRev
                lstmPred = reverse lstmPredRev
                meta = reverse metaRev
            pure
                ( Just (normState, obsAll, lstmModel)
                , Just history
                , kalPred
                , lstmPred
                , Just (predictors, kalFinal, hmmFinal, svFinal)
                , Just meta
                )
        runDualPredictorBacktestNoPhysics =
            (\(a, b, c, d, e, f) -> (a, b, c, d, e, f, Nothing)) <$> runDualPredictorBacktest

    (mLstmCtx, mHistory, kalPredAll, lstmPredAll, mKalmanCtx, mMetaAll, mPhysicsLatestPred) <-
        case methodForComputation of
            MethodKalmanPhysicsError -> do
                let predictors = trainPredictorsWithInputsWithMarket (argPredictors args) lookback mMarketModel fitFeatureInputs
                    hmmInitReturns = forwardReturns (take (predStart + 1) prices)
                    hmm0 = initHMMFilter predictors hmmInitReturns
                    kal0 =
                        initKalman1
                            0
                            (max 1e-12 (argKalmanMeasurementVar args))
                            (max 0 (argKalmanProcessVar args) * max 0 (argKalmanDt args))
                    sv0 = emptySensorVar
                    (kalFinal, hmmFinal, svFinal, _kalPredRev, metaRev) =
                        foldl'
                            (backtestStepKalmanOnly args allFeatureInputs predictors predStart mMarketModel)
                            (kal0, hmm0, sv0, [], [])
                            [0 .. stepCount - 1]
                    opensV = V.fromList opensAllForBars
                    highsV' = V.fromList highsAll
                    lowsV' = V.fromList lowsAll
                    closesV = V.fromList prices
                    volumesV = V.fromList volumesAll
                    barsV =
                        V.generate n $ \i ->
                            OhlcvBar
                                { obOpen = opensV V.! i
                                , obHigh = highsV' V.! i
                                , obLow = lowsV' V.! i
                                , obClose = closesV V.! i
                                , obVolume = volumesV V.! i
                                }
                kalPred <-
                    case predictKalmanPhysicsError (argKalmanDt args) (argKalmanProcessVar args) (argKalmanMeasurementVar args) predStart barsV of
                        Left err -> throwIO (userError ("kalman_physics_error: " ++ err))
                        Right preds -> pure preds
                let mLastBar =
                        if n <= 0
                            then Nothing
                            else Just (barsV V.! (n - 1))
                mLatestPred <-
                    case mLastBar of
                        Nothing -> pure Nothing
                        Just lastBar -> do
                            let barsVExtended = V.snoc barsV lastBar
                            case predictKalmanPhysicsError (argKalmanDt args) (argKalmanProcessVar args) (argKalmanMeasurementVar args) predStart barsVExtended of
                                Left _ -> pure Nothing
                                Right predsExt ->
                                    pure $
                                        case reverse predsExt of
                                            p : _ | not (isNaN p || isInfinite p) -> Just p
                                            _ -> Nothing
                let meta = reverse metaRev
                pure (Nothing, Nothing, kalPred, kalPred, Just (predictors, kalFinal, hmmFinal, svFinal), Just meta, mLatestPred)
            MethodKalmanOnly -> do
                let predictors = trainPredictorsWithInputsWithMarket (argPredictors args) lookback mMarketModel fitFeatureInputs
                    hmmInitReturns = forwardReturns (take (predStart + 1) prices)
                    hmm0 = initHMMFilter predictors hmmInitReturns
                    kal0 =
                        initKalman1
                            0
                            (max 1e-12 (argKalmanMeasurementVar args))
                            (max 0 (argKalmanProcessVar args) * max 0 (argKalmanDt args))
                    sv0 = emptySensorVar
                    (kalFinal, hmmFinal, svFinal, kalPredRev, metaRev) =
                        foldl'
                            (backtestStepKalmanOnly args allFeatureInputs predictors predStart mMarketModel)
                            (kal0, hmm0, sv0, [], [])
                            [0 .. stepCount - 1]
                    kalPred = reverse kalPredRev
                    meta = reverse metaRev
                pure (Nothing, Nothing, kalPred, kalPred, Just (predictors, kalFinal, hmmFinal, svFinal), Just meta, Nothing)
            MethodLstmOnly -> do
                let normState = fitNorm (argNormalization args) fitPrices
                    obsAll = forwardSeries normState prices
                    obsTrain = take predStart obsAll
                (lstmModel, history) <- trainLstmWithPersistence args lookback lstmCfg obsTrain
                let lstmPred =
                        [ let t = predStart + i
                              window = take lookback (drop (t - lookback + 1) obsAll)
                              predObs = predictNext lstmModel window
                           in inverseNorm normState predObs
                        | i <- [0 .. stepCount - 1]
                        ]
                pure (Just (normState, obsAll, lstmModel), Just history, lstmPred, lstmPred, Nothing, Nothing, Nothing)
            MethodBoth -> runDualPredictorBacktestNoPhysics
            MethodBlend -> runDualPredictorBacktestNoPhysics
            MethodConfBlend -> runDualPredictorBacktestNoPhysics
            MethodConfPick -> runDualPredictorBacktestNoPhysics
            MethodConformalClip -> runDualPredictorBacktestNoPhysics
            MethodCostPick -> runDualPredictorBacktestNoPhysics
            MethodHarmonicBlend -> runDualPredictorBacktestNoPhysics
            MethodDisagreementGuard -> runDualPredictorBacktestNoPhysics
            MethodMedianBlend -> runDualPredictorBacktestNoPhysics
            MethodNeutralGuard -> runDualPredictorBacktestNoPhysics
            MethodRiskParityBlend -> runDualPredictorBacktestNoPhysics
            MethodConsensusBoost -> runDualPredictorBacktestNoPhysics
            MethodAnchorBlend -> runDualPredictorBacktestNoPhysics
            MethodTensionGate -> runDualPredictorBacktestNoPhysics
            MethodEntropyBlend -> runDualPredictorBacktestNoPhysics
            MethodCoherenceGate -> runDualPredictorBacktestNoPhysics
            MethodDivergenceGate -> runDualPredictorBacktestNoPhysics
            MethodFractalBlend -> runDualPredictorBacktestNoPhysics
            MethodPhaseCancel -> runDualPredictorBacktestNoPhysics
            MethodSoftmaxBlend -> runDualPredictorBacktestNoPhysics
            MethodSmoothSoftmaxBlend -> runDualPredictorBacktestNoPhysics
            MethodHedgeBlend -> runDualPredictorBacktestNoPhysics
            MethodNetSoftmaxBlend -> runDualPredictorBacktestNoPhysics
            MethodEdgeBlend -> runDualPredictorBacktestNoPhysics
            MethodEdgePick -> runDualPredictorBacktestNoPhysics
            MethodGeoBlend -> runDualPredictorBacktestNoPhysics
            MethodRegimeSwitch -> runDualPredictorBacktestNoPhysics
            MethodRouter -> runDualPredictorBacktestNoPhysics
            MethodBanditRouter -> runDualPredictorBacktestNoPhysics

    let feeUsed = max 0 (argFee args)
        slippageUsed = max 0 (argSlippage args)
        spreadUsed = max 0 (argSpread args)
        volPerBar = volPerBarFromPrices prices
        sizeRef = max 1e-6 (argMaxPositionSize args)
        perSideCost = estimatedPerSideCost args sizeRef volPerBar
        roundTripCost = estimatedRoundTripCost args sizeRef volPerBar
        rebalanceThresholdBase = max 0 (argRebalanceThreshold args)
        rebalanceCostMult = max 0 (argRebalanceCostMult args)
        rebalanceThresholdUsed =
            if rebalanceCostMult <= 0
                then rebalanceThresholdBase
                else max rebalanceThresholdBase (rebalanceCostMult * perSideCost)
        minEdgeBase = max 0 (argMinEdge args)
        minEdge =
            if argCostAwareEdge args
                then max minEdgeBase (breakEvenThresholdFromPerSideCost perSideCost + max 0 (argEdgeBuffer args))
                else minEdgeBase
        hasHmm = predictorEnabled (argPredictors args) SensorHMM
        hasConformal = predictorEnabled (argPredictors args) SensorConformal
        hasQuantile = predictorEnabled (argPredictors args) SensorQuantile
        lstmHealth = mHistory >>= lstmHealthScore
        maxHighVolProb = if hasHmm then argMaxHighVolProb args else Nothing
        maxConformalWidth = if hasConformal then argMaxConformalWidth args else Nothing
        maxQuantileWidth = if hasQuantile then argMaxQuantileWidth args else Nothing
        confirmConformal = argConfirmConformal args && hasConformal
        confirmQuantiles = argConfirmQuantiles args && hasQuantile

        baseCfg =
            EnsembleConfig
                { ecOpenThreshold = argOpenThreshold args
                , ecCloseThreshold = argCloseThreshold args
                , ecFee = feeUsed
                , ecSlippage = slippageUsed
                , ecSpread = spreadUsed
                , ecFeeFixed = argFeeFixed args
                , ecFeeMin = argFeeMin args
                , ecSlippageVolMult = argSlippageVolMult args
                , ecSlippageImpact = argSlippageImpact args
                , ecSlippageImpactPower = argSlippageImpactPower args
                , ecSpreadVolMult = argSpreadVolMult args
                , ecStopLoss = argStopLoss args
                , ecTakeProfit = argTakeProfit args
                , ecTrailingStop = argTrailingStop args
                , ecStopLossVolMult = argStopLossVolMult args
                , ecTakeProfitVolMult = argTakeProfitVolMult args
                , ecTrailingStopVolMult = argTrailingStopVolMult args
                , ecMinHoldBars = argMinHoldBars args
                , ecCooldownBars = argCooldownBars args
                , ecMaxHoldBars = argMaxHoldBars args
                , ecMaxDrawdown = argMaxDrawdown args
                , ecMaxDailyLoss = argMaxDailyLoss args
                , ecMaxWeeklyLoss = argMaxWeeklyLoss args
                , ecRiskPerTrade = argRiskPerTrade args
                , ecMaxTradesPerDay = argMaxTradesPerDay args
                , ecExpectancyLookback = argExpectancyLookback args
                , ecMinExpectancy = argMinExpectancy args
                , ecPerfLookback = argPerfLookback args
                , ecPerfMinWinRate = argPerfMinWinRate args
                , ecPerfMinProfitFactor = argPerfMinProfitFactor args
                , ecAdaptiveFilters = argAdaptiveFilters args
                , ecAdaptiveEdgeBufferMax = argAdaptiveEdgeBufferMax args
                , ecAdaptiveMinSignalToNoiseMax = argAdaptiveMinSignalToNoiseMax args
                , ecAdaptiveKalmanZMinMax = argAdaptiveKalmanZMinMax args
                , ecAdaptiveTrendLookbackMax = argAdaptiveTrendLookbackMax args
                , ecLossStreakMax = argLossStreakMax args
                , ecLossStreakCooldownBars = argLossStreakCooldownBars args
                , ecNoTradeWindows = argNoTradeWindows args
                , ecIntervalSeconds = parseIntervalSeconds (argInterval args)
                , ecOpenTimes = Nothing
                , ecOpenPrices = Nothing
                , ecMetaMask = Nothing
                , ecPositioning = argPositioning args
                , ecIntrabarFill = argIntrabarFill args
                , ecMaxPositionSize = argMaxPositionSize args
                , ecMinEdge = minEdge
                , ecMinSignalToNoise = argMinSignalToNoise args
                , ecSnrSizeWeight = argSnrSizeWeight args
                , ecThresholdFactorEnabled = argThresholdFactorEnabled args
                , ecThresholdFactorAlpha = argThresholdFactorAlpha args
                , ecThresholdFactorMin = argThresholdFactorMin args
                , ecThresholdFactorMax = argThresholdFactorMax args
                , ecThresholdFactorFloor = argThresholdFactorFloor args
                , ecThresholdFactorEdgeKalWeight = argThresholdFactorEdgeKalWeight args
                , ecThresholdFactorEdgeLstmWeight = argThresholdFactorEdgeLstmWeight args
                , ecThresholdFactorKalmanZWeight = argThresholdFactorKalmanZWeight args
                , ecThresholdFactorHighVolWeight = argThresholdFactorHighVolWeight args
                , ecThresholdFactorConformalWeight = argThresholdFactorConformalWeight args
                , ecThresholdFactorQuantileWeight = argThresholdFactorQuantileWeight args
                , ecThresholdFactorLstmConfWeight = argThresholdFactorLstmConfWeight args
                , ecThresholdFactorLstmHealthWeight = argThresholdFactorLstmHealthWeight args
                , ecLstmTrainingHealth = lstmHealth
                , ecTrendLookback = argTrendLookback args
                , ecPeriodsPerYear = periodsPerYear args
                , ecVolTarget = argVolTarget args
                , ecVolLookback = argVolLookback args
                , ecVolEwmaAlpha = argVolEwmaAlpha args
                , ecVolFloor = argVolFloor args
                , ecVolScaleMax = argVolScaleMax args
                , ecMaxVolatility = argMaxVolatility args
                , ecVolConfGate = argVolConfGate args
                , ecRebalanceBars = argRebalanceBars args
                , ecRebalanceThreshold = rebalanceThresholdUsed
                , ecRebalanceGlobal = argRebalanceGlobal args
                , ecRebalanceResetOnSignal = argRebalanceResetOnSignal args
                , ecFundingRate = argFundingRate args
                , ecFundingBySide = argFundingBySide args
                , ecFundingOnOpen = argFundingOnOpen args
                , ecBlendWeight = argBlendWeight args
                , ecRouterLookback = argRouterLookback args
                , ecRouterMinScore = argRouterMinScore args
                , ecRouterScorePnlWeight = argRouterScorePnlWeight args
                , ecKalmanDt = argKalmanDt args
                , ecKalmanProcessVar = argKalmanProcessVar args
                , ecKalmanMeasurementVar = argKalmanMeasurementVar args
                , ecTriLayer = argTriLayer args
                , ecTriLayerFastMult = argTriLayerFastMult args
                , ecTriLayerSlowMult = argTriLayerSlowMult args
                , ecTriLayerCloudPadding = argTriLayerCloudPadding args
                , ecTriLayerCloudSlope = argTriLayerCloudSlope args
                , ecTriLayerCloudWidth = argTriLayerCloudWidth args
                , ecTriLayerTouchLookback = argTriLayerTouchLookback args
                , ecTriLayerRequirePriceAction = argTriLayerRequirePriceAction args
                , ecTriLayerPriceActionBody = argTriLayerPriceActionBody args
                , ecTriLayerExitOnSlow = argTriLayerExitOnSlow args
                , ecKalmanBandLookback = argKalmanBandLookback args
                , ecKalmanBandStdMult = argKalmanBandStdMult args
                , ecLstmExitFlipBars = argLstmExitFlipBars args
                , ecLstmExitFlipGraceBars = argLstmExitFlipGraceBars args
                , ecLstmExitFlipStrong = argLstmExitFlipStrong args
                , ecLstmConfidenceSoft = argLstmConfidenceSoft args
                , ecLstmConfidenceHard = argLstmConfidenceHard args
                , ecKalmanZMin = argKalmanZMin args
                , ecKalmanZMax = argKalmanZMax args
                , ecMaxHighVolProb = maxHighVolProb
                , ecMaxConformalWidth = maxConformalWidth
                , ecMaxQuantileWidth = maxQuantileWidth
                , ecConfirmConformal = confirmConformal
                , ecConfirmQuantiles = confirmQuantiles
                , ecConfidenceSizing = argConfidenceSizing args
                , ecMinPositionSize = argMinPositionSize args
                }

        baseCfgTune = baseCfg{ecOpenTimes = V.fromList <$> tuneOpenTimes, ecOpenPrices = V.fromList <$> tuneOpens}
        baseCfgBacktest = baseCfg{ecOpenTimes = V.fromList <$> backtestOpenTimes, ecOpenPrices = V.fromList <$> backtestOpens}

        offsetBacktestPred = max 0 (trainEnd - predStart)
        kalPredBacktest = drop offsetBacktestPred kalPredAll
        lstmPredBacktest = drop offsetBacktestPred lstmPredAll
        kalPredTune = take (max 0 (tuneSize - 1)) kalPredAll
        lstmPredTune = take (max 0 (tuneSize - 1)) lstmPredAll
        metaBacktest = fmap (drop offsetBacktestPred) mMetaAll
        metaTune = fmap (take (max 0 (tuneSize - 1))) mMetaAll

        ppy = periodsPerYear args
        tuneObjectiveUsed = argTuneObjective args
        tuneCfg =
            TuneConfig
                { tcObjective = tuneObjectiveUsed
                , tcPenaltyMaxDrawdown = argTunePenaltyMaxDrawdown args
                , tcPenaltyTurnover = argTunePenaltyTurnover args
                , tcPeriodsPerYear = ppy
                , tcWalkForwardFolds = argWalkForwardFolds args
                , tcWalkForwardEmbargoBars = argWalkForwardEmbargoBars args
                , tcMinRoundTrips = argMinRoundTrips args
                , tcStressVolMultiplier = argTuneStressVolMult args
                , tcStressShock = argTuneStressShock args
                , tcStressWeight = argTuneStressWeight args
                }

    (methodUsed, bestOpenThr, bestCloseThr, mTuneStats, mTuneMetrics) <-
        if argOptimizeOperations args
            then case optimizeOperationsWithHLWith tuneCfg baseCfgTune tunePrices tuneHighs tuneLows kalPredTune lstmPredTune metaTune of
                Left e -> throwIO (userError ("optimizeOperations: " ++ e))
                Right (m, openThr, closeThr, btTune, stats) ->
                    pure (m, openThr, closeThr, Just stats, Just (computeMetrics ppy btTune))
            else
                if argSweepThreshold args
                    then case sweepThresholdWithHLWith tuneCfg methodRequested baseCfgTune tunePrices tuneHighs tuneLows kalPredTune lstmPredTune metaTune of
                        Left e -> throwIO (userError ("sweepThreshold: " ++ e))
                        Right (openThr, closeThr, btTune, stats) ->
                            pure (methodRequested, openThr, closeThr, Just stats, Just (computeMetrics ppy btTune))
                    else pure (methodRequestedForReporting, argOpenThreshold args, argCloseThreshold args, Nothing, Nothing)

    let lstmFlipEnabled method =
            case method of
                MethodBoth -> True
                MethodLstmOnly -> True
                _ -> False
        applyLstmFlip method cfg =
            if lstmFlipEnabled method
                then cfg
                else cfg{ecLstmExitFlipBars = 0, ecLstmExitFlipGraceBars = 0}
        routerOpenThr = max bestOpenThr minEdge
        blendWeight0 = argBlendWeight args
        blendWeight = max 0 (min 1 blendWeight0)
        kalZMinForBlend = max 0 (argKalmanZMin args)
        kalZMaxForBlend = max kalZMinForBlend (argKalmanZMax args)
        blendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (blendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        edgeBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (edgeBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        edgePickPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (edgePickPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        costPickPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (costPickPredictionsV blendWeight roundTripCost pricesBacktestV kalBacktestV lstmBacktestV)
        harmonicBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (harmonicBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        disagreementGuardPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (disagreementGuardPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        medianBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (medianBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        neutralGuardPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (neutralGuardPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        riskParityBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (riskParityBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        consensusBoostPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (consensusBoostPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        anchorBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (anchorBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        tensionGatePredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (tensionGatePredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        entropyBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (entropyBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        coherenceGatePredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (coherenceGatePredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        fractalBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (fractalBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        phaseCancelPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (phaseCancelPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        softmaxBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (softmaxBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        smoothSoftmaxBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (smoothSoftmaxBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        netSoftmaxBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (netSoftmaxBlendPredictionsV blendWeight roundTripCost pricesBacktestV kalBacktestV lstmBacktestV)
        divergenceGatePredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (divergenceGatePredictionsV blendWeight routerOpenThr pricesBacktestV kalBacktestV lstmBacktestV)
        geoBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (geometricBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        confBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
                metaBacktestV = V.fromList <$> metaBacktest
             in V.toList
                    ( confidenceBlendPredictionsV
                        blendWeight
                        kalZMinForBlend
                        kalZMaxForBlend
                        routerOpenThr
                        pricesBacktestV
                        kalBacktestV
                        lstmBacktestV
                        metaBacktestV
                    )
        confPickPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
                metaBacktestV = V.fromList <$> metaBacktest
             in V.toList
                    ( confidencePickPredictionsV
                        blendWeight
                        kalZMinForBlend
                        kalZMaxForBlend
                        routerOpenThr
                        pricesBacktestV
                        kalBacktestV
                        lstmBacktestV
                        metaBacktestV
                    )
        conformalClipPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
                metaBacktestV = V.fromList <$> metaBacktest
             in V.toList (conformalClipPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV metaBacktestV)
        regimeSwitchPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
                metaBacktestV = V.fromList <$> metaBacktest
             in V.toList
                    ( regimeSwitchPredictionsV
                        blendWeight
                        0.6
                        1.0
                        pricesBacktestV
                        kalBacktestV
                        lstmBacktestV
                        metaBacktestV
                    )
        hedgeBlendPredBacktest =
            let pricesBacktestV = V.fromList backtestPrices
                kalBacktestV = V.fromList kalPredBacktest
                lstmBacktestV = V.fromList lstmPredBacktest
             in V.toList (hedgeBlendPredictionsV blendWeight pricesBacktestV kalBacktestV lstmBacktestV)
        runRouterBacktest selectFn =
            let pricesV = V.fromList backtestPrices
                kalV = V.fromList kalPredBacktest
                lstmV = V.fromList lstmPredBacktest
                blendV = V.fromList blendPredBacktest
                costPickV = V.fromList costPickPredBacktest
                regimeSwitchV = V.fromList regimeSwitchPredBacktest
                edgeBlendV = V.fromList edgeBlendPredBacktest
                metaV = V.fromList <$> metaBacktest
             in selectFn
                    routerOpenThr
                    roundTripCost
                    (argRouterScorePnlWeight args)
                    (argRouterLookback args)
                    (argRouterMinScore args)
                    pricesV
                    kalV
                    lstmV
                    blendV
                    costPickV
                    regimeSwitchV
                    edgeBlendV
                    metaV
        routerPredBacktest =
            case methodUsed of
                MethodRouter ->
                    Just (runRouterBacktest routerPredictionsWithModelsV)
                MethodBanditRouter ->
                    Just (runRouterBacktest banditPredictionsWithModelsV)
                _ -> Nothing
        (kalPredUsedBacktest, lstmPredUsedBacktest, metaUsedBacktest, metaMaskUsedBacktest) =
            case methodUsed of
                MethodRouter ->
                    case routerPredBacktest of
                        Just (routerPredV, routerModelsV) ->
                            let routerPred = V.toList routerPredV
                                routerMaskV = V.map routerUsesKalmanGating routerModelsV
                             in (routerPred, routerPred, metaBacktest, Just routerMaskV)
                        Nothing -> (kalPredBacktest, lstmPredBacktest, metaBacktest, Nothing)
                MethodBanditRouter ->
                    case routerPredBacktest of
                        Just (routerPredV, routerModelsV) ->
                            let routerPred = V.toList routerPredV
                                routerMaskV = V.map routerUsesKalmanGating routerModelsV
                             in (routerPred, routerPred, metaBacktest, Just routerMaskV)
                        Nothing -> (kalPredBacktest, lstmPredBacktest, metaBacktest, Nothing)
                MethodConfBlend ->
                    (confBlendPredBacktest, confBlendPredBacktest, metaBacktest, Nothing)
                MethodConfPick ->
                    (confPickPredBacktest, confPickPredBacktest, metaBacktest, Nothing)
                MethodConformalClip ->
                    (conformalClipPredBacktest, conformalClipPredBacktest, metaBacktest, Nothing)
                MethodCostPick ->
                    (costPickPredBacktest, costPickPredBacktest, metaBacktest, Nothing)
                MethodHarmonicBlend ->
                    (harmonicBlendPredBacktest, harmonicBlendPredBacktest, metaBacktest, Nothing)
                MethodDisagreementGuard ->
                    (disagreementGuardPredBacktest, disagreementGuardPredBacktest, metaBacktest, Nothing)
                MethodMedianBlend ->
                    (medianBlendPredBacktest, medianBlendPredBacktest, metaBacktest, Nothing)
                MethodNeutralGuard ->
                    (neutralGuardPredBacktest, neutralGuardPredBacktest, metaBacktest, Nothing)
                MethodRiskParityBlend ->
                    (riskParityBlendPredBacktest, riskParityBlendPredBacktest, metaBacktest, Nothing)
                MethodConsensusBoost ->
                    (consensusBoostPredBacktest, consensusBoostPredBacktest, metaBacktest, Nothing)
                MethodAnchorBlend ->
                    (anchorBlendPredBacktest, anchorBlendPredBacktest, metaBacktest, Nothing)
                MethodTensionGate ->
                    (tensionGatePredBacktest, tensionGatePredBacktest, metaBacktest, Nothing)
                MethodEntropyBlend ->
                    (entropyBlendPredBacktest, entropyBlendPredBacktest, metaBacktest, Nothing)
                MethodCoherenceGate ->
                    (coherenceGatePredBacktest, coherenceGatePredBacktest, metaBacktest, Nothing)
                MethodFractalBlend ->
                    (fractalBlendPredBacktest, fractalBlendPredBacktest, metaBacktest, Nothing)
                MethodPhaseCancel ->
                    (phaseCancelPredBacktest, phaseCancelPredBacktest, metaBacktest, Nothing)
                MethodSoftmaxBlend ->
                    (softmaxBlendPredBacktest, softmaxBlendPredBacktest, metaBacktest, Nothing)
                MethodSmoothSoftmaxBlend ->
                    (smoothSoftmaxBlendPredBacktest, smoothSoftmaxBlendPredBacktest, metaBacktest, Nothing)
                MethodHedgeBlend ->
                    (hedgeBlendPredBacktest, hedgeBlendPredBacktest, metaBacktest, Nothing)
                MethodNetSoftmaxBlend ->
                    (netSoftmaxBlendPredBacktest, netSoftmaxBlendPredBacktest, metaBacktest, Nothing)
                MethodDivergenceGate ->
                    (divergenceGatePredBacktest, divergenceGatePredBacktest, metaBacktest, Nothing)
                MethodEdgeBlend ->
                    (edgeBlendPredBacktest, edgeBlendPredBacktest, metaBacktest, Nothing)
                MethodEdgePick ->
                    (edgePickPredBacktest, edgePickPredBacktest, metaBacktest, Nothing)
                MethodGeoBlend ->
                    (geoBlendPredBacktest, geoBlendPredBacktest, metaBacktest, Nothing)
                MethodRegimeSwitch ->
                    (regimeSwitchPredBacktest, regimeSwitchPredBacktest, metaBacktest, Nothing)
                _ ->
                    let (kalPredUsed, lstmPredUsed) =
                            selectPredictions methodUsed blendWeight0 kalPredBacktest lstmPredBacktest
                        metaUsed =
                            case methodUsed of
                                MethodLstmOnly -> Nothing
                                _ -> metaBacktest
                     in (kalPredUsed, lstmPredUsed, metaUsed, Nothing)

        backtestCfgBase = baseCfgBacktest{ecOpenThreshold = bestOpenThr, ecCloseThreshold = bestCloseThr}
        backtestCfgNoMask = applyLstmFlip methodUsed backtestCfgBase
        backtestCfg = backtestCfgNoMask{ecMetaMask = metaMaskUsedBacktest}
        backtestCfgAgreement = backtestCfgNoMask{ecMetaMask = Nothing}

    let backtestRawE =
            simulateEnsembleWithHLChecked
                backtestCfg
                1
                backtestPrices
                backtestHighs
                backtestLows
                kalPredUsedBacktest
                lstmPredUsedBacktest
                metaUsedBacktest
    backtestRaw <-
        case backtestRawE of
            Left err -> throwIO (userError err)
            Right bt -> pure bt
    backtest <-
        case methodUsed of
            MethodRouter -> do
                let agreementBacktestE =
                        simulateEnsembleWithHLChecked
                            backtestCfgAgreement
                            1
                            backtestPrices
                            backtestHighs
                            backtestLows
                            kalPredBacktest
                            lstmPredBacktest
                            metaBacktest
                agreementBacktest <-
                    case agreementBacktestE of
                        Left err -> throwIO (userError err)
                        Right bt -> pure bt
                pure
                    backtestRaw
                        { brAgreementOk = brAgreementOk agreementBacktest
                        , brAgreementValid = brAgreementValid agreementBacktest
                        }
            MethodBanditRouter -> do
                let agreementBacktestE =
                        simulateEnsembleWithHLChecked
                            backtestCfgAgreement
                            1
                            backtestPrices
                            backtestHighs
                            backtestLows
                            kalPredBacktest
                            lstmPredBacktest
                            metaBacktest
                agreementBacktest <-
                    case agreementBacktestE of
                        Left err -> throwIO (userError err)
                        Right bt -> pure bt
                pure
                    backtestRaw
                        { brAgreementOk = brAgreementOk agreementBacktest
                        , brAgreementValid = brAgreementValid agreementBacktest
                        }
            _ -> pure backtestRaw

    let metricsRaw = computeMetrics ppy backtest
        baselinesRaw = computeBaselines ppy perSideCost backtestPrices

        walkForwardE =
            let wfReq = max 1 (argWalkForwardFolds args)
                stepsAll = max 0 (length backtestPrices - 1)
                embargoBars = max 0 (argWalkForwardEmbargoBars args)

                foldRangesSteps :: Int -> Int -> [(Int, Int)]
                foldRangesSteps steps0 k0 =
                    let steps = max 0 steps0
                        k = max 1 (min steps (max 1 k0))
                        base = if k <= 0 then 0 else steps `div` k
                        extra = if k <= 0 then 0 else steps `mod` k
                        go i start =
                            if i >= k
                                then []
                                else
                                    let len = base + if i < extra then 1 else 0
                                        end = start + len - 1
                                     in if len <= 0 then [] else (start, end) : go (i + 1) (end + 1)
                     in go 0 0
                applyEmbargo e (t0, t1) =
                    let t0' = t0 + e
                        t1' = t1 - e
                     in if t1' < t0' then Nothing else Just (t0', t1')
                foldRangesAll = foldRangesSteps stepsAll wfReq
                foldRangesEval =
                    if length foldRangesAll <= 1 || embargoBars <= 0
                        then foldRangesAll
                        else mapMaybe (applyEmbargo embargoBars) foldRangesAll

                bad x = isNaN x || isInfinite x
                meanD xs =
                    let ys = filter (not . bad) xs
                     in if null ys then 0 else sum ys / fromIntegral (length ys)
                stdD xs =
                    let ys = filter (not . bad) xs
                     in case ys of
                            [] -> 0
                            [_] -> 0
                            _ ->
                                let m = meanD ys
                                    var = sum (map (\x -> (x - m) ** 2) ys) / fromIntegral (length ys - 1)
                                 in sqrt var

                mkFold (t0, t1) =
                    let steps = t1 - t0 + 1
                        pricesF = take (steps + 1) (drop t0 backtestPrices)
                        highsF = take (steps + 1) (drop t0 backtestHighs)
                        lowsF = take (steps + 1) (drop t0 backtestLows)
                        kalF = take steps (drop t0 kalPredUsedBacktest)
                        lstmF = take steps (drop t0 lstmPredUsedBacktest)
                        metaF = fmap (take steps . drop t0) metaUsedBacktest
                        openTimesF = fmap (V.slice t0 (steps + 1)) (ecOpenTimes backtestCfg)
                        metaMaskF = fmap (V.slice t0 steps) metaMaskUsedBacktest
                        openPricesF = fmap (V.slice t0 (steps + 1)) (ecOpenPrices backtestCfg)
                        backtestCfgFold = backtestCfg{ecOpenTimes = openTimesF, ecOpenPrices = openPricesF, ecMetaMask = metaMaskF}
                     in case simulateEnsembleWithHLChecked backtestCfgFold 1 pricesF highsF lowsF kalF lstmF metaF of
                            Left err -> Left err
                            Right bt ->
                                let mFold = computeMetrics ppy bt
                                 in Right WalkForwardFold{wffStartIndex = trainEnd + t0, wffEndIndex = trainEnd + t1 + 1, wffMetrics = mFold}

                foldsE =
                    traverse
                        mkFold
                        [ r
                        | r@(t0, t1) <- foldRangesEval
                        , t1 >= t0
                        ]
             in case foldsE of
                    Left err -> Left err
                    Right folds ->
                        if wfReq <= 1 || stepsAll <= 1 || null folds
                            then Right Nothing
                            else
                                let ms = map wffMetrics folds
                                    finalEqs = map bmFinalEquity ms
                                    annRets = map bmAnnualizedReturn ms
                                    sharpes = map bmSharpe ms
                                    maxDds = map bmMaxDrawdown ms
                                    turns = map bmTurnover ms
                                    summary =
                                        WalkForwardSummary
                                            { wfsFinalEquityMean = meanD finalEqs
                                            , wfsFinalEquityStd = stdD finalEqs
                                            , wfsAnnualizedReturnMean = meanD annRets
                                            , wfsAnnualizedReturnStd = stdD annRets
                                            , wfsSharpeMean = meanD sharpes
                                            , wfsSharpeStd = stdD sharpes
                                            , wfsMaxDrawdownMean = meanD maxDds
                                            , wfsMaxDrawdownStd = stdD maxDds
                                            , wfsTurnoverMean = meanD turns
                                            , wfsTurnoverStd = stdD turns
                                            }
                                 in Right (Just (WalkForwardReport{wfrFoldCount = length folds, wfrFolds = folds, wfrSummary = summary}))

    walkForward <-
        case walkForwardE of
            Left err -> throwIO (userError err)
            Right wf -> pure wf

    let metrics = scaleBacktestMetrics initialBalance metricsRaw
        baselines = map (scaleBaselineMetrics initialBalance) baselinesRaw
        tuneMetrics = fmap (scaleBacktestMetrics initialBalance) mTuneMetrics
        walkForwardScaled = fmap (scaleWalkForwardReport initialBalance) walkForward
        equityCurveScaled = map (* initialBalance) (brEquityCurve backtest)
        tradesScaled = map (scaleTradeEquity initialBalance) (brTrades backtest)

        argsForSignal
            | argOptimizeOperations args =
                args{argMethod = methodUsed, argOpenThreshold = bestOpenThr, argCloseThreshold = bestCloseThr}
            | argSweepThreshold args =
                args{argOpenThreshold = bestOpenThr, argCloseThreshold = bestCloseThr}
            | otherwise = args

        historyEnabled =
            argThresholdFactorEnabled argsForSignal
                || methodUsed == MethodRouter
                || methodUsed == MethodBanditRouter
                || methodUsed == MethodKalmanPhysicsError
        alignPredHistory preds =
            let targetLen = max 0 (n - 1)
                start = max 0 (min targetLen predStart)
                predV = V.fromList preds
             in V.generate targetLen $ \i ->
                    if i < start
                        then pricesV V.! i
                        else
                            let j = i - start
                             in if j < V.length predV
                                    then predV V.! j
                                    else pricesV V.! i
        neutralMeta =
            StepMeta
                { smKalmanMean = 0
                , smKalmanVar = 0
                , smHighVolProb = Nothing
                , smQuantile10 = Nothing
                , smQuantile90 = Nothing
                , smConformalLo = Nothing
                , smConformalHi = Nothing
                }
        alignMetaHistory metas =
            let targetLen = max 0 (n - 1)
                start = max 0 (min targetLen predStart)
                metaV = V.fromList metas
             in V.generate targetLen $ \i ->
                    if i < start
                        then neutralMeta
                        else
                            let j = i - start
                             in if j < V.length metaV
                                    then metaV V.! j
                                    else neutralMeta
        kalHistBase = alignPredHistory kalPredAll
        lstmHistBase = alignPredHistory lstmPredAll
        kalHistAligned =
            case (methodUsed, mPhysicsLatestPred) of
                (MethodKalmanPhysicsError, Just p) | not (isNaN p || isInfinite p) -> V.snoc kalHistBase p
                _ -> kalHistBase
        lstmHistAligned =
            case methodUsed of
                MethodKalmanPhysicsError -> kalHistAligned
                _ -> lstmHistBase
        metaHistAligned = alignMetaHistory <$> mMetaAll
        mPredHistorySignal =
            if historyEnabled
                then
                    Just
                        PredHistory
                            { phKalman = kalHistAligned
                            , phLstm = lstmHistAligned
                            , phMeta = metaHistAligned
                            , phLstmHealth = lstmHealth
                            }
                else Nothing

    latestSignal <-
        case computeLatestSignal argsForSignal lookback allFeatureInputs mLstmCtx mKalmanCtx mMarketModel mPredHistorySignal of
            Left err -> throwIO (userError err)
            Right sig -> pure sig

    let finiteMaybe x =
            if isNaN x || isInfinite x
                then Nothing
                else Just x
        alignPred mCtx preds =
            let n0 = length backtestPrices
                -- `preds` are next-bar predictions for each bar `t` (0..n-2).
                -- Align to the bar index so `predNext[t]` lines up with decisions/positions for t→t+1.
                aligned = map finiteMaybe preds ++ [Nothing]
             in if n0 <= 0
                    then []
                    else
                        if isJust mCtx
                            then take n0 (aligned ++ repeat Nothing)
                            else replicate n0 Nothing
        kalmanPredNext = alignPred mKalmanCtx kalPredBacktest
        lstmPredNext = alignPred mLstmCtx lstmPredBacktest

    pure
        BacktestSummary
            { bsTrainEndRaw = trainEndRaw
            , bsTrainEnd = trainEnd
            , bsTrainSize = trainSize
            , bsFitSize = fitSize
            , bsTuneSize = tuneSize
            , bsTuneRatio = tuneRatioUsed
            , bsTuneObjective = tuneObjectiveUsed
            , bsTunePenaltyMaxDrawdown = argTunePenaltyMaxDrawdown args
            , bsTunePenaltyTurnover = argTunePenaltyTurnover args
            , bsTuneStressVolMult = argTuneStressVolMult args
            , bsTuneStressShock = argTuneStressShock args
            , bsTuneStressWeight = argTuneStressWeight args
            , bsMinRoundTrips = argMinRoundTrips args
            , bsWalkForwardFolds = argWalkForwardFolds args
            , bsWalkForwardEmbargoBars = argWalkForwardEmbargoBars args
            , bsTuneStats = mTuneStats
            , bsTuneMetrics = tuneMetrics
            , bsBacktestSize = length backtestPrices
            , bsBacktestRatio = backtestRatio
            , bsBacktestFromMs = backtestFromMs
            , bsBacktestToMs = backtestToMs
            , bsInitialBalance = initialBalance
            , bsMethodUsed = methodUsed
            , bsVolConfGate = argVolConfGate args
            , bsBestOpenThreshold = bestOpenThr
            , bsBestCloseThreshold = bestCloseThr
            , bsMinHoldBars = argMinHoldBars args
            , bsCooldownBars = argCooldownBars args
            , bsMaxHoldBars = argMaxHoldBars args
            , bsStopLossVolMult = argStopLossVolMult args
            , bsTakeProfitVolMult = argTakeProfitVolMult args
            , bsTrailingStopVolMult = argTrailingStopVolMult args
            , bsMaxPositionSize = argMaxPositionSize args
            , bsMinEdge = minEdge
            , bsMinSignalToNoise = argMinSignalToNoise args
            , bsCostAwareEdge = argCostAwareEdge args
            , bsEdgeBuffer = argEdgeBuffer args
            , bsTrendLookback = argTrendLookback args
            , bsVolTarget = argVolTarget args
            , bsVolLookback = argVolLookback args
            , bsVolEwmaAlpha = argVolEwmaAlpha args
            , bsVolFloor = argVolFloor args
            , bsVolScaleMax = argVolScaleMax args
            , bsMaxVolatility = argMaxVolatility args
            , bsRebalanceBars = argRebalanceBars args
            , bsRebalanceThreshold = rebalanceThresholdUsed
            , bsRebalanceCostMult = rebalanceCostMult
            , bsRebalanceGlobal = argRebalanceGlobal args
            , bsFundingRate = argFundingRate args
            , bsFundingBySide = argFundingBySide args
            , bsRebalanceResetOnSignal = argRebalanceResetOnSignal args
            , bsFundingOnOpen = argFundingOnOpen args
            , bsBlendWeight = argBlendWeight args
            , bsTriLayer = argTriLayer args
            , bsTriLayerFastMult = argTriLayerFastMult args
            , bsTriLayerSlowMult = argTriLayerSlowMult args
            , bsTriLayerCloudPadding = argTriLayerCloudPadding args
            , bsTriLayerCloudSlope = argTriLayerCloudSlope args
            , bsTriLayerCloudWidth = argTriLayerCloudWidth args
            , bsTriLayerTouchLookback = argTriLayerTouchLookback args
            , bsTriLayerPriceAction = argTriLayerRequirePriceAction args
            , bsTriLayerPriceActionBody = argTriLayerPriceActionBody args
            , bsTriLayerExitOnSlow = argTriLayerExitOnSlow args
            , bsKalmanBandLookback = argKalmanBandLookback args
            , bsKalmanBandStdMult = argKalmanBandStdMult args
            , bsLstmExitFlipStrong = argLstmExitFlipStrong args
            , bsLstmExitFlipBars = argLstmExitFlipBars args
            , bsLstmExitFlipGraceBars = argLstmExitFlipGraceBars args
            , bsLstmConfidenceSoft = argLstmConfidenceSoft args
            , bsLstmConfidenceHard = argLstmConfidenceHard args
            , bsFee = feeUsed
            , bsSlippage = slippageUsed
            , bsSpread = spreadUsed
            , bsFeeFixed = argFeeFixed args
            , bsFeeMin = argFeeMin args
            , bsSlippageVolMult = argSlippageVolMult args
            , bsSlippageImpact = argSlippageImpact args
            , bsSlippageImpactPower = argSlippageImpactPower args
            , bsSpreadVolMult = argSpreadVolMult args
            , bsEstimatedPerSideCost = perSideCost
            , bsEstimatedRoundTripCost = roundTripCost
            , bsMetrics = metrics
            , bsBaselines = baselines
            , bsWalkForward = walkForwardScaled
            , bsLstmHistory = mHistory
            , bsLatestSignal = latestSignal
            , bsEquityCurve = equityCurveScaled
            , bsBacktestPrices = backtestPrices
            , bsOpenTimes = backtestOpenTimes
            , bsKalmanPredNext = kalmanPredNext
            , bsLstmPredNext = lstmPredNext
            , bsPositions = brPositions backtest
            , bsAgreementOk = brAgreementOk backtest
            , bsTrades = tradesScaled
            }
computeBaselines :: Double -> Double -> [Double] -> [Baseline]
computeBaselines periodsPerYear perSideCost prices =
    let ppy = max 1e-12 periodsPerYear
        perSide = min 0.999999 (max 0 perSideCost)
        n = length prices
        steps = max 0 (n - 1)
        buyHoldBt = baselineSimLongFlat perSide prices (replicate steps True)
        buyHold = Baseline{blName = "buy-hold", blMetrics = computeMetrics ppy buyHoldBt}

        pricesV = V.fromList prices
        prefix = V.scanl (+) 0 pricesV
        smaAt w i =
            if w <= 0 || i < 0
                then Nothing
                else
                    let w' = max 1 w
                        i1 = i + 1
                     in if i1 < w'
                            then Nothing
                            else
                                let s = (prefix V.! i1) - (prefix V.! (i1 - w'))
                                 in Just (s / fromIntegral w')

        longW0 = max 10 (min 60 (n `div` 5))
        longW = min (max 2 longW0) (max 2 (n - 1))
        shortW = max 2 (min (longW - 1) (max 2 (longW `div` 2)))

        smaCrossBaseline =
            if n < 3 || shortW >= longW || longW >= n
                then Nothing
                else
                    let wantLong =
                            [ case (smaAt shortW t, smaAt longW t) of
                                (Just s, Just l) -> s > l
                                _ -> False
                            | t <- [0 .. steps - 1]
                            ]
                        bt = baselineSimLongFlat perSide prices wantLong
                        name = printf "sma-cross(%d/%d)" shortW longW
                     in Just (Baseline{blName = name, blMetrics = computeMetrics ppy bt})
     in buyHold : maybeToList smaCrossBaseline

baselineSimLongFlat :: Double -> [Double] -> [Bool] -> BacktestResult
baselineSimLongFlat perSideCost prices wantLong =
    let perSide = min 0.999999 (max 0 perSideCost)
        pricesV = V.fromList prices
        n = V.length pricesV
        stepCount = max 0 (n - 1)
        wantV = V.fromList (take stepCount wantLong <> replicate (max 0 (stepCount - length wantLong)) False)

        applyCost eq size =
            let s = min 1 (max 0 (abs size))
             in eq * (1 - perSide * s)

        isBad x = isNaN x || isInfinite x

        closeTrade exitIndex eqExit (entryIndex, entryEquity, holdingPeriods) =
            Trade
                { trEntryIndex = entryIndex
                , trExitIndex = exitIndex
                , trEntryEquity = entryEquity
                , trExitEquity = eqExit
                , trReturn = if entryEquity == 0 then 0 else eqExit / entryEquity - 1
                , trHoldingPeriods = holdingPeriods
                , trEntryHighVolProb = Nothing
                , trExitReason = Nothing
                , trEntryIp = Nothing
                , trExitIp = Nothing
                }

        stepFn (posSize, equity, eqAcc, posAcc, changes, mOpen, tradesAcc) t =
            let prev = pricesV V.! t
                next = pricesV V.! (t + 1)
                desired = if wantV V.! t then 1 else 0

                (pos1, eq1, changes1, mOpen1, tradesAcc1)
                    | desired == posSize = (posSize, equity, changes, mOpen, tradesAcc)
                    | desired == 0 && posSize > 0 =
                        let eqExit = applyCost equity posSize
                            tradesAcc' =
                                case mOpen of
                                    Nothing -> tradesAcc
                                    Just ot -> closeTrade t eqExit ot : tradesAcc
                         in (0, eqExit, changes + 1, Nothing, tradesAcc')
                    | desired > 0 && posSize == 0 =
                        let eqEntry = applyCost equity desired
                         in (desired, eqEntry, changes + 1, Just (t, eqEntry, 0 :: Int), tradesAcc)
                    | otherwise = (posSize, equity, changes, mOpen, tradesAcc)

                factor = if prev == 0 then 1 else next / prev
                eqClose0 = eq1 * (1 + pos1 * (factor - 1))
                eqClose = if isBad eqClose0 then eq1 else eqClose0

                mOpen2 =
                    case mOpen1 of
                        Nothing -> Nothing
                        Just (entryIndex, entryEq, holding) -> Just (entryIndex, entryEq, holding + 1)
             in (pos1, eqClose, eqClose : eqAcc, pos1 : posAcc, changes1, mOpen2, tradesAcc1)

        (posFinal, eqFinal, eqRev, posRev, changesFinal, mOpenFinal, tradesRev) =
            foldl'
                stepFn
                (0 :: Double, 1.0 :: Double, [1.0], [], 0 :: Int, Nothing :: Maybe (Int, Double, Int), [])
                [0 .. stepCount - 1]

        (eqRev', changesFinal', tradesRev') =
            case (posFinal, mOpenFinal) of
                (p, Just ot)
                    | p > 0 ->
                        let eqExit = applyCost eqFinal p
                            eqRev1 =
                                case eqRev of
                                    [] -> [eqExit]
                                    (_ : rest) -> eqExit : rest
                            tr = closeTrade stepCount eqExit ot
                         in (eqRev1, changesFinal + 1, tr : tradesRev)
                _ -> (eqRev, changesFinal, tradesRev)
     in BacktestResult
            { brEquityCurve = reverse eqRev'
            , brPositions = reverse posRev
            , brAgreementOk = replicate stepCount True
            , brAgreementValid = replicate stepCount True
            , brPositionChanges = changesFinal'
            , brTrades = reverse tradesRev'
            }

data RouterModel
    = RouterKalman
    | RouterLstm
    | RouterBlend
    | RouterCostPick
    | RouterRegimeSwitch
    | RouterEdgeBlend
    deriving (Eq, Show)

routerUsesKalmanGating :: Maybe RouterModel -> Bool
routerUsesKalmanGating mModel =
    case mModel of
        Just RouterKalman -> True
        Just RouterRegimeSwitch -> True
        _ -> False

data RouterStats = RouterStats
    { rsScore :: !Double
    , rsAccuracy :: !Double
    , rsCoverage :: !Double
    , rsSignals :: !Int
    }
    deriving (Eq, Show)

routerStatsWindowWith :: Double -> Double -> Double -> V.Vector Double -> V.Vector Double -> (Int -> Bool) -> Int -> Int -> RouterStats
routerStatsWindowWith openThr roundTripCost pnlWeight pricesV predsV useIdx start0 end0 =
    let stepCount = min (V.length predsV) (V.length pricesV - 1)
        start = max 0 start0
        end = min end0 (stepCount - 1)
        bad x = isNaN x || isInfinite x
        direction prev next =
            if prev <= 0 || bad prev || bad next
                then Nothing
                else
                    let up = prev * (1 + openThr)
                        down = prev * (1 - openThr)
                     in if next > up
                            then Just (1 :: Int)
                            else if next < down then Just (-1) else Nothing
        step (correct, wrong, signals, netAcc, netAccSq, bars) i =
            if not (useIdx i)
                then (correct, wrong, signals, netAcc, netAccSq, bars)
                else
                    let bars' = bars + 1
                        prev = pricesV V.! i
                        next = pricesV V.! (i + 1)
                        pred = predsV V.! i
                        predDir = direction prev pred
                        actualDir = direction prev next
                        ret = if prev <= 0 || bad prev || bad next then 0 else next / prev - 1
                     in case predDir of
                            Nothing -> (correct, wrong, signals, netAcc, netAccSq, bars')
                            Just dir ->
                                let signals' = signals + 1
                                    net = fromIntegral dir * ret - roundTripCost
                                    netAcc' = netAcc + if bad net then 0 else net
                                    netAccSq' = netAccSq + if bad net then 0 else net * net
                                 in if actualDir == Just dir
                                        then (correct + 1, wrong, signals', netAcc', netAccSq', bars')
                                        else (correct, wrong + 1, signals', netAcc', netAccSq', bars')
     in if stepCount <= 0 || end < start
            then RouterStats{rsScore = 0, rsAccuracy = 0, rsCoverage = 0, rsSignals = 0}
            else
                let (correct, _wrong, signals, netAcc, netAccSq, bars) = foldl' step (0, 0, 0, 0, 0, 0) [start .. end]
                    accuracy =
                        if signals <= 0
                            then 0
                            else fromIntegral correct / fromIntegral signals
                    coverage =
                        if bars <= 0
                            then 0
                            else fromIntegral signals / fromIntegral bars
                    avgNet =
                        if signals <= 0
                            then 0
                            else netAcc / fromIntegral signals
                    meanSq =
                        if signals <= 0
                            then 0
                            else netAccSq / fromIntegral signals
                    varNet = max 0 (meanSq - avgNet * avgNet)
                    stdNet = sqrt varNet
                    denom = max 1e-12 (openThr + roundTripCost)
                    riskAdj =
                        if signals <= 0
                            then 0
                            else avgNet / (stdNet + denom)
                    pnlScore =
                        if signals <= 0
                            then 0
                            else clamp01 (0.5 + 0.5 * riskAdj)
                    pnlWeight' = clamp01 pnlWeight
                    scoreAcc = accuracy * coverage
                    score = (1 - pnlWeight') * scoreAcc + pnlWeight' * pnlScore
                 in RouterStats{rsScore = score, rsAccuracy = accuracy, rsCoverage = coverage, rsSignals = signals}

routerStatsWindow :: Double -> Double -> Double -> V.Vector Double -> V.Vector Double -> Int -> Int -> RouterStats
routerStatsWindow openThr roundTripCost pnlWeight pricesV predsV =
    routerStatsWindowWith openThr roundTripCost pnlWeight pricesV predsV (const True)

routerSelectModelAt ::
    Double ->
    Double ->
    Double ->
    Int ->
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    Maybe (V.Vector StepMeta) ->
    Int ->
    (Maybe RouterModel, Double, Maybe String)
routerSelectModelAt openThr roundTripCost pnlWeight lookback0 minScore0 pricesV kalPredV lstmPredV blendPredV costPickPredV regimeSwitchPredV edgeBlendPredV mMetaV t =
    let stepCount =
            minimum
                [ V.length pricesV - 1
                , V.length kalPredV
                , V.length lstmPredV
                , V.length blendPredV
                , V.length costPickPredV
                , V.length regimeSwitchPredV
                , V.length edgeBlendPredV
                ]
        lookback = max 1 lookback0
        minScore = max 0 (min 1 minScore0)
        windowEnd = min (t - 1) (stepCount - 1)
        volCutoff = 0.6 :: Double
        minRegimeBars = max 3 (lookback `div` 4)
        regimeAt i =
            case mMetaV of
                Just metaV
                    | i >= 0 && i < V.length metaV ->
                        case smHighVolProb (metaV V.! i) of
                            Just hv -> Just (hv >= volCutoff)
                            Nothing -> Nothing
                _ -> Nothing
        modelRank m =
            case m of
                RouterCostPick -> 5 :: Int
                RouterRegimeSwitch -> 4
                RouterEdgeBlend -> 3
                RouterBlend -> 2
                RouterKalman -> 1
                RouterLstm -> 0
        scoreKey (m, stats) = (rsScore stats, rsCoverage stats, rsAccuracy stats, modelRank m)
        pick best cand =
            if scoreKey cand > scoreKey best
                then cand
                else best
     in if stepCount <= 0 || windowEnd < 0
            then (Nothing, 0, Just "ROUTER_WARMUP")
            else
                let windowStart = max 0 (windowEnd - lookback + 1)
                    mRegNow = regimeAt windowEnd
                    sameReg i = regimeAt i == mRegNow
                    regimeBars =
                        case mRegNow of
                            Nothing -> 0
                            Just _ -> length [i | i <- [windowStart .. windowEnd], sameReg i]
                    useRegime = regimeBars >= minRegimeBars
                    useIdx = if useRegime then sameReg else const True
                    statsKal = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV kalPredV useIdx windowStart windowEnd
                    statsLstm = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV lstmPredV useIdx windowStart windowEnd
                    statsBlend = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV blendPredV useIdx windowStart windowEnd
                    statsCostPick = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV costPickPredV useIdx windowStart windowEnd
                    statsRegimeSwitch = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV regimeSwitchPredV useIdx windowStart windowEnd
                    statsEdgeBlend = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV edgeBlendPredV useIdx windowStart windowEnd
                    (bestModel, bestStats) =
                        foldl'
                            pick
                            (RouterKalman, statsKal)
                            [ (RouterLstm, statsLstm)
                            , (RouterBlend, statsBlend)
                            , (RouterCostPick, statsCostPick)
                            , (RouterRegimeSwitch, statsRegimeSwitch)
                            , (RouterEdgeBlend, statsEdgeBlend)
                            ]
                    bestScore = rsScore bestStats
                 in if bestScore < minScore
                        then (Nothing, bestScore, Just "ROUTER_MIN_SCORE")
                        else (Just bestModel, bestScore, Nothing)

banditSelectModelAt ::
    Double ->
    Double ->
    Double ->
    Int ->
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    Maybe (V.Vector StepMeta) ->
    Int ->
    (Maybe RouterModel, Double, Maybe String)
banditSelectModelAt openThr roundTripCost pnlWeight lookback0 minScore0 pricesV kalPredV lstmPredV blendPredV costPickPredV regimeSwitchPredV edgeBlendPredV mMetaV t =
    let stepCount =
            minimum
                [ V.length pricesV - 1
                , V.length kalPredV
                , V.length lstmPredV
                , V.length blendPredV
                , V.length costPickPredV
                , V.length regimeSwitchPredV
                , V.length edgeBlendPredV
                ]
        lookback = max 1 lookback0
        minScore = max 0 (min 1 minScore0)
        windowEnd = min (t - 1) (stepCount - 1)
        volCutoff = 0.6 :: Double
        minRegimeBars = max 3 (lookback `div` 4)
        regimeAt i =
            case mMetaV of
                Just metaV
                    | i >= 0 && i < V.length metaV ->
                        case smHighVolProb (metaV V.! i) of
                            Just hv -> Just (hv >= volCutoff)
                            Nothing -> Nothing
                _ -> Nothing
        modelRank m =
            case m of
                RouterCostPick -> 5 :: Int
                RouterRegimeSwitch -> 4
                RouterEdgeBlend -> 3
                RouterBlend -> 2
                RouterKalman -> 1
                RouterLstm -> 0
        bonusScale = 0.25 :: Double
        scoreKey totalSignals (m, stats) =
            let n = max 0 (rsSignals stats)
                explore = sqrt (2 * log (max 2 totalSignals) / fromIntegral (n + 1))
                score = rsScore stats + bonusScale * explore
             in (score, rsScore stats, rsCoverage stats, rsAccuracy stats, modelRank m)
        pick totalSignals best cand =
            if scoreKey totalSignals cand > scoreKey totalSignals best
                then cand
                else best
     in if stepCount <= 0 || windowEnd < 0
            then (Nothing, 0, Just "BANDIT_WARMUP")
            else
                let windowStart = max 0 (windowEnd - lookback + 1)
                    mRegNow = regimeAt windowEnd
                    sameReg i = regimeAt i == mRegNow
                    regimeBars =
                        case mRegNow of
                            Nothing -> 0
                            Just _ -> length [i | i <- [windowStart .. windowEnd], sameReg i]
                    useRegime = regimeBars >= minRegimeBars
                    useIdx = if useRegime then sameReg else const True
                    statsKal = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV kalPredV useIdx windowStart windowEnd
                    statsLstm = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV lstmPredV useIdx windowStart windowEnd
                    statsBlend = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV blendPredV useIdx windowStart windowEnd
                    statsCostPick = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV costPickPredV useIdx windowStart windowEnd
                    statsRegimeSwitch = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV regimeSwitchPredV useIdx windowStart windowEnd
                    statsEdgeBlend = routerStatsWindowWith openThr roundTripCost pnlWeight pricesV edgeBlendPredV useIdx windowStart windowEnd
                    totalSignals =
                        fromIntegral
                            ( 1
                                + rsSignals statsKal
                                + rsSignals statsLstm
                                + rsSignals statsBlend
                                + rsSignals statsCostPick
                                + rsSignals statsRegimeSwitch
                                + rsSignals statsEdgeBlend
                            )
                    (bestModel, bestStats) =
                        foldl'
                            (pick totalSignals)
                            (RouterKalman, statsKal)
                            [ (RouterLstm, statsLstm)
                            , (RouterBlend, statsBlend)
                            , (RouterCostPick, statsCostPick)
                            , (RouterRegimeSwitch, statsRegimeSwitch)
                            , (RouterEdgeBlend, statsEdgeBlend)
                            ]
                    bestScore = rsScore bestStats
                 in if bestScore < minScore
                        then (Nothing, bestScore, Just "BANDIT_MIN_SCORE")
                        else (Just bestModel, bestScore, Nothing)

routerPredictionsWithModelsV ::
    Double ->
    Double ->
    Double ->
    Int ->
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    Maybe (V.Vector StepMeta) ->
    (V.Vector Double, V.Vector (Maybe RouterModel))
routerPredictionsWithModelsV openThr roundTripCost pnlWeight lookback minScore pricesV kalPredV lstmPredV blendPredV costPickPredV regimeSwitchPredV edgeBlendPredV mMetaV =
    let stepCount =
            minimum
                [ V.length pricesV - 1
                , V.length kalPredV
                , V.length lstmPredV
                , V.length blendPredV
                , V.length costPickPredV
                , V.length regimeSwitchPredV
                , V.length edgeBlendPredV
                ]
        pickPred t =
            case routerSelectModelAt openThr roundTripCost pnlWeight lookback minScore pricesV kalPredV lstmPredV blendPredV costPickPredV regimeSwitchPredV edgeBlendPredV mMetaV t of
                (Just RouterKalman, _, _) -> (kalPredV V.! t, Just RouterKalman)
                (Just RouterLstm, _, _) -> (lstmPredV V.! t, Just RouterLstm)
                (Just RouterBlend, _, _) -> (blendPredV V.! t, Just RouterBlend)
                (Just RouterCostPick, _, _) -> (costPickPredV V.! t, Just RouterCostPick)
                (Just RouterRegimeSwitch, _, _) -> (regimeSwitchPredV V.! t, Just RouterRegimeSwitch)
                (Just RouterEdgeBlend, _, _) -> (edgeBlendPredV V.! t, Just RouterEdgeBlend)
                _ -> (pricesV V.! t, Nothing)
        picks = V.generate (max 0 stepCount) pickPred
     in (V.map fst picks, V.map snd picks)

banditPredictionsWithModelsV ::
    Double ->
    Double ->
    Double ->
    Int ->
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    Maybe (V.Vector StepMeta) ->
    (V.Vector Double, V.Vector (Maybe RouterModel))
banditPredictionsWithModelsV openThr roundTripCost pnlWeight lookback minScore pricesV kalPredV lstmPredV blendPredV costPickPredV regimeSwitchPredV edgeBlendPredV mMetaV =
    let stepCount =
            minimum
                [ V.length pricesV - 1
                , V.length kalPredV
                , V.length lstmPredV
                , V.length blendPredV
                , V.length costPickPredV
                , V.length regimeSwitchPredV
                , V.length edgeBlendPredV
                ]
        pickPred t =
            case banditSelectModelAt openThr roundTripCost pnlWeight lookback minScore pricesV kalPredV lstmPredV blendPredV costPickPredV regimeSwitchPredV edgeBlendPredV mMetaV t of
                (Just RouterKalman, _, _) -> (kalPredV V.! t, Just RouterKalman)
                (Just RouterLstm, _, _) -> (lstmPredV V.! t, Just RouterLstm)
                (Just RouterBlend, _, _) -> (blendPredV V.! t, Just RouterBlend)
                (Just RouterCostPick, _, _) -> (costPickPredV V.! t, Just RouterCostPick)
                (Just RouterRegimeSwitch, _, _) -> (regimeSwitchPredV V.! t, Just RouterRegimeSwitch)
                (Just RouterEdgeBlend, _, _) -> (edgeBlendPredV V.! t, Just RouterEdgeBlend)
                _ -> (pricesV V.! t, Nothing)
        picks = V.generate (max 0 stepCount) pickPred
     in (V.map fst picks, V.map snd picks)

routerPredictionsV ::
    Double ->
    Double ->
    Double ->
    Int ->
    Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double ->
    V.Vector Double
routerPredictionsV openThr roundTripCost pnlWeight lookback minScore pricesV kalPredV lstmPredV blendPredV costPickPredV regimeSwitchPredV edgeBlendPredV =
    fst (routerPredictionsWithModelsV openThr roundTripCost pnlWeight lookback minScore pricesV kalPredV lstmPredV blendPredV costPickPredV regimeSwitchPredV edgeBlendPredV Nothing)

computeLatestSignal ::
    Args ->
    Int ->
    FeatureInputs ->
    Maybe LstmCtx ->
    Maybe KalmanCtx ->
    Maybe MarketModel ->
    Maybe PredHistory ->
    Either String LatestSignal
computeLatestSignal args lookback featureInputs mLstmCtx mKalmanCtx mMarketModel mPredHistory
    | nAll < 1 = Left ("Need at least 1 price to compute latest signal (got " ++ show nAll ++ ")")
    | methodNeedsLstm && not lstmWindowOk = Left "Not enough data to compute LSTM window for latest signal."
    | otherwise =
        case method of
            MethodBoth ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method 11 requires both Kalman and LSTM contexts."
            MethodKalmanOnly ->
                case mKalmanCtx of
                    Just _ -> Right compute
                    Nothing -> Left missingKalmanCtxError
            MethodKalmanPhysicsError ->
                case mKalmanCtx of
                    Just _ -> Right compute
                    Nothing -> Left missingKalmanCtxError
            MethodLstmOnly ->
                case mLstmCtxSafe of
                    Just _ -> Right compute
                    Nothing -> Left "Method 01 requires LSTM context."
            MethodBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method blend requires both Kalman and LSTM contexts."
            MethodConfBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method conf_blend requires both Kalman and LSTM contexts."
            MethodConfPick ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method conf_pick requires both Kalman and LSTM contexts."
            MethodConformalClip ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method conformal_clip requires both Kalman and LSTM contexts."
            MethodCostPick ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method cost_pick requires both Kalman and LSTM contexts."
            MethodHarmonicBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method harmonic_blend requires both Kalman and LSTM contexts."
            MethodDisagreementGuard ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method disagreement_guard requires both Kalman and LSTM contexts."
            MethodMedianBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method median_blend requires both Kalman and LSTM contexts."
            MethodNeutralGuard ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method neutral_guard requires both Kalman and LSTM contexts."
            MethodRiskParityBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method risk_parity_blend requires both Kalman and LSTM contexts."
            MethodConsensusBoost ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method consensus_boost requires both Kalman and LSTM contexts."
            MethodAnchorBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method anchor_blend requires both Kalman and LSTM contexts."
            MethodTensionGate ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method tension_gate requires both Kalman and LSTM contexts."
            MethodEntropyBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method entropy_blend requires both Kalman and LSTM contexts."
            MethodCoherenceGate ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method coherence_gate requires both Kalman and LSTM contexts."
            MethodDivergenceGate ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method divergence_gate requires both Kalman and LSTM contexts."
            MethodFractalBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method fractal_blend requires both Kalman and LSTM contexts."
            MethodPhaseCancel ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method phase_cancel requires both Kalman and LSTM contexts."
            MethodSoftmaxBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method softmax_blend requires both Kalman and LSTM contexts."
            MethodSmoothSoftmaxBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method smooth_softmax_blend requires both Kalman and LSTM contexts."
            MethodHedgeBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method hedge_blend requires both Kalman and LSTM contexts."
            MethodNetSoftmaxBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method net_softmax_blend requires both Kalman and LSTM contexts."
            MethodEdgeBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method edge_blend requires both Kalman and LSTM contexts."
            MethodEdgePick ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method edge_pick requires both Kalman and LSTM contexts."
            MethodGeoBlend ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method geo_blend requires both Kalman and LSTM contexts."
            MethodRegimeSwitch ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method regime_switch requires both Kalman and LSTM contexts."
            MethodRouter ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method router requires both Kalman and LSTM contexts."
            MethodBanditRouter ->
                case (mKalmanCtx, mLstmCtxSafe) of
                    (Just _, Just _) -> Right compute
                    _ -> Left "Method bandit_router requires both Kalman and LSTM contexts."
  where
    methodRequested = argMethod args
    method = runtimeMethod methodRequested
    methodForReport =
        case methodRequested of
            MethodKalmanPhysicsError -> MethodKalmanPhysicsError
            _ -> method
    missingKalmanCtxError =
        case methodForReport of
            MethodKalmanPhysicsError -> "Method kalman_physics_error requires Kalman context."
            _ -> "Method 10 requires Kalman context."
    pricesV = fiClose featureInputs
    nAll = V.length pricesV
    methodNeedsLstm =
        case method of
            MethodLstmOnly -> True
            MethodBoth -> True
            MethodBlend -> True
            MethodConfBlend -> True
            MethodConfPick -> True
            MethodConformalClip -> True
            MethodCostPick -> True
            MethodHarmonicBlend -> True
            MethodDisagreementGuard -> True
            MethodMedianBlend -> True
            MethodNeutralGuard -> True
            MethodRiskParityBlend -> True
            MethodConsensusBoost -> True
            MethodAnchorBlend -> True
            MethodTensionGate -> True
            MethodEntropyBlend -> True
            MethodCoherenceGate -> True
            MethodDivergenceGate -> True
            MethodFractalBlend -> True
            MethodPhaseCancel -> True
            MethodSoftmaxBlend -> True
            MethodSmoothSoftmaxBlend -> True
            MethodHedgeBlend -> True
            MethodNetSoftmaxBlend -> True
            MethodEdgeBlend -> True
            MethodEdgePick -> True
            MethodGeoBlend -> True
            MethodRegimeSwitch -> True
            MethodRouter -> True
            MethodBanditRouter -> True
            _ -> False
    lstmWindowOk =
        case mLstmCtx of
            Just (_, obsAll, _) -> lookback > 0 && length obsAll >= lookback
            Nothing -> True
    mLstmCtxSafe =
        if lstmWindowOk
            then mLstmCtx
            else Nothing
    compute =
        let n = V.length pricesV
            t = n - 1
            currentPrice = pricesV V.! t
            volPerBarCost = volPerBarFromPricesV pricesV
            sizeRef = max 1e-6 (argMaxPositionSize args)
            perSideCost = estimatedPerSideCost args sizeRef volPerBarCost
            roundTripCost = estimatedRoundTripCost args sizeRef volPerBarCost
            minEdgeBase = max 0 (argMinEdge args)
            minEdge =
                if argCostAwareEdge args
                    then max minEdgeBase (breakEvenThresholdFromPerSideCost perSideCost + max 0 (argEdgeBuffer args))
                    else minEdgeBase
            minSignalToNoiseBase = max 0 (argMinSignalToNoise args)
            openThrBase =
                normalizeSignalThreshold (max (max 0 (argOpenThreshold args)) minEdge)
            closeThrBase =
                normalizeSignalThreshold (max 0 (argCloseThreshold args))
            factorEnabled = argThresholdFactorEnabled args
            factorMinRaw = argThresholdFactorMin args
            factorMaxRaw = argThresholdFactorMax args
            factorMin = max 1e-6 (min factorMinRaw factorMaxRaw)
            factorMax = max factorMin (max factorMinRaw factorMaxRaw)
            factorFloor = max 0 (argThresholdFactorFloor args)
            (factorOpenPrev, factorClosePrev) =
                case mPredHistory of
                    Just hist ->
                        computeThresholdFactorsFromHistory
                            args
                            method
                            openThrBase
                            closeThrBase
                            minEdge
                            lookback
                            roundTripCost
                            pricesV
                            hist
                    Nothing -> (1, 1)
            factorOpenBase =
                if factorEnabled
                    then clampRange factorMin factorMax factorOpenPrev
                    else 1
            factorCloseBase =
                if factorEnabled
                    then clampRange factorMin factorMax factorClosePrev
                    else 1
            minEdgeAdj =
                if factorEnabled
                    then max factorFloor (minEdge * factorOpenBase)
                    else minEdge
            openThrAdj =
                if factorEnabled
                    then normalizeSignalThreshold (max minEdgeAdj (max factorFloor (openThrBase * factorOpenBase)))
                    else openThrBase
            closeThrAdj =
                if factorEnabled
                    then normalizeSignalThreshold (max factorFloor (closeThrBase * factorCloseBase))
                    else closeThrBase
            minSignalToNoise =
                if factorEnabled
                    then max factorFloor (minSignalToNoiseBase * factorOpenBase)
                    else minSignalToNoiseBase
            metaLabelEnabled = argMetaLabelFilter args
            metaLabelMinEdge = max 0 (argMetaLabelMinEdge args)
            metaLabelMinConfidence = clamp01 (argMetaLabelMinConfidence args)
            metaLabelRequireBand = argMetaLabelRequireBand args
            regimeBankEnabled = argRegimeParameterBank args
            regimeBankHysteresis = clamp01 (argRegimeBankHysteresis args)
            regimeTrendOpenMult = max 0 (argRegimeTrendOpenMult args)
            regimeMrOpenMult = max 0 (argRegimeMrOpenMult args)
            regimeHighVolOpenMult = max 0 (argRegimeHighVolOpenMult args)
            regimeTrendSizeMult = max 0 (argRegimeTrendSizeMult args)
            regimeMrSizeMult = max 0 (argRegimeMrSizeMult args)
            regimeHighVolSizeMult = max 0 (argRegimeHighVolSizeMult args)
            mtfConsensusEnabled = argMultiTimeframeConsensus args
            mtfFastBars = max 1 (argMtfFastBars args)
            mtfMidBars = max 1 (argMtfMidBars args)
            mtfSlowBars = max 1 (argMtfSlowBars args)
            mtfMinAgree = max 1 (min 3 (argMtfMinAgree args))
            crossAssetEnabled = argCrossAssetConfirmation args
            crossAssetMinBeta = max 0 (argCrossAssetMinBeta args)
            crossAssetMinEdge = max 0 (argCrossAssetMinEdge args)
            pairsStatArbEnabled = argPairsStatArb args
            pairsLookback = max 2 (argPairsStatArbLookback args)
            pairsZEntry = max 1e-9 (argPairsStatArbZEntry args)
            pairsSizeMult = clamp01 (argPairsStatArbSizeMult args)
            fundingOiEnabled = argFundingOiAware args
            fundingOiFundingCap =
                case argFundingOiFundingCap args of
                    Just v | v > 0 && not (isNaN v || isInfinite v) -> Just v
                    _ -> Nothing
            fundingOiVolLookback = max 2 (argFundingOiVolLookback args)
            fundingOiVolCap =
                case argFundingOiVolCap args of
                    Just v | v > 0 && not (isNaN v || isInfinite v) -> Just v
                    _ -> Nothing
            fundingOiSizeMult = clamp01 (argFundingOiSizeMult args)
            kellyLiteEnabled = argKellyLiteSizing args
            kellyLiteFraction = max 0 (argKellyLiteFraction args)
            kellyLiteFloor = max 0 (argKellyLiteFloor args)
            kellyLiteCap = max kellyLiteFloor (argKellyLiteCap args)
            directionPrice thr pred =
                let thr' = normalizeSignalThreshold thr
                    upEdge = currentPrice * (1 + thr')
                    downEdge = currentPrice * (1 - thr')
                 in if pred > upEdge
                        then Just (1 :: Int)
                        else if pred < downEdge then Just (-1) else Nothing

            trendLookback = max 0 (argTrendLookback args)
            maxPositionSize = max 0 (argMaxPositionSize args)
            ppy = max 1e-12 (periodsPerYear args)
            volConfGatePreset = argVolConfGate args
            volConfGateEnabled = volConfGatePreset /= VolConfGateDisabled
            confidenceSizingEnabled = argConfidenceSizing args && not volConfGateEnabled
            volTarget =
                case argVolTarget args of
                    Just v | v > 0 && not (isNaN v || isInfinite v) -> Just v
                    _ -> Nothing
            volLookback = max 0 (argVolLookback args)
            volFloor = max 0 (argVolFloor args)
            volScaleMax = max 0 (argVolScaleMax args)
            volAlpha =
                case argVolEwmaAlpha args of
                    Just a | a > 0 && not (isNaN a || isInfinite a) -> Just (max 0 (min 1 a))
                    _ -> Nothing
            maxVolatility =
                case argMaxVolatility args of
                    Just v | v > 0 && not (isNaN v || isInfinite v) -> Just v
                    _ -> Nothing

            bad x = isNaN x || isInfinite x

            alignVector mv =
                case mv of
                    Just v
                        | V.length v == n -> Just v
                        | V.length v > n -> Just (V.drop (V.length v - n) v)
                    _ -> Nothing

            opensV = alignVector (fiOpen featureInputs)
            highsV = alignVector (fiHigh featureInputs)
            lowsV = alignVector (fiLow featureInputs)

            returnsFromPrices =
                case n of
                    _ | n < 2 -> []
                    _ ->
                        let pricesList = V.toList pricesV
                         in [ let r = if p0 == 0 || bad p0 || bad p1 then 0 else p1 / p0 - 1
                               in if bad r then 0 else r
                            | (p0, p1) <- zip pricesList (drop 1 pricesList)
                            ]

            meanList xs =
                if null xs then 0 else sum xs / fromIntegral (length xs)

            stddevList xs =
                case xs of
                    [] -> 0
                    [_] -> 0
                    _ ->
                        let m = meanList xs
                            var = sum (map (\x -> (x - m) ** 2) xs) / fromIntegral (length xs - 1)
                         in sqrt var

            returnAt i =
                if i <= 0 || i >= n
                    then Nothing
                    else
                        let p0 = pricesV V.! (i - 1)
                            p1 = pricesV V.! i
                            r =
                                if p0 == 0 || bad p0 || bad p1
                                    then 0
                                    else p1 / p0 - 1
                         in if bad r then Nothing else Just r

            horizonDir bars =
                if bars <= 0 || t < bars
                    then Nothing
                    else
                        let p0 = pricesV V.! (t - bars)
                            p1 = pricesV V.! t
                            r =
                                if p0 == 0 || bad p0 || bad p1
                                    then 0
                                    else p1 / p0 - 1
                            eps = max 1e-12 (openThrAdj * sqrt (fromIntegral (max 1 bars)))
                         in if bad r
                                then Nothing
                                else
                                    if r > eps
                                        then Just (1 :: Int)
                                        else if r < negate eps then Just (-1) else Nothing

            mtfDirs = map horizonDir [mtfFastBars, mtfMidBars, mtfSlowBars]

            fundingPressure dir =
                let baseFunding = argFundingRate args
                 in if argFundingBySide args
                        then
                            if dir >= 0
                                then baseFunding
                                else negate baseFunding
                        else baseFunding

            volEstimate =
                let total = length returnsFromPrices
                 in if total < 2
                        then Nothing
                        else case volAlpha of
                            Just a ->
                                let var = foldl' (\v r -> a * v + (1 - a) * (r * r)) 0 returnsFromPrices
                                    vol = sqrt (max 0 var) * sqrt ppy
                                 in if bad vol then Nothing else Just vol
                            Nothing ->
                                let lb = if volLookback <= 0 then total else min total volLookback
                                    window = drop (total - lb) returnsFromPrices
                                    vol = stddevList window * sqrt ppy
                                 in if bad vol then Nothing else Just vol

            physicsKalNext =
                case mPredHistory of
                    Just PredHistory{phKalman = kalHist}
                        | methodForReport == MethodKalmanPhysicsError && V.length kalHist > t ->
                            let p = kalHist V.! t
                             in if bad p then Nothing else Just p
                    _ -> Nothing

            volScale =
                case volTarget of
                    Nothing -> 1
                    Just target ->
                        case volEstimate of
                            Nothing -> 1
                            Just vol ->
                                let volAdj = max volFloor vol
                                    scale0 = if volAdj <= 0 then 1 else target / volAdj
                                    scale1 = min volScaleMax (max 0 scale0)
                                 in if bad scale1 then 1 else scale1

            volOk =
                case maxVolatility of
                    Nothing -> True
                    Just maxVol ->
                        case volEstimate of
                            Just vol -> vol <= maxVol
                            Nothing -> False

            volPerBar =
                case volEstimate of
                    Just vol ->
                        let perBar = vol / sqrt ppy
                         in if bad perBar || perBar <= 0 then Nothing else Just perBar
                    _ -> Nothing

            clampFrac x = min 0.999999 (max 0 x)

            stopFromVol mult =
                if mult <= 0
                    then Nothing
                    else case volPerBar of
                        Just v ->
                            let f = mult * v
                             in if bad f || f <= 0 then Nothing else Just (clampFrac f)
                        _ -> Nothing

            stopLossFrac =
                case stopFromVol (argStopLossVolMult args) of
                    Just v -> Just v
                    Nothing ->
                        case argStopLoss args of
                            Just sl | sl > 0 -> Just (clampFrac sl)
                            _ -> Nothing

            riskScale =
                case argRiskPerTrade args of
                    Just risk | risk > 0 ->
                        case stopLossFrac of
                            Just sl
                                | sl > 0 ->
                                    let s = risk / sl
                                     in if bad s || s <= 0 then 1 else s
                            _ -> 1
                    _ -> 1

            volTargetReady =
                case volTarget of
                    Nothing -> True
                    Just _ ->
                        case volEstimate of
                            Just _ -> True
                            Nothing -> False

            trendOk dir =
                (trendLookback <= 1 || n < trendLookback)
                    || ( let start = n - trendLookback
                             v = V.slice start trendLookback pricesV
                             sma = V.sum v / fromIntegral trendLookback
                          in (bad sma || bad currentPrice)
                                || case dir of
                                    1 -> currentPrice >= sma
                                    (-1) -> currentPrice <= sma
                                    _ -> True
                       )

            triLayerEnabled = argTriLayer args
            requirePriceAction = argTriLayerRequirePriceAction args
            priceActionBodyMin = max 0 (argTriLayerPriceActionBody args)
            bodyMinFracBase = max 1e-6 (0.25 * openThrBase)
            bodyMinFrac =
                if priceActionBodyMin > 0
                    then priceActionBodyMin
                    else bodyMinFracBase
            cloudPadFrac = max 0 (argTriLayerCloudPadding args)
            cloudSlopeMin = max 0 (argTriLayerCloudSlope args)
            cloudWidthMax = max 0 (argTriLayerCloudWidth args)
            touchLookback = max 1 (argTriLayerTouchLookback args)
            cloudReady = triLayerEnabled && n >= 2
            kalDt = max 1e-12 (argKalmanDt args)
            kalProcessVar = max 0 (argKalmanProcessVar args)
            kalMeasVar = max 1e-12 (argKalmanMeasurementVar args)
            fastMult = max 1e-6 (argTriLayerFastMult args)
            slowMult = max 1e-6 (argTriLayerSlowMult args)
            (cloudFastV, cloudSlowV) =
                if cloudReady
                    then
                        let run mult =
                                let mv = max 1e-12 (kalMeasVar * mult)
                                    KalmanRunV{krFilteredV = filts} =
                                        runConstantAcceleration1DVec kalDt kalProcessVar mv pricesV
                                 in filts
                         in (run fastMult, run slowMult)
                    else (pricesV, pricesV)

            candleAt i =
                let c = pricesV V.! i
                    prevClose = if i <= 0 then c else pricesV V.! (i - 1)
                    oRaw =
                        case opensV of
                            Just ov | i >= 0 && i < V.length ov -> ov V.! i
                            _ -> prevClose
                    hRaw =
                        case highsV of
                            Just hv | i >= 0 && i < V.length hv -> hv V.! i
                            _ -> c
                    lRaw =
                        case lowsV of
                            Just lv | i >= 0 && i < V.length lv -> lv V.! i
                            _ -> c
                    o = if bad oRaw then prevClose else oRaw
                    h = max (max o c) (if bad hRaw then c else hRaw)
                    l = min (min o c) (if bad lRaw then c else lRaw)
                 in (o, h, l, c)

            candleOpen (o, _, _, _) = o
            candleClose (_, _, _, c) = c
            candleBody (o, _, _, c) = abs (c - o)
            candleBull (o, _, _, c) = c > o
            candleBear (o, _, _, c) = c < o
            candleUpperWick (o, h, _, c) = max 0 (h - max o c)
            candleLowerWick (o, _, l, c) = max 0 (min o c - l)

            bodyOk closePx body =
                let denom = max 1e-12 (abs closePx)
                 in body / denom >= bodyMinFrac

            hammer candle =
                let body = candleBody candle
                    upper = candleUpperWick candle
                    lower = candleLowerWick candle
                    closePx = candleClose candle
                 in candleBull candle
                        && body > 0
                        && bodyOk closePx body
                        && lower >= 2 * body
                        && upper <= 0.5 * body

            shootingStar candle =
                let body = candleBody candle
                    upper = candleUpperWick candle
                    lower = candleLowerWick candle
                    closePx = candleClose candle
                 in candleBear candle
                        && body > 0
                        && bodyOk closePx body
                        && upper >= 2 * body
                        && lower <= 0.5 * body

            bullishEngulf cur prev =
                let bodyCur = candleBody cur
                    bodyPrev = candleBody prev
                    closePx = candleClose cur
                 in candleBull cur
                        && candleBear prev
                        && bodyCur >= bodyPrev
                        && bodyOk closePx bodyCur
                        && candleClose cur >= candleOpen prev
                        && candleOpen cur <= candleClose prev

            bearishEngulf cur prev =
                let bodyCur = candleBody cur
                    bodyPrev = candleBody prev
                    closePx = candleClose cur
                 in candleBear cur
                        && candleBull prev
                        && bodyCur >= bodyPrev
                        && bodyOk closePx bodyCur
                        && candleClose cur <= candleOpen prev
                        && candleOpen cur >= candleClose prev

            railroadTracksLong cur prev =
                let bodyCur = candleBody cur
                    bodyPrev = candleBody prev
                    closePx = candleClose cur
                    tol = 0.2
                 in candleBull cur
                        && candleBear prev
                        && bodyPrev > 0
                        && bodyOk closePx bodyCur
                        && abs (bodyCur - bodyPrev) / bodyPrev <= tol

            darkCloudCover cur prev =
                let midPrev = (candleOpen prev + candleClose prev) / 2
                 in candleBear cur && candleBull prev && candleClose cur < midPrev

            touchCloudAt idx =
                let fastIdx = cloudFastV V.! idx
                    slowIdx = cloudSlowV V.! idx
                    cloudTopIdx = max fastIdx slowIdx
                    cloudBotIdx = min fastIdx slowIdx
                    pxIdx = pricesV V.! idx
                    padIdx = cloudPadFrac * (if bad pxIdx then 0 else abs pxIdx)
                    cloudTopPadIdx = cloudTopIdx + padIdx
                    cloudBotPadIdx = cloudBotIdx - padIdx
                    (_, h, l, _) = candleAt idx
                 in not (bad fastIdx || bad slowIdx)
                        && l <= cloudTopPadIdx
                        && h >= cloudBotPadIdx

            touchCloudInWindow t' =
                ( not cloudReady
                    || ( let start = max 0 (t' - touchLookback + 1)
                          in any touchCloudAt [start .. t']
                       )
                )

            cloudOk dir =
                ( (not cloudReady || t <= 0)
                    || ( let fast = cloudFastV V.! t
                             slow = cloudSlowV V.! t
                             slope = slow - cloudSlowV V.! (t - 1)
                             cloudTop = max fast slow
                             cloudBot = min fast slow
                             px = pricesV V.! t
                             slopeFrac =
                                if bad px || px == 0
                                    then 0
                                    else slope / abs px
                             widthFrac =
                                if bad px || px == 0
                                    then 0
                                    else (cloudTop - cloudBot) / abs px
                             widthOk = cloudWidthMax <= 0 || bad widthFrac || widthFrac <= cloudWidthMax
                             touchCloud = touchCloudInWindow t
                             trendOkCloud =
                                case dir of
                                    1 -> fast > slow && slopeFrac >= cloudSlopeMin
                                    (-1) -> fast < slow && slopeFrac <= negate cloudSlopeMin
                                    _ -> True
                          in (bad fast || bad slow || bad slope)
                                || (touchCloud && trendOkCloud && widthOk)
                       )
                )

            priceActionOk dir =
                ( (not triLayerEnabled || not requirePriceAction || t < 2)
                    || ( let cur = candleAt t
                             prev = candleAt (t - 1)
                             bullish = hammer cur || bullishEngulf cur prev || railroadTracksLong cur prev
                             bearish = shootingStar cur || bearishEngulf cur prev || darkCloudCover cur prev
                          in case dir of
                                1 -> bullish
                                (-1) -> bearish
                                _ -> True
                       )
                )

            blendWeight = clamp01 (argBlendWeight args)
            kalZMinForBlend = max 0 (argKalmanZMin args)
            kalZMaxForBlend = max kalZMinForBlend (argKalmanZMax args)

            (mKalNext, mKalReturn, mKalStd, mKalZ, mRegimes, mQuantiles, mConformal, kalDirRaw, kalDir, kalCloseDir, mConfidence, mPosSize, mGateReason) =
                case mKalmanCtx of
                    Nothing -> (Nothing, Nothing, Nothing, Nothing, Nothing, Nothing, Nothing, Nothing, Nothing, Nothing, Nothing, Just 0, Nothing)
                    Just (predictors, kalPrev, hmmPrev, svPrev) ->
                        let (sensorOuts, _) = predictSensorsWithInputs predictors featureInputs hmmPrev t
                            mReg = listToMaybe [r | (_sid, out) <- sensorOuts, Just r <- [soRegimes out]]
                            mQ = listToMaybe [q | (_sid, out) <- sensorOuts, Just q <- [soQuantiles out]]
                            mI = listToMaybe [i | (_sid, out) <- sensorOuts, Just i <- [soInterval out]]
                            meas = mapMaybe (toMeasurement args svPrev) sensorOuts ++ maybeToList (mMarketModel >>= (`marketMeasurementAt` t))
                            kalNow = stepMulti meas kalPrev
                            kalReturnRaw = kMean kalNow
                            kalVar = max 0 (kVar kalNow)
                            kalStd = sqrt kalVar
                            kalNextRaw = currentPrice * (1 + kalReturnRaw)
                            kalNext = fromMaybe kalNextRaw physicsKalNext
                            kalReturn =
                                if currentPrice == 0 || bad currentPrice || bad kalNext
                                    then kalReturnRaw
                                    else kalNext / currentPrice - 1
                            kalZ = if kalStd <= 0 then 0 else abs kalReturn / kalStd
                            dirRaw = directionPrice openThrAdj kalNext
                            closeDirRaw = directionPrice closeThrAdj kalNext
                            confScore = confidenceScoreKalman args kalZ mReg mI mQ
                            sizeRaw =
                                if argConfidenceSizing args
                                    then confScore
                                    else case dirRaw of
                                        Nothing -> 0
                                        Just _ -> 1
                            (dirUsed, mWhy) = gateKalmanDir args (argConfidenceSizing args) openThrAdj kalZ mReg mI mQ confScore dirRaw
                            (closeDirUsed, _) = gateKalmanDir args False closeThrAdj kalZ mReg mI mQ confScore closeDirRaw
                            sizeUsed =
                                case dirUsed of
                                    Nothing -> 0
                                    Just _ ->
                                        let s0 = if argConfidenceSizing args then sizeRaw else 1
                                         in if argConfidenceSizing args && s0 < argMinPositionSize args then 0 else s0
                         in ( Just kalNext
                            , Just kalReturn
                            , Just kalStd
                            , Just kalZ
                            , mReg
                            , mQ
                            , mI
                            , dirRaw
                            , dirUsed
                            , closeDirUsed
                            , Just confScore
                            , Just sizeUsed
                            , mWhy
                            )

            (mLstmNext, lstmDir) =
                case mLstmCtxSafe of
                    Nothing -> (Nothing, Nothing)
                    Just (normState, obsAll, lstmModel) ->
                        let start = t - lookback + 1
                         in if start < 0
                                then (Nothing, Nothing)
                                else
                                    let window = take lookback (drop start obsAll)
                                        lstmNextObs = predictNext lstmModel window
                                        lstmNext = inverseNorm normState lstmNextObs
                                     in (Just lstmNext, directionPrice openThrAdj lstmNext)

            blendNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) -> Just (blendPredFromPreds blendWeight currentPrice k l)
                    _ -> Nothing
            confBlendNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        Just
                            ( confidenceBlendPredFromPreds
                                blendWeight
                                kalZMinForBlend
                                kalZMaxForBlend
                                openThrAdj
                                currentPrice
                                k
                                l
                                mKalZ
                            )
                    _ -> Nothing
            confPickNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        Just
                            ( confidencePickPredFromPreds
                                blendWeight
                                kalZMinForBlend
                                kalZMaxForBlend
                                openThrAdj
                                currentPrice
                                k
                                l
                                mKalZ
                            )
                    _ -> Nothing
            conformalClipNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        let bounds =
                                case mConformal of
                                    Just i -> Just (iLo i, iHi i)
                                    Nothing ->
                                        case mQuantiles of
                                            Just q -> Just (q10 q, q90 q)
                                            Nothing -> Nothing
                         in Just (conformalClipPredFromPreds blendWeight currentPrice k l bounds)
                    _ -> Nothing
            costPickNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        Just
                            ( costPickPredFromPreds
                                blendWeight
                                roundTripCost
                                currentPrice
                                k
                                l
                            )
                    _ -> Nothing
            softmaxBlendNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        Just (softmaxBlendPredFromPreds blendWeight currentPrice k l)
                    _ -> Nothing
            smoothSoftmaxBlendNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        let alpha = 0.2
                            w0 = clamp01 blendWeight
                            wPrev =
                                case mPredHistory of
                                    Just PredHistory{phKalman = kalHist, phLstm = lstmHist}
                                        | t > 0 ->
                                            let histLen = min t (min (V.length kalHist) (V.length lstmHist))
                                                step w i =
                                                    let prev = pricesV V.! i
                                                        kp = kalHist V.! i
                                                        lp = lstmHist V.! i
                                                        wSoft = softmaxBlendWeightFromPreds w0 prev kp lp
                                                        wRaw = (1 - alpha) * w + alpha * wSoft
                                                     in if bad wRaw then w else clamp01 wRaw
                                             in foldl' step w0 [0 .. histLen - 1]
                                    _ -> w0
                            wSoftCur = softmaxBlendWeightFromPreds w0 currentPrice k l
                            wRaw = (1 - alpha) * wPrev + alpha * wSoftCur
                            w =
                                if bad wRaw
                                    then wPrev
                                    else clamp01 wRaw
                            fallbackPred = finiteBlendOrNeutral w0 currentPrice k l
                            pred = w * k + (1 - w) * l
                         in Just (if bad pred then fallbackPred else pred)
                    _ -> Nothing
            hedgeBlendNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        let epsW = 1e-6
                            w0Raw = clamp01 blendWeight
                            w0 = max epsW (min (1 - epsW) (if bad w0Raw then 0.5 else w0Raw))
                            logit p = log (p / (1 - p))
                            sigmoid z
                                | z >= 30 = 1
                                | z <= (-30) = 0
                                | otherwise = 1 / (1 + exp (negate z))
                            eta = 6.0
                            maxErr = 0.1
                            safePred w prev kalPred lstmPred =
                                case (bad kalPred, bad lstmPred) of
                                    (False, False) ->
                                        let v = w * kalPred + (1 - w) * lstmPred
                                            fallback = finiteBlendOrNeutral w0 prev kalPred lstmPred
                                         in if bad v then fallback else v
                                    (False, True) -> kalPred
                                    (True, False) -> lstmPred
                                    (True, True) -> neutralPredFromPrev prev
                            ret prev x =
                                if prev <= 0 || bad prev || bad x
                                    then Nothing
                                    else
                                        let r = x / prev - 1
                                         in if bad r then Nothing else Just r
                            lossFromR rPred rReal =
                                let e = abs (rPred - rReal)
                                    e' = min maxErr (max 0 e)
                                 in if bad e' then maxErr else e'
                            updateZ z prev actual kalPred lstmPred =
                                case ret prev actual of
                                    Nothing -> z
                                    Just rReal ->
                                        let mRKal = ret prev kalPred
                                            mRLstm = ret prev lstmPred
                                            lKal = maybe maxErr (`lossFromR` rReal) mRKal
                                            lLstm = maybe maxErr (`lossFromR` rReal) mRLstm
                                            z' = z - eta * (lKal - lLstm)
                                         in if bad z' then z else z'
                            zPrev =
                                case mPredHistory of
                                    Just PredHistory{phKalman = kalHist, phLstm = lstmHist}
                                        | t > 0 ->
                                            let histLen = min t (min (V.length kalHist) (V.length lstmHist))
                                                step z i =
                                                    let prev = pricesV V.! i
                                                        actual = pricesV V.! (i + 1)
                                                        kp = kalHist V.! i
                                                        lp = lstmHist V.! i
                                                     in updateZ z prev actual kp lp
                                             in foldl' step (logit w0) [0 .. histLen - 1]
                                    _ -> logit w0
                            wCur = sigmoid zPrev
                            pred = safePred wCur currentPrice k l
                         in Just pred
                    _ -> Nothing
            netSoftmaxBlendNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        Just (netSoftmaxBlendPredFromPreds blendWeight roundTripCost currentPrice k l)
                    _ -> Nothing
            divergenceGateNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        Just (divergenceGatePredFromPreds blendWeight openThrAdj currentPrice k l)
                    _ -> Nothing
            harmonicBlendNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        Just
                            ( harmonicBlendPredFromPreds
                                blendWeight
                                currentPrice
                                k
                                l
                            )
                    _ -> Nothing
            disagreementGuardNext =
                case (mKalNext, mLstmNext) of
                    (Just k, Just l) ->
                        Just
                            ( disagreementGuardPredFromPreds
                                blendWeight
                                currentPrice
                                k
                                l
                            )
                    _ -> Nothing
            medianBlendNext =
