                    MethodHedgeBlend -> hedgeBlendDirGated
                    MethodNetSoftmaxBlend -> netSoftmaxBlendDirGated
                    MethodEdgeBlend -> edgeBlendDirGated
                    MethodEdgePick -> edgePickDirGated
                    MethodGeoBlend -> geoBlendDirGated
                    MethodRegimeSwitch -> regimeSwitchDirGated
                    MethodRouter -> routerDirGated
                    MethodBanditRouter -> routerDirGated
            chosenDirBase1 =
                case chosenDirBase of
                    Just dir
                        | signalEntryEdgeSpikeOk openThrAdj edgeForMethod -> Just dir
                    Just _ -> Nothing
                    Nothing -> Nothing
            mEdgeSpikeReason =
                case (chosenDirBase, chosenDirBase1) of
                    (Just _, Nothing) -> Just "EDGE_SPIKE"
                    _ -> Nothing
            (chosenDir0, pairsOverlayActive, mPairsOverlayReason) =
                if not pairsStatArbEnabled
                    then (chosenDirBase1, False, Nothing)
                    else case (chosenDirBase1, pairsDirRaw) of
                        (Nothing, Just d) -> (Just d, True, Nothing)
                        (Just d0, Just d1) ->
                            if d0 == d1
                                then (Just d0, True, Nothing)
                                else (Nothing, False, Just "PAIRS_CONFLICT")
                        (x, Nothing) -> (x, False, Nothing)
            (chosenDir1Base, mPostGateReasonBase) =
                signalRunPostDirectionGates
                    chosenDir0
                    mPairsOverlayReason
                    volOk
                    volTargetReady
                    trendOk
                    cloudOk
                    priceActionOk
                    signalToNoiseOk
                    regimeEdgeOk
                    mtfConsensusCheck
                    crossAssetCheck
                    metaLabelOk
                    fundingOiCheck
            (chosenDir1, mPostGateReason) =
                case chosenDir1Base of
                    Just _ -> (chosenDir1Base, mPostGateReasonBase)
                    Nothing -> (Nothing, mPostGateReasonBase <|> mEdgeSpikeReason)

            chosenDir2 =
                case chosenDir1 of
                    Nothing -> Nothing
                    Just _ ->
                        case method of
                            MethodLstmOnly -> chosenDir1
                            _ ->
                                case tradePosSize of
                                    Just sz | sz <= 0 -> Nothing
                                    _ -> chosenDir1

            volConfCell =
                volConfGateCell volConfGatePreset volEstimate volConfConfidence
            volConfBehavior = vcgBehavior volConfCell
            volConfSizeMult =
                if isJust chosenDir2
                    then vcgSizeMult volConfCell
                    else 1
            closeDir =
                case volConfBehavior of
                    VolConfGateHold -> Nothing
                    _ -> closeDirBase

            baseSize =
                case method of
                    MethodLstmOnly ->
                        case chosenDir2 of
                            Nothing -> 0
                            Just _ -> 1
                    _ ->
                        case (chosenDir2, tradePosSize) of
                            (Just _, Just sz) -> sz
                            _ -> 0

            fundingOiSizeScale =
                case chosenDir2 of
                    Just dir ->
                        let (_ok, sc) = fundingOiCheck dir
                         in sc
                    Nothing -> 1
            pairsSizeScale =
                if pairsOverlayActive
                    then pairsSizeMult
                    else 1
            kellyLiteScale =
                if not kellyLiteEnabled
                    then 1
                    else
                        let mu = fromMaybe 0 edgeForMethod
                            sig2 =
                                case volPerBar of
                                    Just v | v > 0 -> v * v
                                    _ -> 0
                            raw =
                                if sig2 <= 1e-12
                                    then 0
                                    else kellyLiteFraction * (mu / sig2)
                         in max kellyLiteFloor (min kellyLiteCap raw)
            sizeScaled = baseSize * volConfSizeMult * volScale * snrScaleWeighted
            sizeScaledRisk = sizeScaled * riskScale
            sizeAfterOverlays = sizeScaledRisk * regimeSizeMult * pairsSizeScale * fundingOiSizeScale * kellyLiteScale
            sizeCapped = min maxPositionSize (max 0 sizeAfterOverlays)
            sizeFinal0 =
                if (confidenceSizingEnabled || volConfGateEnabled) && sizeCapped < argMinPositionSize args
                    then 0
                    else sizeCapped

            (chosenDirVolConf, sizeFinal1) =
                applyVolConfGateBehavior volConfBehavior Nothing 0 chosenDir2 sizeFinal0

            volConfGateReason =
                if isNothing chosenDir2
                    then Nothing
                    else case volConfBehavior of
                        VolConfGateAllowEntry -> Nothing
                        VolConfGateHold -> Just "VOL_CONF_GATE_HOLD"
                        VolConfGateBlock -> Just "VOL_CONF_GATE_BLOCK"
                        VolConfGateAllowExitOnly -> Just "VOL_CONF_GATE_ALLOW_EXIT_ONLY"

            (chosenDir, mSizeGateReason) =
                case chosenDirVolConf of
                    Nothing -> (Nothing, Nothing)
                    Just _ ->
                        if sizeFinal1 <= 0
                            then (Nothing, Just "MIN_SIZE")
                            else (chosenDirVolConf, Nothing)

            gateReasonFinal = mPostGateReason <|> volConfGateReason <|> mSizeGateReason <|> gateReasonForMethod

            action =
                let downAction =
                        case argPositioning args of
                            LongShort -> "SHORT"
                            LongFlat -> "FLAT"
                 in case method of
                        MethodBoth ->
                            case (kalDirRaw, lstmDir, chosenDir) of
                                (Just 1, Just 1, Just 1) -> "LONG"
                                (Just (-1), Just (-1), Just (-1)) -> downAction
                                (Nothing, Nothing, Nothing) -> "HOLD (both neutral)"
                                (Just _, Just _, Nothing) ->
                                    case agreeDir of
                                        Just _ ->
                                            case gateReasonFinal of
                                                Just why -> "HOLD (" ++ why ++ ")"
                                                Nothing -> "HOLD (confidence gate)"
                                        Nothing -> "HOLD (directions disagree)"
                                _ -> "HOLD (directions disagree)"
                        MethodKalmanOnly ->
                            case (kalDirRaw, chosenDir) of
                                (Just 1, Just 1) -> "LONG"
                                (Just (-1), Just (-1)) -> downAction
                                (Just _, Nothing) ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (confidence gate)"
                                _ -> "HOLD (Kalman neutral)"
                        MethodKalmanPhysicsError ->
                            case (kalDirRaw, chosenDir) of
                                (Just 1, Just 1) -> "LONG"
                                (Just (-1), Just (-1)) -> downAction
                                (Just _, Nothing) ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (confidence gate)"
                                _ -> "HOLD (Kalman neutral)"
                        MethodLstmOnly ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (LSTM neutral)"
                        MethodBlend ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (blend neutral)"
                        MethodConfBlend ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (conf_blend neutral)"
                        MethodConfPick ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (conf_pick neutral)"
                        MethodConformalClip ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (conformal_clip neutral)"
                        MethodCostPick ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (cost_pick neutral)"
                        MethodHarmonicBlend ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (harmonic_blend neutral)"
                        MethodDisagreementGuard ->
