                                        Nothing -> "HOLD (median_blend neutral)"
                        MethodNeutralGuard ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (neutral_guard neutral)"
                        MethodRiskParityBlend ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
