                                        Nothing -> "HOLD (fractal_blend neutral)"
                        MethodPhaseCancel ->
                            case chosenDir of
                                Just 1 -> "LONG"
                                Just (-1) -> downAction
                                _ ->
                                    case gateReasonFinal of
                                        Just why -> "HOLD (" ++ why ++ ")"
                                        Nothing -> "HOLD (phase_cancel neutral)"
                        MethodSoftmaxBlend ->
                            case chosenDir of
