                , lsConfidence = methodConfidence
                , lsPositionSize = posSizeFinal
                , lsExitSize = Nothing
                , lsKalmanDir = kalDir
                , lsLstmNext = mLstmNext
                , lsSizingNext = sizingNext
                , lsLstmDir = lstmDir
                , lsChosenDir = chosenDir
                , lsCloseDir = closeDir
                , lsAction = action
                }

printLatestSignalSummary :: LatestSignal -> IO ()
printLatestSignalSummary sig = do
    let showDir :: Maybe Int -> String
        showDir d =
            case d of
                Just 1 -> "UP"
                Just (-1) -> "DOWN"
                _ -> "NEUTRAL"

    putStrLn ""
    putStrLn "**Latest Signal**"
    putStrLn (printf "Method: %s" (methodCode (lsMethod sig)))
    putStrLn (printf "Vol/conf gate: %s" (volConfGateCode (lsVolConfGate sig)))
    case lsKalmanNext sig of
        Nothing -> putStrLn "Kalman next: (disabled)"
        Just kalNext -> putStrLn (printf "Kalman next: %.4f (%s)" kalNext (showDir (lsKalmanDir sig)))
    case lsKalmanZ sig of
        Nothing -> pure ()
        Just z -> putStrLn (printf "Kalman z:    %.3f" z)
    case lsConfidence sig of
        Nothing -> pure ()
        Just c -> putStrLn (printf "Confidence:  %.3f" c)
    case lsPositionSize sig of
        Nothing -> pure ()
        Just s -> putStrLn (printf "Pos size:    %.3f" s)
    case lsLstmNext sig of
        Nothing -> putStrLn "LSTM next:   (disabled)"
        Just lstmNext -> putStrLn (printf "LSTM next:   %.4f (%s)" lstmNext (showDir (lsLstmDir sig)))
    putStrLn (printf "Open threshold:  %.3f%%" (lsOpenThreshold sig * 100))
    putStrLn (printf "Close threshold: %.3f%%" (lsCloseThreshold sig * 100))
    putStrLn (printf "Close dir:       %s" (showDir (lsCloseDir sig)))
    putStrLn (printf "Action: %s" (lsAction sig))

volPerBarFromSignal :: Args -> LatestSignal -> Maybe Double
volPerBarFromSignal args sig =
    case lsVolatility sig of
        Just vol ->
            let ppy = max 1e-12 (periodsPerYear args)
                perBar = vol / sqrt ppy
             in if isNaN perBar || isInfinite perBar || perBar <= 0 then Nothing else Just perBar
        _ -> Nothing

volPerBarFromPrices :: [Double] -> Maybe Double
volPerBarFromPrices prices =
    let rs =
            case prices of
                [] -> []
                [_] -> []
                _ ->
                    zipWith
                        (\p0 p1 -> if p0 == 0 then 0 else p1 / p0 - 1)
                        prices
                        (drop 1 prices)
        rsClean = filter (\x -> not (isNaN x || isInfinite x)) rs
        n = length rsClean
     in if n < 2
            then Nothing
            else
                let m = sum rsClean / fromIntegral n
                    var = sum (map (\x -> (x - m) ** 2) rsClean) / fromIntegral (n - 1)
                    std = sqrt (max 0 var)
                 in if isNaN std || isInfinite std || std <= 0 then Nothing else Just std

volPerBarFromPricesV :: V.Vector Double -> Maybe Double
volPerBarFromPricesV = volPerBarFromPrices . V.toList

costPerSideTotal :: Args -> Double -> Maybe Double -> Double
costPerSideTotal args size mVolPerBar =
    let s = max 0 (abs size)
     in if s <= 0
            then 0
            else
                let vol = max 0 (fromMaybe 0 mVolPerBar)
                    feeRate = max 0 (argFee args)
                    feeFixed = max 0 (argFeeFixed args)
                    feeMin = max 0 (argFeeMin args)
                    slipBase = max 0 (argSlippage args)
                    slipVol = max 0 (argSlippageVolMult args) * vol
                    impactPower = max 0 (argSlippageImpactPower args)
                    impactRate = max 0 (argSlippageImpact args) * (s ** impactPower)
                    spreadBase = max 0 (argSpread args)
                    spreadVol = max 0 (argSpreadVolMult args) * vol
                    spreadTotal = spreadBase + spreadVol
                    perNotional = feeRate + slipBase + slipVol + impactRate + spreadTotal / 2
                    total0 = perNotional * s + feeFixed
                    total1 = if feeMin > 0 then max feeMin total0 else total0
                 in min 0.999999 (max 0 total1)

costPerSideRate :: Args -> Double -> Maybe Double -> Double
costPerSideRate args size mVolPerBar =
    let s = max 0 (abs size)
     in if s <= 0
            then 0
            else costPerSideTotal args s mVolPerBar / s

estimatedPerSideCost :: Args -> Double -> Maybe Double -> Double
estimatedPerSideCost = costPerSideRate

estimatedRoundTripCost :: Args -> Double -> Maybe Double -> Double
estimatedRoundTripCost args size mVolPerBar =
    let perSide = estimatedPerSideCost args size mVolPerBar
     in min 0.999999 (2 * perSide)

breakEvenThresholdFromPerSideCost :: Double -> Double
breakEvenThresholdFromPerSideCost perSide0 =
    let perSide = min 0.999999 (max 0 perSide0)
        denom = max 1e-12 ((1 - perSide) * (1 - perSide))
        be = 1 / denom - 1
     in max 0 be

estimatedBreakEvenThreshold :: Args -> Double -> Maybe Double -> Double
estimatedBreakEvenThreshold args size mVolPerBar =
    let perSide = estimatedPerSideCost args size mVolPerBar
     in breakEvenThresholdFromPerSideCost perSide

printCostGuidance :: Double -> Double -> Double -> Double -> IO ()
printCostGuidance openThr closeThr perSide roundTrip = do
    let breakEven = breakEvenThresholdFromPerSideCost perSide
    putStrLn ""
    putStrLn "**Estimated Costs**"
    putStrLn (printf "Per side:  %.3f%%" (perSide * 100))
    putStrLn (printf "Round trip (approx): %.3f%%" (roundTrip * 100))
    putStrLn (printf "Break-even threshold: %.3f%%" (breakEven * 100))
    when (openThr < breakEven) $
        putStrLn
            ( printf
                "Warning: openThreshold %.3f%% is below break-even threshold %.3f%% (may churn after costs)."
                (openThr * 100)
                (breakEven * 100)
            )
    when (closeThr < breakEven) $
        putStrLn
            ( printf
                "Note: closeThreshold %.3f%% is below break-even threshold %.3f%%."
                (closeThr * 100)
                (breakEven * 100)
            )

printFundingGuidance :: Double -> Bool -> IO ()
printFundingGuidance fundingRate fundingBySide =
    when (fundingRate < 0 && not fundingBySide) $
        putStrLn
            ( printf
                "Warning: fundingRate %.3f%% is negative with side-agnostic funding; enable --funding-by-side for long/short sign."
                (fundingRate * 100)
            )

maybeSendOrder :: Maybe Webhook -> Args -> Maybe BinanceEnv -> LatestSignal -> IO ()
maybeSendOrder mWebhook args mBinanceEnv sig =
    case argPlatform args of
        PlatformBinance ->
            case (argBinanceSymbol args, mBinanceEnv) of
                (Just sym, Just env)
                    | argBinanceTrade args -> do
                        res <- placeOrderForSignal args sym sig env
                        putStrLn (aorMessage res)
                        webhookNotifyMaybeSync mWebhook (webhookEventTradeOrder args sig res)
                    | otherwise -> pure ()
                _ -> pure ()
        PlatformCoinbase ->
            case argBinanceSymbol args of
                Just sym
                    | argBinanceTrade args -> do
                        envOrErr <- try (makeCoinbaseEnv args) :: IO (Either SomeException CoinbaseEnv)
                        case envOrErr of
                            Left _ -> pure ()
                            Right env -> do
                                res <- placeCoinbaseOrderForSignal args sym sig env
                                putStrLn (aorMessage res)
                                webhookNotifyMaybeSync mWebhook (webhookEventTradeOrder args sig res)
                    | otherwise -> pure ()
                _ -> pure ()
        _ -> pure ()

data PriceSeries = PriceSeries
    { psClose :: ![Double]
    , psOpen :: !(Maybe [Double])
    , psHigh :: !(Maybe [Double])
    , psLow :: !(Maybe [Double])
    , psVolume :: !(Maybe [Double])
    , psOpenTimes :: !(Maybe [Int64])
    }
    deriving (Eq, Show)

featureInputsFromSeries :: PriceSeries -> FeatureInputs
featureInputsFromSeries series =
    mkFeatureInputs
        (V.fromList (psClose series))
        (V.fromList <$> psOpen series)
        (V.fromList <$> psHigh series)
        (V.fromList <$> psLow series)
        (V.fromList <$> psVolume series)

featureInputsFromLists ::
    [Double] ->
    Maybe [Double] ->
    Maybe [Double] ->
    Maybe [Double] ->
    Maybe [Double] ->
    FeatureInputs
featureInputsFromLists closes opens highs lows volumes =
    mkFeatureInputs
        (V.fromList closes)
        (V.fromList <$> opens)
        (V.fromList <$> highs)
        (V.fromList <$> lows)
        (V.fromList <$> volumes)

priceSourceLabel :: Args -> String
priceSourceLabel args =
    if prefersCsvBars args
        then case argData args of
            Just path -> "CSV " ++ path ++ " (column " ++ show (argPriceCol args) ++ ")"
            Nothing -> "data source"
        else case (argBinanceSymbol args, argData args) of
            (Just sym, _) ->
                platformLabel (argPlatform args) ++ " " ++ sym ++ " (" ++ argInterval args ++ ")"
            (_, Just path) ->
                "CSV " ++ path ++ " (column " ++ show (argPriceCol args) ++ ")"
            _ ->
                "data source"

ensureMinPriceRows :: Args -> Int -> [Double] -> IO ()
ensureMinPriceRows args minRows prices =
    let n = length prices
        hint =
            if prefersCsvBars args
                then " Check the CSV has at least " ++ show minRows ++ " data rows (not counting the header)."
                else case (argBinanceSymbol args, argData args) of
                    (Just _, _) ->
                        " Check symbol/interval and increase --bars (requested " ++ show (resolveBarsForPlatform args) ++ ")."
                    (_, Just _) ->
                        " Check the CSV has at least " ++ show minRows ++ " data rows (not counting the header)."
                    _ -> ""
     in (when (n < minRows) $ throwIO (userError ("Need at least " ++ show minRows ++ " price rows (got " ++ show n ++ ") from " ++ priceSourceLabel args ++ "." ++ hint)))

ensureLookbackRows :: Args -> Int -> [Double] -> IO ()
ensureLookbackRows args lookback prices =
    let n = length prices
        minRows = lookback + 1
        hint =
            if prefersCsvBars args
                then " Check the CSV has at least " ++ show minRows ++ " data rows (not counting the header), or reduce --lookback-bars/--lookback-window."
                else case (argBinanceSymbol args, argData args) of
                    (Just _, _) ->
                        " Increase --bars (requested " ++ show (resolveBarsForPlatform args) ++ ") or reduce --lookback-bars/--lookback-window."
                    (_, Just _) ->
                        " Check the CSV has at least " ++ show minRows ++ " data rows (not counting the header), or reduce --lookback-bars/--lookback-window."
                    _ ->
                        " Increase --bars or reduce --lookback-bars/--lookback-window."
     in ( when (n < minRows) $
            throwIO
                ( userError
                    ( "Need at least "
                        ++ show minRows
                        ++ " price rows for lookback="
                        ++ show lookback
                        ++ " (got "
                        ++ show n
                        ++ ") from "
                        ++ priceSourceLabel args
                        ++ "."
                        ++ hint
                    )
                )
        )

loadPrices :: Maybe OpsStore -> Args -> IO (PriceSeries, Maybe BinanceEnv)
loadPrices mOps args =
    let isDex = isDexPlatform (argPlatform args)
        loadCsv path = do
            csvOrErr <- loadCsvPriceSeries path (argPriceCol args) (argHighCol args) (argLowCol args)
            (closes, mOpens, mHighs, mLows, mVolumes, mOpenTimes) <-
                case csvOrErr of
                    Left err -> throwIO (userError err)
                    Right out -> pure out
            let bars = resolveBarsForCsv args
            let closes' =
                    if bars > 0
                        then takeLast bars closes
                        else closes
                opens' =
                    if bars > 0
                        then fmap (takeLast bars) mOpens
                        else mOpens
                highs' =
                    if bars > 0
                        then fmap (takeLast bars) mHighs
                        else mHighs
                lows' =
                    if bars > 0
                        then fmap (takeLast bars) mLows
                        else mLows
                volumes' =
                    if bars > 0
                        then fmap (takeLast bars) mVolumes
                        else mVolumes
                openTimes' =
                    if bars > 0
                        then fmap (takeLast bars) mOpenTimes
                        else mOpenTimes
            pure (PriceSeries closes' opens' highs' lows' volumes' openTimes', Nothing)
     in case (argData args, argBinanceSymbol args) of
            (Just path, Nothing) -> loadCsv path
            (Just path, Just _sym) | isDex -> loadCsv path
            (Nothing, Just sym) ->
                case argPlatform args of
                    PlatformBinance -> do
                        (env, series) <- loadPricesBinance mOps args sym
                        pure (series, Just env)
                    PlatformCoinbase -> do
                        series <- loadPricesCoinbase args sym
                        pure (series, Nothing)
                    PlatformKraken -> do
                        series <- loadPricesKraken args sym
                        pure (series, Nothing)
                    PlatformPoloniex -> do
                        series <- loadPricesPoloniex args sym
                        pure (series, Nothing)
                    _ ->
                        throwIO
                            ( userError
                                ("DEX platforms require --data for price input (platform=" ++ platformCode (argPlatform args) ++ ").")
                            )
            (Just _, Just _) ->
                throwIO (userError "Provide only one of --data or --binance-symbol (unless using a DEX platform).")
            (Nothing, Nothing) ->
                throwIO (userError "Provide --data or --binance-symbol")

takeLast :: Int -> [a] -> [a]
takeLast n xs
    | n <= 0 = []
    | otherwise =
        let k = length xs - n
         in if k <= 0 then xs else drop k xs

loadPricesBinance :: Maybe OpsStore -> Args -> String -> IO (BinanceEnv, PriceSeries)
loadPricesBinance mOps args sym = do
    let market = argBinanceMarket args
    when (market == MarketMargin && argBinanceTestnet args) $
        throwIO (userError "--binance-testnet is not supported for margin operations")
    let barsBase = resolveBarsForBinance args
        bars =
            if argMethod args == MethodKalmanPhysicsError
                then 1000
                else barsBase
    urls <- resolveBinanceBaseUrls
    let tradeBase = selectBinanceBaseUrl urls (argBinanceTestnet args) market
        dataBase = selectBinanceDataBaseUrl urls market
    apiKey <- resolveEnv "BINANCE_API_KEY" (argBinanceApiKey args)
    apiSecret <- resolveEnv "BINANCE_API_SECRET" (argBinanceApiSecret args)
    envTrade <- newBinanceEnvWithOps mOps market tradeBase (BS.pack <$> apiKey) (BS.pack <$> apiSecret)
    klinesE <- try (fetchKlines envTrade sym (argInterval args) bars) :: IO (Either HttpException [Kline])
    ks <-
        case klinesE of
            Right out -> pure out
            Left ex ->
                if argBinanceTestnet args
                    then do
                        envData <- newBinanceEnvWithOps mOps market dataBase (BS.pack <$> apiKey) (BS.pack <$> apiSecret)
                        fetchKlines envData sym (argInterval args) bars
                    else throwIO ex
    let opens = map kOpen ks
        closes = map kClose ks
        highs = map kHigh ks
        lows = map kLow ks
        volumes = map kVolume ks
        openTimes = map (normalizeEpochMs . kOpenTime) ks
    pure (envTrade, PriceSeries closes (Just opens) (Just highs) (Just lows) (Just volumes) (Just openTimes))

loadPricesCoinbase :: Args -> String -> IO PriceSeries
loadPricesCoinbase args sym = do
    let interval = argInterval args
        bars = resolveBarsForPlatform args
    granularity <-
        case coinbaseIntervalSeconds interval of
            Just v -> pure v
            Nothing -> throwIO (userError ("Interval not supported by Coinbase: " ++ interval))
    candles <- fetchCoinbaseCandles sym granularity (max 1 bars)
    let closes = map ccClose candles
        highs = map ccHigh candles
        lows = map ccLow candles
        openTimes = map (normalizeEpochMs . ccOpenTime) candles
        closes' = if bars > 0 then takeLast bars closes else closes
        highs' = if bars > 0 then takeLast bars highs else highs
        lows' = if bars > 0 then takeLast bars lows else lows
        openTimes' = if bars > 0 then takeLast bars openTimes else openTimes
    pure (PriceSeries closes' Nothing (Just highs') (Just lows') Nothing (Just openTimes'))

loadPricesKraken :: Args -> String -> IO PriceSeries
loadPricesKraken args sym = do
    let interval = argInterval args
        bars = resolveBarsForPlatform args
    minutes <-
        case krakenIntervalMinutes interval of
            Just v -> pure v
            Nothing -> throwIO (userError ("Interval not supported by Kraken: " ++ interval))
    candles <- fetchKrakenCandles sym minutes
    let closes = map kcClose candles
        highs = map kcHigh candles
        lows = map kcLow candles
        openTimes = map (normalizeEpochMs . kcOpenTime) candles
        closes' = if bars > 0 then takeLast bars closes else closes
        highs' = if bars > 0 then takeLast bars highs else highs
        lows' = if bars > 0 then takeLast bars lows else lows
        openTimes' = if bars > 0 then takeLast bars openTimes else openTimes
    pure (PriceSeries closes' Nothing (Just highs') (Just lows') Nothing (Just openTimes'))

loadPricesPoloniex :: Args -> String -> IO PriceSeries
loadPricesPoloniex args sym = do
    let interval = argInterval args
        bars = resolveBarsForPlatform args
    (label, period) <-
        case (poloniexIntervalLabel interval, poloniexIntervalSeconds interval) of
            (Just l, Just p) -> pure (l, p)
            _ -> throwIO (userError ("Interval not supported by Poloniex: " ++ interval))
    candles <- fetchPoloniexCandles sym label period (max 1 bars)
    let closes = map pcClose candles
        highs = map pcHigh candles
        lows = map pcLow candles
        openTimes = map (normalizeEpochMs . pcOpenTime) candles
        closes' = if bars > 0 then takeLast bars closes else closes
        highs' = if bars > 0 then takeLast bars highs else highs
        lows' = if bars > 0 then takeLast bars lows else lows
        openTimes' = if bars > 0 then takeLast bars openTimes else openTimes
    pure (PriceSeries closes' Nothing (Just highs') (Just lows') Nothing (Just openTimes'))

data BinanceBaseUrls = BinanceBaseUrls
    { bbuSpot :: !String
    , bbuSpotTestnet :: !String
    , bbuFutures :: !String
    , bbuFuturesTestnet :: !String
    }
    deriving (Eq, Show)

resolveBinanceBaseUrls :: IO BinanceBaseUrls
resolveBinanceBaseUrls = do
    spot <- resolveUrlEnv "TRADER_BINANCE_REST_URL" binanceBaseUrl
    spotTestnet <- resolveUrlEnv "TRADER_BINANCE_TESTNET_REST_URL" binanceTestnetBaseUrl
    futures <- resolveUrlEnv "TRADER_BINANCE_FUTURES_REST_URL" binanceFuturesBaseUrl
    futuresTestnet <- resolveUrlEnv "TRADER_BINANCE_FUTURES_TESTNET_REST_URL" binanceFuturesTestnetBaseUrl
    pure
        BinanceBaseUrls
            { bbuSpot = spot
            , bbuSpotTestnet = spotTestnet
            , bbuFutures = futures
            , bbuFuturesTestnet = futuresTestnet
            }

resolveUrlEnv :: String -> String -> IO String
resolveUrlEnv key fallback = do
    raw <- lookupEnv key
    pure $
        maybe fallback sanitizeBaseUrl (raw >>= nonEmptyTrim)

selectBinanceBaseUrl :: BinanceBaseUrls -> Bool -> BinanceMarket -> String
selectBinanceBaseUrl urls testnet market =
    case market of
        MarketFutures -> if testnet then bbuFuturesTestnet urls else bbuFutures urls
        _ -> if testnet then bbuSpotTestnet urls else bbuSpot urls

selectBinanceDataBaseUrl :: BinanceBaseUrls -> BinanceMarket -> String
selectBinanceDataBaseUrl urls market =
    case market of
        MarketFutures -> bbuFutures urls
        _ -> bbuSpot urls

sanitizeBaseUrl :: String -> String
sanitizeBaseUrl raw =
    let trimmed = trimString raw
        stripped = dropWhileEnd (== '/') trimmed
     in if null stripped then trimmed else stripped

nonEmptyTrim :: String -> Maybe String
nonEmptyTrim raw =
    let trimmed = trimString raw
     in if null trimmed then Nothing else Just trimmed

trimString :: String -> String
trimString = dropWhileEnd isSpace . dropWhile isSpace

resolveEnv :: String -> Maybe String -> IO (Maybe String)
resolveEnv name override =
    case override of
        Just v -> pure (Just v)
        Nothing -> lookupEnv name

periodsPerYear :: Args -> Double
periodsPerYear args =
    case argPeriodsPerYear args of
        Just v -> v
        Nothing ->
            inferPeriodsPerYear (argInterval args)

forwardReturns :: [Double] -> [Double]
forwardReturns ps =
    [ if p0 == 0 then 0 else p1 / p0 - 1
    | (p0, p1) <- zip ps (drop 1 ps)
    ]

toMeasurement :: Args -> SensorVar -> (SensorId, SensorOutput) -> Maybe (Double, Double)
toMeasurement args sv (sid, out) =
    let fallbackVar = max 1e-12 (argKalmanMeasurementVar args)
        var =
            case soSigma out of
                Just s | s > 0 -> s * s
                _ -> fromMaybe fallbackVar (varianceFor sid sv)
        var' = max 1e-12 var
     in Just (soMu out, var')

backtestStepKalmanOnly ::
    Args ->
    FeatureInputs ->
    PredictorBundle ->
    Int ->
    Maybe MarketModel ->
    (Kalman1, HMMFilter, SensorVar, [Double], [StepMeta]) ->
    Int ->
    (Kalman1, HMMFilter, SensorVar, [Double], [StepMeta])
backtestStepKalmanOnly args inputs predictors trainEnd mMarketModel (kal, hmm, sv, kalAcc, metaAcc) i =
    let pricesV = fiClose inputs
        t = trainEnd + i
        priceT = pricesV V.! t
        nextP = pricesV V.! (t + 1)
        realizedR = if priceT == 0 then 0 else nextP / priceT - 1

        (sensorOuts, predState) = predictSensorsWithInputs predictors inputs hmm t
        mReg = listToMaybe [r | (_sid, out) <- sensorOuts, Just r <- [soRegimes out]]
        mQ = listToMaybe [q | (_sid, out) <- sensorOuts, Just q <- [soQuantiles out]]
        mI = listToMaybe [i' | (_sid, out) <- sensorOuts, Just i' <- [soInterval out]]
        meas = mapMaybe (toMeasurement args sv) sensorOuts ++ maybeToList (mMarketModel >>= (`marketMeasurementAt` t))
        kal' = stepMulti meas kal
        fusedR = kMean kal'
        kalNext = priceT * (1 + fusedR)
        meta =
            StepMeta
                { smKalmanMean = kMean kal'
                , smKalmanVar = kVar kal'
                , smHighVolProb = rpHighVol <$> mReg
                , smQuantile10 = q10 <$> mQ
                , smQuantile90 = q90 <$> mQ
                , smConformalLo = iLo <$> mI
                , smConformalHi = iHi <$> mI
                }

        sv' =
            foldl'
                (\acc (sid, out) -> updateResidual sid (realizedR - soMu out) acc)
                sv
                sensorOuts
        hmm' = updateHMM predictors predState realizedR
     in (kal', hmm', sv', kalNext : kalAcc, meta : metaAcc)

backtestStep ::
    Args ->
    Int ->
    NormState ->
    [Double] ->
    FeatureInputs ->
    LSTMModel ->
    PredictorBundle ->
    Int ->
    Maybe MarketModel ->
    (Kalman1, HMMFilter, SensorVar, [Double], [Double], [StepMeta]) ->
    Int ->
    (Kalman1, HMMFilter, SensorVar, [Double], [Double], [StepMeta])
backtestStep args lookback normState obsAll inputs lstmModel predictors trainEnd mMarketModel (kal, hmm, sv, kalAcc, lstmAcc, metaAcc) i =
    let pricesV = fiClose inputs
        t = trainEnd + i
        priceT = pricesV V.! t
        nextP = pricesV V.! (t + 1)
        realizedR = if priceT == 0 then 0 else nextP / priceT - 1

        (sensorOuts, predState) = predictSensorsWithInputs predictors inputs hmm t
        mReg = listToMaybe [r | (_sid, out) <- sensorOuts, Just r <- [soRegimes out]]
        mQ = listToMaybe [q | (_sid, out) <- sensorOuts, Just q <- [soQuantiles out]]
        mI = listToMaybe [i' | (_sid, out) <- sensorOuts, Just i' <- [soInterval out]]
        meas = mapMaybe (toMeasurement args sv) sensorOuts ++ maybeToList (mMarketModel >>= (`marketMeasurementAt` t))
        kal' = stepMulti meas kal
        fusedR = kMean kal'
        kalNext = priceT * (1 + fusedR)
        meta =
            StepMeta
                { smKalmanMean = kMean kal'
                , smKalmanVar = kVar kal'
                , smHighVolProb = rpHighVol <$> mReg
                , smQuantile10 = q10 <$> mQ
                , smQuantile90 = q90 <$> mQ
                , smConformalLo = iLo <$> mI
                , smConformalHi = iHi <$> mI
                }

        window = take lookback (drop (t - lookback + 1) obsAll)
        lstmNextObs = predictNext lstmModel window
        lstmNext = inverseNorm normState lstmNextObs

        sv' =
            foldl'
                (\acc (sid, out) -> updateResidual sid (realizedR - soMu out) acc)
                sv
                sensorOuts
        hmm' = updateHMM predictors predState realizedR
     in (kal', hmm', sv', kalNext : kalAcc, lstmNext : lstmAcc, meta : metaAcc)

printLstmSummary :: [EpochStats] -> IO ()
printLstmSummary history =
    case history of
        [] -> putStrLn "LSTM: no training history"
        _ ->
            let bestVal = minimum (map esValLoss history)
             in putStrLn (printf "LSTM: epochs=%d best_val_loss=%.6f" (length history) bestVal)

lstmHealthScore :: [EpochStats] -> Maybe Double
lstmHealthScore history =
    case reverse history of
        (latest : prev : _) ->
            let prevLoss = esValLoss prev
                latestLoss = esValLoss latest
                denom = max 1e-12 (abs prevLoss)
                trend = (prevLoss - latestLoss) / denom
                score = clamp01 (0.5 + 0.5 * trend)
             in if bad score then Nothing else Just score
        _ -> Nothing
  where
    bad x = isNaN x || isInfinite x

printMetrics :: Method -> Double -> BacktestMetrics -> IO ()
printMetrics method initialBalance m = do
    putStrLn ""
    putStrLn "**Profitability**"
    if abs (initialBalance - 1) <= 1e-12
        then putStrLn (printf "Final equity: %.4fx" (bmFinalEquity m))
        else putStrLn (printf "Final equity: %.4f (from initial balance %.4f)" (bmFinalEquity m) initialBalance)
    putStrLn (printf "Total return: %.2f%%" (bmTotalReturn m * 100))
    putStrLn (printf "Annualized return: %.2f%%" (bmAnnualizedReturn m * 100))

    putStrLn ""
    putStrLn "**Risk & Volatility**"
    putStrLn (printf "Annualized volatility: %.2f%%" (bmAnnualizedVolatility m * 100))
    putStrLn (printf "Downside volatility (ann.): %.2f%%" (bmDownsideVolatility m * 100))
    putStrLn (printf "Sharpe ratio (rf=0): %.3f" (bmSharpe m))
    putStrLn (printf "Sortino ratio (rf=0): %.3f" (bmSortino m))
    putStrLn (printf "Max drawdown: %.2f%%" (bmMaxDrawdown m * 100))
    putStrLn (printf "Calmar ratio: %.3f" (bmCalmar m))
    putStrLn (printf "VaR 95%% (per-period): %.2f%%" (bmVaR95 m * 100))
    putStrLn (printf "CVaR 95%% (per-period): %.2f%%" (bmCVaR95 m * 100))

    putStrLn ""
    putStrLn "**Trade Execution**"
    putStrLn (printf "Position changes: %d" (bmPositionChanges m))
    putStrLn (printf "Trades: %d" (bmTradeCount m))
    putStrLn (printf "Closed trades (round trips): %d" (bmRoundTrips m))
    putStrLn (printf "Win rate: %.1f%%" (bmWinRate m * 100))
    let profitFactorLabel :: String
        profitFactorLabel =
            case bmProfitFactor m of
                Just pf -> printf "%.3f" pf
                Nothing ->
                    if bmGrossProfit m > 0
                        then "∞"
                        else "0"
    putStrLn (printf "Gross profit: %.4f" (bmGrossProfit m))
    putStrLn (printf "Gross loss: %.4f" (bmGrossLoss m))
    putStrLn (printf "Profit factor: %s" profitFactorLabel)
    putStrLn (printf "Avg trade return: %.2f%%" (bmAvgTradeReturn m * 100))
    putStrLn (printf "Avg holding (periods): %.2f" (bmAvgHoldingPeriods m))

    putStrLn ""
    putStrLn "**Efficiency**"
    putStrLn (printf "Exposure (time in market): %.1f%%" (bmExposure m * 100))
    let agreeLabel :: String
        agreeLabel =
            case method of
                MethodBoth -> "Direction agreement rate"
                MethodKalmanOnly -> "Signal rate (Kalman)"
                MethodKalmanPhysicsError -> "Signal rate (Kalman)"
                MethodLstmOnly -> "Signal rate (LSTM)"
                MethodBlend -> "Signal rate (Blend)"
                MethodConfBlend -> "Signal rate (Conf blend)"
                MethodConfPick -> "Signal rate (Conf pick)"
                MethodConformalClip -> "Signal rate (Conformal clip)"
                MethodCostPick -> "Signal rate (Cost pick)"
                MethodHarmonicBlend -> "Signal rate (Harmonic blend)"
                MethodDisagreementGuard -> "Signal rate (Disagreement guard)"
                MethodMedianBlend -> "Signal rate (Median blend)"
                MethodNeutralGuard -> "Signal rate (Neutral guard)"
                MethodRiskParityBlend -> "Signal rate (Risk parity blend)"
                MethodConsensusBoost -> "Signal rate (Consensus boost)"
                MethodAnchorBlend -> "Signal rate (Anchor blend)"
                MethodTensionGate -> "Signal rate (Tension gate)"
                MethodEntropyBlend -> "Signal rate (Entropy blend)"
                MethodCoherenceGate -> "Signal rate (Coherence gate)"
                MethodDivergenceGate -> "Signal rate (Divergence gate)"
                MethodFractalBlend -> "Signal rate (Fractal blend)"
                MethodPhaseCancel -> "Signal rate (Phase cancel)"
                MethodSoftmaxBlend -> "Signal rate (Softmax blend)"
                MethodSmoothSoftmaxBlend -> "Signal rate (Smooth softmax blend)"
                MethodHedgeBlend -> "Signal rate (Hedge blend)"
                MethodNetSoftmaxBlend -> "Signal rate (Net softmax blend)"
                MethodEdgeBlend -> "Signal rate (Edge blend)"
                MethodEdgePick -> "Signal rate (Edge pick)"
                MethodGeoBlend -> "Signal rate (Geo blend)"
                MethodRegimeSwitch -> "Signal rate (Regime switch)"
                MethodRouter -> "Signal rate (Router)"
                MethodBanditRouter -> "Signal rate (Bandit router)"
    putStrLn (printf "%s: %.1f%%" agreeLabel (bmAgreementRate m * 100))
    putStrLn (printf "Turnover (changes/period): %.4f" (bmTurnover m))

shortResp :: BL.ByteString -> String
shortResp bs =
    let s = BS.unpack (BL.toStrict bs)
     in take 200 s
